#!/usr/bin/env python3
"""
Chuga Chocho — location scene generator.

Scenes are hand-authored ART, but the *furniture* (road, track, both crossing gates)
must be pixel-identical in every scene or the engine breaks. So this script owns the
furniture and the layer order, and each scene supplies only its artwork, slotted into
the correct depth planes.

That makes the classic bugs structurally impossible:
  * a scene can't be missing a gate — the generator always emits both
  * geometry can't drift — road/track/gate coords come from one place
  * layer order can't be wrong — the generator assembles it
  * props can't sit in the train's path — art goes in BACK (above the rails) or
    FRONT (below them), never in the y=450..516 band

See SCENE_GUIDE.md for the spec this implements. Run: python3 tools/gen-scenes.py
"""
import pathlib

OUT = pathlib.Path(__file__).resolve().parent.parent / 'play/assets/scenes'
OUT.mkdir(parents=True, exist_ok=True)

W, H = 1280, 720
HORIZON = 300
TRACK_TOP, TRACK_BOT = 450, 516

# ============================================================== FURNITURE ====

def road(surface='#6a6a6f', surface2='#54545a', shoulder='#e8e2c9', dash='#ffe066'):
    """Perspective road: vanishing point on the horizon, so it recedes INTO the
    scene rather than slicing through it."""
    return f'''  <g id="road">
    <defs><linearGradient id="roadg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="{surface}"/><stop offset="1" stop-color="{surface2}"/>
    </linearGradient></defs>
    <polygon points="510,720 770,720 658,300 622,300" fill="url(#roadg)"/>
    <polygon points="510,720 528,720 636,300 622,300" fill="{shoulder}" opacity="0.45"/>
    <polygon points="752,720 770,720 658,300 644,300" fill="{shoulder}" opacity="0.45"/>
    <g fill="{dash}">
      <polygon points="634,704 646,704 645,660 635,660"/><polygon points="636,626 644,626 643,590 637,590"/>
      <polygon points="637,560 643,560 642,532 638,532"/><polygon points="638,392 642,392 641,368 639,368"/>
      <polygon points="639,352 641,352 641,336 639,336"/>
    </g>
  </g>'''


def track(ballast='#a98c68', ballast_hi='#bb9d76', tie='#6b4a2a', rail='#d3d7dc'):
    ties = ''.join(f'<rect x="{x}" y="452" width="15" height="62"/>' for x in range(6, 1280, 44))
    return f'''  <g id="track">
    <rect x="0" y="450" width="1280" height="66" fill="{ballast}"/>
    <rect x="0" y="450" width="1280" height="8" fill="{ballast_hi}"/>
    <g fill="{tie}">{ties}</g>
    <rect x="0" y="466" width="1280" height="6" fill="{rail}"/>
    <rect x="0" y="496" width="1280" height="6" fill="{rail}"/>
  </g>'''


def _gate_pair(gid, y, scale, arm, post='#2f3136', stripe='#d23b34'):
    def side(x, dirn):
        arm_x = 0 if dirn > 0 else -arm
        blocks = ''.join(
            f'<rect x="{arm_x + 6 + i*28}" y="-5" width="15" height="10" fill="{stripe}"/>'
            for i in range(int(arm // 28)))
        return f'''    <g transform="translate({x},{y}) scale({scale})">
      <rect x="-8" y="0" width="16" height="70" rx="4" fill="{post}"/>
      <g transform="translate(0,-4)" stroke="#ffffff" stroke-width="6" stroke-linecap="round">
        <line x1="-15" y1="-15" x2="15" y2="15"/><line x1="15" y1="-15" x2="-15" y2="15"/></g>
      <circle cx="-13" cy="16" r="6.5" fill="{'#ff2a2a' if dirn > 0 else '#7a1c1c'}"/>
      <circle cx="13" cy="16" r="6.5" fill="{'#7a1c1c' if dirn > 0 else '#ff2a2a'}"/>
      <g transform="translate(0,40)">
        <rect x="{arm_x}" y="-5" width="{arm}" height="10" rx="5" fill="#ffffff"/>{blocks}
      </g>
    </g>'''
    return f'  <g id="{gid}">\n' + side(*GATE_POS[gid][0]) + '\n' + side(*GATE_POS[gid][1]) + '\n  </g>'


# near gate sits below the tracks (bigger, foreground); far gate above (smaller).
GATE_POS = {'gate-near': [(552, 1), (728, -1)], 'gate-far': [(580, 1), (700, -1)]}
gate_near = lambda: _gate_pair('gate-near', 480, 1.2, 76)
gate_far  = lambda: _gate_pair('gate-far', 388, 0.82, 76)

# ================================================================ ASSEMBLY ====

SCENES = {}

def scene(sid, title, layers, defs=''):
    """layers: dict with any of sky, far, mid, ground, water, back, front, fg."""
    g = lambda k: f'  <g id="{k}">\n{layers[k]}\n  </g>' if layers.get(k) else f'  <g id="{k}"/>'
    body = '\n'.join([
        g('sky'), g('far'), g('mid'), g('ground'), g('water'),
        '  <!-- scenery BEHIND the rails: the train passes in front of this -->',
        g('scenery-back'),
        road(**layers.get('roadkw', {})),
        track(**layers.get('trackkw', {})),
        gate_far(),
        '  <!-- ENGINE RENDERS THE MOVING TRAIN HERE (between the two gates) -->',
        '  <!-- foreground props: IN FRONT of the train, bases below the rails -->',
        g('scenery-front'),
        gate_near(),
        g('foreground'),
    ])
    svg = f'''<?xml version="1.0" encoding="UTF-8"?>
<!-- Chuga Chocho — {title}
     Generated by tools/gen-scenes.py. Furniture (road, track, both gates) is shared
     and identical across scenes; only the artwork differs. See SCENE_GUIDE.md.
     Horizon y=300 · track band y=450-516 (kept clear) · train renders between
     #gate-far and #scenery-front. -->
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" id="scene-{sid}">
  <defs>
{defs}
  </defs>
{body}
</svg>
'''
    (OUT / f'{sid}.svg').write_text(svg)
    SCENES[sid] = title
    return svg


# ------------------------------------------------------------- helpers ------

def sky(top, mid, bot, sun=None, sun_col='#fff8dc'):
    d = f'''    <rect x="0" y="0" width="1280" height="320" fill="url(#skyg)"/>'''
    if sun:
        d += f'\n    <circle cx="{sun[0]}" cy="{sun[1]}" r="{sun[2]}" fill="url(#sung)"/>'
    return d

def sky_defs(top, mid, bot, sun_col='#fff8dc', sun_mid='#fff0bd'):
    return f'''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="{top}"/><stop offset="0.62" stop-color="{mid}"/><stop offset="1" stop-color="{bot}"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="{sun_col}" stop-opacity="0.95"/>
      <stop offset="0.55" stop-color="{sun_mid}" stop-opacity="0.45"/>
      <stop offset="1" stop-color="{sun_mid}" stop-opacity="0"/>
    </radialGradient>'''

def grass_defs(top, bot, gid='grassg'):
    return f'''    <linearGradient id="{gid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="{top}"/><stop offset="1" stop-color="{bot}"/>
    </linearGradient>'''

def ground(fill='url(#grassg)', shade=None):
    d = f'    <rect x="0" y="300" width="1280" height="420" fill="{fill}"/>'
    if shade:
        d += (f'\n    <path d="M0,392 Q 240,360 470,388 L470,470 L0,470 Z" fill="{shade}" opacity="0.5"/>'
              f'\n    <path d="M810,388 Q 1050,360 1280,392 L1280,470 L810,470 Z" fill="{shade}" opacity="0.5"/>')
    return d

def clouds(items, fill='#ffffff', op=0.9):
    out = []
    for (cx, cy, rx) in items:
        out.append(f'<g opacity="{op}" fill="{fill}"><ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{rx*0.42:.0f}"/>'
                   f'<ellipse cx="{cx+rx*0.8:.0f}" cy="{cy-rx*0.12:.0f}" rx="{rx*0.72:.0f}" ry="{rx*0.36:.0f}"/>'
                   f'<ellipse cx="{cx-rx*0.75:.0f}" cy="{cy+rx*0.1:.0f}" rx="{rx*0.62:.0f}" ry="{rx*0.32:.0f}"/></g>')
    return '    ' + ''.join(out)

def birds(items, col='#5f7d92'):
    out = ''.join(f'<path d="M{x},{y} q10,-9 20,0 q10,-9 20,0"/>' for (x, y) in items)
    return f'    <g stroke="{col}" stroke-width="3" fill="none" stroke-linecap="round" opacity="0.45">{out}</g>'

def shadow(cx, cy, rx, ry=6, op=0.14):
    return f'<ellipse cx="{cx}" cy="{cy}" rx="{rx}" ry="{ry}" fill="#000" opacity="{op}"/>'

def palm(x, y, s=1.0, trunk='#8a6a45', frond='#2f8f5b', frond2='#3aa76c'):
    return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 26)}'
            f'<path d="M-5,0 C -8,-40 4,-70 10,-96 L18,-94 C 12,-68 2,-38 5,0 Z" fill="{trunk}"/>'
            f'<g fill="{frond}">'
            f'<path d="M14,-96 C -18,-108 -40,-96 -52,-80 C -28,-88 -6,-88 12,-88 Z"/>'
            f'<path d="M14,-96 C 46,-110 70,-98 82,-82 C 58,-90 34,-90 16,-88 Z"/>'
            f'<path d="M14,-96 C 2,-126 -14,-136 -34,-140 C -14,-126 0,-112 8,-92 Z"/></g>'
            f'<g fill="{frond2}">'
            f'<path d="M14,-96 C 30,-126 48,-134 66,-138 C 46,-124 30,-110 20,-92 Z"/>'
            f'<path d="M14,-96 C 40,-88 58,-72 66,-54 C 48,-72 30,-84 14,-88 Z"/></g>'
            f'<circle cx="14" cy="-96" r="5" fill="#6b4a2a"/></g>')

def conifer(x, y, s=1.0, a='#2f6f47', b='#3c8556', c='#4aa168', trunk='#573b22'):
    return (f'<g transform="translate({x},{y}) scale({s})">{shadow(-4, 50, 24, 6, 0.12)}'
            f'<rect x="-5" y="30" width="10" height="20" rx="3" fill="{trunk}"/>'
            f'<polygon points="0,-4 24,32 -24,32" fill="{a}"/>'
            f'<polygon points="0,-4 18,20 -18,20" fill="{b}"/>'
            f'<polygon points="0,-4 12,8 -12,8" fill="{c}"/></g>')

def oak(x, y, s=1.0, canopy='#3f7a4a', canopy2='#4c8f58', trunk='#6b4a2a', moss=None):
    m = ''
    if moss:
        m = ''.join(f'<path d="M{dx},{dy} q3,16 -2,26" stroke="{moss}" stroke-width="3" fill="none" opacity="0.75"/>'
                    for dx, dy in [(-44, -46), (-16, -34), (22, -40), (52, -30)])
    return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 54, 8)}'
            f'<path d="M-8,4 C -10,-30 -22,-44 -30,-56 L-14,-52 C -8,-62 -2,-70 0,-84 '
            f'C 4,-70 10,-62 16,-52 L32,-58 C 22,-44 10,-30 8,4 Z" fill="{trunk}"/>'
            f'<ellipse cx="0" cy="-86" rx="66" ry="34" fill="{canopy}"/>'
            f'<ellipse cx="-34" cy="-72" rx="34" ry="22" fill="{canopy2}"/>'
            f'<ellipse cx="34" cy="-74" rx="32" ry="20" fill="{canopy2}"/>'
            f'<ellipse cx="4" cy="-102" rx="40" ry="22" fill="{canopy2}"/>{m}</g>')

def saguaro(x, y, s=1.0, col='#3f8556', dark='#33714a'):
    return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 24)}'
            f'<rect x="-11" y="-96" width="22" height="100" rx="11" fill="{col}"/>'
            f'<path d="M-11,-56 C -34,-56 -38,-62 -38,-78 L-38,-92" stroke="{col}" stroke-width="17" fill="none" stroke-linecap="round"/>'
            f'<path d="M11,-70 C 30,-70 34,-76 34,-90 L34,-100" stroke="{col}" stroke-width="15" fill="none" stroke-linecap="round"/>'
            f'<g stroke="{dark}" stroke-width="2" opacity="0.8">'
            f'<line x1="-4" y1="-92" x2="-4" y2="0"/><line x1="4" y1="-92" x2="4" y2="0"/></g></g>')

print('helpers ready')


# ============================================================ 1. SAN FRANCISCO
def sf():
    """Composed like the New York scene: a wide bay with the Golden Gate spanning it,
    city on both sides, a green waterfront park along the shore, and a dense row of
    Painted Ladies right up against the street and the tracks."""
    d = (sky_defs('#8fb8d4', '#c3d9e6', '#e8eff1', '#fff6e0', '#ffeecc') + '''
    <linearGradient id="bay" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#4f86ab"/><stop offset="1" stop-color="#79aecb"/>
    </linearGradient>
    <linearGradient id="asphalt" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#8b8e94"/><stop offset="1" stop-color="#727579"/>
    </linearGradient>
    <linearGradient id="park" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#6fa055"/><stop offset="1" stop-color="#5a8845"/>
    </linearGradient>''')

    # ---- Marin headlands behind, then the city on both sides ----
    headlands = ('    <polygon points="-20,254 90,196 210,226 330,190 430,222 520,206 600,232 700,208 '
                 '820,230 940,202 1060,228 1180,198 1300,226 1300,254" fill="#b6a882"/>\n'
                 '    <polygon points="-20,254 90,196 210,226 300,254" fill="#a1946f" opacity="0.45"/>')
    def block(x, y, w, h, base='#8695a6', lit='#98a6b6', win='#cfe4ee', step=13):
        wins = ''.join(f'<rect x="{x+4}" y="{y+9+r*step}" width="{w-8}" height="4"/>'
                       for r in range(int((h - 16) // step)))
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="1.5" fill="{base}"/>'
                f'<rect x="{x}" y="{y}" width="{w*0.3:.0f}" height="{h}" fill="{lit}"/>'
                f'<g fill="{win}" opacity="0.55">{wins}</g>')
    T = [(30,206,24,86),(58,182,20,110),(82,220,26,72),(112,196,18,96),
         (1080,208,24,84),(1108,186,20,106),(1132,222,26,70),(1162,200,18,92),
         (1186,228,24,64),(1214,196,20,96),(1240,216,26,76)]
    city = '    <g>' + ''.join(block(*t) for t in T) + '</g>'

    # ---- the bay: wide, like New York's river ----
    bay = ('    <rect x="0" y="244" width="1280" height="50" fill="url(#bay)"/>\n'
           '    <g fill="#ffffff" opacity="0.3">'
           + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2.5" rx="1"/>'
                     for x, y, w in [(120, 262, 70), (360, 278, 90), (620, 256, 66),
                                     (840, 282, 84), (1080, 266, 74), (240, 286, 60)]) + '</g>'
            # a sailboat and a ferry, because the bay is always busy
            '<g transform="translate(430,290)"><path d="M0,-34 L0,-2 L-20,-2 Z" fill="#f6f1e4"/>'
            '<path d="M3,-30 L16,-2 L3,-2 Z" fill="#dfe8ee"/>'
            '<path d="M-24,-2 L24,-2 L18,4 L-18,4 Z" fill="#2f3a44"/></g>'
            '<g transform="translate(880,288)"><rect x="-30" y="-12" width="60" height="9" rx="2" fill="#e8edf0"/>'
            '<rect x="-22" y="-20" width="44" height="8" rx="2" fill="#f4f7f9"/>'
            '<rect x="-4" y="-28" width="5" height="9" fill="#41474f"/></g>')

    # ---- the Golden Gate, spanning the whole bay ----
    def gg_tower(x):
        return (f'<g><rect x="{x-24}" y="122" width="15" height="130" fill="#c0442a"/>'
                f'<rect x="{x+9}" y="122" width="15" height="130" fill="#a5391f"/>'
                f'<rect x="{x-29}" y="112" width="58" height="11" rx="3" fill="#d2552f"/>'
                f'<rect x="{x-21}" y="96" width="42" height="13" rx="3" fill="#c0442a"/>'
                f'<rect x="{x-13}" y="84" width="26" height="11" rx="3" fill="#d2552f"/>'
                f'<g fill="#c0442a"><rect x="{x-24}" y="158" width="48" height="9"/>'
                f'<rect x="{x-24}" y="200" width="48" height="9"/></g></g>')
    def cable_y(x):
        if 330 <= x <= 950:
            t = (x - 640) / 310.0
            return 122 + (232 - 122) * (1 - t * t)
        if x < 330:
            t = (330 - x) / 300.0
            return 122 + (246 - 122) * min(1.0, t * t)
        t = (x - 950) / 300.0
        return 122 + (246 - 122) * min(1.0, t * t)
    susp = ''.join(f'<line x1="{x}" y1="{cable_y(x):.0f}" x2="{x}" y2="248"/>' for x in range(40, 1256, 24))
    bridge = ('    <g id="goldengate">'
              '<path d="M30,246 Q 180,250 330,122" fill="none" stroke="#c0442a" stroke-width="4.5"/>'
              '<path d="M330,122 Q 640,344 950,122" fill="none" stroke="#c0442a" stroke-width="4.5"/>'
              '<path d="M950,122 Q 1100,250 1250,246" fill="none" stroke="#c0442a" stroke-width="4.5"/>'
              f'<g stroke="#c0442a" stroke-width="1.8" opacity="0.85">{susp}</g>'
              '<rect x="0" y="244" width="1280" height="10" fill="#d2552f"/>'
              '<rect x="0" y="252" width="1280" height="4" fill="#a5391f"/>'
              + gg_tower(330) + gg_tower(950) + '</g>')
    fog = ('    <g fill="#ffffff"><ellipse cx="240" cy="240" rx="280" ry="12" opacity="0.3"/>'
           '<ellipse cx="1020" cy="234" rx="300" ry="11" opacity="0.26"/>'
           '<rect x="0" y="286" width="1280" height="10" opacity="0.16"/></g>')

    # ---- the waterfront: seawall, promenade, then a green park (Marina Green) ----
    shore = ('    <rect x="0" y="292" width="1280" height="4" fill="#8d8f95"/>'
             '<rect x="0" y="296" width="1280" height="10" fill="#b7bac0"/>'
             '<g fill="#9da1a8" opacity="0.6">'
             + ''.join(f'<rect x="{x}" y="296" width="2" height="10"/>' for x in range(0, 1280, 32)) + '</g>'
             + ''.join(f'<g transform="translate({x},292)"><rect x="-3" y="-22" width="6" height="22" fill="#2f333a"/>'
                       f'<circle cx="0" cy="-25" r="4" fill="#ffe9a8"/></g>' for x in range(50, 1280, 110)))

    # ---- MANY Painted Ladies, right up against the street and the tracks ----
    def lady(x, y, s, body, trim, roof):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-42" y="-150" width="84" height="150" fill="{body}"/>'
                f'<rect x="-46" y="-158" width="92" height="10" rx="2" fill="{trim}"/>'
                f'<polygon points="-48,-158 0,-196 48,-158" fill="{roof}"/>'
                f'<polygon points="-16,-176 0,-190 16,-176 16,-158 -16,-158" fill="{trim}"/>'
                f'<rect x="-8" y="-174" width="16" height="16" rx="7" fill="#dff0f6"/>'
                + ''.join(f'<rect x="{-34+c*36}" y="{-140+r*46}" width="30" height="34" rx="2" fill="{trim}"/>'
                          f'<rect x="{-30+c*36}" y="{-136+r*46}" width="22" height="26" rx="2" fill="#dff0f6"/>'
                          for r in range(2) for c in range(2))
                + f'<rect x="-14" y="-46" width="28" height="46" rx="2" fill="{trim}"/>'
                f'<rect x="-10" y="-42" width="20" height="34" rx="2" fill="{roof}"/>'
                f'<g stroke="{trim}" stroke-width="3" fill="none"><path d="M-26,0 L-26,-22 L26,-22 L26,0"/></g>'
                f'<g fill="{trim}"><rect x="-46" y="-104" width="92" height="5"/>'
                f'<rect x="-46" y="-56" width="92" height="5"/></g></g>')
    PAL = [('#f0d5b0', '#f8f4ec', '#8f6a52'), ('#cfd9ea', '#f8f4ec', '#5d6f8a'),
           ('#f2c7c4', '#f8f4ec', '#8a5248'), ('#d8e6cc', '#f8f4ec', '#5f7a5c'),
           ('#f6e3b8', '#f8f4ec', '#8f7452'), ('#e0d2e8', '#f8f4ec', '#6d5f8a'),
           ('#f4d3c2', '#f8f4ec', '#8a6248'), ('#cfe3e6', '#f8f4ec', '#5a7c82')]
    ladies = '    ' + ''.join(lady(52 + i * 92, 448, 0.5, *PAL[i % 8]) for i in range(6)) \
             + ''.join(lady(742 + i * 92, 448, 0.5, *PAL[(i + 3) % 8]) for i in range(6))

    # ---- park band along the shore, then the city street ----
    street = ('    <rect x="0" y="306" width="1280" height="60" fill="url(#park)"/>\n'
              '    <rect x="0" y="306" width="1280" height="6" fill="#7cae5f"/>\n'
              '    <g fill="#79a862" opacity="0.6">'
              + ''.join(f'<ellipse cx="{x}" cy="352" rx="46" ry="10"/>' for x in range(60, 1280, 190)) + '</g>\n'
              '    <rect x="0" y="366" width="1280" height="354" fill="url(#asphalt)"/>\n'
              '    <g fill="#b7bac0"><rect x="0" y="404" width="1280" height="32"/>'
              '<rect x="0" y="560" width="1280" height="42"/></g>\n'
              '    <g fill="#c9ccd2"><rect x="0" y="404" width="1280" height="5"/>'
              '<rect x="0" y="560" width="1280" height="5"/></g>\n'
              '    <g fill="#9da1a8" opacity="0.7">'
              + ''.join(f'<rect x="{x}" y="409" width="2.5" height="27"/>' for x in range(0, 1280, 40))
              + ''.join(f'<rect x="{x}" y="565" width="2.5" height="37"/>' for x in range(18, 1280, 40)) + '</g>\n'
              '    <g fill="#6d7076"><rect x="0" y="436" width="1280" height="5"/>'
              '<rect x="0" y="602" width="1280" height="5"/></g>\n'
              '    <rect x="0" y="622" width="1280" height="44" fill="#5f8f4c"/>\n'
              '    <rect x="0" y="622" width="1280" height="5" fill="#6fa059"/>\n'
              '    <g fill="#e8e2c9" opacity="0.4">'
              + ''.join(f'<rect x="{x}" y="382" width="24" height="4"/>' for x in range(0, 1280, 60)) + '</g>')

    def bike(x, y, s=1.0, col='#3d7bd6'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 26)}'
                f'<g fill="none" stroke="#2f333a" stroke-width="3">'
                f'<circle cx="-18" cy="-12" r="12"/><circle cx="18" cy="-12" r="12"/></g>'
                f'<g stroke="{col}" stroke-width="3.5" fill="none" stroke-linecap="round">'
                f'<path d="M-18,-12 L-2,-12 L8,-30 L18,-12 M-2,-12 L6,-30 M8,-30 L-4,-30"/></g>'
                f'<path d="M18,-12 L22,-32 L14,-34" stroke="{col}" stroke-width="3" fill="none"/></g>')

    back = ('    ' + ladies
            + ''.join(f'<g transform="translate({x},446)"><rect x="-3" y="-52" width="6" height="52" fill="#2f333a"/>'
                      f'<circle cx="0" cy="-56" r="7" fill="#ffe9a8"/></g>' for x in (600, 690))
            + ''.join(conifer(x, 330, 0.42, '#2c5f46', '#376f53', '#43815f') for x in (170, 430, 900, 1150))
            + ''.join(palm(x, 348, 0.36) for x in (300, 780, 1030)))

    front = ('    ' + conifer(64, 646, 1.55, '#2c5f46', '#376f53', '#43815f')
             + conifer(1228, 662, 1.45, '#2c5f46', '#376f53', '#43815f')
             + bike(300, 692, 1.25, '#c0392b') + bike(392, 702, 1.15, '#3d7bd6')
             + bike(980, 688, 1.2, '#f2b134')
             + ''.join(f'<g transform="translate({x},{y})">'
                       f'<rect x="-3" y="-72" width="7" height="72" fill="#2f333a"/>'
                       f'<circle cx="0" cy="-78" r="9" fill="#ffe9a8"/>'
                       f'<rect x="-9" y="-4" width="19" height="6" rx="2" fill="#2f333a"/></g>'
                       for x, y in [(180, 648), (806, 670), (886, 630)])
             + f'<g transform="translate(1100,700)">{shadow(0, 6, 44, 8)}'
             '<rect x="-42" y="-14" width="84" height="9" rx="3" fill="#4f6b3f"/>'
             '<rect x="-42" y="-30" width="84" height="8" rx="3" fill="#5d7d4a"/>'
             '<rect x="-36" y="-6" width="8" height="18" fill="#2f333a"/>'
             '<rect x="28" y="-6" width="8" height="18" fill="#2f333a"/></g>')

    scene('sf', 'SAN FRANCISCO — the bay under the Golden Gate, waterfront park, Painted Ladies', {
        'sky': sky('', '', '', sun=(1080, 92, 150)) + '\n' + clouds([(250, 88, 52), (700, 66, 42)], op=0.65)
               + '\n' + birds([(540, 130), (588, 154)]),
        'far': headlands + '\n' + city + '\n' + bay + '\n' + bridge + '\n' + fog + '\n' + shore,
        'ground': street,
        'scenery-back': back, 'scenery-front': front,
        'foreground': '    <g fill="#82858b" opacity="0.5"><rect x="0" y="706" width="1280" height="3"/></g>',
    }, d)


# ============================================================== 2. LOS ANGELES
def la():
    """LA is the BEACH. The Pacific runs the whole width behind the scene, the sand
    is the ground, and the life on it — volleyball, Muscle Beach, surfboards — is the
    subject. The hills with HOLLYWOOD and a few glass houses sit off to the left as
    supporting texture. No downtown: one hero, not a souvenir shelf."""
    d = (sky_defs('#4fa8dc', '#9ed3ea', '#ffd9a8', '#fff4d2', '#ffd18a') + '''
    <linearGradient id="sand" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#f0e0ba"/><stop offset="1" stop-color="#dcc796"/>
    </linearGradient>
    <linearGradient id="ocean" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#2b7fb5"/><stop offset="1" stop-color="#5cbcd8"/>
    </linearGradient>''')

    # ---- the Pacific: full width, the whole back of the picture ----
    waves = ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2.5" rx="1"/>'
                    for x, y, w in [(60, 254, 54), (150, 272, 70), (300, 246, 48),
                                    (392, 266, 84), (520, 252, 60), (640, 278, 92),
                                    (760, 244, 56), (846, 268, 78), (960, 256, 66),
                                    (1046, 282, 96), (1150, 260, 62), (1216, 276, 54),
                                    (240, 286, 66), (560, 240, 44), (1000, 240, 50),
                                    (700, 290, 74), (120, 240, 40), (890, 250, 52)])

    def sailboat(x, y, s=1.0, sail='#fdfbf4'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<path d="M-11,0 L11,0 L7,5 L-7,5 Z" fill="#e8e2d4"/>'
                f'<rect x="-0.8" y="-26" width="1.6" height="26" fill="#8a7f6c"/>'
                f'<path d="M0,-25 L0,-3 L-13,-3 Z" fill="{sail}"/>'
                f'<path d="M1.6,-22 L1.6,-3 L11,-3 Z" fill="#e6dfcd"/></g>')

    def surfer(x, y, s=1.0, col='#e8574a'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g fill="#ffffff" opacity="0.7"><ellipse cx="0" cy="2" rx="18" ry="2"/></g>'
                f'<ellipse cx="0" cy="0" rx="13" ry="2.6" fill="{col}"/>'
                f'<rect x="-1.6" y="-6" width="3.2" height="6" fill="#2f3a44"/>'
                f'<circle cx="0" cy="-8" r="3" fill="#c98d5e"/></g>')

    ocean = ('    <rect x="0" y="234" width="1280" height="60" fill="url(#ocean)"/>\n'
             '    <rect x="0" y="234" width="1280" height="5" fill="#1c6694" opacity="0.6"/>\n'
             '    <g fill="#ffffff" opacity="0.4">' + waves + '</g>\n'
             # a long low pier off to the right — beach furniture, not a landmark
             '    <g opacity="0.9">'
             + ''.join(f'<rect x="{x}" y="258" width="4" height="30" fill="#8a6a52"/>'
                       for x in range(1004, 1280, 24))
             + '<rect x="996" y="252" width="290" height="7" rx="2" fill="#b08c66"/>'
             '<rect x="996" y="250" width="290" height="3" rx="1.5" fill="#c9a37a"/>'
             '<rect x="1084" y="234" width="40" height="16" rx="2" fill="#f4efe2"/>'
             '<polygon points="1080,234 1104,224 1128,234" fill="#e8574a"/></g>\n'
             '    ' + sailboat(430, 262, 0.9) + sailboat(700, 250, 0.7)
             + sailboat(880, 272, 1.0, '#ffe9c2') + '\n'
             '    ' + surfer(560, 286, 0.85) + surfer(792, 292, 0.95, '#f2b134')
             + surfer(628, 284, 0.75, '#4fb8d6'))

    # ---- shoreline: WET SAND sits behind the road's vanishing point ----
    shore = ('    <path d="M0,290 Q 180,300 380,294 T 760,296 T 1120,292 T 1280,296 L1280,318 L0,318 Z" '
             'fill="#c9bb96"/>\n'
             '    <g fill="#ffffff" opacity="0.9">'
             '<path d="M0,288 Q 180,298 380,292 T 760,294 T 1120,290 T 1280,294 L1280,300 '
             'Q 1120,296 760,300 T 380,298 T 0,294 Z"/></g>\n'
             '    <g fill="#ffffff" opacity="0.55">'
             '<path d="M0,304 Q 240,312 520,306 T 1010,308 T 1280,304 L1280,309 '
             'Q 1010,313 520,311 T 0,309 Z"/></g>')

    # ---- hills on the left: HOLLYWOOD + the glass houses, kept in their corner ----
    hills = ('    <polygon points="-20,300 46,182 168,220 300,158 418,206 520,246 586,300" fill="#b89a6c"/>\n'
             '    <polygon points="300,158 418,206 380,300 268,300" fill="#a98a5c" opacity="0.35"/>\n'
             '    <polygon points="-20,300 30,226 140,254 258,208 372,244 476,270 532,300" fill="#c9a878"/>\n'
             '    <polygon points="-20,300 30,226 140,254 196,300" fill="#ae8d61" opacity="0.5"/>\n'
             '    <g stroke="#a8874f" stroke-width="3" opacity="0.28" fill="none">'
             '<path d="M258,218 l-30,58"/><path d="M30,238 l-22,48"/><path d="M372,252 l-26,44"/>'
             '<path d="M140,264 l-18,36"/></g>\n'
             '    <g fill="#7f9d5e" opacity="0.5">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.6:.0f}"/>'
                       for x, y, r in [(64, 262, 13), (168, 276, 11), (300, 238, 12), (232, 226, 10),
                                       (392, 264, 11), (452, 284, 12), (118, 292, 10), (508, 292, 9)])
             + '</g>')
    sign = ('    <g id="hollywood" transform="rotate(-5 306 196)">'
            '<g fill="#b9b3a2" opacity="0.45">'
            + ''.join(f'<rect x="{240 + i*16}" y="197" width="3" height="13"/>' for i in range(10))
            + '</g>'
            '<text x="306" y="196" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
            'font-weight="bold" font-size="20" letter-spacing="2" fill="#fbf9f2" '
            'stroke="#cfc9bb" stroke-width="0.7">HOLLYWOOD</text></g>')

    def mansion(x, y, s, body='#f6f1e6', roof='#e0d7c8', glass='#a9d6ea'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-56" y="-30" width="112" height="30" fill="{body}"/>'
                f'<rect x="-60" y="-34" width="120" height="6" rx="2" fill="{roof}"/>'
                f'<rect x="-38" y="-58" width="76" height="26" fill="{body}"/>'
                f'<rect x="-42" y="-62" width="84" height="6" rx="2" fill="{roof}"/>'
                f'<rect x="-34" y="-54" width="66" height="17" rx="2" fill="{glass}"/>'
                f'<rect x="-50" y="-25" width="44" height="19" rx="2" fill="{glass}"/>'
                f'<rect x="2" y="-25" width="30" height="19" rx="2" fill="{glass}"/>'
                f'<rect x="-62" y="0" width="124" height="7" rx="2" fill="#e6ded0"/>'
                f'<rect x="-40" y="1" width="58" height="5" rx="2" fill="#5fc2dd"/>'
                f'<g fill="#3f8556"><ellipse cx="-56" cy="-2" rx="9" ry="6"/>'
                f'<ellipse cx="52" cy="-2" rx="8" ry="5"/></g></g>')
    mansions = ('    ' + mansion(76, 260, 0.66) + mansion(190, 284, 0.58, '#fbf6ea')
                + mansion(300, 252, 0.62, '#f2ece0') + mansion(412, 280, 0.54)
                + mansion(496, 296, 0.46, '#fbf6ea'))

    # ---- ground: sand, bike path, sand ripples ----
    beach = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#sand)"/>\n'
             + shore + '\n'
             # the Marvin Braude bike path
             '    <rect x="0" y="396" width="1280" height="34" fill="#dfd6c2"/>\n'
             '    <rect x="0" y="396" width="1280" height="4" fill="#ece4d3"/>\n'
             '    <g fill="#f2e6a8" opacity="0.75">'
             + ''.join(f'<rect x="{x}" y="411" width="26" height="3"/>' for x in range(0, 1280, 62))
             + '</g>\n'
             '    <rect x="0" y="428" width="1280" height="3" fill="#cbbfa8" opacity="0.6"/>\n'
             # wind-blown sand ripples
             '    <g stroke="#d3c096" stroke-width="3" fill="none" opacity="0.45">'
             + ''.join(f'<path d="M{x},{y} q 46,-7 92,0"/>'
                       for x, y in [(40, 552), (300, 588), (620, 566), (900, 600),
                                    (1120, 560), (170, 660), (760, 668), (1010, 700)])
             + '</g>')

    # ---------------------------------------------------------------- people --
    def person(x, y, s=1.0, suit='#e8574a', skin='#c98d5e', hair='#33241c',
               arms='up', lean=0):
        A = {'up':   'M-6,-31 L-15,-49 M6,-31 L15,-49',
             'out':  'M-6,-30 L-19,-24 M6,-30 L19,-24',
             'down': 'M-6,-30 L-11,-13 M6,-30 L11,-13',
             'dig':  'M-6,-29 L-3,-16 M6,-29 L3,-16',
             'wave': 'M-6,-30 L-12,-14 M6,-31 L16,-48'}[arms]
        return (f'<g transform="translate({x},{y}) rotate({lean}) scale({s})">{shadow(0, 2, 13, 3.5)}'
                f'<g stroke="{skin}" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-15 L-5,-1 M3,-15 L6,-1"/><path d="{A}"/></g>'
                f'<rect x="-7" y="-33" width="14" height="20" rx="6" fill="{suit}"/>'
                f'<circle cx="0" cy="-40" r="6.5" fill="{skin}"/>'
                f'<path d="M-6.5,-42 a6.5,6.5 0 0 1 13,0 z" fill="{hair}"/></g>')

    def towel(x, y, s=1.0, col='#e8574a', suit='#4fb8d6'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(2, 7, 34, 5, 0.1)}'
                f'<rect x="-31" y="-5" width="62" height="13" rx="2" fill="{col}"/>'
                f'<rect x="-31" y="-5" width="62" height="3.5" rx="1.7" fill="#ffffff" opacity="0.4"/>'
                f'<rect x="-21" y="-12" width="36" height="9" rx="4.5" fill="{suit}"/>'
                f'<circle cx="20" cy="-10" r="5.5" fill="#c98d5e"/>'
                f'<path d="M14.5,-12 a5.5,5.5 0 0 1 11,0 z" fill="#33241c"/></g>')

    def chair(x, y, s=1.0, col='#4fb8d6', frame='#e6dfcd'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 22, 4)}'
                f'<g stroke="{frame}" stroke-width="3.5" stroke-linecap="round" fill="none">'
                f'<path d="M-18,0 L-6,-16 M16,0 L6,-16 M-6,-16 L18,-16"/></g>'
                f'<path d="M-20,-16 L-2,-16 L4,-40 L-10,-40 Z" fill="{col}"/>'
                f'<rect x="-4" y="-19" width="24" height="7" rx="3" fill="{col}"/></g>')

    def kite(hx, hy, kx, ky, col='#e8574a', col2='#f2b134'):
        tail = ''.join(f'<circle cx="{kx + 5 + i*4}" cy="{ky + 22 + i*13}" r="3.2" '
                       f'fill="{col2 if i % 2 else col}"/>' for i in range(4))
        return (f'<path d="M{hx},{hy} Q {(hx+kx)/2 + 26:.0f},{(hy+ky)/2:.0f} {kx},{ky+14}" '
                f'stroke="#efe7d4" stroke-width="1.4" fill="none" opacity="0.8"/>'
                f'<g transform="translate({kx},{ky})">'
                f'<polygon points="0,-16 13,0 0,16 -13,0" fill="{col}"/>'
                f'<polygon points="0,-16 13,0 0,0" fill="{col2}"/>'
                f'<polygon points="0,0 0,16 -13,0" fill="{col2}"/>'
                f'<path d="M0,-16 L0,16 M-13,0 L13,0" stroke="#ffffff" stroke-width="1" opacity="0.6"/></g>'
                f'{tail}')

    def volleyball(x, y, s=1.0):
        mesh = (''.join(f'<line x1="{v}" y1="-86" x2="{v}" y2="-46"/>' for v in range(-84, 85, 12))
                + ''.join(f'<line x1="-86" y1="{h}" x2="86" y2="{h}"/>' for h in range(-84, -45, 10)))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="0" cy="4" rx="196" ry="30" fill="#ecdcb2" opacity="0.75"/>'
                f'<g stroke="#d8c69a" stroke-width="2.5" fill="none" opacity="0.9">'
                f'<ellipse cx="0" cy="4" rx="190" ry="27"/></g>'
                f'<g stroke="#ffffff" stroke-width="1" opacity="0.5">{mesh}</g>'
                f'<rect x="-86" y="-90" width="172" height="7" rx="3" fill="#fbf9f2"/>'
                f'<rect x="-86" y="-48" width="172" height="4" rx="2" fill="#efece0"/>'
                f'<g fill="#5e6a74"><rect x="-92" y="-92" width="7" height="94" rx="3"/>'
                f'<rect x="85" y="-92" width="7" height="94" rx="3"/></g>'
                f'{shadow(-88, 4, 12, 4)}{shadow(88, 4, 12, 4)}'
                # ball in the air over the net
                f'<g transform="translate(6,-124)">'
                f'<circle cx="0" cy="0" r="11" fill="#fbf9f2"/>'
                f'<g stroke="#e8574a" stroke-width="2" fill="none">'
                f'<path d="M-10,-4 q10,-6 20,0"/><path d="M-7,6 q7,5 14,0"/>'
                f'<path d="M-2,-11 q-5,11 0,22"/></g></g>'
                + person(-140, 6, 1.0, '#f2b134', arms='up', lean=-6)
                + person(-52, 4, 0.92, '#4fb8d6', arms='dig')
                + person(56, 4, 0.96, '#e8574a', arms='up', lean=5)
                + person(146, 6, 0.9, '#7bc86c', arms='out') + '</g>')

    def gym(x, y, s=1.0, steel='#3f7fae', steel2='#2f6b96'):
        rings = ''.join(f'<g><line x1="{rx}" y1="-116" x2="{rx}" y2="-74" stroke="#d8cfba" stroke-width="2.5"/>'
                        f'<circle cx="{rx}" cy="-68" r="7" fill="none" stroke="#8a6a45" stroke-width="4"/></g>'
                        for rx in (30, 56))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="10" cy="4" rx="188" ry="26" fill="#e6d4aa" opacity="0.7"/>'
                # frame
                f'{shadow(-96, 4, 12, 4)}{shadow(84, 4, 12, 4)}'
                f'<g fill="{steel}"><rect x="-102" y="-120" width="11" height="124" rx="4"/>'
                f'<rect x="79" y="-120" width="11" height="124" rx="4"/></g>'
                f'<rect x="-104" y="-124" width="196" height="10" rx="5" fill="{steel2}"/>'
                f'<rect x="-104" y="-124" width="196" height="4" rx="2" fill="#5b9cc6"/>'
                # low bar
                f'<rect x="-102" y="-62" width="70" height="8" rx="4" fill="{steel2}"/>'
                f'{rings}'
                # pull-up figure hanging from the top bar
                f'<g transform="translate(-24,0)">'
                f'<g stroke="#c98d5e" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-9,-92 L-13,-116 M9,-92 L13,-116"/>'
                f'<path d="M-4,-64 L-7,-44 M4,-64 L8,-46"/></g>'
                f'<rect x="-10" y="-95" width="20" height="30" rx="7" fill="#f2b134"/>'
                f'<circle cx="0" cy="-102" r="7" fill="#c98d5e"/>'
                f'<path d="M-7,-104 a7,7 0 0 1 14,0 z" fill="#33241c"/></g>'
                # bench press to the right
                f'<g transform="translate(150,0)">'
                f'{shadow(0, 4, 46, 7)}'
                f'<g fill="#4f5a64"><rect x="-40" y="-26" width="8" height="26" rx="3"/>'
                f'<rect x="30" y="-26" width="8" height="26" rx="3"/></g>'
                f'<rect x="-46" y="-34" width="92" height="9" rx="4" fill="#8f4f3f"/>'
                f'<rect x="-46" y="-34" width="92" height="3" rx="1.5" fill="#a3604d"/>'
                # lifter lying on the bench
                f'<g stroke="#c98d5e" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-14,-40 L-16,-58 M6,-40 L4,-58"/>'
                f'<path d="M30,-38 L46,-30 M30,-42 L48,-44"/></g>'
                f'<rect x="-18" y="-46" width="46" height="14" rx="7" fill="#4fb8d6"/>'
                f'<circle cx="-27" cy="-40" r="7" fill="#c98d5e"/>'
                f'<path d="M-34,-42 a7,7 0 0 1 14,0 z" fill="#33241c"/>'
                # barbell
                f'<rect x="-34" y="-62" width="76" height="4" rx="2" fill="#9aa2ab"/>'
                f'<g fill="#2f3a44"><rect x="-38" y="-72" width="9" height="24" rx="3"/>'
                f'<rect x="40" y="-72" width="9" height="24" rx="3"/></g></g>'
                # standing figure pressing a dumbbell overhead
                f'<g transform="translate(-150,0)">' + person(0, 0, 1.05, '#7bc86c', arms='up')
                + f'<g fill="#2f3a44"><rect x="-26" y="-58" width="8" height="16" rx="3"/>'
                f'<rect x="18" y="-58" width="8" height="16" rx="3"/></g>'
                f'<rect x="-20" y="-52" width="40" height="3.5" rx="1.7" fill="#9aa2ab"/></g>'
                # MUSCLE BEACH lettering on the frame
                f'<g transform="translate(-6,-142)">'
                f'<rect x="-84" y="-19" width="168" height="26" rx="5" fill="#fbf6e6"/>'
                f'<rect x="-84" y="-19" width="168" height="6" rx="3" fill="{steel}"/>'
                f'<text x="0" y="2" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
                f'font-weight="bold" font-size="15" letter-spacing="1.5" fill="{steel2}"'
                f'>MUSCLE BEACH</text></g></g>')

    def lifeguard(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 6, 46, 8)}'
                f'<g stroke="#8a6a52" stroke-width="7" stroke-linecap="round">'
                f'<path d="M-30,4 L-20,-40"/><path d="M30,4 L20,-40"/></g>'
                f'<rect x="-34" y="-72" width="68" height="34" rx="4" fill="#f2ede0"/>'
                f'<rect x="-34" y="-72" width="68" height="10" rx="4" fill="#e8574a"/>'
                f'<rect x="-26" y="-58" width="24" height="16" rx="2" fill="#a9d6ea"/>'
                f'<rect x="4" y="-58" width="22" height="16" rx="2" fill="#a9d6ea"/>'
                f'<polygon points="-40,-72 0,-90 40,-72" fill="#e8574a"/>'
                f'<rect x="-36" y="-40" width="72" height="5" rx="2" fill="#d9cfbc"/>'
                f'<path d="M-20,-36 L-28,4" stroke="#d9cfbc" stroke-width="4"/></g>')

    def umbrella(x, y, s=1.0, a='#e8574a', b='#f6f1e4'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 26)}'
                f'<rect x="-2" y="-42" width="4" height="42" fill="#a89880"/>'
                f'<path d="M-34,-40 A34,20 0 0 1 34,-40 Z" fill="{a}"/>'
                f'<path d="M-34,-40 A34,20 0 0 1 -12,-40 Z" fill="{b}"/>'
                f'<path d="M0,-40 A34,20 0 0 1 22,-40 Z" fill="{b}"/></g>')

    def surfboard(x, y, s=1.0, col='#f2b134'):
        return (f'<g transform="translate({x},{y}) rotate(-12) scale({s})">{shadow(4, 6, 14)}'
                f'<rect x="-9" y="-76" width="18" height="80" rx="9" fill="{col}"/>'
                f'<rect x="-2" y="-72" width="4" height="72" rx="2" fill="#ffffff" opacity="0.6"/></g>')

    # ---- behind the rails: the far strip of beach and the bike path ----
    back = ('    ' + lifeguard(176, 398, 0.66) + lifeguard(1030, 396, 0.6)
            + palm(88, 396, 0.6) + palm(408, 392, 0.52) + palm(1148, 398, 0.62)
            + umbrella(300, 380, 0.58, '#4fb8d6') + umbrella(352, 384, 0.52, '#f2b134')
            + umbrella(860, 382, 0.58, '#e8574a') + umbrella(918, 378, 0.5, '#7bc86c')
            + umbrella(120, 348, 0.44, '#f2b134') + umbrella(1206, 352, 0.46, '#4fb8d6')
            # towels and sunbathers scattered up the beach
            + ''.join(towel(x, y, sc, c1, c2) for x, y, sc, c1, c2 in
                      [(132, 372, 0.62, '#e8574a', '#4fb8d6'), (238, 386, 0.68, '#f2b134', '#e8574a'),
                       (466, 376, 0.62, '#7bc86c', '#f2b134'), (546, 392, 0.7, '#4fb8d6', '#e8574a'),
                       (716, 374, 0.62, '#e8574a', '#7bc86c'), (772, 390, 0.7, '#f2b134', '#4fb8d6'),
                       (988, 366, 0.58, '#7bc86c', '#e8574a'), (1092, 384, 0.66, '#4fb8d6', '#f2b134'),
                       (62, 340, 0.5, '#7bc86c', '#e8574a'), (1238, 344, 0.5, '#e8574a', '#f2b134')])
            + person(258, 386, 0.5, '#e8574a', arms='out')
            + person(806, 384, 0.48, '#4fb8d6', arms='wave')
            + person(960, 388, 0.5, '#f2b134', arms='down')
            + person(392, 344, 0.4, '#7bc86c', arms='up')
            + person(430, 346, 0.38, '#4fb8d6', arms='out')
            # a kid flying a kite out over the water
            + f'<g>' + person(1148, 344, 0.44, '#e8574a', arms='up')
            + kite(1142, 326, 1042, 168) + '</g>'
            # cyclists on the bike path
            + ''.join(f'<g transform="translate({x},426) scale(0.62)">{shadow(0, 3, 26, 4)}'
                      f'<g stroke="#2f3a44" stroke-width="3" fill="none">'
                      f'<circle cx="-18" cy="-8" r="9"/><circle cx="18" cy="-8" r="9"/>'
                      f'<path d="M-18,-8 L0,-28 L18,-8 M0,-28 L-6,-8 M0,-28 L10,-30"/></g>'
                      + person(0, -26, 0.62, c, arms='out') + '</g>'
                      for x, c in [(508, '#7bc86c'), (1102, '#e8574a'), (206, '#f2b134')]))

    # ---- in front of the train: the life of the beach ----
    front = ('    ' + palm(44, 716, 1.45) + palm(1254, 712, 1.5) + palm(178, 626, 0.9)
             + volleyball(300, 684, 0.88)
             + chair(452, 700, 1.15, '#e8574a') + chair(492, 712, 1.2, '#f2b134')
             + surfboard(414, 716, 0.95, '#4fb8d6')
             + person(796, 710, 1.15, '#4fb8d6', arms='wave')
             + f'<g transform="translate(852,706)">{shadow(0, 3, 14, 4)}'
             '<circle cx="0" cy="-11" r="11" fill="#fbf9f2"/>'
             '<g stroke="#4fb8d6" stroke-width="2" fill="none">'
             '<path d="M-10,-15 q10,-6 20,0"/><path d="M-7,-5 q7,5 14,0"/>'
             '<path d="M-2,-22 q-5,11 0,22"/></g></g>'
             + surfboard(886, 714, 1.0, '#e8574a')
             + gym(1012, 700, 0.9)
             + umbrella(104, 618, 0.95, '#e8574a') + towel(196, 630, 0.88, '#4fb8d6', '#f2b134')
             + umbrella(1216, 612, 0.92, '#7bc86c')
             + towel(404, 566, 0.74, '#f2b134', '#7bc86c') + chair(336, 574, 0.82, '#7bc86c')
             + towel(866, 558, 0.74, '#4fb8d6', '#e8574a') + chair(792, 570, 0.84, '#e8574a')
             # footprint trails wandering down the sand
             + '<g fill="#cdb98d" opacity="0.55">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="5" ry="3.2" transform="rotate(-14 {x} {y})"/>'
                       for i, (x, y) in enumerate(
                           [(150 + i * 17, 690 - i * 13) for i in range(9)]
                           + [(1150 - i * 15, 700 - i * 12) for i in range(9)]
                           + [(470 + (i % 2) * 11, 664 - i * 14) for i in range(7)]))
             + '</g>')

    scene('la', 'LOS ANGELES — the Pacific, Muscle Beach, volleyball, HOLLYWOOD on the hills', {
        'sky': sky('', '', '', sun=(1006, 176, 168)) + '\n'
               + clouds([(276, 74, 42), (760, 60, 34)], op=0.5)
               + '\n' + birds([(560, 120), (614, 146)], col='#6f93a8'),
        'far': ocean + '\n' + hills + '\n' + mansions + '\n' + sign,
        'ground': beach,
        'scenery-back': back, 'scenery-front': front,
        'foreground': '    <g fill="#cbbfa8" opacity="0.55"><rect x="0" y="708" width="1280" height="3"/></g>',
    }, d)


# ================================================================= 3. CHICAGO
def chicago():
    """Chicago is a CITY: streets, brick, steel, skyscrapers, the elevated L and the
    lake. Green is an accent (Grant Park), not the ground."""
    d = (sky_defs('#5ea6dc', '#a3cee8', '#dbe8f0', '#fff6e0', '#ffeecc') + '''
    <linearGradient id="lake" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#3d86b5"/><stop offset="1" stop-color="#69aecb"/>
    </linearGradient>
    <linearGradient id="asphalt" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#8f9298"/><stop offset="1" stop-color="#74777d"/>
    </linearGradient>''')

    # ---- Lake Michigan on the right, with Navy Pier running out into it ----
    def wheel(cx, cy, r, cabins=16):
        import math
        spokes = ''.join(f'<line x1="0" y1="0" x2="{r*math.cos(a):.1f}" y2="{r*math.sin(a):.1f}"/>'
                         for a in [i * math.pi / 8 for i in range(16)])
        cols = ['#e8574a', '#f2b134', '#4fb8d6', '#7bc86c', '#b47fd0', '#f28c34']
        pods = ''.join(f'<g transform="translate({r*math.cos(i*2*math.pi/cabins):.1f},'
                       f'{r*math.sin(i*2*math.pi/cabins):.1f})">'
                       f'<rect x="-3.6" y="-1" width="7.2" height="7" rx="2.4" fill="{cols[i%6]}"/>'
                       f'<rect x="-3.6" y="-2.4" width="7.2" height="2.4" rx="1.2" fill="#f6f6f0"/></g>'
                       for i in range(cabins))
        return (f'<g transform="translate({cx},{cy})">'
                f'<g stroke="#dfe6ea" stroke-width="2.6" fill="none"><circle cx="0" cy="0" r="{r}"/>'
                f'<circle cx="0" cy="0" r="{r-7}"/></g>'
                f'<g stroke="#cfd8de" stroke-width="1.3">{spokes}</g>'
                f'{pods}<circle cx="0" cy="0" r="5" fill="#e8eef2"/>'
                f'<circle cx="0" cy="0" r="2" fill="#8e9daa"/>'
                f'<g stroke="#b9c4cc" stroke-width="3.5" fill="none">'
                f'<path d="M-{r*0.62:.0f},{r*0.92:.0f} L0,2 L{r*0.62:.0f},{r*0.92:.0f}"/></g></g>')

    lake = ('    <rect x="884" y="258" width="396" height="44" fill="url(#lake)"/>\n'
            '    <g fill="#ffffff" opacity="0.35">'
            + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2.5" rx="1"/>'
                      for x, y, w in [(898, 270, 46), (1006, 284, 62), (1108, 266, 50),
                                      (1192, 290, 56), (940, 292, 52), (1240, 274, 38)])
            + '</g>'
            # a tour boat heading out
            '<g transform="translate(920,290)"><rect x="-24" y="-11" width="48" height="7" rx="2" fill="#f2f2ec"/>'
            '<rect x="-15" y="-19" width="28" height="9" rx="2" fill="#fbf9f2"/>'
            '<rect x="-3" y="-28" width="4" height="10" fill="#41474f"/>'
            '<rect x="-26" y="-4" width="52" height="3" fill="#3f6b8f"/></g>')

    navy_pier = ('    <g id="navy-pier">'
                 # deck out over the water
                 + ''.join(f'<rect x="{x}" y="284" width="4" height="18" fill="#6f6f66" opacity="0.8"/>'
                           for x in range(966, 1276, 22))
                 + '<rect x="958" y="276" width="322" height="9" rx="2" fill="#b6bcc2"/>'
                 '<rect x="958" y="274" width="322" height="3" rx="1.5" fill="#ccd2d7"/>'
                 # the Centennial Wheel — the thing everyone pictures
                 + wheel(1092, 232, 42)
                 # pavilions along the pier
                 + '<g><rect x="972" y="252" width="46" height="23" rx="2" fill="#f2ede0"/>'
                 '<polygon points="967,252 995,238 1023,252" fill="#c0392b"/>'
                 '<g fill="#9fc6dd"><rect x="978" y="258" width="12" height="10" rx="2"/>'
                 '<rect x="998" y="258" width="12" height="10" rx="2"/></g></g>'
                 '<g><rect x="1188" y="248" width="58" height="27" rx="2" fill="#f4f0e4"/>'
                 '<path d="M1183,248 A31,22 0 0 1 1251,248 Z" fill="#3f6b8f"/>'
                 '<g fill="#9fc6dd"><rect x="1196" y="256" width="13" height="12" rx="2"/>'
                 '<rect x="1216" y="256" width="13" height="12" rx="2"/></g></g>'
                 # flag masts down the deck
                 + ''.join(f'<g transform="translate({x},274)">'
                           f'<rect x="-1.4" y="-26" width="2.8" height="26" fill="#8e9daa"/>'
                           f'<path d="M1.4,-26 L14,-22 L1.4,-18 Z" fill="{c}"/></g>'
                           for x, c in [(1040, '#e8574a'), (1150, '#f2b134'), (1266, '#4fb8d6')])
                 + '</g>')

    # ---- a dense, tall skyline — the point of Chicago ----
    def block(x, y, w, h, base='#7a8593', lit='#8e99a7', win='#cfe0ee', step=13):
        wins = ''.join(f'<rect x="{x+4}" y="{y+9+r*step}" width="{w-8}" height="4"/>'
                       for r in range(int((h - 16) // step)))
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="1.5" fill="{base}"/>'
                f'<rect x="{x}" y="{y}" width="{w*0.32:.0f}" height="{h}" fill="{lit}"/>'
                f'<g fill="{win}" opacity="0.55">{wins}</g>')
    T = [(30,214,30,88),(64,182,26,120),(96,226,32,76),(132,168,28,134),(166,206,24,96),
         (194,238,30,64),(228,190,26,112),(258,222,32,80),(296,160,26,142),(326,204,30,98),
         (360,232,24,70),(388,186,28,116),(420,226,30,76),(454,196,24,106),(482,240,32,62),
         (560,214,28,88),(592,178,26,124),(622,232,30,70),(700,204,26,98),(730,236,30,66),
         (764,190,26,112),(794,226,32,76),(830,212,24,90)]
    skyline = '    <g>' + ''.join(block(*t) for t in T) + '</g>'
    # Willis Tower (black, twin antennas) and the John Hancock (tapered, X-braced)
    willis = ('    <g><rect x="510" y="140" width="42" height="162" fill="#4e5763"/>'
              '<rect x="510" y="140" width="15" height="162" fill="#616b78"/>'
              '<rect x="518" y="92" width="4" height="50" fill="#3f4753"/>'
              '<rect x="538" y="84" width="4" height="58" fill="#3f4753"/>'
              '<g fill="#cfe0ee" opacity="0.5">'
              + ''.join(f'<rect x="514" y="{152+r*13}" width="34" height="4"/>' for r in range(11)) + '</g></g>')
    hancock = ('    <g><polygon points="652,302 660,166 686,166 694,302" fill="#464e59"/>'
               '<polygon points="652,302 660,166 672,166 668,302" fill="#59626e"/>'
               '<g stroke="#79828f" stroke-width="2.5" fill="none">'
               '<path d="M657,262 L689,262 M659,222 L687,222 M661,186 L685,186"/>'
               '<path d="M657,262 L687,222 M689,262 L659,222 M659,222 L685,186 M687,222 L661,186"/></g>'
               '<rect x="664" y="132" width="3" height="34" fill="#3f4753"/>'
               '<rect x="680" y="132" width="3" height="34" fill="#3f4753"/></g>')

    # ---- the elevated L, steel and riveted, with a train on it ----
    piers = ''.join(f'<g><rect x="{x}" y="332" width="11" height="74" fill="#57606b"/>'
                    f'<rect x="{x+56}" y="332" width="11" height="74" fill="#4b535d"/>'
                    f'<path d="M{x+11},338 L{x+56},398 M{x+56},338 L{x+11},398" stroke="#69727d" stroke-width="3"/>'
                    f'<rect x="{x-4}" y="398" width="79" height="8" rx="2" fill="#4b535d"/></g>'
                    for x in range(30, 1260, 132))
    ltrain = ('<g transform="translate(150,318)">'
              '<rect x="0" y="-38" width="196" height="38" rx="5" fill="#c9d2da"/>'
              '<rect x="0" y="-38" width="196" height="9" rx="4" fill="#aab5c0"/>'
              '<rect x="0" y="-18" width="196" height="5" fill="#1f6f3d"/>'
              '<rect x="0" y="-13" width="196" height="4" fill="#a63a2c"/>'
              + ''.join(f'<rect x="{10+i*34}" y="-32" width="22" height="12" rx="2" fill="#bfe3f5"/>' for i in range(5))
              + '<rect x="192" y="-34" width="8" height="28" rx="3" fill="#8d959e"/></g>')
    el = ('    <g id="el">' + piers
          + '<rect x="0" y="318" width="1280" height="16" fill="#6b7480"/>'
          + '<rect x="0" y="312" width="1280" height="7" fill="#7d8794"/>'
          + '<rect x="0" y="332" width="1280" height="5" fill="#565f69"/>'
          + '<g fill="#8b94a0" opacity="0.6">'
          + ''.join(f'<rect x="{x}" y="320" width="4" height="12"/>' for x in range(8, 1280, 22)) + '</g>'
          + ltrain + '</g>')

    # ---- brick low-rise behind the tracks ----
    def brick(x, y, s, body='#9c5a44', trim='#c8bda8'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-52" y="-104" width="104" height="104" fill="{body}"/>'
                f'<rect x="-56" y="-112" width="112" height="10" rx="2" fill="{trim}"/>'
                + ''.join(f'<rect x="{-38+c*28}" y="{-92+r*34}" width="20" height="24" rx="2" fill="#cfe0ee"/>'
                          f'<rect x="{-40+c*28}" y="{-95+r*34}" width="24" height="4" rx="1" fill="{trim}"/>'
                          for r in range(2) for c in range(3))
                + f'<rect x="-14" y="-30" width="28" height="30" rx="2" fill="#5f4636"/>'
                f'<rect x="-18" y="-34" width="36" height="5" rx="2" fill="{trim}"/></g>')

    back = ('    ' + el
            + brick(90, 446, 0.62, '#9c5a44') + brick(230, 446, 0.62, '#8a6a52')
            + brick(1080, 446, 0.62, '#a8674a') + brick(1216, 446, 0.62, '#8f7460')
            + ''.join(f'<g transform="translate({x},444)"><rect x="-3" y="-56" width="6" height="56" fill="#3a3f47"/>'
                      f'<circle cx="0" cy="-60" r="7" fill="#ffe9a8"/></g>' for x in (400, 500, 800, 900))
            + oak(346, 448, 0.5, '#3f7548', '#4c8a56') + oak(960, 448, 0.48, '#3f7548', '#4c8a56'))

    # ---- streets: asphalt, kerbs, sidewalks, a green park strip ----
    street = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#asphalt)"/>\n'
              # sidewalks
              '    <g fill="#b9bcc2"><rect x="0" y="406" width="1280" height="34"/>'
              '<rect x="0" y="556" width="1280" height="40"/></g>\n'
              '    <g fill="#cbced4"><rect x="0" y="406" width="1280" height="5"/>'
              '<rect x="0" y="556" width="1280" height="5"/></g>\n'
              '    <g fill="#9ea2a9" opacity="0.7">'
              + ''.join(f'<rect x="{x}" y="411" width="2.5" height="29"/>' for x in range(0, 1280, 42))
              + ''.join(f'<rect x="{x}" y="561" width="2.5" height="35"/>' for x in range(20, 1280, 42))
              + '</g>\n'
              # kerbs
              '    <g fill="#6d7076"><rect x="0" y="440" width="1280" height="5"/>'
              '<rect x="0" y="596" width="1280" height="5"/></g>\n'
              # Grant Park green strip
              '    <rect x="0" y="616" width="1280" height="46" fill="#5f8f4c"/>\n'
              '    <rect x="0" y="616" width="1280" height="5" fill="#6fa059"/>\n'
              # lane markings on the cross street
              '    <g fill="#e8e2c9" opacity="0.5">'
              + ''.join(f'<rect x="{x}" y="380" width="26" height="4"/>' for x in range(0, 1280, 60)) + '</g>')

    # ---- Cloud Gate ("the Bean") and a subway entrance: very Chicago ----
    bean = ('<g transform="translate(214,650)">' + shadow(0, 8, 62, 10, 0.2) +
            '<ellipse cx="0" cy="-26" rx="60" ry="34" fill="#aab4bd"/>'
            '<ellipse cx="0" cy="-30" rx="58" ry="30" fill="#c4ced6"/>'
            '<ellipse cx="-18" cy="-40" rx="26" ry="12" fill="#e6edf2" opacity="0.9"/>'
            '<path d="M-58,-22 Q 0,-4 58,-22 Q 0,-12 -58,-22 Z" fill="#8e98a2" opacity="0.8"/>'
            '<ellipse cx="22" cy="-18" rx="16" ry="7" fill="#7f8992" opacity="0.7"/></g>')
    subway = ('<g transform="translate(1010,646)">' + shadow(0, 8, 54, 9) +
              '<rect x="-48" y="-6" width="96" height="14" rx="3" fill="#5a5f66"/>'
              '<g fill="#3f434a">' + ''.join(f'<rect x="{-42+i*16}" y="-2" width="13" height="7"/>' for i in range(5)) + '</g>'
              '<g stroke="#c9ced4" stroke-width="4" fill="none" stroke-linecap="round">'
              '<path d="M-46,-8 L-46,-42"/><path d="M46,-8 L46,-42"/><path d="M-46,-42 L46,-42"/></g>'
              '<rect x="-30" y="-70" width="60" height="20" rx="4" fill="#1f4f8f"/>'
              '<text x="0" y="-56" text-anchor="middle" font-family="Trebuchet MS,sans-serif" '
              'font-size="13" font-weight="bold" fill="#ffffff">SUBWAY</text></g>')

    front = ('    ' + bean + subway
             + oak(120, 690, 1.05, '#3f7548', '#4c8a56') + oak(1210, 700, 1.0, '#3f7548', '#4c8a56')
             + ''.join(f'<g transform="translate({x},{y})">'
                       f'<rect x="-3" y="-72" width="7" height="72" fill="#3a3f47"/>'
                       f'<circle cx="0" cy="-78" r="9" fill="#ffe9a8"/>'
                       f'<rect x="-9" y="-4" width="19" height="6" rx="2" fill="#3a3f47"/></g>'
                       for x, y in [(380, 620), (802, 662), (900, 616)])
             + f'<g transform="translate(470,690)">{shadow(0, 8, 22)}'
             '<rect x="-9" y="-34" width="18" height="40" rx="4" fill="#c0392b"/>'
             '<rect x="-15" y="-24" width="30" height="8" rx="3" fill="#c0392b"/>'
             '<circle cx="0" cy="-38" r="8" fill="#d24a3b"/></g>'
             + f'<g transform="translate(800,700)">{shadow(0, 6, 46, 8)}'
             '<rect x="-44" y="-14" width="88" height="9" rx="3" fill="#7a5a3a"/>'
             '<rect x="-44" y="-30" width="88" height="8" rx="3" fill="#8a6a45"/>'
             '<rect x="-38" y="-6" width="8" height="18" fill="#41474f"/>'
             '<rect x="30" y="-6" width="8" height="18" fill="#41474f"/></g>')

    plane = ('    <g transform="translate(1090,126) rotate(-9)">'
             '<ellipse cx="0" cy="0" rx="46" ry="7" fill="#eef2f6"/>'
             '<path d="M-30,0 L-4,-4 L14,-26 L26,-26 L18,-2 L26,26 L14,26 L-4,4 Z" fill="#e2e8ee"/>'
             '<path d="M30,-2 L44,-10 L48,-2 L44,6 Z" fill="#cfd7df"/>'
             '<rect x="-40" y="-3" width="16" height="6" rx="3" fill="#3d7bd6"/>'
             '<g fill="#bfe3f5">' + ''.join(f'<rect x="{6+i*8}" y="-2.5" width="4" height="4" rx="1"/>'
                                            for i in range(4)) + '</g>'
             '<ellipse cx="-30" cy="1" rx="6" ry="4" fill="#cfd7df"/></g>')

    scene('chicago', 'CHICAGO — skyline, the elevated L, Lake Michigan, city streets', {
        'sky': (sky('', '', '', sun=(1150, 88, 145)) + '\n' + clouds([(300, 74, 48), (760, 60, 40)], op=0.75)
                + '\n' + birds([(880, 178), (932, 202)]) + '\n' + plane),
        'far': lake + '\n' + skyline + '\n' + willis + '\n' + hancock + '\n' + navy_pier,
        'ground': street,
        'scenery-back': back, 'scenery-front': front,
        'foreground': '    <g fill="#8a8d93" opacity="0.5"><rect x="0" y="706" width="1280" height="3"/></g>',
    }, d)


# ============================================================ 4. GRAND CANYON
def grand_canyon():
    """A canyon is a VOID, not a cliff. Read it top-down: hazy far rim, walls stepping
    DOWN and away into shadow, the Colorado a thin ribbon at the bottom, then the near
    wall rising back toward us and the dry rim we're standing on."""
    d = (sky_defs('#2f86c8', '#7fbde0', '#ddd3b6', '#fff4d6', '#ffe9b8')
         + grass_defs('#d3b485', '#b8965f'))

    def ledge(tops, y_bot, fill, seg_w=None, op=1.0):
        """A rock shelf with a flat-topped, notched profile — mesas, not hills."""
        n = len(tops)
        seg = seg_w or (1320.0 / n)
        pts, x = [], -20.0
        for y in tops:
            pts.append(f'{x:.0f},{y}')
            x += seg
            pts.append(f'{x:.0f},{y}')
        pts.append(f'{x:.0f},{y_bot}'); pts.append(f'-20,{y_bot}')
        return f'<polygon points="{" ".join(pts)}" fill="{fill}" opacity="{op}"/>'

    def gullies(xs, y0, y1, col, w=6, op=0.2):
        return (f'<g fill="{col}" opacity="{op}">'
                + ''.join(f'<polygon points="{x},{y0} {x+w},{y0} {x+w*0.4:.0f},{y1} {x-w*0.2:.0f},{y1}"/>'
                          for x in xs) + '</g>')

    def spur(pts, ybase, bands, rim='#e6cfa4', rim_w=2.6):
        """A promontory reaching out into the void: one ridge line, strata that follow
        it down, a lit lip along the top. Stacking these at three depths is what turns a
        striped wall into a canyon."""
        x0, xN = pts[0][0], pts[-1][0]
        out = []
        for k, (dy, fill) in enumerate(bands):
            poly = ' '.join(f'{x},{y+dy}' for x, y in pts)
            out.append(f'<polygon points="{poly} {xN},{ybase} {x0},{ybase}" fill="{fill}"/>')
        line = ' '.join(('M' if n == 0 else 'L') + f'{x},{y}' for n, (x, y) in enumerate(pts))
        out.append(f'<path d="{line}" fill="none" stroke="{rim}" stroke-width="{rim_w}" opacity="0.75"/>')
        return '<g>' + ''.join(out) + '</g>'

    def butte(x, ytop, w, ybase, warm='#b06437', lit='#d09059', dark='#8a4a22'):
        h = ybase - ytop
        return (f'<g><polygon points="{x-w},{ybase} {x-w*0.86:.0f},{ytop+h*0.09:.0f} '
                f'{x+w*0.34:.0f},{ytop} {x+w*0.78:.0f},{ytop+h*0.16:.0f} {x+w},{ybase}" fill="{warm}"/>'
                f'<polygon points="{x-w*0.86:.0f},{ytop+h*0.09:.0f} {x+w*0.34:.0f},{ytop} '
                f'{x+w*0.78:.0f},{ytop+h*0.16:.0f} {x+w*0.3:.0f},{ytop+h*0.24:.0f} '
                f'{x-w*0.6:.0f},{ytop+h*0.18:.0f}" fill="{lit}"/>'
                f'<polygon points="{x-w},{ybase} {x-w*0.86:.0f},{ytop+h*0.09:.0f} '
                f'{x-w*0.6:.0f},{ytop+h*0.18:.0f} {x-w*0.72:.0f},{ybase}" fill="{dark}"/>'
                f'<g fill="#7f4423" opacity="0.3">'
                + ''.join(f'<rect x="{x-w*0.92:.0f}" y="{ytop+h*f:.0f}" width="{w*1.84:.0f}" height="4"/>'
                          for f in (0.46, 0.66, 0.84)) + '</g></g>')

    # --- the far rim, twenty miles off and washed out to almost nothing ---
    far = ('    <g fill="#c4cfd4">'
           + ''.join(f'<rect x="0" y="{y}" width="1280" height="{h}" opacity="{o}"/>'
                     for y, h, o in [(150, 26, 0.18), (176, 26, 0.34), (202, 100, 0.46)])
           + '</g>\n'
           '    ' + ledge([178, 172, 183, 174, 185, 176, 180, 174], 200, '#e2d7c0', op=0.66)
           + ledge([196, 190, 201, 192, 203, 194, 198, 192], 216, '#dbcdb0', op=0.78))

    canyon = ('    <g id="canyon">'
              # ---- the far wall: one mass, eroded VERTICALLY, not a stack of stripes ----
              + ledge([214, 206, 222, 208, 224, 210, 216, 208, 218], 246, '#d0aa7c')
              + gullies(range(20, 1280, 34), 216, 250, '#a8814f', 11, 0.2)
              + ledge([242, 234, 250, 236, 252, 238, 244, 236], 272, '#c1904f')
              + gullies(range(38, 1280, 30), 244, 276, '#94643a', 10, 0.22)
              + ledge([266, 260, 272, 261, 274, 262, 268, 261], 290, '#a96a3c')
              + gullies(range(26, 1280, 26), 268, 292, '#7c4523', 9, 0.24)
              + ledge([286, 282, 289, 283, 291, 284, 288, 283], 297, '#5c3628')
              # ---- the Colorado, a thread at the bottom of the world ----
              + '<path d="M-20,290 C 180,285 300,294 500,288 C 700,283 860,292 1060,286 '
              'C 1180,283 1240,289 1300,285 L1300,296 C 1240,300 1180,294 1060,297 '
              'C 860,303 700,293 500,299 C 300,305 180,296 -20,302 Z" fill="#93c0a4"/>'
              '<path d="M-20,290 C 180,285 300,294 500,288 C 700,283 860,292 1060,286" '
              'fill="none" stroke="#c6e0cf" stroke-width="2" opacity="0.9"/>'
              # ---- temples: tall, and the only vertical thing in the void ----
              + butte(214, 192, 50, 294, '#c9895a', '#e8b07c', '#8f5c33')
              + butte(1010, 200, 48, 294, '#c9895a', '#e8b07c', '#8f5c33')
              + butte(560, 214, 42, 294, '#bd7c4a', '#dda36f', '#84502a')
              + butte(742, 230, 34, 294, '#b06437', '#d09059', '#7d451f')
              + butte(392, 244, 28, 294, '#a85c32', '#c88a54', '#743d1c')
              + butte(886, 250, 26, 294, '#a85c32', '#c88a54', '#743d1c')
              # ---- a ridge across the middle distance, tying the two sides together ----
              + spur([(320, 306), (392, 290), (470, 278), (556, 272), (648, 274),
                      (734, 282), (812, 294), (876, 306)], 308,
                     [(0, '#b0743f'), (10, '#a36936'), (21, '#96602f')], '#dcb887', 2.0)
              # ---- middle-distance spurs reaching in from both sides ----
              + spur([(-20, 238), (76, 226), (162, 234), (248, 228), (330, 242),
                      (404, 258), (462, 276), (506, 298), (528, 308)], 310,
                     [(0, '#9c5730'), (11, '#904d29'), (23, '#824323'), (37, '#743a1e')], '#e6c294', 2.4)
              + spur([(752, 308), (776, 298), (820, 276), (878, 258), (952, 242),
                      (1034, 228), (1120, 234), (1206, 226), (1300, 238)], 310,
                     [(0, '#9c5730'), (11, '#904d29'), (23, '#824323'), (37, '#743a1e')], '#e6c294', 2.4)
              # ---- the near rim: the promontory we are standing on the end of ----
              + spur([(-20, 258), (52, 244), (114, 250), (172, 240), (222, 252),
                      (268, 268), (304, 284), (336, 306)], 310,
                     [(0, '#7a4630'), (10, '#6d3d29'), (21, '#5f3422'), (34, '#4e2a1b')], '#f4dfb6', 3.2)
              + spur([(944, 306), (976, 284), (1012, 268), (1058, 252), (1108, 240),
                      (1166, 250), (1228, 244), (1300, 258)], 310,
                     [(0, '#7a4630'), (10, '#6d3d29'), (21, '#5f3422'), (34, '#4e2a1b')], '#f4dfb6', 3.2)
              # ---- the lip right at our feet ----
              + '<path d="M300,308 C 430,298 530,302 640,300 C 750,298 850,302 980,308 '
              'L980,312 L300,312 Z" fill="#5f3422"/>'
              '<path d="M300,306 C 430,296 530,300 640,298 C 750,296 850,300 980,306" '
              'fill="none" stroke="#f4dfb6" stroke-width="3.2"/>'
              + '</g>')

    # --- the rim we're standing on: dust, slickrock, gravel ---
    rim = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#grassg)"/>\n'
           '    <path d="M0,300 C 200,312 420,302 640,310 C 860,318 1060,304 1280,312 L1280,300 Z" fill="#e0c79a"/>\n'
           '    <path d="M0,366 Q 300,342 640,364 T 1280,358 L1280,432 L0,432 Z" fill="#c2a06a" opacity="0.55"/>\n'
           '    <path d="M0,540 Q 340,516 700,542 T 1280,532 L1280,720 L0,720 Z" fill="#bb9760" opacity="0.45"/>\n'
           '    <g fill="#a8874f" opacity="0.3">'
           + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.34:.0f}"/>'
                     for x, y, r in [(120, 600, 46), (420, 646, 38), (860, 612, 42),
                                     (1140, 660, 44), (300, 700, 40), (980, 700, 36)]) + '</g>\n'
           # flat slickrock slabs breaking up the dirt
           '    <g>'
           + ''.join(f'<g><ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.3:.0f}" fill="#c9ac7c"/>'
                     f'<ellipse cx="{x-r*0.12:.0f}" cy="{y-2}" rx="{r*0.82:.0f}" ry="{r*0.22:.0f}" '
                     f'fill="#d8bd91"/></g>'
                     for x, y, r in [(210, 492, 74), (520, 528, 58), (760, 500, 66),
                                     (1090, 546, 70), (90, 660, 62), (420, 596, 50),
                                     (960, 620, 56), (1220, 486, 48), (640, 676, 54),
                                     (300, 388, 40), (860, 384, 36), (1160, 390, 38)]) + '</g>\n'
           '    <g fill="#8f7440" opacity="0.28">'
           + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="3" rx="1.5"/>'
                     for x, y, w in [(60, 574, 120), (330, 620, 90), (760, 586, 110),
                                     (1050, 636, 96), (200, 676, 84), (900, 690, 100)]) + '</g>\n'
           # the rim trail, with the low stone wall that keeps you off the edge
           '    <rect x="0" y="330" width="1280" height="15" fill="#cbb083" opacity="0.85"/>\n'
           '    <rect x="0" y="330" width="1280" height="3" fill="#dcc599" opacity="0.8"/>\n'
           '    <g fill="#a8874f" opacity="0.35">'
           + ''.join(f'<rect x="{x}" y="{333 + (x % 7)}" width="{5 + x % 5}" height="4" rx="2"/>'
                     for x in range(4, 1280, 19)) + '</g>\n'
           '    <g>'
           + ''.join(f'<rect x="{x}" y="{320 + (x*3 % 3)}" width="{13 + x % 6}" height="9" '
                     f'rx="2" fill="{"#ab9067" if x % 3 else "#9c815a"}"/>'
                     for a, b in [(0, 250), (296, 560), (700, 902), (940, 1146), (1186, 1280)]
                     for x in range(a, b, 17))
           + '</g>\n'
           '    <g fill="#7f6844" opacity="0.35">'
           + ''.join(f'<rect x="{x}" y="{328}" width="16" height="2.5" rx="1.2"/>'
                     for a, b in [(0, 250), (296, 560), (700, 902), (940, 1146), (1186, 1280)]
                     for x in range(a, b, 17)) + '</g>')

    def juniper(x, y, s):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 6, 30)}'
                f'<path d="M-5,4 L-7,-22 L-14,-32 L-2,-26 L0,-44 L3,-26 L14,-34 L5,-22 L4,4 Z" fill="#6b4a2a"/>'
                f'<ellipse cx="0" cy="-46" rx="34" ry="24" fill="#3f6f4c"/>'
                f'<ellipse cx="-16" cy="-38" rx="20" ry="15" fill="#4a805a"/>'
                f'<ellipse cx="16" cy="-40" rx="18" ry="14" fill="#4a805a"/>'
                f'<ellipse cx="2" cy="-58" rx="20" ry="12" fill="#54906a"/></g>')

    def rock(x, y, s, a='#a5764c', b='#c08d5e', c='#8a6039'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 14, 52, 10)}'
                f'<polygon points="-50,14 -42,-24 -16,-42 16,-40 44,-16 50,14" fill="{a}"/>'
                f'<polygon points="-16,-42 16,-40 44,-16 8,-12 -14,-24" fill="{b}"/>'
                f'<polygon points="-50,14 -42,-24 -14,-24 -8,10" fill="{c}"/>'
                f'<g stroke="{c}" stroke-width="2" opacity="0.5" fill="none">'
                f'<path d="M-30,-6 L30,-2 M-34,4 L26,8"/></g></g>')

    def yucca(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 24)}'
                f'<g stroke="#6f8f4e" stroke-width="4" stroke-linecap="round" fill="none">'
                f'<path d="M0,0 L-26,-34"/><path d="M0,0 L-12,-42"/><path d="M0,0 L0,-48"/>'
                f'<path d="M0,0 L12,-42"/><path d="M0,0 L26,-34"/></g>'
                f'<path d="M0,-20 L0,-62" stroke="#b8a06a" stroke-width="4"/>'
                f'<ellipse cx="0" cy="-66" rx="7" ry="10" fill="#e8e0c4"/></g>')

    def pricklypear(x, y, s=1.0, col='#5f8f52', dark='#4d7743'):
        pads = [(-16, -14, 13, 16, -22), (14, -18, 12, 15, 18), (-4, -32, 11, 14, -6),
                (16, -40, 9, 12, 26), (-20, -36, 8, 11, -30), (2, -54, 8, 10, 4)]
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 26)}'
                + ''.join(f'<g transform="translate({px},{py}) rotate({r})">'
                          f'<ellipse cx="0" cy="0" rx="{rx}" ry="{ry}" fill="{col}"/>'
                          f'<ellipse cx="-{rx*0.3:.0f}" cy="-{ry*0.2:.0f}" rx="{rx*0.55:.0f}" '
                          f'ry="{ry*0.6:.0f}" fill="{dark}" opacity="0.45"/></g>'
                          for px, py, rx, ry, r in pads)
                + f'<g fill="#c0392b"><circle cx="4" cy="-64" r="4"/><circle cx="-14" cy="-46" r="3.4"/>'
                f'<circle cx="24" cy="-50" r="3.2"/></g></g>')

    def agave(x, y, s=1.0, col='#7f9c72', dark='#657f5b'):
        blades = ''.join(f'<path d="M0,0 L{28*__import__("math").cos(a):.0f},'
                         f'{-6 + 34*__import__("math").sin(a):.0f} L{7*__import__("math").cos(a+0.5):.0f},'
                         f'-4 Z" fill="{col if i % 2 else dark}"/>'
                         for i, a in enumerate([-3.05, -2.7, -2.35, -2.0, -1.57, -1.15, -0.8, -0.45, -0.1]))
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 26)}{blades}</g>')

    def pinyon(x, y, s=1.0, a='#2f5c3c', b='#3a6f4a', c='#487f57'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(-3, 4, 26)}'
                f'<path d="M-4,4 C -7,-14 -13,-22 -18,-30 L-6,-25 L-3,-44 L2,-25 L14,-32 '
                f'L5,-18 L4,4 Z" fill="#5f4630"/>'
                f'<ellipse cx="-13" cy="-40" rx="16" ry="12" fill="{a}"/>'
                f'<ellipse cx="14" cy="-44" rx="15" ry="11" fill="{a}"/>'
                f'<ellipse cx="0" cy="-54" rx="21" ry="15" fill="{b}"/>'
                f'<ellipse cx="-8" cy="-62" rx="13" ry="9" fill="{c}"/>'
                f'<ellipse cx="11" cy="-58" rx="11" ry="8" fill="{c}"/></g>')

    def deer(x, y, s=1.0, coat='#a8825a', dark='#8d6a45'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 30, 5)}'
                f'<g stroke="{dark}" stroke-width="4" stroke-linecap="round">'
                f'<path d="M-16,-14 L-18,0 M-9,-14 L-6,0 M12,-14 L14,0 M19,-14 L23,0"/></g>'
                f'<ellipse cx="0" cy="-20" rx="26" ry="12" fill="{coat}"/>'
                f'<ellipse cx="-4" cy="-24" rx="20" ry="7" fill="#bb9468"/>'
                f'<path d="M22,-26 L32,-40 L38,-38 L30,-24 Z" fill="{coat}"/>'
                f'<ellipse cx="38" cy="-42" rx="9" ry="6" fill="{coat}"/>'
                f'<circle cx="44" cy="-43" r="2" fill="#3f3630"/>'
                f'<g stroke="{dark}" stroke-width="2.2" fill="none" stroke-linecap="round">'
                f'<path d="M36,-47 L33,-58 M33,-58 L28,-64 M33,-58 L38,-65"/>'
                f'<path d="M41,-47 L45,-58 M45,-58 L42,-66 M45,-58 L52,-63"/></g>'
                f'<path d="M-26,-22 L-34,-30" stroke="{coat}" stroke-width="5" stroke-linecap="round"/></g>')

    def watchtower(x, y, s=1.0):
        stones = ''.join(f'<rect x="{-15 + (r % 2) * 5 + c * 9:.0f}" y="{-16 - r * 8}" '
                         f'width="7" height="6" rx="1.5" fill="#9c7f5c" opacity="0.5"/>'
                         for r in range(15) for c in range(4))
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 5, 46, 9)}'
                # low round room at the base
                f'<ellipse cx="0" cy="0" rx="46" ry="11" fill="#8a7050"/>'
                f'<rect x="-46" y="-26" width="92" height="26" fill="#a8886098"/>'
                f'<rect x="-46" y="-26" width="92" height="26" fill="#a88860"/>'
                f'<rect x="-46" y="-26" width="26" height="26" fill="#bb9a70"/>'
                f'<ellipse cx="0" cy="-26" rx="46" ry="10" fill="#c0a075"/>'
                f'<rect x="-10" y="-20" width="14" height="20" rx="2" fill="#4a3a2a"/>'
                # the tower
                f'<path d="M-20,-26 L-16,-134 L16,-134 L20,-26 Z" fill="#ad8d64"/>'
                f'<path d="M-20,-26 L-16,-134 L-6,-134 L-8,-26 Z" fill="#c2a179"/>'
                f'<g>{stones}</g>'
                f'<g fill="#4a3a2a"><rect x="-6" y="-60" width="9" height="12" rx="2"/>'
                f'<rect x="-6" y="-92" width="9" height="12" rx="2"/>'
                f'<rect x="-6" y="-122" width="9" height="10" rx="2"/></g>'
                f'<rect x="-22" y="-142" width="45" height="9" fill="#9c7f5c"/>'
                f'<g fill="#ad8d64">' + ''.join(f'<rect x="{-22 + i*11}" y="-150" width="7" height="9"/>'
                                                 for i in range(5)) + '</g></g>')

    def hiker(x, y, s=1.0, shirt='#c0392b', pack='#3f6b8f'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 11, 3)}'
                f'<g stroke="#c98d5e" stroke-width="4.5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-13 L-5,-1 M3,-13 L6,-1"/><path d="M5,-27 L12,-14"/></g>'
                f'<rect x="-6" y="-30" width="13" height="18" rx="5" fill="{shirt}"/>'
                f'<rect x="-12" y="-30" width="8" height="14" rx="3" fill="{pack}"/>'
                f'<circle cx="0" cy="-36" r="6" fill="#c98d5e"/>'
                f'<path d="M-8,-38 a8,5 0 0 1 16,0 z" fill="#d8c9a0"/>'
                f'<path d="M12,-16 L13,4" stroke="#8a7050" stroke-width="2"/></g>')

    back = ('    ' + watchtower(1108, 398, 0.86)
            + juniper(110, 420, 0.72) + juniper(360, 428, 0.62) + juniper(940, 426, 0.66)
            + juniper(1236, 424, 0.7)
            + juniper(228, 392, 0.5) + juniper(468, 396, 0.44) + juniper(830, 394, 0.48)
            + juniper(1024, 390, 0.42) + juniper(66, 396, 0.46) + juniper(742, 398, 0.4)
            + pinyon(148, 434, 0.8) + pinyon(300, 430, 0.7) + pinyon(430, 436, 0.75)
            + pinyon(700, 432, 0.68) + pinyon(866, 438, 0.82) + pinyon(1010, 430, 0.72)
            + pinyon(1160, 436, 0.78) + pinyon(56, 430, 0.72) + pinyon(560, 428, 0.62)
            + pinyon(392, 396, 0.42) + pinyon(940, 394, 0.44) + pinyon(126, 392, 0.4)
            + pinyon(1132, 396, 0.42) + pinyon(660, 392, 0.36) + pinyon(268, 394, 0.38)
            + pricklypear(340, 402, 0.5) + pricklypear(880, 404, 0.46) + pricklypear(566, 400, 0.42)
            + pricklypear(760, 430, 0.6) + pricklypear(214, 428, 0.62)
            + agave(180, 402, 0.5) + agave(1000, 406, 0.46) + agave(452, 400, 0.44)
            + agave(1210, 404, 0.42) + agave(636, 434, 0.55)
            + rock(520, 434, 0.5) + rock(800, 436, 0.46) + rock(1064, 430, 0.4)
            + deer(994, 428, 0.62)
            # hikers on the rim trail, for scale
            + hiker(262, 344, 0.62, '#c0392b', '#3f6b8f') + hiker(292, 346, 0.58, '#e8a34a', '#4f7d4a')
            + hiker(884, 345, 0.6, '#3f6b8f', '#c0392b')
            # trail sign
            + '<g transform="translate(452,344) scale(0.7)">'
            '<rect x="-2.5" y="-30" width="5" height="30" fill="#7a5f3f"/>'
            '<rect x="-26" y="-32" width="52" height="11" rx="2" fill="#6f5a3c"/>'
            '<rect x="-24" y="-30" width="48" height="7" rx="2" fill="#8a7050"/>'
            '<rect x="-22" y="-45" width="44" height="11" rx="2" fill="#6f5a3c"/>'
            '<rect x="-20" y="-43" width="40" height="7" rx="2" fill="#8a7050"/></g>')

    front = ('    ' + rock(110, 596, 1.3) + rock(300, 648, 0.95) + rock(1170, 604, 1.35)
             + rock(980, 652, 1.0)
             + juniper(56, 692, 1.55) + juniper(1236, 702, 1.45)
             + pinyon(150, 706, 1.45) + pinyon(330, 542, 0.7) + pinyon(940, 578, 0.9)
             + pinyon(1240, 566, 0.8) + pinyon(452, 700, 1.05) + pinyon(1054, 596, 0.95)
             + yucca(420, 664, 1.15) + yucca(860, 690, 1.25) + yucca(452, 712, 1.0)
             + pricklypear(206, 700, 1.35) + pricklypear(1058, 712, 1.25)
             + pricklypear(478, 606, 0.9) + agave(790, 640, 1.1) + agave(360, 580, 0.85)
             + agave(1130, 700, 1.05) + juniper(880, 566, 0.72) + juniper(232, 560, 0.66)
             + ''.join(f'<g transform="translate({x},{y})" opacity="0.8">'
                       f'<g stroke="#b8a06a" stroke-width="2.5" stroke-linecap="round" fill="none">'
                       f'<path d="M0,0 L-11,-19"/><path d="M0,0 L-3,-24"/><path d="M0,0 L5,-22"/>'
                       f'<path d="M0,0 L13,-16"/></g></g>'
                       for x, y in [(150, 636), (520, 692), (930, 620), (1200, 656),
                                    (330, 706), (760, 578), (1090, 600), (60, 588)])
             + f'<g transform="translate(806,624)">{shadow(0, 4, 20)}'
             '<path d="M0,0 L-18,-26 L-4,-22 L0,-44 L4,-22 L18,-26 Z" fill="#6f8f4e"/></g>')

    scene('grand-canyon', 'GRAND CANYON — the void, the Colorado far below, the Watchtower on the rim trail', {
        'sky': sky('', '', '', sun=(1090, 84, 150)) + '\n' + clouds([(300, 70, 44), (760, 56, 36)], op=0.65)
               + '\n' + birds([(560, 116), (612, 140)], col='#8a7a5a'),
        'far': far + '\n' + canyon,
        'ground': rim,
        'scenery-back': back, 'scenery-front': front,
        'foreground': '    <g fill="#a8894f" opacity="0.5"><rect x="0" y="706" width="1280" height="3"/></g>',
    }, d)


# ================================================================ 5. NEW YORK
def nyc():
    """The densest city in America: asphalt, brownstones, water towers, steam from the
    manhole, and the Brooklyn Bridge. Green is a street tree, not a lawn."""
    d = (sky_defs('#6f9fd0', '#b7cde2', '#f6dcbe', '#ffeccb', '#ffd9a8') + '''
    <linearGradient id="river" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5c7f9c"/><stop offset="1" stop-color="#7ba0ba"/>
    </linearGradient>
    <linearGradient id="asphalt" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#83868c"/><stop offset="1" stop-color="#6a6d73"/>
    </linearGradient>''')

    def block(x, y, w, h, base='#77808f', lit='#8a93a2', win='#ffe9b8', step=13):
        wins = ''.join(f'<rect x="{x+4}" y="{y+9+r*step}" width="{w-8}" height="4"/>'
                       for r in range(int((h - 16) // step)))
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="1.5" fill="{base}"/>'
                f'<rect x="{x}" y="{y}" width="{w*0.3:.0f}" height="{h}" fill="{lit}"/>'
                f'<g fill="{win}" opacity="0.6">{wins}</g>')
    T = [(20,206,28,96),(52,176,24,126),(80,222,30,80),(114,190,22,112),(140,214,26,88),
         (200,214,30,88),(234,186,22,116),(260,232,28,70),(292,200,24,102),(320,226,30,76),
         (1010,200,28,102),(1042,172,24,130),(1070,226,30,76),(1104,192,22,110),
         (1130,236,28,66),(1162,178,24,124),(1190,216,30,86),(1224,196,26,106)]
    skyline = '    <g>' + ''.join(block(*t) for t in T) + '</g>'
    # a second, hazier rank filling the middle so Manhattan doesn't stop at the corners
    MID = [(352,222,26,80),(382,198,22,104),(410,232,28,70),(444,210,24,92),(474,238,26,64),
           (504,216,22,86),(530,240,28,62),(560,224,24,78),(590,244,26,58),(620,228,22,74),
           (648,246,28,56),(678,226,24,76),(706,242,26,60),(734,214,22,88),(760,238,28,64),
           (792,220,24,82),(820,240,26,62),(848,204,22,98),(874,232,28,70),(906,212,24,90),
           (936,238,26,64),(966,220,22,82)]
    midrank = ('    <g opacity="0.55">' + ''.join(block(*t, '#8d97a5', '#9ea8b5', '#e8eef4', 14) for t in MID)
               + '</g>')

    # Empire State — stepped setbacks and a mast
    empire = ('    <g><rect x="82" y="190" width="22" height="112" fill="#69727f"/>'
              '<rect x="86" y="160" width="14" height="32" fill="#727b88"/>'
              '<rect x="89" y="142" width="8" height="20" fill="#69727f"/>'
              '<rect x="91.5" y="120" width="3" height="24" fill="#5b6470"/>'
              '<g fill="#ffe9b8" opacity="0.55">'
              + ''.join(f'<rect x="86" y="{200+r*13}" width="14" height="4"/>' for r in range(7)) + '</g></g>')
    # Chrysler — the sunburst crown, unmistakable
    chrysler = ('    <g><rect x="1042" y="172" width="24" height="130" fill="#6d7683"/>'
                '<rect x="1042" y="172" width="8" height="130" fill="#7e8794"/>'
                + ''.join(f'<path d="M{1054-w},{164-i*13} A{w},{w*0.8:.0f} 0 0 1 {1054+w},{164-i*13} Z" '
                          f'fill="#c9d4dd" opacity="{0.9-i*0.12}"/>'
                          for i, w in enumerate([12, 10, 8, 6]))
                + '<rect x="1052.5" y="108" width="3" height="24" fill="#aab5c0"/></g>')
    # One World Trade — tapered with a long spire
    owtc = ('    <g><polygon points="1224,302 1228,196 1246,196 1250,302" fill="#8fa3b5"/>'
            '<polygon points="1224,302 1228,196 1237,196 1237,302" fill="#a3b6c6"/>'
            '<rect x="1235.5" y="132" width="3" height="64" fill="#8fa3b5"/></g>')
    river = ('    <rect x="0" y="266" width="1280" height="28" fill="url(#river)"/>'
             '<g fill="#ffffff" opacity="0.3">'
             + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2" rx="1"/>'
                       for x, y, w in [(300, 276, 70), (560, 284, 90), (820, 272, 60)]) + '</g>'
             # waterfront: seawall + promenade, so the street ends on land not water
             '<rect x="0" y="292" width="1280" height="4" fill="#8d8f95"/>'
             '<rect x="0" y="296" width="1280" height="8" fill="#b4b7bd"/>'
             '<g fill="#9a9ea5" opacity="0.6">'
             + ''.join(f'<rect x="{x}" y="296" width="2" height="8"/>' for x in range(0, 1280, 34)) + '</g>'
             + ''.join(f'<g transform="translate({x},292)"><rect x="-3" y="-22" width="6" height="22" fill="#2f333a"/>'
                       f'<circle cx="0" cy="-25" r="4" fill="#ffe9a8"/></g>' for x in range(60, 1280, 120)))

    # ---- the Statue of Liberty, standing in the harbour ----
    def liberty(x, y, s=1.0, skin='#7cb8a2', shade='#69a48f', lite='#93cbb5',
                stone='#c0b49a', stone2='#a99d84'):
        crown = ''.join(
            f'<polygon points="0,-6 {6*__import__("math").cos(a):.1f},{-6+6*__import__("math").sin(a):.1f} '
            f'{13*__import__("math").cos(a):.1f},{-6+13*__import__("math").sin(a):.1f}" fill="{lite}"/>'
            for a in [-2.7, -2.25, -1.8, -1.35, -0.9, -0.45, 0.0])
        return (f'<g transform="translate({x},{y}) scale({s})">'
                # island + star-fort pedestal
                f'<ellipse cx="0" cy="4" rx="52" ry="8" fill="#6f8a63"/>'
                f'<rect x="-34" y="-10" width="68" height="14" fill="{stone2}"/>'
                f'<rect x="-27" y="-46" width="54" height="36" fill="{stone}"/>'
                f'<rect x="-27" y="-46" width="18" height="36" fill="#cdc2a9"/>'
                f'<g fill="{stone2}"><rect x="-27" y="-30" width="54" height="3"/>'
                f'<rect x="-22" y="-42" width="8" height="12"/><rect x="-4" y="-42" width="8" height="12"/>'
                f'<rect x="14" y="-42" width="8" height="12"/></g>'
                f'<rect x="-31" y="-52" width="62" height="7" rx="2" fill="{stone}"/>'
                # robe
                f'<polygon points="-20,-52 -8,-118 10,-118 22,-52" fill="{skin}"/>'
                f'<polygon points="-20,-52 -8,-118 0,-118 -2,-52" fill="{lite}"/>'
                f'<g fill="{shade}" opacity="0.55">'
                f'<polygon points="6,-116 12,-116 20,-54 12,-54"/>'
                f'<polygon points="-4,-114 0,-114 2,-54 -3,-54"/></g>'
                # tablet in the left arm
                f'<g transform="rotate(-18 -14 -96)"><rect x="-26" y="-104" width="19" height="26" rx="2" fill="{shade}"/>'
                f'<rect x="-24" y="-101" width="15" height="20" rx="2" fill="{lite}"/></g>'
                # head + crown
                f'<circle cx="1" cy="-128" r="9" fill="{skin}"/>'
                f'<circle cx="-2" cy="-129" r="6" fill="{lite}"/>'
                f'<g transform="translate(1,-131)">{crown}</g>'
                # raised right arm + torch
                f'<path d="M12,-112 L26,-146 L34,-144 L22,-110 Z" fill="{skin}"/>'
                f'<rect x="26" y="-160" width="12" height="16" rx="3" fill="{stone}"/>'
                f'<rect x="24" y="-163" width="16" height="5" rx="2" fill="{shade}"/>'
                f'<path d="M32,-164 C 24,-176 30,-186 32,-192 C 34,-186 40,-176 32,-164 Z" fill="#f2c230"/>'
                f'<path d="M32,-168 C 28,-176 31,-183 32,-187 C 33,-183 36,-176 32,-168 Z" fill="#ffe89a"/>'
                f'</g>')

    def bb_tower(x):
        return (f'<g><rect x="{x-34}" y="146" width="68" height="124" fill="#b8a68c"/>'
                f'<rect x="{x-34}" y="146" width="24" height="124" fill="#c9b79c"/>'
                f'<path d="M{x-26},270 L{x-26},200 A14,16 0 0 1 {x-2},200 L{x-2},270 Z" fill="#6f6350"/>'
                f'<path d="M{x+2},270 L{x+2},200 A14,16 0 0 1 {x+26},200 L{x+26},270 Z" fill="#6f6350"/>'
                f'<rect x="{x-38}" y="140" width="76" height="10" rx="3" fill="#cbbaa0"/></g>')
    cables = ''.join(f'<line x1="{x}" y1="{262 - max(0, 74 - abs(x-640)*0.28):.0f}" x2="{x}" y2="262"/>'
                     for x in range(268, 1024, 26))
    bridge = ('    <g id="brooklyn-bridge">'
              '<path d="M232,206 Q 430,272 640,196" fill="none" stroke="#9a8b74" stroke-width="4"/>'
              '<path d="M640,196 Q 850,272 1050,206" fill="none" stroke="#9a8b74" stroke-width="4"/>'
              f'<g stroke="#9a8b74" stroke-width="1.6" opacity="0.85">{cables}</g>'
              '<rect x="228" y="256" width="828" height="9" fill="#a8977d"/>'
              '<rect x="228" y="264" width="828" height="4" fill="#7d6f5a"/>'
              + bb_tower(330) + bb_tower(950) + '</g>')

    # ---- the far side of the avenue: walk-ups, shopfronts, fire escapes ----
    def walkup(x, y, s, body='#8f6a52', trim='#cfc6b8', awn='#c0392b', name=None):
        floors = ''.join(f'<rect x="{-30+c*24}" y="{-96+r*30}" width="17" height="21" rx="2" '
                         f'fill="#ffe9b8" opacity="0.8"/>' for r in range(2) for c in range(3))
        esc = (f'<g stroke="#4b5158" stroke-width="1.6" fill="none" opacity="0.85">'
               f'<path d="M-34,-100 L34,-100 M-34,-70 L34,-70 M-34,-40 L34,-40"/>'
               f'<path d="M-34,-100 L-34,-36 M34,-100 L34,-36 M-14,-70 L-14,-40"/></g>')
        sign = (f'<rect x="-34" y="-30" width="68" height="12" rx="2" fill="{awn}"/>'
                f'<text x="0" y="-21" text-anchor="middle" font-family="Trebuchet MS,sans-serif" '
                f'font-size="8.5" font-weight="bold" fill="#ffe9c2">{name}</text>' if name else '')
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-36" y="-112" width="72" height="112" fill="{body}"/>'
                f'<rect x="-36" y="-112" width="18" height="112" fill="#ffffff" opacity="0.08"/>'
                f'<rect x="-40" y="-120" width="80" height="9" rx="2" fill="{trim}"/>'
                f'<g>{floors}</g>{esc}'
                f'<rect x="-36" y="-18" width="72" height="18" fill="#4b4038"/>'
                f'<rect x="-30" y="-14" width="26" height="14" rx="2" fill="#9fd0e8" opacity="0.8"/>'
                f'<rect x="6" y="-14" width="22" height="14" rx="2" fill="#3f3630"/>'
                f'<path d="M-38,-20 L38,-20 L32,-30 L-32,-30 Z" fill="{awn}"/>'
                f'{sign}</g>')
    avenue = ('    ' + ''.join(
        walkup(x, 402, 0.72, b, '#cfc6b8', a, n) for x, b, a, n in
        [(40, '#8f6a52', '#c0392b', 'DELI'), (132, '#7d6a5c', '#3f6b8f', None),
         (224, '#9a6a4c', '#4f7d4a', 'PIZZA'), (316, '#816d5e', '#c0392b', None),
         (408, '#8f6a52', '#7a4f8f', 'LAUNDRY'), (500, '#7d6a5c', '#3f6b8f', None),
         (546, '#9a6a4c', '#4f7d4a', None), (726, '#816d5e', '#c0392b', None),
         (780, '#9a6a4c', '#c0392b', 'BODEGA'), (872, '#816d5e', '#4f7d4a', None),
         (964, '#8f6a52', '#3f6b8f', 'BAGELS'), (1056, '#7d6a5c', '#c0392b', None),
         (1148, '#9a6a4c', '#7a4f8f', None), (1240, '#816d5e', '#3f6b8f', 'DINER')])
        # scaffolding over one of them, because this is New York
        + '<g transform="translate(224,402)">'
        '<g stroke="#c9a34a" stroke-width="3" fill="none" opacity="0.95">'
        '<path d="M-30,0 L-30,-40 M30,0 L30,-40 M0,0 L0,-40"/></g>'
        '<rect x="-34" y="-46" width="68" height="7" rx="2" fill="#d8b35c"/>'
        '<rect x="-34" y="-40" width="68" height="3" fill="#a8853a"/></g>')

    # ---- brownstone row with stoops and rooftop water towers ----
    def watertower(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g stroke="#5f4636" stroke-width="3"><path d="M-13,0 L-9,-20 M13,0 L9,-20"/></g>'
                f'<rect x="-15" y="-44" width="30" height="26" rx="2" fill="#8a6a52"/>'
                f'<g fill="#7a5c46">' + ''.join(f'<rect x="-15" y="{-40+i*8}" width="30" height="2"/>' for i in range(3)) + '</g>'
                f'<polygon points="-18,-44 18,-44 0,-58" fill="#6f5442"/></g>')

    def brownstone(x, y, s, body='#a9694a', trim='#d8cfc0'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-46" y="-136" width="92" height="136" fill="{body}"/>'
                f'<rect x="-50" y="-146" width="100" height="12" rx="3" fill="{trim}"/>'
                f'<g fill="{body}" opacity="0.55">'
                + ''.join(f'<rect x="-46" y="{-130+i*14}" width="92" height="1.6"/>' for i in range(9)) + '</g>'
                + ''.join(f'<rect x="{-34+c*32}" y="{-124+r*40}" width="22" height="28" rx="2" fill="#ffe9b8" opacity="0.85"/>'
                          f'<rect x="{-37+c*32}" y="{-128+r*40}" width="28" height="5" rx="2" fill="{trim}"/>'
                          for r in range(2) for c in range(3))
                # stoop
                + f'<rect x="-14" y="-44" width="28" height="44" rx="2" fill="#7a4a34"/>'
                f'<rect x="-11" y="-40" width="22" height="30" rx="2" fill="#5f3a28"/>'
                f'<g fill="{trim}">' + ''.join(f'<rect x="-26" y="{-14+i*5}" width="52" height="4"/>' for i in range(3)) + '</g>'
                + f'<g stroke="#3f434a" stroke-width="2.5" fill="none">'
                f'<path d="M-26,0 L-26,-26 M26,0 L26,-26 M-26,-26 L-14,-30 M26,-26 L14,-30"/></g>'
                + watertower(0, -146, 0.9) + '</g>')

    back = ('    ' + avenue
            + ''.join(brownstone(x, 448, 0.62, c) for x, c in
                      [(38, '#a9694a'), (144, '#8f6a52'), (250, '#a06046'), (356, '#94765c'),
                       (462, '#9c6a4e'), (542, '#8f6a52')])
            + ''.join(brownstone(x, 448, 0.62, c) for x, c in
                      [(738, '#a06046'), (818, '#94765c'), (924, '#a9694a'),
                       (1030, '#8f6a52'), (1136, '#a06046'), (1242, '#94765c')])
            + ''.join(f'<g transform="translate({x},446)"><rect x="-3" y="-58" width="6" height="58" fill="#2f333a"/>'
                      f'<circle cx="0" cy="-62" r="7" fill="#ffe9a8"/></g>' for x in (500, 560, 760, 830))
            + oak(500, 450, 0.36, '#3d7548', '#4a8a56') + oak(788, 450, 0.36, '#3d7548', '#4a8a56'))

    # ---- streets: asphalt, sidewalks, crosswalk, hardly any green ----
    street = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#asphalt)"/>\n'
              '    <g fill="#b4b7bd"><rect x="0" y="404" width="1280" height="36"/>'
              '<rect x="0" y="558" width="1280" height="44"/></g>\n'
              '    <g fill="#c6c9cf"><rect x="0" y="404" width="1280" height="5"/>'
              '<rect x="0" y="558" width="1280" height="5"/></g>\n'
              '    <g fill="#9a9ea5" opacity="0.75">'
              + ''.join(f'<rect x="{x}" y="409" width="2.5" height="31"/>' for x in range(0, 1280, 40))
              + ''.join(f'<rect x="{x}" y="563" width="2.5" height="39"/>' for x in range(18, 1280, 40)) + '</g>\n'
              '    <g fill="#6a6d73"><rect x="0" y="440" width="1280" height="5"/>'
              '<rect x="0" y="602" width="1280" height="5"/></g>\n'
              # lane dashes on the cross street
              '    <g fill="#e8e2c9" opacity="0.45">'
              + ''.join(f'<rect x="{x}" y="376" width="26" height="4"/>' for x in range(0, 1280, 62)) + '</g>')

    def taxi(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 6, 62, 9)}'
                f'<rect x="-58" y="-34" width="116" height="30" rx="8" fill="#f2c230"/>'
                f'<path d="M-34,-34 L-24,-56 L26,-56 L38,-34 Z" fill="#f2c230"/>'
                f'<path d="M-30,-36 L-21,-52 L0,-52 L0,-36 Z" fill="#bfe3f5"/>'
                f'<path d="M4,-36 L4,-52 L24,-52 L34,-36 Z" fill="#bfe3f5"/>'
                f'<rect x="-10" y="-64" width="22" height="9" rx="3" fill="#f2f2ec"/>'
                f'<g fill="#2a2f36"><rect x="-58" y="-16" width="116" height="6"/></g>'
                f'<g fill="#1b1f25"><circle cx="-34" cy="-4" r="11"/><circle cx="34" cy="-4" r="11"/></g>'
                f'<g fill="#8d949c"><circle cx="-34" cy="-4" r="4"/><circle cx="34" cy="-4" r="4"/></g>'
                f'<rect x="-58" y="-30" width="116" height="6" fill="#2a2f36" opacity="0.25"/></g>')

    def subway_ent(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 8, 50, 9)}'
                f'<rect x="-44" y="-6" width="88" height="14" rx="3" fill="#4f545b"/>'
                f'<g fill="#33373d">' + ''.join(f'<rect x="{-38+i*15}" y="-2" width="12" height="7"/>' for i in range(5)) + '</g>'
                f'<g stroke="#c9ced4" stroke-width="4" fill="none" stroke-linecap="round">'
                f'<path d="M-42,-8 L-42,-40"/><path d="M42,-8 L42,-40"/><path d="M-42,-40 L42,-40"/></g>'
                f'<g><rect x="-3" y="-70" width="6" height="30" fill="#3f434a"/>'
                f'<circle cx="0" cy="-76" r="9" fill="#5fbf5f"/>'
                f'<circle cx="-2" cy="-79" r="3" fill="#8fe08f"/></g></g>')

    def steam(x, y):
        return (f'<g transform="translate({x},{y})">'
                f'<ellipse cx="0" cy="0" rx="20" ry="5" fill="#3f434a"/>'
                f'<g fill="#ffffff" opacity="0.5"><ellipse cx="-2" cy="-16" rx="14" ry="9"/>'
                f'<ellipse cx="4" cy="-32" rx="18" ry="11" opacity="0.7"/>'
                f'<ellipse cx="-4" cy="-50" rx="22" ry="13" opacity="0.45"/></g></g>')

    def bus(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 7, 92, 10)}'
                f'<rect x="-96" y="-62" width="192" height="52" rx="7" fill="#5f6b76"/>'
                f'<rect x="-96" y="-62" width="192" height="15" rx="7" fill="#7a8794"/>'
                f'<rect x="-96" y="-34" width="192" height="7" fill="#3f6b8f"/>'
                f'<g fill="#bfe3f5" opacity="0.9">'
                + ''.join(f'<rect x="{-88+i*33}" y="-56" width="26" height="18" rx="2"/>' for i in range(5))
                + f'</g><rect x="-92" y="-58" width="46" height="10" rx="3" fill="#2f333a"/>'
                f'<text x="-69" y="-50" text-anchor="middle" font-family="Trebuchet MS,sans-serif" '
                f'font-size="8" font-weight="bold" fill="#ffe066">M14</text>'
                f'<rect x="16" y="-27" width="34" height="17" fill="#3f4750"/>'
                f'<g fill="#1b1f25"><circle cx="-58" cy="-8" r="12"/><circle cx="56" cy="-8" r="12"/></g>'
                f'<g fill="#8d949c"><circle cx="-58" cy="-8" r="4.5"/><circle cx="56" cy="-8" r="4.5"/></g></g>')

    def cart(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 5, 34, 6)}'
                f'<rect x="-28" y="-30" width="56" height="26" rx="3" fill="#c9ced4"/>'
                f'<rect x="-28" y="-30" width="56" height="6" rx="3" fill="#e2e7ec"/>'
                f'<g fill="#c0392b"><rect x="-30" y="-22" width="60" height="5"/></g>'
                f'<path d="M-34,-34 L34,-34 L26,-52 L-26,-52 Z" fill="#f2b134"/>'
                f'<g fill="#c0392b"><rect x="-26" y="-52" width="52" height="4"/></g>'
                f'<rect x="-1.6" y="-52" width="3.2" height="22" fill="#8d949c"/>'
                f'<g fill="#1b1f25"><circle cx="-16" cy="-2" r="6"/><circle cx="16" cy="-2" r="6"/></g>'
                f'<g fill="#e8eef2" opacity="0.5"><ellipse cx="8" cy="-40" rx="7" ry="4"/>'
                f'<ellipse cx="14" cy="-48" rx="5" ry="3"/></g></g>')

    def pigeon(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="0" cy="0" rx="9" ry="5.5" fill="#8d97a2"/>'
                f'<path d="M-6,-2 L-14,-7 L-3,-4 Z" fill="#6f7a86"/>'
                f'<circle cx="7" cy="-4" r="4" fill="#9aa4ae"/>'
                f'<circle cx="6" cy="-6" r="2.4" fill="#6f9a8f"/>'
                f'<path d="M10,-4 L15,-3 L10,-2 Z" fill="#e8a34a"/>'
                f'<g stroke="#e8a34a" stroke-width="1.4"><path d="M-2,5 L-2,9 M3,5 L3,9"/></g></g>')

    front = ('    ' + bus(980, 596, 0.72) + cart(432, 700, 1.1)
             + ''.join(pigeon(x, y, sc) for x, y, sc in
                       [(348, 712, 1.1), (372, 704, 0.95), (318, 700, 0.9),
                        (1096, 690, 1.05), (1120, 700, 0.9)])
             + taxi(250, 690, 1.1) + subway_ent(1020, 660, 1.05) + steam(830, 700)
             + oak(90, 700, 0.95, '#3d7548', '#4a8a56') + oak(1210, 706, 0.9, '#3d7548', '#4a8a56')
             + ''.join(f'<g transform="translate({x},{y})">'
                       f'<rect x="-3" y="-74" width="7" height="74" fill="#2f333a"/>'
                       f'<circle cx="0" cy="-80" r="9" fill="#ffe9a8"/>'
                       f'<rect x="-9" y="-4" width="19" height="6" rx="2" fill="#2f333a"/></g>'
                       for x, y in [(400, 626), (804, 666), (912, 620)])
             + f'<g transform="translate(470,700)">{shadow(0, 8, 20)}'
             '<rect x="-9" y="-34" width="18" height="40" rx="4" fill="#c0392b"/>'
             '<rect x="-15" y="-24" width="30" height="8" rx="3" fill="#c0392b"/>'
             '<circle cx="0" cy="-38" r="8" fill="#d24a3b"/></g>'
             + f'<g transform="translate(1140,630)">{shadow(0, 6, 40, 8)}'
             '<rect x="-38" y="-14" width="76" height="9" rx="3" fill="#4f6b3f"/>'
             '<rect x="-38" y="-30" width="76" height="8" rx="3" fill="#5d7d4a"/>'
             '<rect x="-32" y="-6" width="8" height="18" fill="#2f333a"/>'
             '<rect x="24" y="-6" width="8" height="18" fill="#2f333a"/></g>')

    scene('nyc', 'NEW YORK CITY — Brooklyn Bridge, Manhattan skyline, brownstones, city streets', {
        'sky': sky('', '', '', sun=(1080, 112, 170)) + '\n' + clouds([(520, 84, 46), (860, 68, 38)], op=0.55)
               + '\n' + birds([(600, 128), (648, 152)]),
        'far': (midrank + '\n' + skyline + '\n' + empire + '\n' + chrysler + '\n' + owtc + '\n' + river
                + '\n    ' + liberty(168, 296, 0.82) + '\n' + bridge),
        'ground': street,
        'scenery-back': back, 'scenery-front': front,
        'foreground': '    <g fill="#7f8288" opacity="0.5"><rect x="0" y="706" width="1280" height="3"/></g>',
    }, d)


# ================================================================= 6. SEATTLE
def seattle():
    """ONE hero: the Space Needle. Everything else is Seattle texture — houseboats on
    the lake, Mount Rainier floating behind the city, evergreen ranges, soft drizzle."""
    d = (sky_defs('#8fa9bd', '#bcccd8', '#dde6e6', '#f0f4f6', '#e6edf0') + '''
    <linearGradient id="sound" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5c8397"/><stop offset="1" stop-color="#8bb0c2"/>
    </linearGradient>
    <linearGradient id="wetst" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#8d9298"/><stop offset="1" stop-color="#767b81"/>
    </linearGradient>''')

    # ---- Rainier: the mountain that floats over the city ----
    rainier = ('    <g id="rainier">'
               '<polygon points="180,268 400,88 500,132 620,268" fill="#aabfd0"/>'
               '<polygon points="400,88 500,132 620,268 470,268" fill="#93a8bb"/>'
               '<polygon points="400,88 352,142 382,134 402,156 428,132 456,144 500,132 452,102" fill="#f6fbfd"/>'
               '<polygon points="366,160 402,156 428,132 456,144 486,156 456,180 410,184 380,172" fill="#e6f0f6"/>'
               '<polygon points="352,142 382,134 366,160" fill="#dce8f0"/>'
               '</g>')
    # sibling summits: Rainier never stands alone on that skyline
    def peak(pts, snow, body='#b9cbd9', shade='#a1b5c6'):
        return (f'<polygon points="{pts}" fill="{body}"/>'
                f'<polygon points="{snow}" fill="#eef5f9"/>')
    siblings = ('    <g opacity="0.85">'
                + peak('-40,272 60,178 118,206 196,272', '60,178 34,204 52,200 66,214 84,200 106,208 118,206 88,188')
                + peak('120,274 214,196 262,218 330,274', '214,196 194,216 208,213 219,224 234,213 250,220 262,218 238,205')
                + peak('560,272 646,184 700,210 772,272', '646,184 624,206 638,203 650,216 666,203 684,211 700,210 674,195')
                + peak('980,276 1046,214 1086,232 1140,276', '1046,214 1030,230 1041,228 1050,238 1062,228 1076,234 1086,232 1066,222')
                + '</g>')

    ranges = ('    <polygon points="-20,270 90,232 210,258 340,226 470,254 600,228 740,256 880,230 '
              '1010,258 1140,232 1280,256 1300,270 1300,300 -20,300" fill="#4f7a5c"/>\n'
              '    <polygon points="-20,270 90,232 210,258 300,300 -20,300" fill="#446a50" opacity="0.55"/>\n'
              '    <polygon points="700,262 820,236 940,260 1060,238 1180,262 1300,240 1300,300 700,300" '
              'fill="#3f6b4e" opacity="0.5"/>')

    # evergreen treeline along the ridges — Seattle's hills are covered in firs
    def treeline(y0, h, col, step, op, jitter=5, seed=1013):
        out = []
        x, sd = -12, seed
        while x < 1292:
            sd = (sd * 1103515245 + 12345) % 2147483648
            r = sd % 1000
            hh = h + (r % 7) - 3
            yy = y0 + (r % jitter) - jitter // 2
            w = hh * 0.42
            out.append(f'<polygon points="{x},{yy} {x + w:.1f},{yy - hh} {x + w * 2:.1f},{yy}"/>')
            x += step + (r % 4)
        return f'<g fill="{col}" opacity="{op}">' + ''.join(out) + '</g>'
    firline = ('    ' + treeline(252, 24, '#2f5c44', 9, 0.9, 6, 6101)
               + '\n    ' + treeline(240, 17, '#3a6b4f', 7, 0.7, 5, 2237)
               + '\n    ' + treeline(230, 12, '#48795c', 6, 0.45, 4, 9091))

    # ---- the Space Needle: the hero, big and central ----
    NX = 800
    needle = (f'    <g id="space-needle">'
              f'<path d="M{NX-72},300 C {NX-42},238 {NX-20},204 {NX-13},166 L{NX-2},166 '
              f'C {NX-9},206 {NX-26},252 {NX-50},300 Z" fill="#cbd4da"/>'
              f'<path d="M{NX+72},300 C {NX+42},238 {NX+20},204 {NX+13},166 L{NX+2},166 '
              f'C {NX+9},206 {NX+26},252 {NX+50},300 Z" fill="#adb8c0"/>'
              f'<rect x="{NX-9}" y="166" width="18" height="134" fill="#d3dae0"/>'
              f'<rect x="{NX-9}" y="166" width="7" height="134" fill="#e2e8ec"/>'
              f'<g stroke="#98a4ad" stroke-width="4" opacity="0.85">'
              f'<path d="M{NX-42},244 L{NX+42},244"/><path d="M{NX-28},206 L{NX+28},206"/></g>'
              f'<rect x="{NX-13}" y="150" width="26" height="18" fill="#bcc6ce"/>'
              f'<ellipse cx="{NX}" cy="144" rx="62" ry="12" fill="#dde4e9"/>'
              f'<path d="M{NX-62},144 A62,12 0 0 0 {NX+62},144 L{NX+42},161 '
              f'A42,9 0 0 1 {NX-42},161 Z" fill="#b9852f"/>'
              f'<ellipse cx="{NX}" cy="136" rx="48" ry="10" fill="#f0f4f7"/>'
              f'<ellipse cx="{NX}" cy="128" rx="28" ry="7" fill="#cbd4da"/>'
              f'<rect x="{NX-2}" y="96" width="5" height="34" fill="#98a4ad"/>'
              f'<circle cx="{NX}" cy="92" r="6" fill="#c0392b"/></g>')
    def tower(x, y, w, h, base='#8e9daa', lit='#a2b0bc', win='#cfe0ea', step=12):
        wins = ''.join(f'<rect x="{x+4}" y="{y+8+r*step}" width="{w-8}" height="4"/>'
                       for r in range(int((h - 12) // step)))
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="2" fill="{base}"/>'
                f'<rect x="{x}" y="{y}" width="{w*0.32:.0f}" height="{h}" fill="{lit}"/>'
                f'<g fill="{win}" opacity="0.45">{wins}</g>')
    RIGHT = [(902,206,26,94),(932,178,22,122),(958,218,30,82),(992,192,24,108),
             (1020,224,28,76),(1084,206,30,94),(1118,184,22,116),(1144,220,28,80),
             (1176,196,24,104),(1204,214,30,86),(1240,182,22,118)]
    LEFT = [(604,236,22,64),(630,216,18,84),(652,240,24,60),(680,224,20,76),(704,246,22,54)]
    downtown = ('    <g>' + ''.join(tower(*t) for t in RIGHT)
                + ''.join(tower(*t, '#9aa8b4', '#adb9c4') for t in LEFT) + '</g>\n'
                # Columbia Center — the dark slab that anchors the Seattle skyline
                '    <g><rect x="1046" y="150" width="34" height="150" fill="#4e5a66"/>'
                '<rect x="1046" y="150" width="12" height="150" fill="#616e7a"/>'
                '<rect x="1052" y="142" width="22" height="10" rx="3" fill="#44505c"/>'
                '<g fill="#cfe0ea" opacity="0.35">'
                + ''.join(f'<rect x="1050" y="{162+r*12}" width="26" height="4"/>' for r in range(11))
                + '</g></g>\n'
                '')

    # ---- the lake, with houseboats ----
    lake = ('    <rect x="0" y="262" width="1280" height="34" fill="url(#sound)"/>'
            '<g fill="#ffffff" opacity="0.25">'
            + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2" rx="1"/>'
                      for x, y, w in [(90, 276, 70), (420, 286, 90), (900, 272, 76), (1150, 288, 60)]) + '</g>')

    def houseboat(x, y, s=1.0, body='#d9a05b', roof='#4f6f5f', trim='#fbf6ea', kayak='#e8574a'):
        bulbs = ''.join(f'<circle cx="{-44 + i*11}" cy="{-52 + abs(i-4)*1.6:.1f}" r="2.2" fill="#ffe9a8"/>'
                        for i in range(9))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                # reflection in the water
                f'<g opacity="0.16" transform="translate(0,10) scale(1,-0.45)">'
                f'<rect x="-46" y="-56" width="92" height="56" fill="{body}"/></g>'
                # float / pontoon
                f'<rect x="-52" y="-2" width="104" height="10" rx="3" fill="#4a4038"/>'
                f'<rect x="-52" y="-2" width="104" height="3" rx="1.5" fill="#6b5c4c"/>'
                # deck
                f'<rect x="-52" y="-8" width="104" height="7" rx="2" fill="#a98b66"/>'
                f'<g stroke="#8d724f" stroke-width="1" opacity="0.7">'
                + ''.join(f'<line x1="{-48+i*10}" y1="-8" x2="{-48+i*10}" y2="-1"/>' for i in range(11)) + '</g>'
                # lower storey
                f'<rect x="-38" y="-46" width="76" height="38" fill="{body}"/>'
                f'<rect x="-38" y="-46" width="20" height="38" fill="#ffffff" opacity="0.13"/>'
                f'<g fill="#000" opacity="0.07">'
                + ''.join(f'<rect x="-38" y="{-40+i*9}" width="76" height="1.6"/>' for i in range(4)) + '</g>'
                f'<rect x="-31" y="-40" width="20" height="17" rx="2" fill="#ffe9b8"/>'
                f'<rect x="-6" y="-40" width="20" height="17" rx="2" fill="#ffe9b8"/>'
                f'<rect x="19" y="-38" width="14" height="30" rx="2" fill="{trim}"/>'
                f'<rect x="22" y="-34" width="8" height="10" rx="1.5" fill="#cfe6f0"/>'
                # upper storey, set back, with a roof deck
                f'<rect x="-28" y="-72" width="54" height="27" fill="{body}"/>'
                f'<rect x="-28" y="-72" width="15" height="27" fill="#ffffff" opacity="0.13"/>'
                f'<rect x="-22" y="-66" width="18" height="14" rx="2" fill="#ffe9b8"/>'
                f'<rect x="2" y="-66" width="18" height="14" rx="2" fill="#ffe9b8"/>'
                f'<polygon points="-34,-72 -1,-88 32,-72" fill="{roof}"/>'
                f'<polygon points="-34,-72 -1,-88 -10,-88 -26,-72" fill="#ffffff" opacity="0.12"/>'
                f'<rect x="-36" y="-74" width="68" height="5" rx="2" fill="#3f5a4d"/>'
                # chimney + smoke
                f'<rect x="14" y="-98" width="7" height="14" fill="#6f6156"/>'
                f'<g fill="#e8eef2" opacity="0.55"><circle cx="18" cy="-106" r="5"/>'
                f'<circle cx="24" cy="-117" r="6.5"/><circle cx="18" cy="-129" r="8"/></g>'
                # deck rail, string lights, planters, a kayak on the rail
                f'<g stroke="{trim}" stroke-width="2" fill="none">'
                f'<path d="M-52,-8 L-52,-22 M52,-8 L52,-22 M-52,-22 L52,-22 M-52,-15 L52,-15"/>'
                f'<path d="M-30,-8 L-30,-22 M0,-8 L0,-22 M30,-8 L30,-22"/></g>'
                f'<path d="M-46,-50 Q -1,-58 44,-50" stroke="#8d8578" stroke-width="1" fill="none"/>'
                f'<g transform="translate(0,-2)">{bulbs}</g>'
                f'<g fill="#4f8a54"><ellipse cx="-46" cy="-14" rx="8" ry="6"/>'
                f'<ellipse cx="46" cy="-13" rx="7" ry="5"/></g>'
                f'<g fill="#c0392b"><rect x="-50" y="-11" width="8" height="4" rx="1"/>'
                f'<rect x="42" y="-10" width="8" height="4" rx="1"/></g>'
                f'<g transform="translate(-34,-16) rotate(-8)">'
                f'<ellipse cx="0" cy="0" rx="26" ry="4.5" fill="{kayak}"/>'
                f'<ellipse cx="0" cy="-1" rx="9" ry="2.2" fill="#3f4750"/></g></g>')

    # the dock they are all tied to
    dock = ('    <rect x="30" y="276" width="560" height="6" rx="2" fill="#8a7358"/>'
            '<rect x="30" y="274" width="560" height="3" rx="1.5" fill="#a3886a"/>'
            + ''.join(f'<rect x="{x}" y="280" width="4" height="12" fill="#6b5942" opacity="0.7"/>'
                      for x in range(40, 590, 70))
            + ''.join(f'<rect x="{x}" y="264" width="5" height="16" rx="2" fill="#6b5942"/>'
                      for x in (34, 176, 318, 460, 582)))

    def ferry(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g opacity="0.16" transform="translate(0,6) scale(1,-0.4)">'
                f'<rect x="-40" y="-16" width="80" height="16" fill="#f2f2ec"/></g>'
                f'<path d="M-44,-8 L44,-8 L38,4 L-38,4 Z" fill="#e8e8e0"/>'
                f'<rect x="-40" y="-20" width="80" height="12" rx="2" fill="#f6f6f0"/>'
                f'<g fill="#7fa8bd">' + ''.join(f'<rect x="{-35+i*10}" y="-17" width="6" height="6"/>'
                                                for i in range(8)) + '</g>'
                f'<rect x="-16" y="-30" width="34" height="11" rx="2" fill="#fbfbf6"/>'
                f'<rect x="-4" y="-40" width="5" height="11" fill="#41474f"/>'
                f'<rect x="-44" y="-9" width="88" height="3" fill="#2f6f4f"/></g>')

    boats = ('    ' + dock + houseboat(96, 283, 0.86, '#d98f4f', '#4f6f5f', '#fbf6ea', '#e8574a')
             + houseboat(222, 285, 0.9, '#6fa8bf', '#5a5f7a', '#fbf6ea', '#f2b134')
             + houseboat(352, 283, 0.86, '#d9736b', '#4f6f5f', '#fbf6ea', '#7bc86c')
             + houseboat(478, 285, 0.9, '#8fbf7f', '#6a5f4a', '#fbf6ea', '#4fb8d6')
             + ferry(1160, 280, 0.95)
             # a little dinghy out on the open water
             + '<g transform="translate(662,286)"><path d="M-16,0 L16,0 L12,6 L-12,6 Z" fill="#f2ede0"/>'
             '<rect x="-2" y="-15" width="3" height="15" fill="#7a6350"/>'
             '<path d="M1,-15 L11,-2 L1,-2 Z" fill="#dfe8ee"/></g>')

    # ---- quay + wet waterfront street ----
    quay = ('    <rect x="0" y="292" width="1280" height="4" fill="#6f5f4c"/>'
            '<rect x="0" y="296" width="1280" height="10" fill="#a8977d"/>'
            '<g fill="#8a7a63" opacity="0.65">'
            + ''.join(f'<rect x="{x}" y="296" width="2" height="10"/>' for x in range(0, 1280, 26)) + '</g>'
            + ''.join(f'<g transform="translate({x},292)"><rect x="-3" y="-20" width="6" height="20" fill="#2f333a"/>'
                      f'<circle cx="0" cy="-23" r="4" fill="#ffe9a8"/></g>' for x in range(70, 1280, 130)))
    drizzle = ('    <g stroke="#cfdde6" stroke-width="1.6" opacity="0.3">'
               + ''.join(f'<line x1="{x}" y1="{(x*37) % 190 + 30}" x2="{x-6}" y2="{(x*37) % 190 + 62}"/>'
                         for x in range(24, 1280, 41)) + '</g>')
    street = ('    <rect x="0" y="306" width="1280" height="414" fill="url(#wetst)"/>\n'
              # a green waterfront park strip between the quay and the buildings
              '    <rect x="0" y="306" width="1280" height="72" fill="#5d8a4f"/>\n'
              '    <rect x="0" y="306" width="1280" height="6" fill="#6d9c5c"/>\n'
              '    <g fill="#6d9c5c" opacity="0.55">'
              + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.3:.0f}"/>'
                        for x, y, r in [(90, 350, 60), (330, 336, 48), (560, 352, 54),
                                        (820, 338, 50), (1080, 352, 58), (1240, 340, 44)]) + '</g>\n'
              # a gravel path threading through the park
              '    <rect x="0" y="356" width="1280" height="9" fill="#b0a894" opacity="0.75"/>\n'
              '    <g fill="#9c937f" opacity="0.5">'
              + ''.join(f'<rect x="{x}" y="357" width="7" height="7" rx="2"/>' for x in range(0, 1280, 26)) + '</g>\n'
              # shrubs and benches along it
              + ''.join(f'<g transform="translate({x},352)">'
                        f'<ellipse cx="0" cy="0" rx="18" ry="11" fill="#3f7a48"/>'
                        f'<ellipse cx="-8" cy="-5" rx="11" ry="7" fill="#4d8b56"/></g>'
                        for x in (150, 420, 700, 900, 1160)) + '\n'
              + ''.join(f'<g transform="translate({x},374)">'
                        f'<rect x="-16" y="-6" width="32" height="4" rx="2" fill="#7a5a3a"/>'
                        f'<rect x="-16" y="-13" width="32" height="4" rx="2" fill="#8a6a45"/>'
                        f'<rect x="-13" y="-2" width="3" height="7" fill="#41474f"/>'
                        f'<rect x="10" y="-2" width="3" height="7" fill="#41474f"/></g>'
                        for x in (250, 620, 1020)) + '\n'
              '    <rect x="0" y="378" width="1280" height="4" fill="#6d7076"/>\n'
              '    <g fill="#aab0b4"><rect x="0" y="406" width="1280" height="34"/>'
              '<rect x="0" y="560" width="1280" height="44"/></g>\n'
              '    <g fill="#bcc2c5"><rect x="0" y="406" width="1280" height="5"/>'
              '<rect x="0" y="560" width="1280" height="5"/></g>\n'
              '    <g fill="#93999d" opacity="0.7">'
              + ''.join(f'<rect x="{x}" y="411" width="2.5" height="29"/>' for x in range(0, 1280, 40))
              + ''.join(f'<rect x="{x}" y="565" width="2.5" height="39"/>' for x in range(18, 1280, 40)) + '</g>\n'
              '    <g fill="#666b70"><rect x="0" y="440" width="1280" height="5"/>'
              '<rect x="0" y="604" width="1280" height="5"/></g>\n'
              '    <rect x="0" y="624" width="1280" height="46" fill="#4f7a48"/>\n'
              '    <rect x="0" y="624" width="1280" height="5" fill="#5d8a53"/>\n'
              '    <g fill="#ffffff" opacity="0.10">'
              + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.22:.0f}"/>'
                        for x, y, r in [(200, 486, 90), (640, 528, 120), (1050, 494, 100),
                                        (380, 690, 110), (900, 700, 96)]) + '</g>')

    fir = lambda x, y, s: conifer(x, y, s, '#24543a', '#2e6746', '#387a53', '#4a3320')

    # ---- waterfront sheds: the fabric every other scene has behind its tracks ----
    def shed(x, y, s, body='#8a7a66', roof='#3f6b56', sign=None, sign_col='#c0392b'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-62" y="-104" width="124" height="104" fill="{body}"/>'
                f'<rect x="-62" y="-104" width="26" height="104" fill="#ffffff" opacity="0.10"/>'
                f'<g fill="#000" opacity="0.10">'
                + ''.join(f'<rect x="-62" y="{-96+i*13}" width="124" height="2"/>' for i in range(8)) + '</g>'
                + f'<polygon points="-70,-104 0,-140 70,-104" fill="{roof}"/>'
                f'<polygon points="-70,-104 0,-140 -10,-140 -58,-104" fill="#4f7d66"/>'
                f'<rect x="-72" y="-108" width="144" height="8" rx="2" fill="#5f5347"/>'
                + ''.join(f'<rect x="{-46+c*34}" y="-88" width="24" height="26" rx="2" fill="#cfe4ee"/>'
                          f'<rect x="{-46+c*34}" y="-88" width="24" height="9" rx="2" fill="#e2f0f7"/>' for c in range(3))
                + f'<rect x="-20" y="-46" width="40" height="46" rx="2" fill="#5f5347"/>'
                f'<rect x="-15" y="-40" width="30" height="34" rx="2" fill="#48403a"/>'
                + (f'<rect x="-44" y="-130" width="88" height="20" rx="3" fill="{sign_col}"/>'
                   f'<text x="0" y="-115" text-anchor="middle" font-family="Trebuchet MS,sans-serif" '
                   f'font-size="13" font-weight="bold" fill="#ffe9b8">{sign}</text>' if sign else '')
                + '</g>')

    def crates(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 34)}'
                f'<rect x="-28" y="-24" width="26" height="24" rx="2" fill="#a88b62"/>'
                f'<rect x="2" y="-20" width="24" height="20" rx="2" fill="#947953"/>'
                f'<rect x="-16" y="-42" width="24" height="20" rx="2" fill="#b89a70"/>'
                f'<g stroke="#7a6244" stroke-width="2" fill="none">'
                f'<path d="M-28,-14 L-2,-14 M2,-12 L26,-12 M-16,-32 L8,-32"/></g></g>')

    def crabpot(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 24)}'
                f'<rect x="-20" y="-22" width="40" height="22" rx="4" fill="none" stroke="#6f6f66" stroke-width="3"/>'
                f'<g stroke="#8a8a80" stroke-width="1.6">'
                f'<path d="M-20,-14 L20,-14 M-20,-6 L20,-6 M-10,-22 L-10,0 M0,-22 L0,0 M10,-22 L10,0"/></g>'
                f'<circle cx="16" cy="-26" r="5" fill="#e8574a"/></g>')

    def gull(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="0" cy="0" rx="11" ry="6" fill="#f4f7f9"/>'
                f'<path d="M-8,-2 L-16,-8 L-4,-4 Z" fill="#d7dee3"/>'
                f'<circle cx="9" cy="-4" r="4.5" fill="#f4f7f9"/>'
                f'<path d="M13,-4 L19,-2 L13,-1 Z" fill="#f2b134"/>'
                f'<circle cx="10" cy="-5" r="1" fill="#2f333a"/>'
                f'<g stroke="#f2b134" stroke-width="1.6"><path d="M-2,6 L-2,11 M4,6 L4,11"/></g></g>')

    back = ('    ' + shed(90, 448, 0.62, '#8a7a66', '#3f6b56', 'FISH')
            + shed(212, 448, 0.62, '#7d7060', '#6b4f3f')
            + shed(334, 448, 0.62, '#8f8068', '#3f6b56', 'COFFEE', '#3f6b56')
            + shed(452, 448, 0.6, '#79705f', '#6b4f3f')
            + shed(846, 448, 0.6, '#8a7a66', '#6b4f3f')
            + shed(968, 448, 0.62, '#8f8068', '#3f6b56', 'MARKET')
            + shed(1090, 448, 0.62, '#7d7060', '#6b4f3f')
            + shed(1212, 448, 0.62, '#8a7a66', '#3f6b56')
            + fir(546, 400, 0.8) + fir(600, 404, 0.7) + fir(700, 402, 0.75) + fir(780, 400, 0.8)
            + ''.join(f'<g transform="translate({x},446)"><rect x="-3" y="-56" width="6" height="56" fill="#2f333a"/>'
                      f'<circle cx="0" cy="-60" r="7" fill="#ffe9a8"/></g>' for x in (560, 740))
            + gull(620, 372, 0.8) + gull(672, 366, 0.7) + gull(806, 376, 0.75))
    front = ('    ' + fir(58, 646, 1.95) + fir(1240, 656, 1.9)
             + crates(210, 636, 1.15) + crates(1090, 660, 1.05) + crates(470, 700, 1.0)
             + crabpot(330, 626, 1.15) + crabpot(392, 640, 0.95) + crabpot(1010, 700, 1.1)
             + gull(486, 596, 1.1) + gull(880, 610, 1.0)
             + ''.join(f'<g transform="translate({x},{y})">{shadow(0, 6, 34)}'
                       f'<ellipse cx="0" cy="-14" rx="34" ry="18" fill="#3f7a48"/>'
                       f'<ellipse cx="-14" cy="-20" rx="20" ry="12" fill="#4d8b56"/>'
                       f'<ellipse cx="14" cy="-18" rx="18" ry="11" fill="#4d8b56"/></g>'
                       for x, y in [(320, 664), (966, 692)])
             + f'<g transform="translate(1010,648)">{shadow(0, 8, 44, 8)}'
             '<polygon points="-40,8 -30,-16 -8,-26 18,-22 38,-4 40,8" fill="#8d949c"/>'
             '<polygon points="-8,-26 18,-22 38,-4 6,-2 -12,-12" fill="#a3aab2"/>'
             '<g fill="#6f9a5e" opacity="0.85"><circle cx="-22" cy="-4" r="6"/><circle cx="24" cy="-8" r="5"/></g></g>'
             + ''.join(f'<g transform="translate({x},{y})">'
                       f'<rect x="-3" y="-72" width="7" height="72" fill="#2f333a"/>'
                       f'<circle cx="0" cy="-78" r="9" fill="#ffe9a8"/>'
                       f'<rect x="-9" y="-4" width="19" height="6" rx="2" fill="#2f333a"/></g>'
                       for x, y in [(400, 634), (808, 672), (896, 628)])
             + f'<g transform="translate(428,700)">{shadow(0, 6, 44, 8)}'
             '<rect x="-42" y="-14" width="84" height="9" rx="3" fill="#4f6b3f"/>'
             '<rect x="-42" y="-30" width="84" height="8" rx="3" fill="#5d7d4a"/>'
             '<rect x="-36" y="-6" width="8" height="18" fill="#2f333a"/>'
             '<rect x="28" y="-6" width="8" height="18" fill="#2f333a"/></g>')

    scene('seattle', 'SEATTLE — the Space Needle over houseboats, Mount Rainier, evergreen ranges', {
        'sky': sky('', '', '') + '\n' + clouds([(240, 74, 60), (620, 58, 52), (1000, 80, 58)],
                                                fill='#e8eef2', op=0.85) + '\n' + drizzle,
        'far': (siblings + '\n' + rainier + '\n' + ranges + '\n' + firline + '\n' + downtown
                + '\n' + needle + '\n' + lake + '\n' + boats + '\n' + quay),
        'ground': street,
        'scenery-back': back, 'scenery-front': front,
        'foreground': '    <g fill="#7a7f84" opacity="0.5"><rect x="0" y="706" width="1280" height="3"/></g>',
    }, d)


# ============================================================= 7. NEW ORLEANS
def new_orleans():
    d = (sky_defs('#f0a45e', '#f9cf9c', '#fdeccb', '#fff2cc', '#ffd89a') + '\n'
         + grass_defs('#78a552', '#5a8140') + '''
    <linearGradient id="river" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#a8a17f"/><stop offset="1" stop-color="#7e8468"/>
    </linearGradient>
    <linearGradient id="pave" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#c7c0b2"/><stop offset="1" stop-color="#aaa295"/>
    </linearGradient>''')

    # ---- the Mississippi. New Orleans is FLAT — sea level, no hills. A levee,
    # a low treeline and a wide muddy river are the whole horizon. ----
    dome = ('<g><ellipse cx="520" cy="238" rx="52" ry="26" fill="#e6e6e0"/>'
            '<ellipse cx="520" cy="234" rx="52" ry="22" fill="#f2f2ec"/>'
            '<rect x="468" y="238" width="104" height="12" fill="#cfcfc6"/></g>')
    T = [(300,222,20,34),(326,208,17,48),(348,226,22,30),(376,214,16,42),(398,230,20,26),
         (760,224,18,32),(784,212,16,44),(806,228,20,28),(832,218,15,38)]
    skyline = ('<g fill="#9aa89a" opacity="0.75">'
               + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="2"/>' for x, y, w, h in T)
               + '</g>')
    treeline = ('    <rect x="0" y="252" width="1280" height="14" fill="#46664a"/>\n'
                '    <g fill="#4d704f">'
                + ''.join(f'<ellipse cx="{x}" cy="252" rx="34" ry="13"/>' for x in range(-10, 1300, 62))
                + '</g>\n    ' + dome + skyline)
    levee = ('    <rect x="0" y="262" width="1280" height="14" fill="#6f8f57"/>'
             '<rect x="0" y="262" width="1280" height="5" fill="#7fa062"/>')
    river = ('    <rect x="0" y="274" width="1280" height="28" fill="url(#river)"/>'
             '<g fill="#c9c9a8" opacity="0.45"><ellipse cx="240" cy="296" rx="140" ry="3"/>'
             '<ellipse cx="900" cy="290" rx="170" ry="3"/><ellipse cx="560" cy="283" rx="110" ry="2.5"/>'
             '<ellipse cx="1150" cy="298" rx="120" ry="3"/></g>')
    boat = ('    <g transform="translate(1010,300)">'
            '<rect x="-78" y="-30" width="156" height="16" rx="3" fill="#f4efe4"/>'
            '<rect x="-68" y="-44" width="136" height="15" rx="3" fill="#fbf7ee"/>'
            '<rect x="-52" y="-56" width="104" height="13" rx="3" fill="#f4efe4"/>'
            '<g fill="#cfe0ea">' + ''.join(f'<rect x="{-62+i*16}" y="-41" width="9" height="8"/>' for i in range(9))
            + ''.join(f'<rect x="{-46+i*16}" y="-53" width="9" height="7"/>' for i in range(7)) + '</g>'
            '<g fill="#2f3a44"><rect x="-16" y="-78" width="7" height="24"/><rect x="6" y="-78" width="7" height="24"/></g>'
            '<rect x="-20" y="-82" width="15" height="5" rx="2" fill="#a63a2c"/>'
            '<rect x="2" y="-82" width="15" height="5" rx="2" fill="#a63a2c"/>'
            '<g><circle cx="-84" cy="-20" r="17" fill="#a63a2c"/><circle cx="-84" cy="-20" r="8" fill="#c05040"/>'
            '<g stroke="#8e2f22" stroke-width="3"><line x1="-101" y1="-20" x2="-67" y2="-20"/>'
            '<line x1="-84" y1="-37" x2="-84" y2="-3"/><line x1="-96" y1="-32" x2="-72" y2="-8"/>'
            '<line x1="-72" y1="-32" x2="-96" y2="-8"/></g></g>'
            '<rect x="-80" y="-16" width="160" height="6" rx="2" fill="#a63a2c"/></g>')

    # ---- St. Louis Cathedral: three white spires, the signature silhouette ----
    def spire(x, y, w, hgt, top):
        return (f'<rect x="{x-w/2}" y="{y-hgt}" width="{w}" height="{hgt}" fill="#f6f1e4"/>'
                f'<rect x="{x-w/2}" y="{y-hgt}" width="{w*0.36:.0f}" height="{hgt}" fill="#fffdf6"/>'
                f'<polygon points="{x-w/2-3},{y-hgt} {x+w/2+3},{y-hgt} {x},{top}" fill="#6f7d86"/>'
                f'<polygon points="{x-w/2-3},{y-hgt} {x},{y-hgt} {x},{top}" fill="#87949c"/>'
                f'<rect x="{x-1.5}" y="{top-14}" width="3" height="14" fill="#8e9aa2"/>'
                f'<path d="M{x-5},{top-9} L{x+5},{top-9} M{x},{top-15} L{x},{top-3}" stroke="#d4a943" stroke-width="2"/>')
    CX = 268
    cathedral = ('    <g id="cathedral">'
                 f'<rect x="{CX-84}" y="-0" width="168" height="0" fill="none"/>'
                 # main block
                 f'<rect x="{CX-78}" y="330" width="156" height="112" fill="#f6f1e4"/>'
                 f'<rect x="{CX-78}" y="330" width="46" height="112" fill="#fffdf6"/>'
                 f'<polygon points="{CX-78},330 {CX},292 {CX+78},330" fill="#efe8d8"/>'
                 # doors + rose window
                 + ''.join(f'<rect x="{CX-52+i*44}" y="382" width="28" height="60" rx="14" fill="#7a5a45"/>'
                           f'<rect x="{CX-48+i*44}" y="386" width="20" height="52" rx="10" fill="#8d6a52"/>' for i in range(3))
                 + f'<circle cx="{CX}" cy="348" r="15" fill="#cfe0ea"/>'
                 f'<circle cx="{CX}" cy="348" r="15" fill="none" stroke="#d4a943" stroke-width="2"/>'
                 f'<path d="M{CX-15},348 L{CX+15},348 M{CX},333 L{CX},363" stroke="#d4a943" stroke-width="2"/>'
                 # clock on the central tower
                 + spire(CX, 330, 40, 118, 128)
                 + f'<circle cx="{CX}" cy="248" r="13" fill="#f2ede0" stroke="#8e9aa2" stroke-width="2"/>'
                 f'<path d="M{CX},248 L{CX},240 M{CX},248 L{CX+6},251" stroke="#3f4a44" stroke-width="2"/>'
                 + spire(CX - 66, 344, 28, 74, 210) + spire(CX + 66, 344, 28, 74, 210)
                 + '</g>')

    # ---- French Quarter row: ornate double galleries ----
    def quarter(x, y, s, body, shutter, trim='#f6f1e4'):
        def rail(yy):
            posts = ''.join(f'<line x1="{-62+i*9}" y1="{yy}" x2="{-62+i*9}" y2="{yy+17}"/>' for i in range(15))
            scroll = ''.join(f'<path d="M{-58+i*18},{yy+3} q9,7 18,0" />' for i in range(7))
            return (f'<g stroke="#333d36" stroke-width="1.8" fill="none">{posts}{scroll}</g>'
                    f'<rect x="-66" y="{yy-3}" width="132" height="4" fill="#333d36"/>'
                    f'<rect x="-66" y="{yy+16}" width="132" height="4" fill="#333d36"/>')
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-64" y="-176" width="128" height="176" fill="{body}"/>'
                f'<rect x="-64" y="-176" width="30" height="176" fill="#ffffff" opacity="0.13"/>'
                # cornice + dormer roof
                f'<rect x="-70" y="-186" width="140" height="12" rx="3" fill="{trim}"/>'
                f'<polygon points="-58,-186 -34,-208 -10,-186" fill="#7c8a80"/>'
                f'<rect x="-40" y="-200" width="12" height="14" rx="2" fill="#dff0f6"/>'
                f'<polygon points="18,-186 42,-208 66,-186" fill="#7c8a80"/>'
                f'<rect x="36" y="-200" width="12" height="14" rx="2" fill="#dff0f6"/>'
                # upper storey: tall shuttered doors behind the gallery
                + ''.join(f'<rect x="{-50+c*34}" y="-166" width="24" height="52" rx="11" fill="{trim}"/>'
                          f'<rect x="{-47+c*34}" y="-163" width="18" height="46" rx="9" fill="#cfe0ea"/>'
                          f'<rect x="{-52+c*34}" y="-166" width="7" height="52" rx="3" fill="{shutter}"/>'
                          f'<rect x="{-28+c*34}" y="-166" width="7" height="52" rx="3" fill="{shutter}"/>' for c in range(3))
                + rail(-124)
                # lower storey
                + ''.join(f'<rect x="{-50+c*34}" y="-96" width="24" height="60" rx="11" fill="{trim}"/>'
                          f'<rect x="{-47+c*34}" y="-93" width="18" height="54" rx="9" fill="#cfe0ea"/>'
                          f'<rect x="{-52+c*34}" y="-96" width="7" height="60" rx="3" fill="{shutter}"/>'
                          f'<rect x="{-28+c*34}" y="-96" width="7" height="60" rx="3" fill="{shutter}"/>' for c in range(3))
                + rail(-54)
                # gallery posts + hanging ferns
                + '<g stroke="#333d36" stroke-width="3"><line x1="-62" y1="-104" x2="-62" y2="-54"/>'
                '<line x1="0" y1="-104" x2="0" y2="-54"/><line x1="62" y1="-104" x2="62" y2="-54"/></g>'
                + '<g fill="#4f8a54"><ellipse cx="-32" cy="-112" rx="13" ry="9"/><ellipse cx="32" cy="-112" rx="12" ry="8"/></g>'
                + '</g>')

    row = ('    ' + quarter(892, 446, 0.6, '#f0cfa2', '#4f7a5e')
           + quarter(1008, 446, 0.6, '#e9bfc0', '#5d6f8a')
           + quarter(1124, 446, 0.6, '#cfe0c2', '#7a5a45')
           + quarter(1236, 446, 0.6, '#f2ddb4', '#4f7a5e'))

    def gaslamp(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-3" y="-58" width="6" height="58" fill="#333d36"/>'
                f'<rect x="-8" y="-2" width="16" height="6" rx="2" fill="#333d36"/>'
                f'<polygon points="-9,-58 9,-58 6,-76 -6,-76" fill="#ffe9a8"/>'
                f'<polygon points="-9,-58 0,-58 0,-76 -6,-76" fill="#fff6d0"/>'
                f'<polygon points="-11,-76 11,-76 0,-88" fill="#333d36"/>'
                f'<circle cx="0" cy="-90" r="3" fill="#333d36"/></g>')

    moss = '#a8bb92'
    back = ('    ' + cathedral + row
            + gaslamp(150, 444, 0.9) + gaslamp(430, 446, 0.9) + gaslamp(820, 444, 0.9)
            + oak(452, 448, 0.6, '#3f6b44', '#4b7d50', '#6b4a2a', moss)
            + oak(806, 448, 0.58, '#3f6b44', '#4b7d50', '#6b4a2a', moss)
            + '<g fill="#5f8f52" opacity="0.85">'
            + ''.join(f'<ellipse cx="{x}" cy="446" rx="30" ry="12"/>' for x in (60, 340, 480, 780)) + '</g>')

    def fern(x, y, s=1.0):
        fronds = ''.join(f'<path d="M0,0 Q {dx*0.5:.0f},{-26} {dx},{-40}" stroke="#4f8a54" stroke-width="5" '
                         f'fill="none" stroke-linecap="round"/>' for dx in (-34, -18, 0, 18, 34))
        return f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 32)}{fronds}</g>'

    front = ('    ' + oak(140, 632, 1.55, '#3f6b44', '#4b7d50', '#6b4a2a', moss)
             + oak(1150, 656, 1.5, '#3f6b44', '#4b7d50', '#6b4a2a', moss)
             + gaslamp(330, 604, 1.5) + gaslamp(980, 626, 1.5)
             + fern(400, 664, 1.2) + fern(880, 690, 1.3) + fern(240, 700, 1.15)
             + f'<g transform="translate(438,706)">{shadow(0, 4, 46)}</g>'
             + ''.join(f'<g transform="translate({x},{y})">{shadow(0, 4, 28)}'
                       f'<ellipse cx="0" cy="-14" rx="30" ry="16" fill="#4f8a54"/>'
                       f'<ellipse cx="-12" cy="-22" rx="17" ry="11" fill="#5f9c64"/>'
                       f'<g fill="#e88fa8"><circle cx="-16" cy="-26" r="4"/><circle cx="4" cy="-30" r="4"/>'
                       f'<circle cx="16" cy="-22" r="3.5"/></g></g>'
                       for x, y in [(520, 640), (1040, 700)]))

    # ---- paved streets: light stone with fine joints, kerbs, and green
    # "neutral ground" strips (what New Orleans calls its medians) ----
    def joints(y0, y1, step=18):
        rows = ''.join(f'<rect x="0" y="{y}" width="1280" height="1.5"/>' for y in range(y0, y1, step))
        cols = ''.join(f'<rect x="{x + (r % 2) * 16}" y="{y0 + r*step}" width="1.5" height="{step}"/>'
                       for r in range((y1 - y0) // step) for x in range(0, 1280, 32))
        return f'<g fill="#ffffff" opacity="0.20">{rows}</g><g fill="#8f887c" opacity="0.13">{cols}</g>'

    paving = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#pave)"/>\n'
              f'    {joints(302, 386, 16)}\n'
              f'    {joints(442, 554, 18)}\n'
              f'    {joints(620, 716, 20)}\n'
              # green neutral ground either side of the crossing
              '    <rect x="0" y="392" width="1280" height="44" fill="#7fa055"/>\n'
              '    <rect x="0" y="392" width="1280" height="6" fill="#8fae64"/>\n'
              '    <rect x="0" y="562" width="1280" height="52" fill="#7fa055"/>\n'
              '    <rect x="0" y="562" width="1280" height="6" fill="#8fae64"/>\n'
              # kerbstones
              '    <g fill="#d8d2c5"><rect x="0" y="384" width="1280" height="8"/>'
              '<rect x="0" y="436" width="1280" height="8"/>'
              '<rect x="0" y="554" width="1280" height="8"/>'
              '<rect x="0" y="614" width="1280" height="9"/></g>\n'
              '    <g fill="#a79f90" opacity="0.7"><rect x="0" y="391" width="1280" height="2.5"/>'
              '<rect x="0" y="443" width="1280" height="2.5"/>'
              '<rect x="0" y="561" width="1280" height="2.5"/>'
              '<rect x="0" y="622" width="1280" height="2.5"/></g>')

    scene('new-orleans', 'NEW ORLEANS — St. Louis Cathedral, French Quarter galleries, riverboat, live oaks', {
        'sky': sky('', '', '', sun=(1080, 128, 200)) + '\n'
               + clouds([(240, 96, 62), (560, 74, 48), (860, 108, 54)], fill='#ffe3bb', op=0.7)
               + '\n' + clouds([(400, 132, 40)], fill='#ffd0a0', op=0.5)
               + '\n' + birds([(600, 138), (652, 162), (700, 128)], col='#8a6a52'),
        'far': treeline + '\n' + river + '\n' + boat,
        'ground': paving,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#8e9a7e" opacity="0.5"><rect x="0" y="704" width="1280" height="3"/></g>',
    }, d)


# ================================================================== 8. AUSTIN
def austin():
    """Austin at dusk. HERO: a million and a half bats pouring out from under the
    Congress Avenue Bridge, unspooling across a burnt-orange sky, with the sun
    setting straight through one of the arches. Second, quieter landmark: the pink
    granite Capitol dome catching the last light. Everything on the ground is
    silhouette and warm bulb light — the only scene in the game lit from behind."""
    d = '''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#1f3f66"/><stop offset="0.34" stop-color="#4d7fa6"/>
      <stop offset="0.60" stop-color="#93b6c6"/><stop offset="0.80" stop-color="#e9c667"/>
      <stop offset="1" stop-color="#f2913a"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#fff6d8" stop-opacity="0.95"/>
      <stop offset="0.34" stop-color="#ffcf72" stop-opacity="0.6"/>
      <stop offset="0.7" stop-color="#f79a3c" stop-opacity="0.25"/>
      <stop offset="1" stop-color="#f0862c" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="lake" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#2c4a5e"/><stop offset="0.5" stop-color="#476a7c"/>
      <stop offset="1" stop-color="#6d8a93"/>
    </linearGradient>
    <linearGradient id="grassg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#27392e"/><stop offset="1" stop-color="#16211b"/>
    </linearGradient>
    <g id="bat"><path d="M-3.4,-0.6 Q-1.7,-2.3 0,-0.4 Q1.7,-2.3 3.4,-0.6 Q1.7,1 0,0.5 Q-1.7,1 -3.4,-0.6 Z" fill="#141a22"/></g>
    <g id="watcher"><path d="M0,0 L-2.1,0 L-2.1,-8.6 A2.3,2.3 0 0 1 2.1,-8.6 L2.1,0 Z" fill="#0d131a"/></g>'''

    SUN = (655, 257)
    WATER_TOP, BANK = 244, 292
    DECK_TOP, DECK_BOT, SPRING = 236, 247, 268
    ARCHES = [115, 385, 655, 925, 1195]

    # ---- sky: dusk gradient, the sun low in the middle arch, warm cloud streaks ----
    sky_l = (f'    <rect x="0" y="0" width="1280" height="{BANK + 8}" fill="url(#skyg)"/>\n'
             f'    <circle cx="{SUN[0]}" cy="{SUN[1]}" r="185" fill="url(#sung)"/>\n'
             '    <g fill="#ffd9a0" opacity="0.3">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{w}" ry="{w*0.09:.0f}"/>'
                       for x, y, w in [(240, 128, 130), (520, 96, 96), (880, 116, 120),
                                       (1080, 84, 84), (400, 168, 110), (960, 172, 100)])
             + '</g>\n'
             '    <g fill="#ffffff" opacity="0.5">'
             + ''.join(f'<circle cx="{x}" cy="{y}" r="{r}"/>'
                       for x, y, r in [(120, 34, 1.4), (300, 22, 1.1), (620, 18, 1.3),
                                       (900, 30, 1.1), (1140, 26, 1.4), (760, 40, 1),
                                       (460, 44, 1.1), (1040, 52, 1)])
             + '</g>')

    # ---- downtown: silhouette with warm windows. The Independent's stacked blocks
    #      and Frost Bank's faceted crown are the two shapes Austinites recognise. ----
    def slab(x, y, w, base='#22303f', win='#ffcf7a', step=13, dens=0.55):
        wins = ''.join(f'<rect x="{x+4}" y="{y+9+r*step}" width="{w-8}" height="4"/>'
                       for r in range(int((WATER_TOP - y - 12) // step)) if (x + r) % 3)
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{WATER_TOP-y}" rx="1.5" fill="{base}"/>'
                f'<g fill="{win}" opacity="{dens}">{wins}</g>')

    jenga = ''.join(f'<rect x="{146 + (8 if i % 2 else -8)}" y="{212 - i*22}" width="46" height="23" '
                    f'rx="2" fill="{"#253444" if i % 2 else "#202d3b"}"/>'
                    f'<g fill="#ffcf7a" opacity="0.5"><rect x="{152 + (8 if i % 2 else -8)}" '
                    f'y="{219 - i*22}" width="34" height="4"/></g>' for i in range(5))
    frost = ('<rect x="286" y="150" width="44" height="94" fill="#243342"/>'
             '<rect x="286" y="150" width="15" height="94" fill="#2b3d4e"/>'
             '<g fill="#25384a"><polygon points="286,150 308,120 330,150"/>'
             '<polygon points="292,150 308,128 324,150" fill="#31485c"/></g>'
             '<g fill="#ffcf7a" opacity="0.45">'
             + ''.join(f'<rect x="292" y="{158+r*13}" width="32" height="4"/>' for r in range(6)) + '</g>')
    skyline = ('    <g>'
               + ''.join(slab(*t) for t in
                         [(34, 196, 30), (68, 172, 24), (98, 208, 28), (196, 186, 26),
                          (228, 206, 30), (262, 214, 22), (336, 178, 26), (368, 200, 30),
                          (404, 212, 24), (434, 190, 28), (468, 206, 26), (500, 218, 30),
                          (536, 200, 24), (566, 212, 26), (700, 214, 24), (730, 200, 28),
                          (762, 216, 22), (1040, 206, 26), (1074, 218, 30), (1112, 200, 24),
                          (1146, 212, 28), (1182, 204, 26), (1218, 216, 30), (1252, 198, 26)])
               + jenga + frost + '</g>\n'
               + '    <g stroke="#2a3a4a" stroke-width="2.5" fill="none" opacity="0.9">'
               '<path d="M600,176 L600,244 M572,176 L640,176 M600,176 L600,166"/>'
               '<path d="M986,166 L986,244 M958,166 L1026,166 M986,166 L986,156"/></g>')

    # ---- the Capitol: pink granite, uplit, the one warm solid thing on the horizon ----
    capitol = ('    <g id="capitol">'
               '<circle cx="880" cy="212" r="88" fill="#f7c078" opacity="0.14"/>'
               # wings, wide and low
               '<rect x="786" y="216" width="188" height="30" fill="#a26a4c"/>'
               '<rect x="786" y="216" width="62" height="30" fill="#bb7d59"/>'
               '<rect x="782" y="212" width="196" height="6" rx="2" fill="#c2825b"/>'
               '<g fill="#6f4634" opacity="0.5">'
               + ''.join(f'<rect x="{792+i*14}" y="222" width="5" height="20"/>' for i in range(13)) + '</g>'
               # centre pavilion + portico
               '<rect x="846" y="192" width="68" height="54" fill="#b97b56"/>'
               '<rect x="846" y="192" width="23" height="54" fill="#cf8d63"/>'
               '<polygon points="840,192 880,176 920,192" fill="#c2825b"/>'
               '<g fill="#7a4c37" opacity="0.55">'
               + ''.join(f'<rect x="{851+i*11}" y="198" width="5" height="48"/>' for i in range(6)) + '</g>'
               # drum, then a proper broad dome
               '<rect x="858" y="170" width="44" height="24" fill="#c2825b"/>'
               '<rect x="858" y="170" width="16" height="24" fill="#d69a6e"/>'
               '<g fill="#6f4634" opacity="0.45">'
               + ''.join(f'<rect x="{862+i*10}" y="175" width="4" height="16"/>' for i in range(4)) + '</g>'
               '<path d="M852,172 A28,30 0 0 1 908,172 Z" fill="#cf8d63"/>'
               '<path d="M852,172 A28,30 0 0 1 874,145 L874,172 Z" fill="#e0a87b"/>'
               '<g stroke="#a26a4c" stroke-width="1.4" opacity="0.5" fill="none">'
               '<path d="M866,148 L864,172 M880,143 L880,172 M894,148 L896,172"/></g>'
               # lantern + the Goddess of Liberty on top
               '<rect x="871" y="128" width="18" height="16" rx="2" fill="#c2825b"/>'
               '<rect x="869" y="125" width="22" height="4" rx="2" fill="#d69a6e"/>'
               '<path d="M873,125 A7,8 0 0 1 887,125 Z" fill="#d69a6e"/>'
               '<rect x="879" y="108" width="2.4" height="10" fill="#c2825b"/>'
               '<circle cx="880" cy="105" r="3.6" fill="#f2d08a"/></g>')

    # ---- Lady Bird Lake: gold road of light under the sun, kayaks out on it ----
    refl = ''.join(f'<rect x="{SUN[0] - w//2 + o}" y="{y}" width="{w}" height="2.5" rx="1.2"/>'
                   for y, w, o in [(272, 34, 0), (277, 52, -4), (282, 74, 6), (287, 96, -8)])
    water = (f'    <rect x="0" y="{WATER_TOP}" width="1280" height="{BANK-WATER_TOP}" fill="url(#lake)"/>\n'
             '    <g fill="#f7bd63" opacity="0.75">' + refl + '</g>\n'
             '    <g fill="#e8dcc0" opacity="0.18">'
             + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2" rx="1"/>'
                       for x, y, w in [(90, 276, 70), (250, 284, 88), (420, 272, 60),
                                       (830, 280, 76), (1010, 288, 92), (1160, 274, 58)])
             + '</g>\n'
             '    <g opacity="0.2" transform="translate(0,488) scale(1,-1)">'
             + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{WATER_TOP-y}" fill="#2a3a4a"/>'
                       for x, y, w in [(34, 196, 30), (146, 116, 46), (286, 150, 44),
                                       (434, 190, 28), (500, 218, 30)]) + '</g>\n'
             + '    <g fill="#16202a">'
             + ''.join(f'<g transform="translate({x},{y})"><ellipse cx="0" cy="0" rx="{r}" ry="1.8"/>'
                       f'<rect x="-0.9" y="-5" width="1.8" height="5"/>'
                       f'<rect x="{-r*0.8:.0f}" y="-4" width="{r*1.6:.0f}" height="1.2" rx="0.6"/></g>'
                       for x, y, r in [(556, 282, 9), (604, 288, 8), (668, 284, 9), (712, 279, 7),
                                       (760, 286, 8), (498, 287, 7), (846, 283, 8), (884, 289, 9)])
             + '</g>')

    # ---- the far bank: LAND behind the road's vanishing point ----
    bank = (f'    <rect x="0" y="{BANK}" width="1280" height="10" fill="#25342c"/>\n'
            f'    <rect x="0" y="{BANK}" width="1280" height="3" fill="#33463a"/>\n'
            '    <g fill="#1b271f">'
            + ''.join(f'<ellipse cx="{x}" cy="{BANK+1}" rx="{r}" ry="{r*0.42:.0f}"/>'
                      for x, r in [(60, 30), (170, 24), (300, 28), (430, 22), (520, 26),
                                   (740, 24), (860, 30), (980, 22), (1120, 28), (1240, 24)])
            + '</g>')

    # ---- the Ann Richards Congress Avenue Bridge ----
    holes = ''.join(f'M{cx-104},{SPRING} A104,{SPRING-DECK_BOT-1} 0 0 1 {cx+104},{SPRING} Z'
                    for cx in ARCHES)
    crowd = ''.join(f'<use href="#watcher" transform="translate({x},{DECK_TOP}) scale({0.95 + (x%6)/8:.2f})"/>'
                    for x in range(6, 1280, 10))
    lamps = ''.join(f'<g transform="translate({x},{DECK_TOP})">'
                    f'<rect x="-1.2" y="-34" width="2.4" height="34" fill="#141c24"/>'
                    f'<path d="M-1,-34 q7,-3 9,3" stroke="#141c24" stroke-width="2" fill="none"/>'
                    f'<circle cx="9" cy="-30" r="3.4" fill="#ffe3a0" opacity="0.9"/>'
                    f'<circle cx="9" cy="-30" r="8" fill="#ffd98a" opacity="0.22"/></g>'
                    for x in (150, 420, 690, 960, 1230))
    bridge = (f'    <g id="congress-bridge">'
              f'<path fill-rule="evenodd" fill="#18212b" '
              f'd="M-10,{DECK_BOT} H1290 V{SPRING+6} H-10 Z {holes}"/>'
              f'<rect x="-10" y="{DECK_TOP}" width="1300" height="{DECK_BOT-DECK_TOP}" fill="#1b242e"/>'
              f'<rect x="-10" y="{DECK_TOP}" width="1300" height="2.5" fill="#5b7488"/>'
              f'<g>{crowd}</g><g>{lamps}</g></g>\n'
              f'    <circle cx="{SUN[0]}" cy="{SUN[1]}" r="120" fill="url(#sung)" opacity="0.5"/>\n'
              f'    <circle cx="{SUN[0]}" cy="{SUN[1]}" r="11" fill="#fff8e0"/>')

    # ---- THE BATS: the hero. Not a flock — a river. Density is the whole point. ----
    PATH = [(594, 232), (534, 196), (462, 158), (404, 118), (398, 80), (456, 50),
            (566, 34), (694, 34), (812, 54), (896, 88), (946, 132), (966, 178),
            (1002, 204), (1082, 184), (1164, 146), (1246, 110)]
    state = [20260729]
    def rnd():
        state[0] = (state[0] * 1103515245 + 12345) % 2147483648
        return state[0] / 2147483648.0

    bands = [[], [], [], []]
    def bat(x, y, sc, band):
        bands[band].append(f'<use href="#bat" transform="translate({x:.0f},{y:.0f}) '
                           f'rotate({-34 + rnd()*68:.0f}) scale({sc:.2f})"/>')

    segs = len(PATH) - 1
    for i2 in range(segs):
        (x0, y0), (x1, y1) = PATH[i2], PATH[i2 + 1]
        dx, dy = x1 - x0, y1 - y0
        L = max(1.0, (dx * dx + dy * dy) ** 0.5)
        nx, ny = -dy / L, dx / L
        t_along = i2 / segs
        thin = max(0.18, 1.0 - t_along * 1.05)          # the tail thins out
        core_n = int(150 * thin)                         # the dense spine
        halo_n = int(90 * thin)                          # the loose cloud around it
        core_w = 7 + 13 * (1 - abs(t_along - 0.4) * 1.4)
        halo_w = 22 + 44 * max(0.2, 1 - abs(t_along - 0.45) * 1.5)
        for k in range(core_n):
            t = (k + rnd()) / core_n
            off = (rnd() + rnd() - 1) * core_w
            bat(x0 + dx * t + nx * off + (rnd() - 0.5) * 5,
                y0 + dy * t + ny * off + (rnd() - 0.5) * 5,
                0.34 + rnd() * 0.42, k % 2)
        for k in range(halo_n):
            t = (k + rnd()) / halo_n
            off = (rnd() + rnd() + rnd() - 1.5) * halo_w
            bat(x0 + dx * t + nx * off + (rnd() - 0.5) * 12,
                y0 + dy * t + ny * off + (rnd() - 0.5) * 12,
                0.3 + rnd() * 0.5, 2 + (k % 2))

    # the emergence: a dense plume boiling straight up from under the deck, then bending
    for k in range(470):
        u = rnd()
        h = u ** 1.35 * 196                               # packed low, fanning as it rises
        jx = 592 + (rnd() + rnd() + rnd() - 1.5) * (17 + h * 0.36) - h * 0.36
        jy = DECK_TOP - 2 - h
        bat(jx, jy, 0.28 + rnd() * 0.44, 1 + (k % 3))
    # a low scatter skimming the water either side of the bridge
    for k in range(120):
        bat(380 + rnd() * 560, DECK_BOT + 2 + rnd() * rnd() * 22, 0.24 + rnd() * 0.3, 2 + (k % 2))

    bats = ('    <g id="bats">'
            + ''.join(f'<g opacity="{op}">' + ''.join(b) + '</g>'
                      for op, b in zip((0.96, 0.82, 0.6, 0.4), bands))
            + '</g>')

    # ---- ground: park at dusk, the hike-and-bike trail, a gravel apron ----
    ground_l = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#grassg)"/>\n'
                '    <rect x="0" y="336" width="1280" height="21" fill="#4e483c"/>\n'
                '    <rect x="0" y="336" width="1280" height="3" fill="#5e5747"/>\n'
                '    <g fill="#3a352c" opacity="0.7">'
                + ''.join(f'<rect x="{x}" y="{342 + (x % 5)}" width="{6 + x % 4}" height="3" rx="1.5"/>'
                          for x in range(4, 1280, 21)) + '</g>\n'
                '    <rect x="0" y="357" width="1280" height="3" fill="#1c2a20"/>\n'
                '    <g fill="#1a2820" opacity="0.6">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.3:.0f}"/>'
                          for x, y, r in [(180, 400, 120), (620, 420, 150), (1080, 404, 130),
                                          (380, 500, 140), (900, 520, 160)]) + '</g>\n'
                '    <path d="M742,720 L806,556 L1280,556 L1280,720 Z" fill="#3b3730"/>\n'
                '    <path d="M742,720 L806,556 L1280,556 L1280,566 L816,566 L760,720 Z" fill="#474238"/>\n'
                '    <g fill="#2f2b25" opacity="0.6">'
                + ''.join(f'<rect x="{x}" y="{y}" width="{7 + x % 5}" height="3" rx="1.5"/>'
                          for x, y in [(880, 600), (1010, 640), (1150, 596), (940, 690),
                                       (1200, 676), (830, 660)]) + '</g>')

    # ---------------------------------------------------------------- props ----
    def cypress(x, y, s=1.0, a='#0d1512', b='#121c18', rim='#557a60'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-5" y="-46" width="10" height="46" fill="#0b1210"/>'
                f'<path d="M-9,0 L0,-14 L9,0 Z" fill="#0b1210"/>'
                f'<ellipse cx="0" cy="-96" rx="40" ry="30" fill="{a}"/>'
                f'<ellipse cx="-24" cy="-78" rx="26" ry="20" fill="{b}"/>'
                f'<ellipse cx="25" cy="-82" rx="24" ry="18" fill="{b}"/>'
                f'<ellipse cx="4" cy="-118" rx="27" ry="18" fill="{b}"/>'
                f'<path d="M22,-112 A34,26 0 0 1 40,-88" stroke="{rim}" stroke-width="2.5" '
                f'fill="none" opacity="0.55"/></g>')

    def oak2(x, y, s=1.0, a='#0e1613', b='#131d19', rim='#557a60'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<path d="M-7,2 C -9,-22 -18,-32 -25,-42 L-11,-38 C -6,-46 -2,-52 0,-64 '
                f'C 3,-52 8,-46 14,-38 L28,-44 C 19,-32 8,-22 7,2 Z" fill="#0b1210"/>'
                f'<ellipse cx="0" cy="-66" rx="58" ry="30" fill="{a}"/>'
                f'<ellipse cx="-30" cy="-54" rx="30" ry="19" fill="{b}"/>'
                f'<ellipse cx="30" cy="-56" rx="28" ry="17" fill="{b}"/>'
                f'<ellipse cx="4" cy="-84" rx="35" ry="19" fill="{b}"/>'
                f'<path d="M28,-80 A44,24 0 0 1 54,-58" stroke="{rim}" stroke-width="2.5" '
                f'fill="none" opacity="0.5"/></g>')

    def person(x, y, s=1.0, col='#131b22', arms='down'):
        A = {'down': 'M-5,-26 L-9,-12 M5,-26 L9,-12',
             'out':  'M-5,-26 L-16,-21 M5,-26 L16,-21',
             'up':   'M-5,-27 L-13,-42 M5,-27 L13,-42'}[arms]
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g stroke="{col}" stroke-width="4.4" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-13 L-4,0 M3,-13 L5,0"/><path d="{A}"/></g>'
                f'<rect x="-6" y="-29" width="12" height="17" rx="5" fill="{col}"/>'
                f'<circle cx="0" cy="-35" r="5.6" fill="{col}"/></g>')

    def cyclist(x, y, s=1.0, col='#131b22'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g stroke="{col}" stroke-width="2.6" fill="none">'
                f'<circle cx="-15" cy="-7" r="7.5"/><circle cx="15" cy="-7" r="7.5"/>'
                f'<path d="M-15,-7 L0,-24 L15,-7 M0,-24 L-5,-7 M0,-24 L9,-26"/></g>'
                + person(0, -22, 0.5, col, 'out') + '</g>')

    def truck(x, y, s=1.0, body='#2f7f96', trim='#f2b134', win='#ffd98a'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 5, 70, 8, 0.3)}'
                f'<rect x="-66" y="-70" width="132" height="62" rx="5" fill="{body}"/>'
                f'<rect x="-66" y="-70" width="132" height="9" rx="4" fill="{trim}"/>'
                f'<rect x="-66" y="-16" width="132" height="8" fill="#1d2730"/>'
                f'<rect x="-46" y="-56" width="88" height="32" rx="3" fill="{win}"/>'
                f'<rect x="-46" y="-56" width="88" height="32" rx="3" fill="#fff0c0" opacity="0.5"/>'
                f'<path d="M-52,-58 L48,-58 L44,-74 L-48,-74 Z" fill="{trim}"/>'
                f'<g fill="#1d2730" opacity="0.8">'
                f'<rect x="-30" y="-48" width="12" height="18" rx="2"/>'
                f'<rect x="6" y="-48" width="12" height="18" rx="2"/></g>'
                f'<rect x="-60" y="-24" width="40" height="6" rx="2" fill="{trim}" opacity="0.85"/>'
                f'<g fill="#0f151b"><circle cx="-40" cy="-6" r="10"/><circle cx="40" cy="-6" r="10"/></g>'
                f'<g fill="#39424c"><circle cx="-40" cy="-6" r="3.6"/><circle cx="40" cy="-6" r="3.6"/></g>'
                f'<ellipse cx="0" cy="-30" rx="86" ry="34" fill="#ffd98a" opacity="0.09"/></g>')

    def table(x, y, s=1.0, col='#3a2f24'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 42, 6, 0.28)}'
                f'<rect x="-40" y="-22" width="80" height="7" rx="2" fill="{col}"/>'
                f'<rect x="-40" y="-22" width="80" height="2.5" rx="1" fill="#4c3d2e"/>'
                f'<rect x="-46" y="-11" width="92" height="5" rx="2" fill="#31281f"/>'
                f'<g stroke="#2a2219" stroke-width="4"><path d="M-30,-15 L-34,2 M30,-15 L34,2"/></g></g>')

    def lightstring(x0, x1, y, sag=26, col='#ffdc96'):
        n = max(6, (x1 - x0) // 26)
        pts = [(x0 + (x1 - x0) * (i / n), y + sag * (4 * (i / n) * (1 - i / n))) for i in range(n + 1)]
        d_ = 'M' + ' L'.join(f'{px:.0f},{py:.0f}' for px, py in pts)
        bulbs = ''.join(f'<circle cx="{px:.0f}" cy="{py+4:.0f}" r="2.6" fill="{col}"/>'
                        f'<circle cx="{px:.0f}" cy="{py+4:.0f}" r="7" fill="{col}" opacity="0.2"/>'
                        for px, py in pts[1:-1])
        return f'<path d="{d_}" stroke="#4a4234" stroke-width="1.4" fill="none"/>{bulbs}'

    def mural(x, y, w, h):
        """The angel wings — the most photographed wall in Austin. Reads instantly."""
        cx, cy = w / 2, -h * 0.5
        def wing(g):
            return (f'<path d="M{cx + g*5:.0f},{cy + h*0.26:.0f} '
                    f'C {cx + g*18:.0f},{cy - h*0.16:.0f} {cx + g*54:.0f},{cy - h*0.44:.0f} '
                    f'{cx + g*96:.0f},{cy - h*0.5:.0f} '
                    f'C {cx + g*86:.0f},{cy - h*0.08:.0f} {cx + g*66:.0f},{cy + h*0.2:.0f} '
                    f'{cx + g*40:.0f},{cy + h*0.36:.0f} '
                    f'L{cx + g*30:.0f},{cy + h*0.2:.0f} L{cx + g*22:.0f},{cy + h*0.34:.0f} '
                    f'L{cx + g*14:.0f},{cy + h*0.18:.0f} L{cx + g*7:.0f},{cy + h*0.3:.0f} Z" '
                    f'fill="#f2ead6"/>'
                    + ''.join(f'<path d="M{cx + g*(12 + k*15):.0f},{cy + h*(0.2 - k*0.03):.0f} '
                              f'L{cx + g*(26 + k*16):.0f},{cy - h*(0.06 + k*0.07):.0f}" '
                              f'stroke="#cdc2a5" stroke-width="1.7" opacity="0.85"/>' for k in range(5)))
        return (f'<g transform="translate({x},{y})">'
                f'<rect x="0" y="{-h}" width="{w}" height="{h}" rx="3" fill="#282932"/>'
                f'<rect x="0" y="{-h}" width="{w}" height="4" rx="2" fill="#383944"/>'
                f'<rect x="0" y="-6" width="{w}" height="6" fill="#1e1f28"/>'
                f'{wing(-1)}{wing(1)}'
                f'<ellipse cx="{cx}" cy="{cy:.0f}" rx="{w*0.36:.0f}" ry="{h*0.44:.0f}" '
                f'fill="#ffd98a" opacity="0.08"/></g>')

    back = ('    '
            + '<g fill="#131d17">'
            + ''.join(f'<ellipse cx="{x}" cy="{318 - (x % 4)}" rx="{r}" ry="{r*0.5:.0f}"/>'
                      for x, r in [(48, 20), (128, 15), (232, 18), (352, 13), (466, 17),
                                   (556, 12), (716, 16), (822, 20), (932, 14), (1046, 18),
                                   (1168, 15), (1256, 19)]) + '</g>'
            + '<g stroke="#1a2820" stroke-width="2" stroke-linecap="round" fill="none" opacity="0.9">'
            + ''.join(f'<path d="M{x},322 L{x-4},{306 - (x%5)} M{x+5},322 L{x+8},{308 - (x%4)} '
                      f'M{x+10},322 L{x+7},{304 - (x%6)}"/>'
                      for x in range(20, 1280, 63)) + '</g>'
            + ''.join(cypress(x, y, s) for x, y, s in
                      [(66, 404, 0.9), (1146, 402, 0.84), (1256, 396, 0.7)])
            + ''.join(oak2(x, y, s) for x, y, s in
                      [(214, 400, 0.64), (348, 406, 0.86), (486, 396, 0.48),
                       (828, 402, 0.72), (982, 406, 0.9), (1066, 396, 0.52)])
            + ''.join(oak2(x, 332, s) for x, s in [(150, 0.38), (420, 0.3), (900, 0.34)])
            + cypress(1012, 330, 0.32)
            + cyclist(238, 354, 0.72) + cyclist(690, 352, 0.66) + cyclist(1074, 355, 0.7)
            + person(456, 353, 0.6, '#131b22', 'out') + person(486, 354, 0.56)
            + person(880, 353, 0.58, '#131b22', 'up') + person(146, 355, 0.6)
            + person(632, 352, 0.6, '#131b22', 'up') + person(1200, 354, 0.58, '#131b22', 'out')
            + ''.join(f'<g transform="translate({x},344)">'
                      f'<rect x="-1.2" y="-40" width="2.4" height="40" fill="#141c24"/>'
                      f'<circle cx="0" cy="-43" r="4" fill="#ffe3a0" opacity="0.85"/>'
                      f'<circle cx="0" cy="-43" r="10" fill="#ffd98a" opacity="0.16"/></g>'
                      for x in (300, 780, 1180)))

    front = ('    '
             # LEFT: the wings wall, with people posing in front of it as they actually do
             + mural(30, 678, 296, 104)
             + lightstring(26, 336, 550, 26)
             + oak2(116, 556, 0.72)
             + person(150, 708, 1.1, '#131b22', 'out') + person(204, 712, 1.02, '#131b22', 'up')
             + cypress(338, 716, 1.38)
             # a family stopped on the grass to watch — the whole point of Austin at dusk
             + person(424, 604, 0.86, '#131b22', 'up') + person(456, 608, 0.64, '#131b22', 'up')
             + person(484, 606, 0.72, '#131b22', 'out')
             + '<g transform="translate(512,610) scale(0.58)">'
             '<g stroke="#131b22" stroke-width="4" stroke-linecap="round" fill="none">'
             '<path d="M-12,-6 L-13,2 M8,-6 L9,2 M-4,-6 L-5,2 M14,-8 L21,-15"/></g>'
             '<rect x="-16" y="-14" width="30" height="9" rx="4.5" fill="#131b22"/>'
             '<circle cx="19" cy="-18" r="5" fill="#131b22"/>'
             '<path d="M22,-22 l5,-4 l1,5 z" fill="#131b22"/></g>'
             # RIGHT: the food-truck lot
             + lightstring(792, 1280, 512, 34) + lightstring(812, 1280, 556, 30)
             + truck(910, 690, 0.94, '#2f7f96', '#f2b134')
             + truck(1148, 706, 1.0, '#b8512f', '#f2d06a')
             + table(986, 716, 1.0) + table(1074, 700, 0.9)
             + f'<g transform="translate(812,646)">{shadow(0, 4, 40, 6, 0.3)}'
             '<rect x="-36" y="-14" width="72" height="6" rx="2" fill="#33291f"/>'
             '<rect x="-36" y="-28" width="72" height="6" rx="2" fill="#3c3125"/>'
             '<g stroke="#231c14" stroke-width="4"><path d="M-28,-8 L-30,4 M28,-8 L30,4"/></g></g>'
             + person(892, 716, 1.15, '#131b22', 'out') + person(1040, 712, 1.1)
             + person(1112, 700, 1.0, '#131b22', 'down') + person(958, 704, 1.05, '#131b22', 'up')
             + person(1224, 716, 1.15) + person(838, 648, 0.72, '#131b22', 'up')
             + ''.join(f'<g transform="translate({x},{y})">'
                       f'<rect x="-1.4" y="-70" width="2.8" height="70" fill="#141c24"/>'
                       f'<circle cx="0" cy="-74" r="5.5" fill="#ffe3a0" opacity="0.9"/>'
                       f'<circle cx="0" cy="-74" r="15" fill="#ffd98a" opacity="0.14"/></g>'
                       for x, y in [(760, 640), (1276, 620)]))

    scene('austin', 'AUSTIN — a million bats off the Congress Avenue Bridge at sunset, the Capitol dome', {
        'sky': sky_l,
        'far': (skyline + '\n' + capitol + '\n' + water + '\n' + bank + '\n'
                + bridge + '\n' + bats),
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#141f19" opacity="0.55"><rect x="0" y="708" width="1280" height="4"/></g>',
        'roadkw': dict(surface='#4a4a52', surface2='#37373e', shoulder='#8a8470', dash='#e8c85a'),
        'trackkw': dict(ballast='#6a5a48', ballast_hi='#7a6a54', tie='#4a3422', rail='#a8adb4'),
    }, d)


# ================================================================= 9. HOUSTON
def houston():
    """Houston is where the ground crew sits. Rockets don't launch here — they are
    FLOWN here, which is why the hero is hardware parked on grass: the shuttle
    Independence riding piggyback on NASA 905. Second landmark: a Saturn V lying on
    its side, so long it reads as a wall. Flat, humid, hazy midday — the opposite of
    Florida's vertical launch and of Austin's dusk."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#3f93cf"/><stop offset="0.5" stop-color="#8cc0de"/>
      <stop offset="0.86" stop-color="#d3e4e6"/><stop offset="1" stop-color="#e8eee8"/>
    </linearGradient>
    <linearGradient id="grassg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#7ea457"/><stop offset="1" stop-color="#5c8140"/>
    </linearGradient>
    <linearGradient id="pave" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#c9ccc6"/><stop offset="1" stop-color="#aeb2ad"/>
    </linearGradient>''')

    # ---- hazy sky, big Gulf-coast cumulus ----
    def cumulus(cx, cy, r, op=0.95):
        return (f'<g opacity="{op}">'
                f'<ellipse cx="{cx}" cy="{cy}" rx="{r}" ry="{r*0.5:.0f}" fill="#ffffff"/>'
                f'<ellipse cx="{cx-r*0.55:.0f}" cy="{cy+r*0.16:.0f}" rx="{r*0.6:.0f}" ry="{r*0.4:.0f}" fill="#ffffff"/>'
                f'<ellipse cx="{cx+r*0.6:.0f}" cy="{cy+r*0.12:.0f}" rx="{r*0.55:.0f}" ry="{r*0.36:.0f}" fill="#ffffff"/>'
                f'<ellipse cx="{cx-r*0.18:.0f}" cy="{cy-r*0.34:.0f}" rx="{r*0.5:.0f}" ry="{r*0.34:.0f}" fill="#ffffff"/>'
                f'<ellipse cx="{cx+r*0.28:.0f}" cy="{cy-r*0.26:.0f}" rx="{r*0.42:.0f}" ry="{r*0.28:.0f}" fill="#ffffff"/>'
                f'<ellipse cx="{cx}" cy="{cy+r*0.36:.0f}" rx="{r*0.94:.0f}" ry="{r*0.2:.0f}" fill="#cfdbe2"/></g>')

    sky_l = ('    <rect x="0" y="0" width="1280" height="304" fill="url(#skyg)"/>\n'
             '    ' + cumulus(210, 92, 74) + cumulus(520, 62, 54, 0.9) + cumulus(830, 104, 64)
             + cumulus(1120, 70, 58, 0.88) + cumulus(660, 150, 44, 0.6) + '\n'
             # the humid haze that flattens every Houston horizon
             '    <rect x="0" y="222" width="1280" height="82" fill="#e2ecec" opacity="0.5"/>\n'
             # a T-38 chase plane, because they are always overhead here
             '    <g transform="translate(1010,176) rotate(-8) scale(0.9)" opacity="0.85">'
             '<path d="M-34,0 L20,-3 L38,0 L20,3 Z" fill="#f2f4f6"/>'
             '<path d="M-6,-1 L-26,-16 L-14,-16 L6,-2 Z" fill="#dfe3e6"/>'
             '<path d="M-6,1 L-26,16 L-14,16 L6,2 Z" fill="#dfe3e6"/>'
             '<path d="M-30,-1 L-40,-13 L-32,-13 L-24,-1 Z" fill="#c9ced4"/>'
             '<circle cx="16" cy="-1" r="2" fill="#4a90c0"/></g>\n'
             '    <g stroke="#ffffff" stroke-width="2.5" opacity="0.35" fill="none">'
             '<path d="M1006,178 q-90,10 -190,26"/></g>')

    # ---- downtown, 25 miles off and half-dissolved in haze ----
    def tower(x, y, w, base='#93aab8', lit='#a6bac6'):
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{292-y}" rx="1.5" fill="{base}"/>'
                f'<rect x="{x}" y="{y}" width="{w*0.34:.0f}" height="{292-y}" fill="{lit}"/>')
    downtown = ('    <g opacity="0.62">'
                + ''.join(tower(*t) for t in
                          [(28, 244, 22), (54, 232, 18), (78, 250, 24), (128, 238, 20),
                           (152, 252, 26), (206, 240, 18), (230, 254, 24), (300, 246, 20),
                           (326, 236, 16), (348, 252, 22), (376, 244, 18), (400, 256, 24)])
                # JPMorgan Chase Tower: the tall one with the sloped, notched crown
                + '<polygon points="98,292 98,196 122,182 122,292" fill="#8ba3b2"/>'
                + '<polygon points="98,196 122,182 122,196" fill="#a6bac6"/>'
                + '<rect x="108" y="150" width="2.5" height="34" fill="#8ba3b2"/>'
                # Heritage Plaza: the stepped crown everyone in Houston can name
                + '<rect x="256" y="212" width="34" height="80" fill="#8ba3b2"/>'
                + '<rect x="256" y="212" width="12" height="80" fill="#a6bac6"/>'
                + ''.join(f'<rect x="{258+i*4}" y="{204-i*7}" width="{30-i*8}" height="8" fill="#7f97a6"/>'
                          for i in range(3))
                + '</g>')

    # ---- the ship channel: stacks and steam, the other half of Houston ----
    refinery = ('    <g opacity="0.5">'
                + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{292-y}" fill="#9aa6ae"/>'
                          for x, y, w in [(1186, 236, 9), (1204, 224, 7), (1218, 244, 11),
                                          (1238, 230, 8), (1256, 248, 13), (1272, 238, 8)])
                + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{h/2:.0f}" fill="#aab4bb"/>'
                          for x, y, w, h in [(1192, 268, 26, 24), (1230, 274, 22, 18)])
                + '<g fill="#ffffff" opacity="0.7"><ellipse cx="1206" cy="212" rx="13" ry="9"/>'
                '<ellipse cx="1214" cy="196" rx="17" ry="11"/><ellipse cx="1204" cy="180" rx="20" ry="12"/></g>'
                + '</g>')

    # ---- a live-oak treeline sitting on the flat horizon ----
    treeline = ('    <g fill="#4a7048" opacity="0.85">'
                + ''.join(f'<ellipse cx="{x}" cy="{292 - (x % 7)}" rx="{r}" ry="{r*0.42:.0f}"/>'
                          for x, r in [(470, 34), (528, 26), (582, 30), (640, 22), (700, 28),
                                       (756, 33), (820, 25), (880, 30), (944, 22), (1010, 28),
                                       (1074, 33), (1136, 24), (160, 30), (250, 24), (350, 28)])
                + '</g>\n'
                '    <rect x="0" y="290" width="1280" height="12" fill="#43663f"/>')

    # ---- ground: mown NASA-campus lawn and a big concrete apron ----
    ground_l = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#grassg)"/>\n'
                # mowing stripes, which is exactly what a NASA lawn looks like
                '    <g fill="#87ad5e" opacity="0.45">'
                + ''.join(f'<rect x="0" y="{y}" width="1280" height="{h}"/>'
                          for y, h in [(312, 14), (344, 16), (382, 18), (426, 20)]) + '</g>\n'
                # the apron the hardware stands on
                '    <path d="M604,404 L1280,404 L1280,470 L586,470 Z" fill="url(#pave)"/>\n'
                '    <path d="M604,404 L1280,404 L1280,410 L601,410 Z" fill="#d6d9d3"/>\n'
                '    <g stroke="#9aa09a" stroke-width="2" opacity="0.6">'
                + ''.join(f'<path d="M{x},404 L{x-6},470"/>' for x in range(660, 1280, 78)) + '</g>\n'
                # a second apron on the left under the Saturn V
                '    <path d="M0,392 L560,392 L548,446 L0,446 Z" fill="url(#pave)"/>\n'
                '    <path d="M0,392 L560,392 L559,398 L0,398 Z" fill="#d6d9d3"/>\n'
                # visitor walkway across the front
                '    <path d="M0,560 L1280,560 L1280,606 L0,606 Z" fill="#c2c6c0"/>\n'
                '    <rect x="0" y="560" width="1280" height="5" fill="#d6d9d3"/>\n'
                '    <g stroke="#a3a8a2" stroke-width="2.5" opacity="0.7">'
                + ''.join(f'<path d="M{x},560 L{x-4},606"/>' for x in range(46, 1280, 92)) + '</g>')

    # ------------------------------------------------------------ hardware ----
    def plaza(x, y, s=1.0):
        """The Independence Plaza block that stands right behind the aircraft."""
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-78" y="-196" width="156" height="196" fill="#b8bcc0"/>'
                f'<rect x="-78" y="-196" width="52" height="196" fill="#cbcfd2"/>'
                f'<rect x="-82" y="-204" width="164" height="10" rx="2" fill="#9ea3a8"/>'
                f'<rect x="-58" y="-176" width="94" height="120" fill="#2f3d47"/>'
                + ''.join(f'<rect x="-54" y="{-170+r*22}" width="86" height="15" fill="#5f7e92" opacity="0.75"/>'
                          for r in range(5))
                + ''.join(f'<rect x="{-54+c*30}" y="-176" width="3" height="120" fill="#8d949c"/>'
                          for c in range(4))
                + f'<g stroke="#8d949c" stroke-width="3" fill="none">'
                f'<path d="M-58,-56 L36,-56 M-58,-96 L36,-96 M-58,-136 L36,-136"/></g>'
                f'<rect x="-72" y="-186" width="60" height="7" rx="2" fill="#4a6f9c"/>'
                f'<rect x="40" y="-176" width="34" height="176" fill="#c4c8cb"/>'
                f'<g stroke="#9ea3a8" stroke-width="2.5" fill="none">'
                + ''.join(f'<path d="M42,{-160+i*28} L72,{-174+i*28}"/>' for i in range(6)) + '</g></g>')

    def b747(x, y, s=1.0):
        """NASA 905. Nose left, tail right, four fans, blue cheatline."""
        white, shade, blue, dark = '#f4f6f7', '#dde2e6', '#2f6fb5', '#2c3a46'
        wins = ''.join(f'<rect x="{86+i*13}" y="-64" width="7" height="6" rx="1.5"/>' for i in range(28))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="262" cy="4" rx="250" ry="10" fill="#000" opacity="0.16"/>'
                # far wing, behind the fuselage
                f'<polygon points="250,-52 316,-56 470,-96 424,-96" fill="{shade}"/>'
                # fuselage
                f'<path d="M8,-56 C 8,-74 26,-84 58,-84 L470,-80 C 502,-78 520,-70 522,-58 '
                f'L522,-52 C 520,-40 500,-32 470,-32 L58,-30 C 26,-30 8,-40 8,-56 Z" fill="{white}"/>'
                f'<path d="M8,-56 C 8,-46 26,-30 58,-30 L470,-32 C 500,-32 520,-40 522,-52 '
                f'L8,-52 Z" fill="{shade}" opacity="0.55"/>'
                # upper-deck hump
                f'<path d="M56,-84 C 62,-104 96,-112 138,-110 L188,-100 L188,-82 Z" fill="{white}"/>'
                f'<path d="M62,-96 C 76,-104 104,-108 132,-106 L132,-96 Z" fill="{dark}"/>'
                # cheatline + windows
                f'<rect x="18" y="-58" width="500" height="9" fill="{blue}"/>'
                f'<rect x="18" y="-49" width="500" height="3" fill="#1f5590"/>'
                f'<g fill="{dark}" opacity="0.85">{wins}</g>'
                f'<text x="150" y="-88" font-family="Trebuchet MS,Arial,sans-serif" font-size="13" '
                f'font-weight="bold" fill="{blue}" letter-spacing="2">NASA</text>'
                # tail
                f'<path d="M470,-72 L500,-176 L528,-176 L528,-64 Z" fill="{white}"/>'
                f'<path d="M470,-72 L500,-176 L512,-176 L490,-66 Z" fill="{shade}"/>'
                f'<path d="M500,-176 L528,-176 L528,-150 L494,-150 Z" fill="{blue}"/>'
                f'<polygon points="500,-78 566,-92 574,-84 508,-70" fill="{shade}"/>'
                # near wing + engines
                f'<polygon points="216,-40 300,-44 452,-4 378,-4" fill="{white}"/>'
                f'<polygon points="216,-40 300,-44 452,-4 430,-4 268,-38" fill="{shade}"/>'
                + ''.join(f'<g transform="translate({ex},{ey})">'
                          f'<rect x="-26" y="-14" width="52" height="28" rx="13" fill="{white}"/>'
                          f'<rect x="-26" y="-14" width="52" height="9" rx="4" fill="{shade}"/>'
                          f'<ellipse cx="-24" cy="0" rx="5" ry="13" fill="{dark}"/>'
                          f'<rect x="-4" y="-24" width="9" height="12" fill="{shade}"/></g>'
                          for ex, ey in [(292, -12), (356, -6)])
                # landing gear
                + ''.join(f'<g><rect x="{gx-4}" y="-30" width="8" height="{26}" fill="#7d848b"/>'
                          f'<circle cx="{gx-7}" cy="-2" r="7" fill="#242a30"/>'
                          f'<circle cx="{gx+7}" cy="-2" r="7" fill="#242a30"/></g>'
                          for gx in (232, 288))
                + f'<g><rect x="72" y="-30" width="7" height="26" fill="#7d848b"/>'
                f'<circle cx="75" cy="-2" r="6" fill="#242a30"/></g></g>')

    def shuttle(x, y, s=1.0):
        """Independence, mated on the back. The black belly is what separates her
        from the white 747 underneath — without it the two read as one blob."""
        white, shade, tile, edge = '#fbfcfd', '#dbe0e4', '#1c2126', '#9aa4ad'
        return (f'<g transform="translate({x},{y}) scale({s})">'
                # mounting struts onto the 747 spine
                f'<g fill="#7d848b"><rect x="70" y="-2" width="13" height="20"/>'
                f'<rect x="252" y="-2" width="15" height="20"/></g>'
                # delta wing, black underside
                f'<polygon points="96,-14 186,-14 322,12 190,14" fill="{white}"/>'
                f'<polygon points="120,-4 200,-2 322,12 190,14" fill="{tile}"/>'
                # fuselage: white top, black belly the whole length
                f'<path d="M0,-18 C 14,-38 46,-46 84,-46 L300,-44 L332,-32 L332,-8 '
                f'L60,-6 C 22,-6 0,-10 0,-18 Z" fill="{white}"/>'
                f'<path d="M0,-18 C 8,-8 24,-6 60,-6 L332,-8 L332,-19 L2,-22 Z" fill="{tile}"/>'
                f'<path d="M0,-18 C 12,-36 30,-44 48,-45 C 28,-33 18,-25 15,-15 Z" fill="{tile}"/>'
                f'<path d="M0,-18 C 14,-38 46,-46 84,-46 L300,-44 L332,-32" fill="none" '
                f'stroke="{edge}" stroke-width="1.6"/>'
                # cargo-bay hinge line and payload doors
                f'<path d="M96,-42 L296,-40" stroke="{edge}" stroke-width="1.4" opacity="0.8"/>'
                # tall vertical fin, clear of the 747 tail
                f'<path d="M236,-44 L280,-128 L314,-128 L318,-42 Z" fill="{white}"/>'
                f'<path d="M236,-44 L280,-128 L292,-128 L262,-42 Z" fill="{shade}"/>'
                f'<path d="M280,-128 L314,-128 L316,-108 L288,-108 Z" fill="{tile}"/>'
                f'<path d="M236,-44 L280,-128 L314,-128 L318,-42" fill="none" stroke="{edge}" '
                f'stroke-width="1.4"/>'
                # OMS pods + main engine bells
                f'<polygon points="286,-50 340,-62 346,-54 292,-44" fill="{white}"/>'
                f'<polygon points="286,-50 340,-62 342,-58 290,-46" fill="{shade}"/>'
                f'<g fill="{tile}"><ellipse cx="330" cy="-28" rx="13" ry="11"/></g>'
                f'<g fill="#7d848b"><circle cx="338" cy="-24" r="4.5"/>'
                f'<circle cx="338" cy="-12" r="4.5"/></g>'
                f'<text x="150" y="-27" font-family="Trebuchet MS,Arial,sans-serif" font-size="11" '
                f'font-weight="bold" fill="#5a6570" letter-spacing="1.5">Independence</text>'
                f'<g fill="#c0392b"><rect x="62" y="-40" width="3.4" height="14"/></g>'
                f'<rect x="68" y="-40" width="3.4" height="14" fill="#2f6fb5"/></g>')

    def saturn_v(x, y, s=1.0):
        """A Saturn V on its side in the rocket park. It reads as a wall."""
        white, dark, shade = '#f2f2ee', '#2b2f34', '#d8dad6'
        rings = ''.join(f'<rect x="{78+i*84}" y="-46" width="22" height="46" fill="{dark}"/>'
                        f'<rect x="{78+i*84}" y="-46" width="22" height="12" fill="#4a4f55"/>'
                        for i in range(5))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="230" cy="6" rx="240" ry="9" fill="#000" opacity="0.14"/>'
                f'<rect x="24" y="-46" width="440" height="46" fill="{white}"/>'
                f'<rect x="24" y="-46" width="440" height="46" fill="none" stroke="#aeb3b8" stroke-width="1.6"/>'
                f'<rect x="24" y="-46" width="440" height="13" fill="{shade}"/>'
                f'<g opacity="0.9">{rings}</g>'
                f'<path d="M24,-46 L24,0 L-16,-8 L-16,-38 Z" fill="{white}"/>'
                f'<path d="M-16,-38 L-16,-8 L-52,-16 L-52,-30 Z" fill="{shade}"/>'
                f'<path d="M-52,-30 L-52,-16 L-84,-23 Z" fill="{white}"/>'
                f'<rect x="-118" y="-26" width="34" height="6" fill="{dark}"/>'
                f'<path d="M-118,-26 l-8,3 8,3 Z" fill="{dark}"/>'
                f'<rect x="464" y="-46" width="26" height="46" fill="{dark}"/>'
                + ''.join(f'<ellipse cx="{500+i*22}" cy="{-36+i*9}" rx="12" ry="10" fill="{dark}"/>'
                          for i in range(3))
                + f'<text x="180" y="-18" font-family="Trebuchet MS,Arial,sans-serif" font-size="15" '
                f'font-weight="bold" fill="#c0392b" letter-spacing="3">USA</text>'
                # display cradles — tall and obvious, so she reads as an exhibit on
                # stands and never as a rocket that fell over
                + ''.join(f'<g>{shadow(cx, 26, 46, 7, 0.2)}'
                          f'<rect x="{cx-44}" y="18" width="88" height="11" rx="3" fill="#6f767d"/>'
                          f'<rect x="{cx-44}" y="18" width="88" height="4" rx="2" fill="#878f96"/>'
                          f'<path d="M{cx-30},18 L{cx-16},2 M{cx+30},18 L{cx+16},2" '
                          f'stroke="#7d848b" stroke-width="9"/>'
                          f'<path d="M{cx-22},2 q22,-9 44,0 l0,7 q-22,-8 -44,0 Z" fill="#5f676e"/>'
                          f'</g>' for cx in (96, 244, 392))
                + '</g>')

    # ------------------------------------------------------------- nature ----
    def liveoak(x, y, s=1.0, a='#3d6b41', b='#4c8050', trunk='#6b5340', moss='#96a68c'):
        """Gulf-coast live oak: wide horizontal limbs, moss hanging in curtains."""
        strands = ''.join(f'<path d="M{mx},{my} q{3 if i%2 else -3},{ml*0.34:.0f} {1 if i%3 else -1},'
                          f'{ml*0.66:.0f} q{-2 if i%2 else 2},{ml*0.3:.0f} 0,{ml*0.34:.0f}" '
                          f'stroke="{moss}" stroke-width="{1.2 + (i % 3) * 0.35:.1f}" fill="none" '
                          f'opacity="{0.34 + (i % 4) * 0.1:.2f}"/>'
                          for i, (mx, my, ml) in enumerate(
                              [(-100, -38, 30), (-92, -44, 44), (-84, -46, 36), (-74, -52, 52),
                               (-66, -54, 38), (-56, -58, 58), (-48, -60, 34), (-38, -64, 48),
                               (-30, -66, 40), (-20, -68, 56), (-12, -70, 32), (0, -70, 46),
                               (10, -68, 38), (20, -66, 54), (30, -62, 36), (42, -60, 50),
                               (52, -56, 34), (62, -52, 46), (72, -48, 38), (82, -44, 52),
                               (90, -40, 30), (100, -34, 42)]))
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 96, 12, 0.16)}'
                f'<path d="M-12,4 C -14,-26 -22,-40 -30,-52 L-13,-48 C -8,-58 -3,-66 0,-82 '
                f'C 4,-66 10,-58 16,-48 L34,-54 C 24,-40 12,-26 10,4 Z" fill="{trunk}"/>'
                f'<g stroke="{trunk}" stroke-width="9" stroke-linecap="round" fill="none">'
                f'<path d="M-6,-56 C -40,-58 -66,-50 -96,-38"/>'
                f'<path d="M6,-58 C 40,-60 70,-52 100,-36"/>'
                f'<path d="M-4,-70 C -30,-78 -52,-76 -70,-66"/>'
                f'<path d="M4,-72 C 30,-80 54,-78 74,-66"/></g>'
                f'<ellipse cx="0" cy="-92" rx="104" ry="40" fill="{a}"/>'
                f'<ellipse cx="-58" cy="-74" rx="52" ry="26" fill="{b}"/>'
                f'<ellipse cx="58" cy="-76" rx="48" ry="24" fill="{b}"/>'
                f'<ellipse cx="6" cy="-116" rx="62" ry="26" fill="{b}"/>'
                f'<g>{strands}</g></g>')

    def crepe(x, y, s=1.0, bloom='#e28ab0'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 30, 5)}'
                f'<g stroke="#8a7259" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M0,0 L-6,-26 M0,0 L4,-28 M0,-14 L-16,-34 M0,-16 L16,-32"/></g>'
                f'<g fill="{bloom}"><ellipse cx="-16" cy="-42" rx="18" ry="14"/>'
                f'<ellipse cx="14" cy="-46" rx="20" ry="15"/><ellipse cx="0" cy="-58" rx="16" ry="12"/></g>'
                f'<g fill="#f0aac8" opacity="0.7"><ellipse cx="-8" cy="-50" rx="11" ry="8"/>'
                f'<ellipse cx="16" cy="-40" rx="9" ry="7"/></g></g>')

    def flagpole(x, y, s=1.0, kind='us'):
        if kind == 'us':
            flag = ('<rect x="3" y="-96" width="58" height="34" fill="#f2f2ee"/>'
                    + ''.join(f'<rect x="3" y="{-96+i*10}" width="58" height="5" fill="#c0392b"/>' for i in range(4))
                    + '<rect x="3" y="-96" width="26" height="18" fill="#2f4d8f"/>'
                    + ''.join(f'<circle cx="{8+c*6}" cy="{-92+r*6}" r="1.2" fill="#f2f2ee"/>'
                              for r in range(3) for c in range(4)))
        else:
            flag = ('<rect x="3" y="-96" width="58" height="34" fill="#f2f2ee"/>'
                    '<rect x="3" y="-79" width="58" height="17" fill="#c0392b"/>'
                    '<rect x="3" y="-96" width="20" height="34" fill="#2f4d8f"/>'
                    '<path d="M13,-84 l2.6,5.4 5.8,0.8 -4.2,4.1 1,5.8 -5.2,-2.8 -5.2,2.8 1,-5.8 '
                    '-4.2,-4.1 5.8,-0.8 Z" fill="#f2f2ee"/>')
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 14, 4)}'
                f'<rect x="-2" y="-104" width="4" height="104" fill="#d2d6d9"/>'
                f'<circle cx="0" cy="-107" r="4" fill="#e0b64a"/>{flag}</g>')

    def person(x, y, s=1.0, shirt='#2f6fb5', skin='#c98d5e', hair='#33241c', hat=None, arms='down'):
        A = {'down': 'M-6,-30 L-11,-13 M6,-30 L11,-13',
             'out':  'M-6,-30 L-19,-24 M6,-30 L19,-24',
             'up':   'M-6,-31 L-15,-49 M6,-31 L15,-49',
             'point':'M-6,-30 L-11,-13 M6,-31 L21,-46'}[arms]
        cap = ''
        if hat == 'cowboy':
            cap = ('<path d="M-15,-42 q15,5 30,0 q-4,7 -15,7 q-11,0 -15,-7 Z" fill="#8a6a45"/>'
                   '<path d="M-8,-42 q0,-9 8,-9 q8,0 8,9 Z" fill="#a3814f"/>')
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 13, 3.5)}'
                f'<g stroke="{skin}" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-15 L-5,-1 M3,-15 L6,-1"/><path d="{A}"/></g>'
                f'<rect x="-7" y="-33" width="14" height="20" rx="6" fill="{shirt}"/>'
                f'<circle cx="0" cy="-40" r="6.5" fill="{skin}"/>'
                + (cap if cap else f'<path d="M-6.5,-42 a6.5,6.5 0 0 1 13,0 z" fill="{hair}"/>') + '</g>')

    def astronaut(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 20, 5)}'
                f'<g stroke="#f2f2ee" stroke-width="9" stroke-linecap="round" fill="none">'
                f'<path d="M-5,-18 L-8,-1 M5,-18 L9,-1"/><path d="M-9,-38 L-22,-22 M9,-38 L22,-22"/></g>'
                f'<rect x="-13" y="-46" width="26" height="30" rx="9" fill="#f2f2ee"/>'
                f'<rect x="-13" y="-34" width="26" height="5" fill="#2f6fb5"/>'
                f'<rect x="-6" y="-42" width="12" height="6" rx="2" fill="#c0392b"/>'
                f'<circle cx="0" cy="-56" r="12" fill="#f2f2ee"/>'
                f'<path d="M-8,-58 a8,7 0 0 1 16,0 a8,9 0 0 1 -16,0 Z" fill="#3b4a57"/>'
                f'<path d="M-6,-59 a5,4 0 0 1 8,-1" stroke="#8fb6d4" stroke-width="2" fill="none"/></g>')

    def fence(x0, x1, y, h=34):
        posts = ''.join(f'<rect x="{x}" y="{-h}" width="3" height="{h}" fill="#2a2f34"/>'
                        for x in range(x0, x1, 15))
        return (f'<g transform="translate(0,{y})" opacity="0.92"><g>{posts}</g>'
                f'<rect x="{x0}" y="{-h}" width="{x1-x0}" height="4" fill="#2a2f34"/>'
                f'<rect x="{x0}" y="{-h*0.42:.0f}" width="{x1-x0}" height="3" fill="#2a2f34"/></g>')

    # NOTE: draw order matters — the car park and treeline sit BEHIND the hardware,
    # so they are emitted first. Put a car after the 747 and it parks on the wing.
    carpark = ('    '
               + ''.join(f'<g transform="translate({x},{y}) scale({sc})">{shadow(0, 4, 34, 5)}'
                         f'<rect x="-30" y="-15" width="60" height="13" rx="4" fill="{c}"/>'
                         f'<path d="M-17,-15 L-11,-26 L14,-26 L21,-15 Z" fill="{c}"/>'
                         f'<path d="M-14,-16 L-9,-24 L1,-24 L1,-16 Z" fill="#bfe3f5"/>'
                         f'<path d="M4,-16 L4,-24 L13,-24 L18,-16 Z" fill="#bfe3f5"/>'
                         f'<g fill="#22272d"><circle cx="-17" cy="-1" r="5"/>'
                         f'<circle cx="17" cy="-1" r="5"/></g></g>'
                         for x, y, sc, c in [(84, 346, 0.62, '#c0392b'), (152, 348, 0.62, '#3f6fa8'),
                                             (220, 346, 0.62, '#e8e8e2'), (288, 348, 0.62, '#4f8a56'),
                                             (356, 346, 0.62, '#8d949c'), (424, 348, 0.62, '#e8752a'),
                                             (786, 344, 0.56, '#e8e8e2'), (846, 342, 0.56, '#c0392b'),
                                             (1128, 344, 0.58, '#8d949c'), (1192, 346, 0.58, '#4f8a56')])
               + f'<g transform="translate(560,344) scale(0.72)">{shadow(0, 5, 66, 7)}'
               '<rect x="-64" y="-34" width="128" height="30" rx="5" fill="#f2f4f6"/>'
               '<rect x="-64" y="-34" width="128" height="9" rx="4" fill="#2f6fb5"/>'
               '<g fill="#bfe3f5">'
               + ''.join(f'<rect x="{-56+k*22}" y="-22" width="16" height="11" rx="2"/>' for k in range(5))
               + '</g><g fill="#22272d"><circle cx="-38" cy="-2" r="7"/>'
               '<circle cx="38" cy="-2" r="7"/></g></g>'
               + ''.join(f'<g transform="translate({x},358) scale({sc})">'
                         f'<ellipse cx="0" cy="-30" rx="46" ry="20" fill="#456f45"/>'
                         f'<ellipse cx="-22" cy="-24" rx="24" ry="13" fill="#547f52"/>'
                         f'<ellipse cx="22" cy="-25" rx="22" ry="12" fill="#547f52"/>'
                         f'<rect x="-4" y="-14" width="8" height="16" fill="#6b5340"/></g>'
                         for x, sc in [(40, 0.8), (472, 0.86), (700, 0.66), (1246, 0.8)]))

    back = (carpark
            + plaza(950, 398, 0.92)
            + b747(690, 398, 0.92)
            + shuttle(812, 322, 0.92)
            + saturn_v(150, 396, 0.8)
            + flagpole(496, 402, 0.66, 'us') + flagpole(540, 402, 0.66, 'tx')
            + crepe(268, 402, 0.5)
            + ''.join(f'<g transform="translate({x},400)">'
                      f'<rect x="-2" y="-52" width="4" height="52" fill="#9aa0a6"/>'
                      f'<rect x="-9" y="-58" width="18" height="7" rx="3" fill="#b4bac0"/></g>'
                      for x in (140, 380, 760, 1120))
            + person(1210, 400, 0.5, '#2f6fb5', arms='out'))

    front = ('    ' + liveoak(112, 690, 1.25) + liveoak(1216, 700, 1.15)
             + fence(756, 1280, 566) + fence(0, 528, 566)
             + crepe(360, 640, 1.0) + crepe(880, 596, 0.8, '#e8a0be')
             # a family on the walkway: dad in a cowboy hat, kid pointing at the shuttle
             + person(430, 604, 1.0, '#3f7d4f', hat='cowboy', arms='out')
             + person(468, 606, 0.72, '#f2b134', arms='point')
             + person(500, 604, 0.92, '#c0392b', arms='down')
             + astronaut(856, 700, 1.15)
             + person(912, 706, 1.1, '#2f6fb5', arms='out')
             + person(956, 710, 0.78, '#e8752a', arms='up')
             + person(268, 600, 0.9, '#7a3f9e', arms='down')
             + f'<g transform="translate(1122,688)">{shadow(0, 6, 56, 8)}'
             '<rect x="-52" y="-30" width="104" height="24" rx="5" fill="#2f3d47"/>'
             '<rect x="-52" y="-30" width="104" height="8" rx="4" fill="#41505c"/>'
             '<text x="0" y="-13" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
             'font-size="12" font-weight="bold" fill="#f2f4f6" letter-spacing="0.5">SPACE CENTER</text>'
             '<g stroke="#7d848b" stroke-width="5"><path d="M-34,-6 L-34,10 M34,-6 L34,10"/></g>'
             '<circle cx="-70" cy="-18" r="15" fill="#2f4d8f"/>'
             '<path d="M-82,-16 q12,-9 24,-3" stroke="#c0392b" stroke-width="3" fill="none"/>'
             '<circle cx="-74" cy="-21" r="1.6" fill="#ffffff"/>'
             '<circle cx="-66" cy="-16" r="1.4" fill="#ffffff"/></g>'
             + f'<g transform="translate(424,668)">{shadow(0, 4, 30, 6)}'
             '<rect x="-24" y="-16" width="48" height="6" rx="2" fill="#5f6b74"/>'
             '<rect x="-24" y="-30" width="48" height="6" rx="2" fill="#6d7982"/>'
             '<g stroke="#454f57" stroke-width="4"><path d="M-18,-10 L-20,4 M18,-10 L20,4"/></g></g>')

    scene('houston', 'HOUSTON — the shuttle Independence riding a 747, a Saturn V on its side, hazy Gulf summer', {
        'sky': sky_l,
        'far': downtown + '\n' + refinery + '\n' + treeline,
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#4f7248" opacity="0.5"><rect x="0" y="708" width="1280" height="4"/></g>',
        'roadkw': dict(surface='#74777c', surface2='#5e6165', shoulder='#e8e2c9', dash='#ffe066'),
    }, d)


# ============================================================ 10. CAPE CANAVERAL
def cape_canaveral():
    """The launch. HERO: a rocket lifting off the pad with the service tower beside
    it and the smoke rolling out sideways. Second landmark: the Vehicle Assembly
    Building, that vast pale box you can see from twenty miles away. Everything else
    is what the Cape actually is — saltmarsh, lagoon, palmetto scrub, and a gator."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#1663a8"/><stop offset="0.45" stop-color="#3d92cf"/>
      <stop offset="0.82" stop-color="#8fc4e2"/><stop offset="1" stop-color="#cfe4ec"/>
    </linearGradient>
    <linearGradient id="lake" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#2c6f96"/><stop offset="1" stop-color="#4f9cb8"/>
    </linearGradient>
    <linearGradient id="sand" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#dfd3ae"/><stop offset="1" stop-color="#c6b78c"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#fff3c0" stop-opacity="0.75"/>
      <stop offset="0.55" stop-color="#ffb54a" stop-opacity="0.3"/>
      <stop offset="1" stop-color="#ff9a2e" stop-opacity="0"/>
    </radialGradient>''')

    PAD_X, PAD_Y = 886, 292
    WATER_TOP, BANK = 258, 292
    LIFT = 74          # how far off the pad she already is

    sky_l = ('    <rect x="0" y="0" width="1280" height="304" fill="url(#skyg)"/>\n'
             '    <g fill="#ffffff" opacity="0.9">'
             + ''.join(f'<g><ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.48:.0f}"/>'
                       f'<ellipse cx="{x-r*0.6:.0f}" cy="{y+r*0.18:.0f}" rx="{r*0.6:.0f}" ry="{r*0.36:.0f}"/>'
                       f'<ellipse cx="{x+r*0.62:.0f}" cy="{y+r*0.14:.0f}" rx="{r*0.55:.0f}" ry="{r*0.32:.0f}"/>'
                       f'<ellipse cx="{x}" cy="{y+r*0.34:.0f}" rx="{r*0.92:.0f}" ry="{r*0.2:.0f}" '
                       f'fill="#d3e2ea"/></g>'
                       for x, y, r in [(180, 96, 52), (486, 66, 40), (1140, 110, 58)])
             + '</g>\n'
             '    <g stroke="#ffffff" stroke-width="3" fill="none" opacity="0.35" stroke-linecap="round">'
             '<path d="M60,52 q60,-10 130,-4"/><path d="M1010,44 q70,-8 150,-2"/></g>')

    # ---- the lagoon, the far bank, and the marsh we stand on ----
    water = (f'    <rect x="0" y="{WATER_TOP}" width="1280" height="{BANK-WATER_TOP}" fill="url(#lake)"/>\n'
             '    <g fill="#ffffff" opacity="0.22">'
             + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2" rx="1"/>'
                       for x, y, w in [(60, 280, 70), (250, 288, 92), (430, 278, 64),
                                       (620, 286, 80), (1010, 282, 74), (1180, 290, 60)])
             + '</g>\n'
             # the flame's reflection running toward us across the water
             '    <g fill="#ffb54a" opacity="0.5">'
             + ''.join(f'<rect x="{878 - w//2}" y="{y}" width="{w}" height="2.5" rx="1.2"/>'
                       for y, w in [(276, 26), (281, 44), (286, 68), (291, 96)])
             + '</g>')

    bank = (f'    <rect x="0" y="{BANK}" width="1280" height="12" fill="#4a6b46"/>\n'
            f'    <rect x="0" y="{BANK}" width="1280" height="3" fill="#5c8054"/>\n'
            '    <g fill="#3c5a3a">'
            + ''.join(f'<ellipse cx="{x}" cy="{BANK+2}" rx="{r}" ry="{r*0.44:.0f}"/>'
                      for x, r in [(50, 30), (150, 22), (270, 28), (390, 20), (500, 26),
                                   (600, 22), (700, 27), (1020, 24), (1120, 30), (1240, 22)])
            + '</g>')

    # ---- the Vehicle Assembly Building: the biggest single-storey box on earth ----
    vab = ('    <g id="vab">'
           '<rect x="118" y="176" width="176" height="92" fill="#d8dad6"/>'
           '<rect x="118" y="176" width="176" height="10" fill="#eceee9"/>'
           '<rect x="118" y="176" width="46" height="92" fill="#e4e6e2"/>'
           # the four vertical high-bay doors
           + ''.join(f'<rect x="{132+i*42}" y="192" width="26" height="76" fill="#9aa0a2"/>'
                     f'<rect x="{132+i*42}" y="192" width="26" height="7" fill="#7f8688"/>'
                     f'<g fill="#8a9092">'
                     + ''.join(f'<rect x="{132+i*42}" y="{208+k*16}" width="26" height="2.5"/>'
                               for k in range(4)) + '</g>' for i in range(4))
           # the flag and the meatball painted on the side, which are really there
           + '<rect x="122" y="182" width="26" height="16" fill="#f2f2ee"/>'
           + ''.join(f'<rect x="122" y="{183+i*3}" width="26" height="1.5" fill="#c0392b"/>' for i in range(5))
           + '<rect x="122" y="182" width="11" height="8" fill="#2f4d8f"/>'
           + '<circle cx="276" cy="192" r="9" fill="#2f4d8f"/>'
           '<path d="M269,194 q7,-6 14,-2" stroke="#c0392b" stroke-width="2" fill="none"/>'
           # low support buildings, a water tower, and the spherical propellant tanks
           + '<g fill="#c6c9c4"><rect x="60" y="244" width="52" height="24"/>'
           '<rect x="300" y="248" width="70" height="20"/><rect x="380" y="252" width="44" height="16"/></g>'
           '<g><rect x="437" y="240" width="4" height="28" fill="#9aa0a2"/>'
           '<ellipse cx="439" cy="236" rx="15" ry="11" fill="#e4e6e2"/>'
           '<g stroke="#9aa0a2" stroke-width="2"><path d="M430,246 L432,268 M448,246 L446,268"/></g></g>'
           + ''.join(f'<g><circle cx="{x}" cy="{254}" r="12" fill="#eceee9"/>'
                     f'<circle cx="{x-4}" cy="250" r="7" fill="#f7f8f6"/>'
                     f'<rect x="{x-11}" y="258" width="22" height="10" fill="#b4b8b3"/></g>'
                     for x in (500, 540))
           + '</g>')

    # ---- the crawlerway running out to the pad ----
    crawlerway = ('    <polygon points="286,292 470,292 700,304 250,304" fill="#cbc4a8"/>\n'
                  '    <polygon points="286,292 470,292 700,304 660,304 300,295" fill="#dbd5bb"/>\n'
                  '    <g stroke="#b6ae92" stroke-width="2" opacity="0.7">'
                  '<path d="M356,292 L392,304"/><path d="M420,292 L520,304"/></g>')

    # ---- the pad: rocket, tower, flame, and the smoke rolling out sideways ----
    def rocket(x, y, s=1.0):
        white, black, grey = '#f4f4f0', '#22262b', '#cfd2ce'
        bands = ''.join(f'<rect x="-15" y="{-46-i*46}" width="30" height="9" fill="{black}"/>'
                        f'<rect x="-15" y="{-46-i*46}" width="8" height="9" fill="#3b4148"/>' for i in range(4))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-15" y="-206" width="30" height="206" fill="{white}"/>'
                f'<rect x="-15" y="-206" width="10" height="206" fill="{grey}"/>'
                f'<g>{bands}</g>'
                f'<path d="M-15,-206 L0,-238 L15,-206 Z" fill="{white}"/>'
                f'<path d="M-15,-206 L0,-238 L-5,-206 Z" fill="{grey}"/>'
                f'<rect x="-3" y="-266" width="6" height="30" fill="{black}"/>'
                f'<rect x="-1.4" y="-282" width="3" height="18" fill="{black}"/>'
                f'<text x="0" y="-108" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
                f'font-size="13" font-weight="bold" fill="#c0392b" letter-spacing="1">USA</text>'
                f'<g fill="{white}"><polygon points="-15,-30 -30,4 -15,4"/>'
                f'<polygon points="15,-30 30,4 15,4"/></g>'
                f'<g fill="{grey}"><polygon points="-15,-30 -30,4 -22,4"/></g>'
                f'<g fill="{black}">' + ''.join(f'<ellipse cx="{-9+i*9}" cy="2" rx="4.4" ry="4"/>'
                                                for i in range(3)) + '</g></g>')

    def tower(x, y, s=1.0, col='#b4563a', col2='#8f4029'):
        legs = ''.join(f'<path d="M{-16+i*32},0 L{-16+i*32},-206" stroke="{col}" stroke-width="5"/>'
                       for i in range(2))
        braces = ''.join(f'<path d="M-16,{-14-i*24} L16,{-32-i*24} M16,{-14-i*24} L-16,{-32-i*24}" '
                         f'stroke="{col2}" stroke-width="2.6"/>' for i in range(8))
        decks = ''.join(f'<rect x="-24" y="{-30-i*30}" width="48" height="6" fill="{col2}"/>'
                        f'<rect x="-46" y="{-30-i*30}" width="24" height="5" fill="{col}"/>' for i in range(6))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g fill="none">{legs}{braces}</g><g>{decks}</g>'
                f'<rect x="-26" y="-222" width="52" height="18" fill="{col2}"/>'
                f'<rect x="-3" y="-252" width="6" height="30" fill="{col}"/>'
                f'<path d="M-46,-186 L-96,-178 L-96,-170 L-46,-178 Z" fill="{col2}"/></g>')

    def flame(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<path d="M-22,0 C -30,34 -22,72 -8,104 C -2,80 2,80 8,104 '
                f'C 22,72 30,34 22,0 Z" fill="#ff9a2e"/>'
                f'<path d="M-14,0 C -20,30 -13,62 -4,86 C -1,66 1,66 4,86 '
                f'C 13,62 20,30 14,0 Z" fill="#ffd35e"/>'
                f'<path d="M-7,0 C -10,26 -6,50 0,68 C 6,50 10,26 7,0 Z" fill="#fff6d2"/></g>')

    def smoke(cx, cy):
        puffs = [(-250, 24, 82, 0.95), (-160, 2, 72, 0.98), (-84, 22, 64, 0.96),
                 (-14, 38, 54, 0.92), (56, 16, 68, 0.96), (134, 32, 76, 0.94),
                 (218, 12, 62, 0.92), (300, 30, 72, 0.9), (382, 18, 56, 0.86),
                 (-330, 34, 62, 0.88), (-410, 22, 50, 0.8), (452, 34, 48, 0.8),
                 (-120, -42, 52, 0.9), (48, -52, 46, 0.88), (186, -34, 40, 0.84),
                 (-30, -84, 36, 0.8), (110, -92, 30, 0.72), (-210, -60, 34, 0.78)]
        body = ''.join(f'<ellipse cx="{cx+dx}" cy="{cy+dy}" rx="{r}" ry="{r*0.62:.0f}" '
                       f'fill="#f4f6f7" opacity="{op}"/>' for dx, dy, r, op in puffs)
        under = ''.join(f'<ellipse cx="{cx+dx}" cy="{cy+dy+r*0.4:.0f}" rx="{r*0.8:.0f}" '
                        f'ry="{r*0.3:.0f}" fill="#d2d8dc" opacity="0.75"/>'
                        for dx, dy, r, op in puffs[:9])
        warm = ''.join(f'<ellipse cx="{cx+dx}" cy="{cy+dy}" rx="{r*0.7:.0f}" ry="{r*0.4:.0f}" '
                       f'fill="#ffcf8a" opacity="0.4"/>' for dx, dy, r, op in puffs[2:6])
        return f'<g>{body}{under}{warm}</g>'

    pad = ('    <g id="pad">'
           # the flame trench and the pad apron
           '<polygon points="790,286 996,286 1016,304 770,304" fill="#c6c9c4"/>'
           '<polygon points="790,286 996,286 1000,292 792,292" fill="#dcdfda"/>'
           + tower(958, 292, 0.82)
           + f'<circle cx="{PAD_X}" cy="{PAD_Y-LIFT}" r="190" fill="url(#sung)"/>'
           + rocket(PAD_X, PAD_Y - LIFT - 26, 0.62)
           + flame(PAD_X, PAD_Y - LIFT - 28, 1.05)
           + smoke(PAD_X - 10, PAD_Y - 16)
           + '</g>')

    # ---- ground: sand, saltmarsh grass, and a tidal creek ----
    ground_l = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#sand)"/>\n'
                '    <g fill="#7f9358" opacity="0.62">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.22:.0f}"/>'
                          for x, y, r in [(120, 330, 150), (430, 344, 130), (770, 332, 160),
                                          (1100, 346, 140), (70, 400, 120), (990, 404, 150),
                                          (310, 476, 170), (1190, 492, 140), (150, 566, 160),
                                          (870, 596, 180), (490, 646, 150), (1130, 666, 160)])
                + '</g>\n'
                # saltmarsh grass, drawn as strokes so it reads as grass and not as pads
                '    <g stroke="#6f8a4c" stroke-width="2" stroke-linecap="round" fill="none" opacity="0.75">'
                + ''.join(f'<path d="M{x},{y} l{-3 - (x % 4)},{-10 - (x % 7)} M{x+5},{y} l{1 + (x % 3)},'
                          f'{-13 - (x % 6)} M{x+10},{y} l{4 + (x % 4)},{-9 - (x % 5)}"/>'
                          for y in (322, 348, 384, 428, 476, 540, 610, 686)
                          for x in range(6 + (y % 17), 1280, 34)) + '</g>\n'
                # a tidal creek winding across, the way the whole Cape is cut up by water
                '    <path d="M-20,398 C 180,392 340,418 452,438 C 560,458 606,492 566,522 '
                'C 522,556 330,552 196,572 C 96,586 22,606 -20,602 Z" fill="#4f8fa8" opacity="0.9"/>\n'
                '    <path d="M-20,398 C 180,392 340,418 452,438 C 560,458 606,492 566,522" '
                'fill="none" stroke="#8ccadb" stroke-width="3" opacity="0.75"/>\n'
                '    <g fill="#6fa8bd" opacity="0.5">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.3:.0f}"/>'
                          for x, y, r in [(120, 430, 46), (300, 470, 40), (420, 520, 34)]) + '</g>\n'
                '    <g fill="#c9bb92" opacity="0.6">'
                + ''.join(f'<path d="M{x},{y} q 40,-6 80,0"/>'
                          for x, y in [(600, 560), (900, 700), (1160, 600), (700, 660)])
                + '</g>')

    # ---------------------------------------------------------------- props ----
    def seaoats(x, y, s=1.0, blade='#a3b066', head='#cfc48d'):
        blades = ''.join(f'<path d="M0,0 C {dx*0.3:.0f},{-h*0.5:.0f} {dx*0.7:.0f},{-h*0.8:.0f} {dx},{-h}" '
                         f'stroke="{blade}" stroke-width="2.4" fill="none" stroke-linecap="round"/>'
                         f'<ellipse cx="{dx}" cy="{-h-4}" rx="1.7" ry="5.5" fill="{head}" '
                         f'transform="rotate({dx*0.5:.0f} {dx} {-h-4})"/>'
                         for dx, h in [(-26, 42), (-15, 56), (-5, 66), (6, 60), (17, 48), (27, 36)])
        low = ''.join(f'<path d="M0,0 C {dx*0.4:.0f},{-h*0.6:.0f} {dx*0.8:.0f},{-h*0.85:.0f} {dx},{-h}" '
                      f'stroke="#8fa055" stroke-width="2" fill="none" stroke-linecap="round"/>'
                      for dx, h in [(-34, 26), (-20, 32), (10, 30), (24, 24), (34, 18)])
        return f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 30, 5)}{low}{blades}</g>'

    def palmetto(x, y, s=1.0, a='#3f7a4a', b='#4d8f58'):
        fans = ''.join(f'<g transform="rotate({r} 0 0)">'
                       f'<path d="M0,0 L-4,-34 L0,-46 L4,-34 Z" fill="{a}"/>'
                       f'<path d="M0,-10 L-18,-32 L-13,-40 L0,-26 Z" fill="{b}"/>'
                       f'<path d="M0,-10 L18,-32 L13,-40 L0,-26 Z" fill="{b}"/></g>'
                       for r in (-42, -20, 0, 20, 42))
        return f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 30, 5)}{fans}</g>'

    def sabal(x, y, s=1.0, trunk='#9a8465', frond='#3f7a4a', frond2='#4d8f58'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 24)}'
                f'<path d="M-6,0 C -8,-40 2,-72 8,-100 L18,-98 C 10,-70 2,-40 6,0 Z" fill="{trunk}"/>'
                f'<g fill="{trunk}" opacity="0.5">'
                + ''.join(f'<rect x="{-6+i*0.6:.0f}" y="{-14-i*11}" width="13" height="3" rx="1.5"/>'
                          for i in range(8)) + '</g>'
                f'<g fill="{frond}">'
                f'<path d="M12,-100 C -16,-116 -40,-112 -54,-98 C -32,-104 -8,-102 10,-94 Z"/>'
                f'<path d="M12,-100 C 40,-118 64,-114 78,-100 C 56,-106 32,-104 14,-94 Z"/>'
                f'<path d="M12,-100 C 2,-128 -12,-140 -30,-146 C -12,-132 2,-118 8,-98 Z"/></g>'
                f'<g fill="{frond2}">'
                f'<path d="M12,-100 C 26,-130 44,-140 62,-146 C 44,-130 28,-116 18,-96 Z"/>'
                f'<path d="M12,-100 C 38,-92 56,-78 64,-60 C 48,-76 30,-88 12,-92 Z"/></g>'
                f'<circle cx="12" cy="-100" r="5" fill="#7a6a4a"/></g>')

    def gator(x, y, s=1.0, a='#3f4a3a', b='#4d5a44'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 62, 6)}'
                f'<path d="M-66,0 L-40,-9 L28,-11 L58,-6 L70,0 L54,3 L26,2 L-38,2 Z" fill="{a}"/>'
                f'<path d="M-66,0 L-40,-9 L28,-11 L34,-8 L-36,-5 Z" fill="{b}"/>'
                f'<g fill="{b}">' + ''.join(f'<path d="M{-30+i*13},-11 l4,-6 l4,6 Z"/>' for i in range(6)) + '</g>'
                f'<path d="M58,-6 L70,0 L54,3 Z" fill="{a}"/>'
                f'<circle cx="-46" cy="-9" r="3.4" fill="#d8cf9a"/>'
                f'<circle cx="-46" cy="-9" r="1.6" fill="#22262b"/>'
                f'<g stroke="{a}" stroke-width="5" stroke-linecap="round">'
                f'<path d="M-14,2 L-20,8 M18,2 L24,8"/></g></g>')

    def spoonbill(x, y, s=1.0, body='#e88fae', wing='#d9709a'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 12, 3)}'
                f'<g stroke="#c9737f" stroke-width="2.2"><path d="M-3,-14 L-4,0 M4,-14 L6,0"/></g>'
                f'<ellipse cx="0" cy="-22" rx="14" ry="10" fill="{body}"/>'
                f'<path d="M-8,-24 q10,-6 18,2 q-9,4 -18,-2 Z" fill="{wing}"/>'
                f'<path d="M10,-28 C 18,-36 22,-40 24,-44" stroke="{body}" stroke-width="4.5" fill="none"/>'
                f'<ellipse cx="26" cy="-46" rx="5" ry="3.6" fill="#d8d2c0"/>'
                f'<circle cx="23" cy="-48" r="1.2" fill="#22262b"/></g>')

    def pelicanpost(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 12, 4)}'
                f'<rect x="-5" y="-52" width="10" height="52" fill="#8a7458"/>'
                f'<rect x="-5" y="-52" width="10" height="4" rx="2" fill="#9c8666"/>'
                f'<ellipse cx="0" cy="-64" rx="15" ry="11" fill="#c9ccc4"/>'
                f'<path d="M-10,-66 q10,-6 18,2 q-9,4 -18,-2 Z" fill="#a8ada4"/>'
                f'<circle cx="9" cy="-74" r="7" fill="#dfe2da"/>'
                f'<path d="M14,-72 C 24,-70 26,-64 20,-62 C 16,-64 14,-68 14,-72 Z" fill="#e0a13c"/>'
                f'<circle cx="11" cy="-76" r="1.4" fill="#22262b"/></g>')

    back = ('    ' + ''.join(sabal(x, y, s) for x, y, s in
                             [(72, 400, 0.66), (300, 396, 0.54), (1160, 402, 0.7), (1244, 394, 0.58)])
            + ''.join(palmetto(x, y, s) for x, y, s in
                      [(180, 404, 0.6), (392, 400, 0.5), (470, 406, 0.66), (760, 402, 0.56),
                       (846, 406, 0.68), (1046, 400, 0.6), (1108, 406, 0.52)])
            + ''.join(seaoats(x, y, s) for x, y, s in
                      [(126, 340, 0.5), (352, 336, 0.44), (642, 340, 0.4), (930, 338, 0.46),
                       (1206, 342, 0.5)])
            + spoonbill(232, 392, 0.62) + spoonbill(266, 396, 0.54)
            + spoonbill(1006, 394, 0.58)
            + pelicanpost(546, 400, 0.6)
            + ''.join(f'<g transform="translate({x},{y}) scale(0.5)">'
                      f'<path d="M-16,0 q8,-7 16,-1 q8,-6 16,1 q-8,4 -16,1 q-8,3 -16,-1 Z" '
                      f'fill="#e8e8e2" opacity="0.9"/></g>'
                      for x, y in [(660, 200), (712, 224), (598, 232)]))

    front = ('    ' + sabal(96, 704, 1.35) + sabal(1214, 712, 1.25) + sabal(258, 640, 0.92)
             + gator(404, 604, 0.86)
             + ''.join(seaoats(x, y, s) for x, y, s in
                       [(40, 640, 1.25), (168, 690, 1.4), (300, 716, 1.3), (452, 700, 1.15),
                        (860, 664, 1.2), (960, 716, 1.35), (1090, 690, 1.25), (1250, 650, 1.1),
                        (818, 578, 0.9), (1150, 566, 0.85), (222, 570, 0.9)])
             + ''.join(palmetto(x, y, s) for x, y, s in
                       [(348, 660, 1.0), (520, 716, 1.05), (900, 604, 0.9), (1030, 640, 1.0),
                        (128, 596, 0.86)])
             + pelicanpost(786, 700, 1.15)
             + spoonbill(432, 690, 1.0) + spoonbill(470, 700, 0.86)
             + f'<g transform="translate(1120,596)">{shadow(0, 4, 34, 6)}'
             '<rect x="-30" y="-30" width="60" height="24" rx="3" fill="#2f4d8f"/>'
             '<rect x="-30" y="-30" width="60" height="7" rx="3" fill="#3f5f9f"/>'
             '<text x="0" y="-13" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
             'font-size="11" font-weight="bold" fill="#f2f4f6">PAD 39</text>'
             '<g stroke="#8a9096" stroke-width="4"><path d="M-16,-6 L-16,8 M16,-6 L16,8"/></g></g>')

    scene('cape-canaveral', 'CAPE CANAVERAL — a rocket off Pad 39, the VAB, saltmarsh and a gator', {
        'sky': sky_l,
        'far': vab + '\n' + water + '\n' + bank + '\n' + crawlerway + '\n' + pad,
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#b6a97e" opacity="0.5"><rect x="0" y="708" width="1280" height="4"/></g>',
        'roadkw': dict(surface='#7a7a74', surface2='#63635e', shoulder='#e8dfc0', dash='#ffe066'),
    }, d)


# =============================================================== 11. OʻAHU
def oahu():
    """Waikīkī looking east. HERO: Diamond Head's crater rim, fluted and gold, across
    the reef. Second: the wall of hotels down the beach with the pink Royal Hawaiian
    in it. Everything in front is what Waikīkī actually is — turquoise reef water,
    outrigger canoes, coconut palms, the Duke with leis on his arms, and hula."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#1f7ec4"/><stop offset="0.52" stop-color="#63aede"/>
      <stop offset="1" stop-color="#c2e2ee"/>
    </linearGradient>
    <linearGradient id="ocean" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#1d6f9e"/><stop offset="0.34" stop-color="#2e9fc0"/>
      <stop offset="0.68" stop-color="#4fc8d2"/><stop offset="1" stop-color="#8fe0dc"/>
    </linearGradient>
    <linearGradient id="sand" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#f4e8cc"/><stop offset="1" stop-color="#e0cfa6"/>
    </linearGradient>
    <linearGradient id="grassg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5f9e4a"/><stop offset="1" stop-color="#457a37"/>
    </linearGradient>''')

    WATER_TOP, SURF, BEACH = 248, 282, 294

    sky_l = ('    <rect x="0" y="0" width="1280" height="304" fill="url(#skyg)"/>\n'
             '    <g fill="#ffffff">'
             + ''.join(f'<g opacity="{op}"><ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.44:.0f}"/>'
                       f'<ellipse cx="{x-r*0.58:.0f}" cy="{y+r*0.16:.0f}" rx="{r*0.56:.0f}" ry="{r*0.34:.0f}"/>'
                       f'<ellipse cx="{x+r*0.6:.0f}" cy="{y+r*0.12:.0f}" rx="{r*0.5:.0f}" ry="{r*0.3:.0f}"/>'
                       f'<ellipse cx="{x-r*0.1:.0f}" cy="{y-r*0.3:.0f}" rx="{r*0.44:.0f}" ry="{r*0.28:.0f}"/></g>'
                       for x, y, r, op in [(150, 78, 62, 0.95), (430, 52, 46, 0.9),
                                           (720, 88, 54, 0.92), (1010, 58, 44, 0.88),
                                           (1210, 96, 50, 0.9)])
             + '</g>\n'
             # the rainbow you get almost daily over the Koʻolau
             '    <g fill="none" opacity="0.26" stroke-linecap="round">'
             + ''.join(f'<path d="M96,262 A 148,148 0 0 1 392,262" stroke="{c}" stroke-width="6" '
                       f'transform="translate(0,{k*6})"/>'
                       for k, c in enumerate(['#e8574a', '#f2a13c', '#f2d84a', '#6fc45f', '#4f9fd6', '#8f6fc4']))
             + '</g>')

    # ---- the Koʻolau ridge behind town, blue with distance ----
    koolau = ('    <polygon points="-20,252 40,214 120,232 210,196 300,224 380,206 460,236 '
              '540,248 -20,252" fill="#6f93a8" opacity="0.75"/>\n'
              '    <g stroke="#5d8296" stroke-width="2.5" opacity="0.5" fill="none">'
              + ''.join(f'<path d="M{x},{y} l{-6 - (x % 5)},{22 + (x % 9)}"/>'
                        for x, y in [(50, 220), (128, 238), (216, 202), (306, 230), (386, 212), (466, 240)])
              + '</g>')

    # ---- Waikīkī's hotel wall, with the pink one in it ----
    def hotel(x, y, w, base='#eef0ea', lit='#f8f9f4', win='#b9c9d2', step=11):
        rows = int((252 - y - 10) // step)
        wins = ''.join(f'<rect x="{x+3}" y="{y+8+r*step}" width="{w-6}" height="4"/>' for r in range(rows))
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{252-y}" rx="1.5" fill="{base}"/>'
                f'<rect x="{x}" y="{y}" width="{w*0.3:.0f}" height="{252-y}" fill="{lit}"/>'
                f'<g fill="{win}" opacity="0.75">{wins}</g>')
    hotels = ('    <g>'
              + ''.join(hotel(*t) for t in
                        [(0, 176, 34), (36, 158, 26), (66, 188, 30), (100, 166, 24),
                         (128, 182, 32), (164, 154, 26), (194, 190, 30), (230, 172, 24),
                         (258, 196, 34), (296, 178, 26), (326, 200, 30), (362, 184, 24),
                         (390, 202, 32), (426, 190, 26), (456, 206, 30), (494, 196, 24),
                         (524, 210, 26), (556, 200, 22), (582, 214, 28)])
              # the Royal Hawaiian — the pink one everybody looks for
              + hotel(214, 222, 40, '#f0b8c2', '#f7cbd2', '#d99aa8', 12)
              + '<path d="M209,222 L234,210 L259,222 Z" fill="#e0a2ae"/>'
              + '</g>\n'
              # the strip of palms and low buildings at the hotels\' feet
              '    <rect x="0" y="246" width="616" height="8" fill="#3f6b3f"/>\n'
              '    <g fill="#3f6b3f">'
              + ''.join(f'<ellipse cx="{x}" cy="248" rx="{r}" ry="{r*0.7:.0f}"/>'
                        for x, r in [(24, 11), (78, 9), (136, 12), (198, 8), (262, 11),
                                     (322, 9), (384, 12), (444, 9), (500, 11),
                                     (556, 10), (604, 12)]) + '</g>')

    # ---- Diamond Head ----
    diamond = ('    <g id="diamond-head">'
               # the crater's asymmetric profile: steep to the peak, long tail east
               '<polygon points="628,252 704,240 772,214 838,182 898,158 952,148 998,154 '
               '1042,176 1104,198 1180,218 1252,236 1280,244 1280,252" fill="#a8865c"/>'
               '<polygon points="952,148 998,154 1042,176 1104,198 1180,218 1252,236 1280,244 '
               '1280,252 1090,252 1000,190" fill="#c2a070"/>'
               '<polygon points="628,252 704,240 772,214 838,182 898,158 952,148 1000,190 '
               '880,252" fill="#8a6844"/>'
               # the notch in the rim
               '<path d="M898,158 L936,166 L952,148" fill="none" stroke="#7a5c3c" stroke-width="3"/>'
               # tapered erosion gullies — wide at the ridge, pinching out at the base
               + '<g fill="#8a6b46" opacity="0.17">'
               + ''.join(f'<polygon points="{x},{170 + abs(x-975)*0.108:.0f} '
                         f'{x + 5},{172 + abs(x-975)*0.108:.0f} '
                         f'{x + (x-975)*0.05 + 3:.0f},252 {x + (x-975)*0.05 - 2:.0f},252"/>'
                         for x in range(672, 1276, 34)) + '</g>'
               + '<g fill="#cfae7c" opacity="0.16">'
               + ''.join(f'<polygon points="{x},{174 + abs(x-975)*0.108:.0f} '
                         f'{x + 6},{176 + abs(x-975)*0.108:.0f} '
                         f'{x + (x-975)*0.05 + 2:.0f},250 {x + (x-975)*0.05 - 1:.0f},250"/>'
                         for x in range(686, 1276, 52)) + '</g>'
               # kiawe scrub skirting the base
               + '<path d="M628,252 Q 760,238 900,236 T 1180,238 T 1280,244 L1280,252 Z" '
               'fill="#5d8a4a" opacity="0.9"/>'
               + '<g fill="#4f7a40" opacity="0.7">'
               + ''.join(f'<ellipse cx="{x}" cy="{248}" rx="{r}" ry="{r*0.3:.0f}"/>'
                         for x, r in [(672, 26), (760, 20), (856, 24), (960, 18),
                                      (1064, 24), (1168, 20), (1250, 22)]) + '</g>'
               + '</g>')

    # ---- the reef: pale turquoise inshore, deep blue out, coral mottling ----
    water = (f'    <rect x="0" y="{WATER_TOP}" width="1280" height="{BEACH-WATER_TOP}" fill="url(#ocean)"/>\n'
             '    <g fill="#2a7f9c" opacity="0.35">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.24:.0f}"/>'
                       for x, y, r in [(140, 268, 54), (330, 274, 40), (520, 266, 46),
                                       (700, 276, 52), (900, 268, 38), (1090, 274, 48),
                                       (240, 262, 30), (820, 262, 34), (1210, 266, 40)])
             + '</g>\n'
             # surf lines on the reef edge and the breakwater groins
             '    <g fill="#ffffff" opacity="0.8">'
             + ''.join(f'<path d="M{x},{y} q {w*0.5:.0f},-4 {w},0 q {-w*0.5:.0f},3 {-w},0 Z"/>'
                       for x, y, w in [(90, 262, 120), (330, 256, 96), (600, 260, 140),
                                       (880, 254, 110), (1120, 260, 120)])
             + '</g>\n'
             '    <g fill="#c6bda4">'
             + ''.join(f'<polygon points="{x},{SURF} {x+9},{SURF} {x+5},{264} {x+2},{264}"/>'
                       for x in (352, 596, 848)) + '</g>\n'
             # catamarans and an outrigger out on the water
             + '    ' + ''.join(f'<g transform="translate({x},{y}) scale({s})">'
                                f'<path d="M-20,0 L20,0 L15,5 L-15,5 Z" fill="#f2f2ea"/>'
                                f'<rect x="-1" y="-26" width="2" height="26" fill="#8a7f6c"/>'
                                f'<path d="M1,-25 L1,-3 L16,-3 Z" fill="{c}"/>'
                                f'<path d="M-1,-22 L-1,-3 L-12,-3 Z" fill="#f7f4e8"/></g>'
                                for x, y, s, c in [(196, 272, 0.9, '#e8574a'), (760, 268, 0.8, '#f2b134'),
                                                   (1024, 276, 0.95, '#4fb8d6')]))

    # ---- the beach: white crescent, wet sand, foam ----
    beach = (f'    <path d="M0,{SURF} Q 220,{SURF+8} 460,{SURF+3} T 900,{SURF+6} T 1280,{SURF+2} '
             f'L1280,{BEACH+10} L0,{BEACH+10} Z" fill="#cfc3a4"/>\n'
             '    <g fill="#ffffff" opacity="0.92">'
             f'<path d="M0,{SURF-2} Q 220,{SURF+6} 460,{SURF+1} T 900,{SURF+4} T 1280,{SURF} '
             f'L1280,{SURF+7} Q 900,{SURF+11} 460,{SURF+8} T 0,{SURF+5} Z"/></g>\n'
             f'    <rect x="0" y="{BEACH}" width="1280" height="12" fill="#efe2c0"/>')

    ground_l = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#sand)"/>\n'
                # the grass of Kapiʻolani-side park, where the hula happens
                '    <path d="M0,430 Q 300,408 640,428 T 1280,418 L1280,720 L0,720 Z" fill="url(#grassg)"/>\n'
                '    <path d="M0,430 Q 300,408 640,428 T 1280,418 L1280,438 Q 640,448 0,440 Z" '
                'fill="#6fae55" opacity="0.7"/>\n'
                # the beach walk
                '    <rect x="0" y="358" width="1280" height="26" fill="#e6d9b4"/>\n'
                '    <rect x="0" y="358" width="1280" height="4" fill="#f2e7c8"/>\n'
                '    <g fill="#d3c39c" opacity="0.7">'
                + ''.join(f'<rect x="{x}" y="365" width="{9 + x % 6}" height="4" rx="2"/>'
                          for x in range(6, 1280, 26)) + '</g>\n'
                '    <g fill="#d8c9a2" opacity="0.55">'
                + ''.join(f'<path d="M{x},{y} q 44,-6 88,0" stroke="#d8c9a2" stroke-width="3" fill="none"/>'
                          for x, y in [(60, 328), (340, 340), (700, 326), (1000, 344), (1180, 332)])
                + '</g>')

    # ---------------------------------------------------------------- props ----
    def palm(x, y, s=1.0, trunk='#a38a63', frond='#3f8f52', frond2='#4fa862'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 28)}'
                f'<path d="M-6,0 C -9,-42 3,-76 10,-104 L20,-102 C 12,-74 2,-42 6,0 Z" fill="{trunk}"/>'
                f'<g fill="{trunk}" opacity="0.45">'
                + ''.join(f'<rect x="{-6+i*0.7:.0f}" y="{-14-i*12}" width="14" height="3" rx="1.5"/>'
                          for i in range(8)) + '</g>'
                f'<g fill="{frond}">'
                f'<path d="M14,-104 C -18,-120 -44,-114 -58,-98 C -34,-106 -8,-104 12,-96 Z"/>'
                f'<path d="M14,-104 C 46,-122 72,-116 86,-100 C 62,-108 36,-106 16,-96 Z"/>'
                f'<path d="M14,-104 C 2,-136 -14,-148 -34,-154 C -14,-140 2,-124 10,-102 Z"/></g>'
                f'<g fill="{frond2}">'
                f'<path d="M14,-104 C 30,-136 50,-146 70,-152 C 50,-136 32,-120 20,-100 Z"/>'
                f'<path d="M14,-104 C 42,-96 62,-80 70,-60 C 52,-78 32,-90 14,-94 Z"/></g>'
                f'<g fill="#8a6f3f"><circle cx="10" cy="-100" r="4"/><circle cx="19" cy="-98" r="3.4"/>'
                f'<circle cx="14" cy="-93" r="3.4"/></g></g>')

    def person(x, y, s=1.0, suit='#e8574a', skin='#a9724a', hair='#241a14', arms='down'):
        A = {'down': 'M-6,-30 L-11,-13 M6,-30 L11,-13',
             'out':  'M-6,-30 L-19,-24 M6,-30 L19,-24',
             'up':   'M-6,-31 L-15,-49 M6,-31 L15,-49'}[arms]
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 13, 3.5)}'
                f'<g stroke="{skin}" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-15 L-5,-1 M3,-15 L6,-1"/><path d="{A}"/></g>'
                f'<rect x="-7" y="-33" width="14" height="20" rx="6" fill="{suit}"/>'
                f'<circle cx="0" cy="-40" r="6.5" fill="{skin}"/>'
                f'<path d="M-6.5,-42 a6.5,6.5 0 0 1 13,0 z" fill="{hair}"/></g>')

    def hula(x, y, s=1.0, top='#c0392b', skin='#a9724a', flip=1):
        """Ti-leaf skirt, lei, a flower over the ear, ʻuliʻuli in the raised hands."""
        leaves = ''.join(f'<path d="M{dx},-30 L{dx*1.9:.0f},{6 + abs(dx)*0.5:.0f} '
                         f'L{dx*1.55:.0f},{10 + abs(dx)*0.5:.0f} L{dx*0.5:.0f},-28 Z" '
                         f'fill="{"#4f9e3a" if i % 2 else "#5fb045"}"/>'
                         for i, dx in enumerate([-15, -11, -7, -3, 2, 6, 10, 14]))
        return (f'<g transform="translate({x},{y}) scale({s * flip},{s})">{shadow(0, 2, 16, 4)}'
                f'<g stroke="{skin}" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-4,-12 L-6,-1 M4,-12 L7,-1"/></g>'
                f'<g>{leaves}</g>'
                f'<rect x="-7" y="-44" width="14" height="18" rx="5" fill="{top}"/>'
                f'<path d="M-7,-40 q7,5 14,0 l0,4 q-7,5 -14,0 Z" fill="#f2c84a"/>'
                # lei
                f'<path d="M-8,-42 q8,9 16,0" stroke="#f7f4e8" stroke-width="4" fill="none"/>'
                f'<g fill="#f7f4e8"><circle cx="-6" cy="-40" r="2"/><circle cx="0" cy="-37" r="2.2"/>'
                f'<circle cx="6" cy="-40" r="2"/></g>'
                # raised arms with ʻuliʻuli
                f'<g stroke="{skin}" stroke-width="4.6" stroke-linecap="round" fill="none">'
                f'<path d="M-6,-42 L-20,-56"/><path d="M6,-42 L21,-52"/></g>'
                f'<g><circle cx="-22" cy="-58" r="4" fill="#a3854f"/>'
                f'<circle cx="-22" cy="-64" r="5.5" fill="#d8342c"/>'
                f'<circle cx="-26" cy="-62" r="3.4" fill="#f2c84a"/>'
                f'<circle cx="23" cy="-54" r="4" fill="#a3854f"/>'
                f'<circle cx="23" cy="-60" r="5.5" fill="#d8342c"/>'
                f'<circle cx="27" cy="-58" r="3.4" fill="#f2c84a"/></g>'
                f'<circle cx="0" cy="-51" r="6.5" fill="{skin}"/>'
                f'<path d="M-6.5,-53 a6.5,6.5 0 0 1 13,0 z" fill="#241a14"/>'
                f'<path d="M-7,-52 q-2,7 1,11" stroke="#241a14" stroke-width="4" fill="none"/>'
                f'<circle cx="7" cy="-55" r="3" fill="#f7f4e8"/>'
                f'<circle cx="7" cy="-55" r="1.2" fill="#f2c84a"/></g>')

    def ukulele(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 14, 4)}'
                f'<g stroke="#a9724a" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-14 L-5,-1 M3,-14 L6,-1"/></g>'
                f'<rect x="-7" y="-34" width="14" height="20" rx="5" fill="#f2e8d0"/>'
                f'<g fill="#4f9e3a"><path d="M-7,-30 q7,4 14,0 l0,5 q-7,4 -14,0 Z"/></g>'
                f'<circle cx="0" cy="-41" r="6.5" fill="#a9724a"/>'
                f'<path d="M-6.5,-43 a6.5,6.5 0 0 1 13,0 z" fill="#241a14"/>'
                f'<g transform="translate(9,-24) rotate(-24)">'
                f'<ellipse cx="0" cy="0" rx="8" ry="10" fill="#c9954f"/>'
                f'<circle cx="0" cy="-1" r="3" fill="#7a5a2f"/>'
                f'<rect x="-1.6" y="-24" width="3.2" height="15" fill="#8a6a3f"/>'
                f'<rect x="-3" y="-27" width="6" height="4" rx="1.5" fill="#7a5a2f"/></g>'
                f'<g stroke="#a9724a" stroke-width="4.4" stroke-linecap="round" fill="none">'
                f'<path d="M-6,-30 L-12,-20"/><path d="M6,-30 L14,-26"/></g></g>')

    def duke(x, y, s=1.0):
        """The Duke Kahanamoku statue: arms out, board behind, leis on his wrists."""
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 40, 7)}'
                f'<ellipse cx="0" cy="-6" rx="42" ry="12" fill="#8a8578"/>'
                f'<ellipse cx="-6" cy="-10" rx="34" ry="9" fill="#9c9789"/>'
                f'<rect x="-15" y="-108" width="30" height="92" rx="15" fill="#6b5a44"/>'
                f'<rect x="-11" y="-104" width="10" height="84" rx="5" fill="#84704f"/>'
                f'<rect x="-15" y="-108" width="30" height="92" rx="15" fill="none" stroke="#4f4232" stroke-width="1.6"/>'
                f'<g stroke="#8a6a3f" stroke-width="7" stroke-linecap="round" fill="none">'
                f'<path d="M-5,-20 L-7,-8 M5,-20 L8,-8"/></g>'
                f'<rect x="-9" y="-56" width="18" height="26" rx="6" fill="#b8823f"/>'
                f'<g stroke="#b8823f" stroke-width="6" stroke-linecap="round" fill="none">'
                f'<path d="M-8,-52 L-30,-44"/><path d="M8,-52 L30,-44"/></g>'
                f'<circle cx="0" cy="-64" r="8.5" fill="#b8823f"/>'
                f'<path d="M-8,-66 a8,8 0 0 1 16,0 z" fill="#4a3a26"/>'
                # leis hanging off both wrists
                + ''.join(f'<g fill="#d9709a"><path d="M{sx},-44 q{sx*0.2:.0f},16 {sx*0.06:.0f},26" '
                          f'stroke="#d9709a" stroke-width="4.5" fill="none"/>'
                          f'<circle cx="{sx*0.95:.0f}" cy="-34" r="3"/>'
                          f'<circle cx="{sx*0.9:.0f}" cy="-26" r="3"/>'
                          f'<circle cx="{sx*0.85:.0f}" cy="-18" r="3"/></g>' for sx in (-31, 31))
                + f'<g fill="#f2c84a"><circle cx="-3" cy="-10" r="3"/><circle cx="5" cy="-9" r="3"/>'
                f'<circle cx="12" cy="-11" r="3"/></g>'
                f'<g fill="#d9709a"><circle cx="-12" cy="-10" r="3"/><circle cx="-20" cy="-11" r="3"/></g></g>')

    def board_rack(x, y, s=1.0):
        cols = ['#e8574a', '#f2b134', '#4fb8d6', '#f7f4e8', '#7bc86c']
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 40, 6)}'
                + ''.join(f'<g transform="translate({-32 + i*16},0) rotate({-8 + i*4})">'
                          f'<rect x="-6" y="-76" width="12" height="78" rx="6" fill="{cols[i]}"/>'
                          f'<rect x="-1.6" y="-72" width="3.2" height="70" rx="1.6" fill="#ffffff" '
                          f'opacity="0.5"/></g>' for i in range(5))
                + f'<rect x="-42" y="-16" width="84" height="5" rx="2" fill="#8a7458"/></g>')

    def outrigger(x, y, s=1.0, hull='#f2e8d0', trim='#c0392b'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 76, 8)}'
                f'<path d="M-78,-10 C -50,-22 50,-22 78,-10 L70,2 C 40,-6 -40,-6 -70,2 Z" fill="{hull}"/>'
                f'<path d="M-78,-10 C -50,-22 50,-22 78,-10 L74,-6 C 46,-17 -46,-17 -74,-6 Z" fill="{trim}"/>'
                f'<g stroke="#8a7458" stroke-width="4"><path d="M-40,-6 L-56,14 M22,-6 L6,14"/></g>'
                f'<path d="M-70,14 C -40,6 20,6 44,14 L40,20 C 18,13 -38,13 -66,20 Z" fill="#c9954f"/>'
                f'<g fill="#8a7458"><rect x="-30" y="-14" width="7" height="6"/>'
                f'<rect x="10" y="-14" width="7" height="6"/></g></g>')

    def umbrella(x, y, s=1.0, a='#e8574a', b='#f7f4e8'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 26)}'
                f'<rect x="-2" y="-42" width="4" height="42" fill="#a89880"/>'
                f'<path d="M-34,-40 A34,20 0 0 1 34,-40 Z" fill="{a}"/>'
                f'<path d="M-34,-40 A34,20 0 0 1 -12,-40 Z" fill="{b}"/>'
                f'<path d="M0,-40 A34,20 0 0 1 22,-40 Z" fill="{b}"/></g>')

    def hibiscus(x, y, s=1.0, col='#e8574a'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 26, 5)}'
                f'<g fill="#3f7a44"><ellipse cx="0" cy="-16" rx="26" ry="17"/>'
                f'<ellipse cx="-14" cy="-24" rx="17" ry="12"/><ellipse cx="15" cy="-25" rx="15" ry="11"/></g>'
                + ''.join(f'<g fill="{c}"><circle cx="{cx}" cy="{cy}" r="6"/>'
                          f'<circle cx="{cx+3}" cy="{cy-3}" r="3.4" fill="#f2c84a"/></g>'
                          for cx, cy, c in [(-16, -30, col), (12, -34, col), (0, -20, col)]) + '</g>')

    back = ('    ' + ''.join(palm(x, y, s) for x, y, s in
                             [(70, 400, 0.66), (196, 404, 0.56), (318, 398, 0.62), (536, 402, 0.5),
                              (760, 400, 0.54), (964, 404, 0.52), (1104, 398, 0.66), (1236, 404, 0.56)])
            + duke(430, 400, 0.86)
            + board_rack(846, 398, 0.66)
            + ''.join(umbrella(x, y, s, a) for x, y, s, a in
                      [(126, 336, 0.46, '#4fb8d6'), (250, 340, 0.42, '#f2b134'),
                       (392, 336, 0.46, '#e8574a'), (700, 338, 0.44, '#7bc86c'),
                       (900, 334, 0.48, '#4fb8d6'), (1050, 340, 0.42, '#f2b134'),
                       (1190, 336, 0.46, '#e8574a')])
            + outrigger(560, 344, 0.44, '#f2e8d0', '#f2b134')
            + outrigger(1010, 348, 0.4, '#f2e8d0', '#4fb8d6')
            + board_rack(236, 346, 0.4) + board_rack(1146, 348, 0.38)
            + ''.join(person(x, y, s, c, arms=a) for x, y, s, c, a in
                      [(180, 344, 0.4, '#f2b134', 'out'), (330, 340, 0.38, '#4fb8d6', 'up'),
                       (462, 342, 0.38, '#e8574a', 'down'), (830, 342, 0.4, '#7bc86c', 'out'),
                       (988, 338, 0.38, '#f2b134', 'up'), (1140, 344, 0.4, '#4fb8d6', 'down')]))

    front = ('    ' + palm(78, 700, 1.5) + palm(1230, 712, 1.42) + palm(226, 604, 0.92)
             + hibiscus(188, 592, 0.9) + hibiscus(1096, 664, 0.9, '#f2b134')
             # the hālau: three dancers and a player, out on the grass
             + ukulele(378, 664, 1.15)
             + hula(452, 668, 1.2, '#c0392b')
             + hula(268, 690, 1.12, '#e08a2c', flip=-1)
             + hula(880, 672, 1.18, '#7a3f9e')
             + outrigger(986, 706, 1.0)
             + board_rack(126, 716, 0.9)
             + umbrella(1160, 596, 0.9, '#e8574a')
             + person(806, 596, 0.86, '#4fb8d6', arms='out')
             + person(1046, 604, 0.9, '#f2b134', arms='up')
             + f'<g transform="translate(958,596)">{shadow(0, 4, 30, 6)}'
             '<rect x="-26" y="-30" width="52" height="24" rx="4" fill="#3f8f8a"/>'
             '<rect x="-26" y="-30" width="52" height="7" rx="3" fill="#4fb0a8"/>'
             '<text x="0" y="-13" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
             'font-size="10" font-weight="bold" fill="#f7f4e8">SHAVE ICE</text>'
             '<g stroke="#2f6b68" stroke-width="4"><path d="M-14,-6 L-14,6 M14,-6 L14,6"/></g>'
             '<g fill="#e8574a"><path d="M22,-40 a9,9 0 0 1 18,0 l-9,14 Z"/></g>'
             '<path d="M22,-40 a9,9 0 0 1 18,0" fill="#4fb8d6"/></g>')

    scene('oahu', 'OʻAHU — Diamond Head over the Waikīkī reef, outriggers, the Duke, and hula', {
        'sky': sky_l,
        'far': koolau + '\n' + hotels + '\n' + diamond + '\n' + water + '\n' + beach,
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#d8c9a2" opacity="0.5"><rect x="0" y="708" width="1280" height="4"/></g>',
        'roadkw': dict(surface='#6f6f6a', surface2='#585853', shoulder='#efe2c0', dash='#ffe066'),
    }, d)


# ================================================================ 12. DENALI
def denali():
    """DENALI, seen the way almost everyone actually sees it: from the south, across
    the Susitna flats near Talkeetna, where the Alaska Railroad runs. That is a real
    place with a real composition — the Range fills the whole horizon, forested
    ridges step down toward you, spruce-covered valley walls close in on both sides,
    and the braided river threads the floor. Aurora overhead, September.

    The mountains must be IRREGULAR. Evenly-spaced matching triangles read as
    wallpaper; a real range is one dominant massif and a mess of unequal peaks."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#040a1c"/><stop offset="0.44" stop-color="#0b1836"/>
      <stop offset="0.8" stop-color="#132a4e"/><stop offset="1" stop-color="#1a3a5c"/>
    </linearGradient>
    <linearGradient id="aurora" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#4ef5b0" stop-opacity="0"/>
      <stop offset="0.22" stop-color="#4ef5b0" stop-opacity="0.5"/>
      <stop offset="0.62" stop-color="#6effc4" stop-opacity="0.52"/>
      <stop offset="0.86" stop-color="#ff7fbf" stop-opacity="0.42"/>
      <stop offset="1" stop-color="#e0508f" stop-opacity="0"/>
    </linearGradient>
    <linearGradient id="aurora2" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#7fe8d0" stop-opacity="0"/>
      <stop offset="0.3" stop-color="#5cf0bc" stop-opacity="0.32"/>
      <stop offset="0.78" stop-color="#a8ff9e" stop-opacity="0.28"/>
      <stop offset="1" stop-color="#ffd36a" stop-opacity="0"/>
    </linearGradient>
    <linearGradient id="river" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#12283f"/><stop offset="1" stop-color="#1d4258"/>
    </linearGradient>
    <linearGradient id="grassg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#1e2a22"/><stop offset="1" stop-color="#111a16"/>
    </linearGradient>''')

    state = [77042]
    def rnd():
        state[0] = (state[0] * 1103515245 + 12345) % 2147483648
        return state[0] / 2147483648.0

    stars = ''.join(f'<circle cx="{rnd()*1280:.0f}" cy="{rnd()*230:.0f}" '
                    f'r="{0.6 + rnd()*1.5:.1f}" opacity="{0.28 + rnd()*0.66:.2f}"/>'
                    for _ in range(250))
    sky_l = ('    <rect x="0" y="0" width="1280" height="306" fill="url(#skyg)"/>\n'
             f'    <g fill="#ffffff">{stars}</g>\n'
             '    <g stroke="#ffffff" stroke-width="1.4" opacity="0.7" stroke-linecap="round">'
             '<path d="M300,44 l26,16"/><path d="M1076,88 l-20,12"/></g>')

    def curtain(pts, grad='aurora', rays=26, ray_op=0.34):
        body = f'<polygon points="{pts}" fill="url(#{grad})"/>'
        coords = [tuple(map(float, p.split(','))) for p in pts.split()]
        top = coords[:len(coords) // 2]
        out = []
        for i in range(rays):
            t = i / max(1, rays - 1)
            k = t * (len(top) - 1)
            k0, k1 = int(k), min(int(k) + 1, len(top) - 1)
            f = k - k0
            x = top[k0][0] + (top[k1][0] - top[k0][0]) * f
            y = top[k0][1] + (top[k1][1] - top[k0][1]) * f
            h, w, lean = 130 + rnd() * 210, 6 + rnd() * 16, (rnd() - 0.5) * 40
            out.append(f'<polygon points="{x-w:.0f},{y:.0f} {x+w:.0f},{y:.0f} '
                       f'{x + w*0.42 + lean:.0f},{y+h:.0f} {x - w*0.42 + lean:.0f},{y+h:.0f}" '
                       f'fill="url(#{grad})" opacity="{ray_op * (0.5 + rnd()):.2f}"/>')
        return f'<g>{body}{"".join(out)}</g>'

    aurora = ('    <g id="aurora">'
              + curtain('-60,2 130,22 320,48 500,68 660,52 820,26 1000,10 1180,28 1300,52 '
                        '1300,112 1180,88 1000,72 820,88 660,114 500,130 320,110 130,84 -60,62',
                        'aurora', 34, 0.42)
              + curtain('-60,44 120,64 300,92 460,116 600,134 720,150 '
                        '720,208 600,192 460,174 300,150 120,124 -60,104', 'aurora2', 20, 0.28)
              + '<polygon points="596,18 668,12 730,208 644,218" fill="url(#aurora)" opacity="0.58"/>'
              '<polygon points="620,22 652,18 686,202 648,208" fill="#b6ffdc" opacity="0.32"/>'
              '<polygon points="632,24 646,22 664,196 646,200" fill="#eafff4" opacity="0.28"/>'
              + '<g fill="#ff7fbf" opacity="0.26">'
              + ''.join(f'<polygon points="{x},{170 + (x % 23)} {x+13},{174 + (x % 19)} '
                        f'{x+9},{222 + (x % 17)} {x-3},{218 + (x % 21)}"/>'
                        for x in range(470, 900, 27)) + '</g></g>')

    # ---- THE ALASKA RANGE. Hand-placed, deliberately unequal. ----
    # Denali is the broad massif left of centre; Foraker sits beside it; everything
    # else trails away at irregular heights and spacings.
    RIDGE = [(-50, 262), (14, 226), (52, 206), (92, 232), (128, 190), (162, 210),
             (196, 158), (226, 184), (262, 140), (296, 112), (330, 92), (362, 84),
             (392, 100), (416, 138), (444, 120), (468, 152), (500, 128), (524, 166),
             (556, 142), (584, 178), (614, 156), (646, 194), (676, 170), (712, 202),
             (748, 182), (784, 214), (818, 190), (856, 220), (894, 198), (934, 226),
             (976, 204), (1018, 232), (1062, 208), (1108, 236), (1152, 212), (1198, 240),
             (1246, 218), (1300, 244)]

    def snowcap(x, y, half, drop, op=0.95):
        return (f'<polygon points="{x},{y} {x + half*1.1:.0f},{y + drop} '
                f'{x + half*0.45:.0f},{y + drop*0.72:.0f} {x - half*0.3:.0f},{y + drop*0.9:.0f} '
                f'{x - half:.0f},{y + drop*0.66:.0f}" fill="#dbe8ee" opacity="{op}"/>')

    range_pts = ' '.join(f'{x},{y}' for x, y in RIDGE)
    ranges = ('    <g id="alaska-range">'
              f'<polygon points="{range_pts} 1300,286 -50,286" fill="#3d5266"/>'
              # the lit south-east flanks
              f'<polygon points="296,112 330,92 362,84 392,100 416,138 444,120 468,152 '
              f'500,128 524,166 556,142 584,178 500,286 330,286" fill="#556e82"/>'
              f'<polygon points="196,158 226,184 262,140 296,112 330,286 200,286" fill="#31465a"/>'
              # snow only on the ones high enough to hold it, at varied sizes
              + ''.join(snowcap(x, y, h, dr, o) for x, y, h, dr, o in
                        [(362, 84, 40, 46, 0.95), (330, 92, 30, 38, 0.9), (296, 112, 24, 32, 0.85),
                         (262, 140, 20, 26, 0.8), (196, 158, 17, 22, 0.72), (444, 120, 22, 28, 0.85),
                         (500, 128, 19, 26, 0.8), (556, 142, 16, 22, 0.72), (128, 190, 13, 17, 0.6),
                         (614, 156, 14, 19, 0.65), (676, 170, 12, 16, 0.55), (52, 206, 10, 13, 0.45)])
              # rock ribs, angled with the slope
              + '<g fill="#22303e" opacity="0.9">'
              + ''.join(f'<polygon points="{x},{y} {x+w},{y+3} {x + w*0.5 + lean:.0f},{y+h} '
                        f'{x + lean:.0f},{y+h-4}"/>'
                        for x, y, w, h, lean in [(316, 106, 13, 62, -14), (350, 96, 11, 54, -9),
                                                 (378, 96, 12, 58, 10), (410, 128, 10, 46, 11),
                                                 (462, 146, 11, 48, 12), (516, 156, 10, 42, 11),
                                                 (242, 154, 10, 44, -11), (206, 172, 9, 38, -9),
                                                 (592, 176, 9, 36, 10), (664, 190, 8, 30, 9)])
              + '</g>'
              # the haze that stacks up at the foot of a big range
              + '<rect x="0" y="242" width="1280" height="46" fill="#5c7488" opacity="0.28"/>'
              + '</g>')

    # ---- forested ridges stepping DOWN toward us. This is what was missing. ----
    def comb(y0, amp, phase, step, h, fill, seed):
        """A ridgeline with a fine comb of spruce along its top edge."""
        import math
        pts, trees = [], []
        x = -20
        while x < 1300:
            yy = y0 + math.sin((x + phase) / 130.0) * amp + math.sin((x + phase) / 47.0) * (amp * 0.35)
            pts.append(f'{x},{yy:.0f}')
            if int(x) % step == 0:
                th = h + ((x * seed) % 7)
                trees.append(f'<polygon points="{x},{yy:.0f} {x + th*0.36:.1f},{yy - th:.0f} '
                             f'{x + th*0.72:.1f},{yy:.0f}"/>')
            x += 6
        return (f'<polygon points="{" ".join(pts)} 1300,300 -20,300" fill="{fill}"/>'
                f'<g fill="{fill}">{"".join(trees)}</g>')

    ridges = ('    <g id="ridges">'
              + comb(256, 9, 0, 12, 9, '#1e3340', 7)
              + comb(270, 11, 220, 12, 11, '#152834', 5)
              + comb(284, 8, 90, 12, 12, '#0f1e28', 3)
              + '</g>')

    # ---- the braided Susitna threading the valley floor ----
    river = ('    <g id="river">'
             '<path d="M-20,292 C 160,286 300,298 470,292 C 640,286 800,298 980,292 '
             'C 1120,288 1220,296 1300,292 L1300,306 L-20,306 Z" fill="url(#river)"/>'
             '<g fill="#2a4d60" opacity="0.9">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.16:.0f}"/>'
                       for x, y, r in [(120, 297, 70), (380, 300, 54), (640, 296, 66),
                                       (900, 300, 58), (1160, 297, 62)]) + '</g>'
             '<g opacity="0.35">'
             + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="3" rx="1.5" fill="{c}"/>'
                       for x, y, w, c in [(200, 294, 160, '#4ef5b0'), (520, 299, 190, '#6effc4'),
                                          (860, 294, 170, '#4ef5b0'), (1080, 300, 140, '#ff7fbf')])
             + '</g></g>')

    # ---- ground: a valley floor with spruce-covered WALLS closing in either side ----
    def wall(side):
        """A forested valley wall rising out of the frame corner."""
        import math
        sgn = 1 if side == 'L' else -1
        x0 = -30 if side == 'L' else 1310
        pts, trees = [], []
        for i in range(34):
            t = i / 33.0
            x = x0 + sgn * (t ** 1.35) * 470
            y = 316 + (t ** 0.8) * 404
            wob = math.sin(i * 1.7) * 16
            pts.append(f'{x + sgn*wob:.0f},{y:.0f}')
            if i % 2 == 0:
                th = 16 + (i % 5) * 5
                trees.append(f'<polygon points="{x + sgn*wob:.0f},{y:.0f} '
                             f'{x + sgn*(wob + th*0.4):.0f},{y - th:.0f} '
                             f'{x + sgn*(wob + th*0.8):.0f},{y:.0f}"/>')
        edge = ' '.join(pts)
        corner = '-30,720' if side == 'L' else '1310,720'
        return (f'<polygon points="{x0},316 {edge} {corner}" fill="#16241d"/>'
                f'<g fill="#16241d">{"".join(trees)}</g>'
                f'<polygon points="{x0},316 {edge} {corner}" fill="#4ef5b0" opacity="0.03"/>')

    ground_l = ('    <rect x="0" y="306" width="1280" height="414" fill="url(#grassg)"/>\n'
                '    <g fill="#2b3a2c" opacity="0.5">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.22:.0f}"/>'
                          for x, y, r in [(300, 344, 170), (760, 360, 190), (1080, 340, 150),
                                          (200, 452, 150), (860, 490, 180), (520, 580, 160),
                                          (1120, 620, 150), (300, 680, 170)]) + '</g>\n'
                '    <g fill="#4ef5b0" opacity="0.045">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.2:.0f}"/>'
                          for x, y, r in [(320, 340, 280), (800, 366, 300), (1140, 340, 220)])
                + '</g>\n'
                # a creek coming down the valley floor to join the river
                '    <path d="M452,306 C 436,352 470,392 448,436 C 424,484 356,506 320,552 '
                'C 288,592 274,646 268,720 L318,720 C 324,652 338,610 368,574 C 408,528 '
                '478,502 500,452 C 524,398 486,354 500,306 Z" fill="#14293a"/>\n'
                '    <path d="M466,306 C 452,350 484,390 462,434 C 438,482 372,504 338,550 '
                'C 308,590 294,644 288,720 L300,720 C 306,648 322,606 350,570 C 390,524 '
                '458,498 478,450 C 500,398 464,352 476,306 Z" fill="#4ef5b0" opacity="0.14"/>\n'
                + '    ' + wall('L') + wall('R'))

    # ---------------------------------------------------------------- props ----
    def spruce(x, y, s=1.0, a='#0c1713', b='#122019'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-2.4" y="-18" width="4.8" height="18" fill="{a}"/>'
                f'<polygon points="0,-104 13,-70 -13,-70" fill="{a}"/>'
                f'<polygon points="0,-104 8,-78 -8,-78" fill="{b}"/>'
                f'<polygon points="0,-84 17,-46 -17,-46" fill="{a}"/>'
                f'<polygon points="0,-84 11,-56 -11,-56" fill="{b}"/>'
                f'<polygon points="0,-60 20,-16 -20,-16" fill="{a}"/>'
                f'<polygon points="0,-60 13,-30 -13,-30" fill="{b}"/>'
                f'<path d="M0,-108 L0,-96" stroke="{a}" stroke-width="2.6"/></g>')

    def birch(x, y, s=1.0, gold='#7f6428', gold2='#9c7c33', bark='#b8b6ac'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<path d="M-3.4,0 L-2.2,-58 L2.2,-58 L3.4,0 Z" fill="{bark}"/>'
                f'<g fill="#2a2a26"><rect x="-3" y="-16" width="4" height="2.4" rx="1"/>'
                f'<rect x="0" y="-31" width="3.4" height="2" rx="1"/>'
                f'<rect x="-3" y="-45" width="3.6" height="2" rx="1"/></g>'
                f'<ellipse cx="0" cy="-74" rx="25" ry="20" fill="{gold}"/>'
                f'<ellipse cx="-13" cy="-66" rx="14" ry="11" fill="{gold2}"/>'
                f'<ellipse cx="13" cy="-68" rx="13" ry="10" fill="{gold2}"/>'
                f'<ellipse cx="2" cy="-88" rx="15" ry="10" fill="{gold2}"/></g>')

    def redshrub(x, y, s=1.0, a='#4f281e', b='#653522'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="-15" cy="-8" rx="14" ry="8" fill="{a}"/>'
                f'<ellipse cx="11" cy="-7" rx="16" ry="9" fill="{a}"/>'
                f'<ellipse cx="-3" cy="-13" rx="19" ry="10" fill="{b}"/>'
                f'<ellipse cx="8" cy="-20" rx="12" ry="7" fill="{b}"/></g>')

    def forest():
        out = []
        for by, bs, op in [(322, 0.20, 0.5), (340, 0.27, 0.62),
                           (362, 0.36, 0.78), (388, 0.46, 0.9), (412, 0.58, 1.0)]:
            row, x = [], 40
            while x < 1250:
                if rnd() < 0.20:
                    x += 44 + rnd() * 78
                    continue
                for _ in range(3 + int(rnd() * 7)):
                    r, yy = rnd(), by + (rnd() * 8) - 4
                    sc = bs * (0.82 + rnd() * 0.42)
                    row.append(spruce(x, yy, sc) if r < 0.68 else
                               (birch(x, yy, sc * 1.15) if r < 0.92 else redshrub(x, yy, sc * 1.1)))
                    x += 10 + rnd() * 13
                x += 18 + rnd() * 28
            out.append(f'<g opacity="{op}">' + ''.join(row) + '</g>')
        return '    ' + ''.join(out)

    def cabin(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="0" cy="2" rx="86" ry="16" fill="#ffcf72" opacity="0.07"/>'
                f'<rect x="-48" y="-46" width="96" height="46" fill="#1f1d19"/>'
                f'<polygon points="-58,-46 0,-76 58,-46" fill="#292c27"/>'
                f'<rect x="-60" y="-49" width="120" height="6" rx="2" fill="#36322c"/>'
                f'<rect x="-14" y="-30" width="28" height="30" rx="2" fill="#14130e"/>'
                f'<g><rect x="-38" y="-34" width="18" height="16" rx="2" fill="#ffcf72"/>'
                f'<rect x="22" y="-34" width="18" height="16" rx="2" fill="#ffcf72"/>'
                f'<ellipse cx="-29" cy="-26" rx="26" ry="18" fill="#ffcf72" opacity="0.14"/>'
                f'<ellipse cx="31" cy="-26" rx="26" ry="18" fill="#ffcf72" opacity="0.14"/></g>'
                f'<rect x="24" y="-84" width="10" height="16" fill="#2a261e"/>'
                f'<g fill="#8fa0a8" opacity="0.26"><circle cx="30" cy="-92" r="6"/>'
                f'<circle cx="36" cy="-102" r="8"/><circle cx="30" cy="-114" r="9"/></g></g>')

    def moose(x, y, s=1.0):
        c = '#141a15'
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g stroke="{c}" stroke-width="6" stroke-linecap="round">'
                f'<path d="M-22,-22 L-24,0 M-10,-22 L-8,0 M14,-22 L16,0 M24,-22 L27,0"/></g>'
                f'<ellipse cx="0" cy="-32" rx="34" ry="17" fill="{c}"/>'
                f'<path d="M28,-40 L40,-58 L48,-56 L38,-36 Z" fill="{c}"/>'
                f'<ellipse cx="50" cy="-60" rx="12" ry="8" fill="{c}"/>'
                f'<g fill="{c}">'
                f'<path d="M44,-70 C 38,-84 46,-94 60,-96 L64,-88 C 54,-86 50,-80 52,-70 Z"/>'
                f'<path d="M60,-96 l14,-6 l2,8 l-12,6 Z"/><path d="M62,-88 l16,-2 l0,8 l-14,2 Z"/>'
                f'<path d="M46,-72 C 40,-88 30,-96 16,-96 L14,-88 C 26,-86 34,-80 36,-70 Z"/>'
                f'<path d="M16,-96 l-14,-8 l-3,8 l13,7 Z"/><path d="M14,-88 l-16,-4 l-1,8 l15,3 Z"/></g>'
                f'<path d="M-34,-34 L-44,-26" stroke="{c}" stroke-width="6" stroke-linecap="round"/></g>')

    def tent(x, y, s=1.0, fly='#c4562f', fly2='#a8462a', lit=True):
        """An A-frame with a lamp inside. Canvas glows from within at night."""
        return (f'<g transform="translate({x},{y}) scale({s})">'
                + (f'<ellipse cx="0" cy="2" rx="62" ry="14" fill="#ffcf72" opacity="0.06"/>' if lit else '')
                + f'<polygon points="-34,0 0,-40 34,0" fill="{fly}"/>'
                f'<polygon points="-34,0 0,-40 -12,0" fill="{fly2}"/>'
                f'<polygon points="-13,0 0,-40 13,0" fill="{"#ffcf72" if lit else "#3a2a22"}" '
                f'opacity="{0.75 if lit else 1}"/>'
                f'<polygon points="-6,0 0,-22 6,0" fill="#2a1e18" opacity="0.5"/>'
                f'<g stroke="#6b5a44" stroke-width="1.6" opacity="0.85">'
                f'<path d="M-34,0 L-48,5 M34,0 L48,5 M0,-42 L0,-46"/></g>'
                f'<rect x="-36" y="-2" width="72" height="3" rx="1.5" fill="#2a2620"/></g>')

    def campfire(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="0" cy="2" rx="70" ry="18" fill="#ff9a3c" opacity="0.1"/>'
                f'<ellipse cx="0" cy="0" rx="40" ry="11" fill="#ff9a3c" opacity="0.13"/>'
                f'<g stroke="#3a2c22" stroke-width="5" stroke-linecap="round">'
                f'<path d="M-15,2 L9,-6 M15,2 L-9,-6"/></g>'
                f'<path d="M-9,0 C -12,-14 -5,-22 0,-34 C 5,-22 12,-14 9,0 Z" fill="#ff8c2e"/>'
                f'<path d="M-5,0 C -7,-11 -3,-17 0,-26 C 3,-17 7,-11 5,0 Z" fill="#ffd25e"/>'
                f'<path d="M-2,0 C -3,-8 -1,-12 0,-18 C 1,-12 3,-8 2,0 Z" fill="#fff2c0"/>'
                f'<g fill="#8fa0a8" opacity="0.2"><circle cx="2" cy="-42" r="6"/>'
                f'<circle cx="7" cy="-54" r="8"/><circle cx="1" cy="-68" r="9"/></g>'
                # two people sitting at it, backs to us
                f'<g fill="#141a15"><ellipse cx="-32" cy="-8" rx="9" ry="12"/>'
                f'<circle cx="-32" cy="-22" r="6"/>'
                f'<ellipse cx="32" cy="-7" rx="9" ry="12"/><circle cx="32" cy="-21" r="6"/></g>'
                f'<g fill="#ff9a3c" opacity="0.35"><ellipse cx="-24" cy="-14" rx="5" ry="9"/>'
                f'<ellipse cx="24" cy="-13" rx="5" ry="9"/></g></g>')

    def boulder(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<polygon points="-38,6 -30,-20 -10,-32 14,-30 32,-14 38,6" fill="#212831"/>'
                f'<polygon points="-10,-32 14,-30 32,-14 4,-12 -12,-20" fill="#2f3944"/>'
                f'<polygon points="-38,6 -30,-20 -12,-20 -8,4" fill="#181d24"/></g>')

    back = (forest()
            + cabin(1064, 404, 0.56) + cabin(232, 402, 0.5) + cabin(792, 398, 0.44)
            + tent(360, 400, 0.5) + tent(1176, 402, 0.44, '#3f7d6a', '#33685a')
            + moose(500, 398, 0.5))

    front = ('    ' + ''.join(spruce(x, y, s) for x, y, s in
                              [(60, 716, 1.5), (188, 672, 1.2), (1196, 716, 1.45),
                               (1112, 660, 1.25), (356, 566, 0.74), (930, 580, 0.8),
                               (452, 700, 1.2), (760, 706, 1.3), (486, 616, 0.66),
                               (1050, 620, 0.86), (240, 596, 0.68), (1246, 654, 1.0)])
             + ''.join(birch(x, y, s) for x, y, s in
                       [(258, 704, 1.35), (1104, 712, 1.3), (466, 560, 0.7),
                        (166, 700, 1.15), (838, 596, 0.8)])
             + boulder(392, 656, 1.1) + boulder(1010, 704, 1.0) + boulder(216, 716, 1.15)
             # a camp on the flat, which is what people actually come here to do
             + tent(948, 596, 1.0) + campfire(1044, 608, 0.92)
             + tent(300, 606, 0.72, '#3f7d6a', '#33685a')
             + ''.join(redshrub(x, y, s) for x, y, s in
                       [(150, 700, 1.25), (496, 664, 1.1), (784, 660, 1.15), (1136, 668, 1.15),
                        (60, 648, 1.0), (1252, 704, 1.1)]))

    scene('denali', 'DENALI — the Alaska Range from the Susitna flats, aurora over a spruce valley', {
        'sky': sky_l + '\n' + aurora,
        'far': ranges + '\n' + ridges + '\n' + river,
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#0d1512" opacity="0.5"><rect x="0" y="708" width="1280" height="4"/></g>',
        'roadkw': dict(surface='#2e3238', surface2='#22262b', shoulder='#42493f', dash='#e8d55a'),
        'trackkw': dict(ballast='#38382f', ballast_hi='#44443a', tie='#201e18', rail='#9aa4ac'),
    }, d)

# ============================================================= 13. LAS VEGAS
def las_vegas():
    """The Strip after dark — the game's only night scene. The whole trick is that
    night is NOT black: the sky is deep indigo with an orange sodium glow along the
    horizon, the mountains are a flat silhouette against it, and every light source
    POOLS on the ground and smears down the wet asphalt. Hero: the Welcome sign."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#0b1030"/><stop offset="0.38" stop-color="#1c1c4a"/>
      <stop offset="0.66" stop-color="#3d2358"/><stop offset="0.86" stop-color="#7a3050"/>
      <stop offset="1" stop-color="#c25a2c"/>
    </linearGradient>
    <linearGradient id="asphalt" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#20202c"/><stop offset="1" stop-color="#14141d"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#ffd9a0" stop-opacity="0.55"/>
      <stop offset="0.5" stop-color="#e8874a" stop-opacity="0.22"/>
      <stop offset="1" stop-color="#c25a2c" stop-opacity="0"/>
    </radialGradient>''')

    def glow(x, y, r, col, op=0.3):
        """Three stacked haloes. Doing this around every light is what sells night."""
        return (f'<circle cx="{x}" cy="{y}" r="{r*1.55:.0f}" fill="{col}" opacity="{op*0.10:.3f}"/>'
                f'<circle cx="{x}" cy="{y}" r="{r*1.0:.0f}" fill="{col}" opacity="{op*0.20:.3f}"/>'
                f'<circle cx="{x}" cy="{y}" r="{r*0.55:.0f}" fill="{col}" opacity="{op*0.38:.3f}"/>')

    def smear(x, top, w, h, col, op=0.22):
        """A light's reflection running down the wet road toward the viewer."""
        return (f'<path d="M{x-w*0.35:.0f},{top} L{x+w*0.35:.0f},{top} L{x+w},{top+h} '
                f'L{x-w},{top+h} Z" fill="{col}" opacity="{op*0.6:.3f}"/>'
                f'<path d="M{x-w*0.15:.0f},{top} L{x+w*0.15:.0f},{top} L{x+w*0.45:.0f},{top+h} '
                f'L{x-w*0.45:.0f},{top+h} Z" fill="{col}" opacity="{op*1.5:.3f}"/>')

    PINK, CYAN, GOLD, PURPLE, RED, GREEN = ('#ff3d7f', '#35e0f0', '#ffc93c',
                                            '#b45cff', '#ff4a3d', '#4dff9e')

    sky_l = ('    <rect x="0" y="0" width="1280" height="306" fill="url(#skyg)"/>\n'
             '    <g fill="#ffffff">'
             + ''.join(f'<circle cx="{x}" cy="{y}" r="{r}" opacity="{o}"/>'
                       for x, y, r, o in [(90, 34, 1.4, 0.8), (250, 20, 1.1, 0.6), (410, 48, 1.3, 0.7),
                                          (560, 26, 1, 0.5), (700, 40, 1.4, 0.75), (860, 18, 1.1, 0.55),
                                          (1010, 44, 1.2, 0.65), (1160, 28, 1.4, 0.8),
                                          (330, 74, 1, 0.45), (940, 76, 1.1, 0.5), (1240, 62, 1, 0.4)])
             + '</g>\n'
             # the city's own glow, thrown back up into the sky
             '    <ellipse cx="640" cy="306" rx="620" ry="140" fill="#e8874a" opacity="0.16"/>\n'
             '    <ellipse cx="640" cy="306" rx="420" ry="96" fill="#ffb35c" opacity="0.14"/>\n'
             '    <ellipse cx="560" cy="300" rx="230" ry="70" fill="#ff7fb0" opacity="0.1"/>')

    # ---- the desert ranges, flat black against the glow ----
    mountains = ('    <polygon points="-20,300 60,254 150,272 250,236 350,266 440,244 540,270 '
                 '640,250 740,272 840,242 950,268 1050,246 1160,270 1280,250 1300,300" '
                 'fill="#14152c"/>\n'
                 '    <polygon points="-20,300 60,254 150,272 250,236 300,300" fill="#0e0f22"/>\n'
                 '    <polygon points="840,242 950,268 1050,246 1160,270 1280,250 1300,300 900,300" '
                 'fill="#0e0f22" opacity="0.7"/>')

    # ---- the Strip itself: lit towers, the pyramid's beam, the wheel ----
    def tower(x, y, w, base='#2a2a3e', win=GOLD, step=11, dens=0.55):
        rows = int((296 - y - 8) // step)
        wins = ''.join(f'<rect x="{x+3+c*7}" y="{y+7+r*step}" width="4" height="4"/>'
                       for r in range(rows) for c in range(max(1, (w - 6) // 7))
                       if (r * 7 + c * 3 + x) % 5)
        return (f'<rect x="{x}" y="{y}" width="{w}" height="{296-y}" rx="1.5" fill="{base}"/>'
                f'<g fill="{win}" opacity="{dens}">{wins}</g>')

    strip = ('    <g>'
             + ''.join(tower(*t) for t in
                       [(40, 214, 26), (72, 196, 22), (100, 226, 28), (170, 206, 24),
                        (200, 230, 30), (236, 212, 22), (300, 222, 26), (332, 200, 24),
                        (392, 228, 28), (426, 208, 22), (486, 224, 26), (520, 202, 24),
                        (560, 232, 22), (700, 226, 24), (732, 204, 26), (768, 230, 22),
                        (830, 214, 28), (866, 234, 24), (924, 208, 26), (1000, 228, 24),
                        (1034, 206, 28), (1074, 232, 22), (1130, 216, 26), (1170, 234, 28),
                        (1214, 210, 24), (1250, 230, 26)])
             + '</g>\n'
             # the pyramid and its beam — the one thing visible from orbit
             '    <g><polygon points="596,296 656,196 716,296" fill="#1e1e30"/>'
             '<polygon points="626,296 656,196 686,296" fill="#26263c"/>'
             + ''.join(f'<circle cx="{656 + (i-3)*9}" cy="{236 + abs(i-3)*15}" r="1.7" fill="{GOLD}" '
                       f'opacity="0.7"/>' for i in range(7))
             + f'<polygon points="650,196 662,196 700,0 604,0" fill="{CYAN}" opacity="0.09"/>'
             f'<polygon points="653,196 659,196 676,0 634,0" fill="#ffffff" opacity="0.09"/>'
             + glow(656, 200, 12, CYAN, 0.4) + '</g>\n'
             # the observation wheel, small and far off
             + '    <g transform="translate(1112,232)">'
             '<g stroke="#4a4a66" stroke-width="2" fill="none"><circle cx="0" cy="0" r="30"/></g>'
             + ''.join(f'<circle cx="{30 * __import__("math").cos(i*0.5236):.1f}" '
                       f'cy="{30 * __import__("math").sin(i*0.5236):.1f}" r="2.6" '
                       f'fill="{[PINK, CYAN, GOLD, PURPLE][i % 4]}" opacity="0.9"/>' for i in range(12))
             + f'<path d="M-18,26 L0,2 L18,26" stroke="#3a3a52" stroke-width="3" fill="none"/>'
             + glow(1112, 232, 15, PINK, 0.22) + '</g>\n'
             # a lattice tower, because the Strip has one
             + '    <g transform="translate(880,296)">'
             '<path d="M-22,0 L-7,-84 L7,-84 L22,0" fill="none" stroke="#3a3a52" stroke-width="3"/>'
             '<path d="M-15,-40 L15,-40 M-11,-62 L11,-62 M-19,-20 L19,-20" stroke="#3a3a52" stroke-width="2"/>'
             '<path d="M-7,-84 L-3,-112 L3,-112 L7,-84" fill="none" stroke="#3a3a52" stroke-width="2.6"/>'
             + glow(0, -112, 5, GOLD, 0.55) + '</g>\n'
             # the glow the whole skyline throws
             + '    <ellipse cx="640" cy="298" rx="560" ry="54" fill="#ffb35c" opacity="0.12"/>')

    # ---- ground: wet black asphalt that reflects everything ----
    ground_l = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#asphalt)"/>\n'
                # the pooled spill of the city onto the near ground
                '    <ellipse cx="640" cy="304" rx="600" ry="66" fill="#ffb35c" opacity="0.1"/>\n'
                # kerbs and a lit sidewalk on each side
                '    <rect x="0" y="352" width="1280" height="26" fill="#2a2a38"/>\n'
                '    <rect x="0" y="352" width="1280" height="3" fill="#43435c"/>\n'
                '    <rect x="0" y="596" width="1280" height="34" fill="#26262f"/>\n'
                '    <rect x="0" y="596" width="1280" height="3" fill="#3c3c4e"/>\n'
                # long reflection smears running down the wet road
                + '    ' + ''.join(smear(x, t, w, h, c, o)
                                   for x, t, w, h, c, o in
                                   [(120, 380, 18, 130, PINK, 0.16), (196, 384, 16, 150, PINK, 0.18),
                                    (300, 382, 16, 120, CYAN, 0.14), (392, 384, 16, 140, CYAN, 0.16),
                                    (560, 386, 14, 100, GOLD, 0.12), (656, 340, 20, 110, CYAN, 0.1),
                                    (880, 384, 16, 150, GOLD, 0.17), (980, 382, 16, 120, GREEN, 0.13),
                                    (1084, 384, 16, 140, PURPLE, 0.16), (1170, 382, 16, 120, PURPLE, 0.13),
                                    (268, 640, 30, 76, GOLD, 0.2), (1020, 646, 24, 68, PINK, 0.2)])
                + '\n    <g fill="#ffffff" opacity="0.05">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.2:.0f}"/>'
                          for x, y, r in [(200, 470, 150), (700, 560, 190), (1100, 500, 160),
                                          (420, 660, 170), (960, 690, 180)]) + '</g>')

    # ---------------------------------------------------------------- props ----
    def palm(x, y, s=1.0, uplight=CYAN):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                + glow(8, -16, 9, uplight, 0.34)
                + f'<path d="M-6,0 C -9,-40 3,-72 10,-100 L20,-98 C 12,-70 2,-40 6,0 Z" fill="#2a2620"/>'
                f'<g fill="#1d3a2c">'
                f'<path d="M14,-100 C -18,-116 -44,-110 -58,-94 C -34,-102 -8,-100 12,-92 Z"/>'
                f'<path d="M14,-100 C 46,-118 72,-112 86,-96 C 62,-104 36,-102 16,-92 Z"/>'
                f'<path d="M14,-100 C 2,-132 -14,-144 -34,-150 C -14,-136 2,-120 10,-98 Z"/>'
                f'<path d="M14,-100 C 30,-132 50,-142 70,-148 C 50,-132 32,-116 20,-96 Z"/></g>'
                f'<g fill="{uplight}" opacity="0.5">'
                f'<path d="M14,-100 C -18,-116 -44,-110 -58,-94 C -40,-100 -20,-99 -2,-95 Z"/>'
                f'<path d="M14,-100 C 46,-118 72,-112 86,-96 C 66,-102 44,-101 24,-96 Z"/></g>'
                f'<rect x="-3" y="-14" width="18" height="14" fill="{uplight}" opacity="0.3"/></g>')

    def neon_sign(x, y, s=1.0, w=54, h=90, col=PINK, col2=GOLD, word='MOTEL'):
        """A vertical motel sign on a pole: bulb-chased border, stacked letters."""
        letters = ''.join(f'<text x="0" y="{-h + 16 + i*13}" text-anchor="middle" '
                          f'font-family="Trebuchet MS,Arial,sans-serif" font-size="12" '
                          f'font-weight="bold" fill="{col2}">{ch}</text>'
                          for i, ch in enumerate(word[:4]))
        bulbs = ''.join(f'<circle cx="{bx}" cy="{by}" r="1.9" fill="{col2}" opacity="0.95"/>'
                        for bx, by in ([(-w/2, -h + 8 + k*12) for k in range(int(h/12))]
                                       + [(w/2, -h + 8 + k*12) for k in range(int(h/12))]))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                + glow(0, -h*0.55, w*0.42, col, 0.4)
                + f'<rect x="-3" y="{-h}" width="6" height="{h}" fill="#33333f"/>'
                f'<rect x="{-w/2}" y="{-h - 6}" width="{w}" height="{h*0.72:.0f}" rx="4" fill="#1a1a26"/>'
                f'<rect x="{-w/2}" y="{-h - 6}" width="{w}" height="{h*0.72:.0f}" rx="4" fill="none" '
                f'stroke="{col}" stroke-width="2.6"/>'
                f'<g>{bulbs}</g><g>{letters}</g>'
                f'<path d="M{-w/2 - 10},{-h*0.2:.0f} l{w*0.4:.0f},-12 l0,6 l{w*0.5:.0f},0 l0,12 '
                f'l{-w*0.5:.0f},0 l0,6 Z" fill="{col}" opacity="0.9"/></g>')

    def welcome_sign(x, y, s=1.0):
        """The Welcome to Fabulous Las Vegas sign. Diamond body, star on top,
        yellow bulb border, WELCOME spelled in white circles."""
        bulbs = ''.join(f'<circle cx="{bx:.0f}" cy="{by:.0f}" r="3" fill="{GOLD}"/>'
                        for bx, by in
                        [(-84 + i * 12, -66 + abs(i - 7) * 3.2) for i in range(15)]
                        + [(-84 + i * 12, 24 - abs(i - 7) * 3.2) for i in range(15)])
        letters = ''.join(f'<g><circle cx="{-66 + i*19}" cy="-44" r="9.5" fill="#f4f2ea"/>'
                          f'<text x="{-66 + i*19}" y="-40" text-anchor="middle" '
                          f'font-family="Trebuchet MS,Arial,sans-serif" font-size="11" '
                          f'font-weight="bold" fill="#c0392b">{ch}</text></g>'
                          for i, ch in enumerate('WELCOME'))
        return (f'<g transform="translate({x},{y}) scale({s})">'
                + glow(0, -34, 54, GOLD, 0.32)
                + f'<g fill="#3a3a48"><rect x="-7" y="-30" width="14" height="30"/>'
                f'<rect x="-30" y="-4" width="60" height="8" rx="3"/></g>'
                # the diamond body
                f'<path d="M-96,-24 L0,-72 L96,-24 L96,4 L0,32 L-96,4 Z" fill="#f4f2ea"/>'
                f'<path d="M-96,-24 L0,-72 L96,-24 L96,4 L0,32 L-96,4 Z" fill="none" '
                f'stroke="#2f4d8f" stroke-width="3"/>'
                f'<g>{bulbs}</g><g>{letters}</g>'
                f'<text x="0" y="-16" text-anchor="middle" font-family="Georgia,serif" '
                f'font-size="17" font-style="italic" fill="#2f4d8f">to Fabulous</text>'
                f'<text x="0" y="4" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
                f'font-size="22" font-weight="bold" fill="#c0392b" letter-spacing="1">LAS VEGAS</text>'
                f'<text x="0" y="22" text-anchor="middle" font-family="Trebuchet MS,Arial,sans-serif" '
                f'font-size="12" font-weight="bold" fill="#2f4d8f" letter-spacing="3">NEVADA</text>'
                # the star
                + glow(0, -98, 13, GOLD, 0.6)
                + f'<path d="M0,-124 L7,-104 L28,-101 L13,-89 L17,-69 L0,-80 L-17,-69 L-13,-89 '
                f'L-28,-101 L-7,-104 Z" fill="{GOLD}"/>'
                f'<path d="M0,-118 L5,-104 L19,-101 L9,-93 L12,-79 L0,-87 L-12,-79 L-9,-93 '
                f'L-19,-101 L-5,-104 Z" fill="#fff3c0"/></g>')

    def lowmotel(x, y, s=1.0, col=CYAN):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                + glow(0, -30, 26, col, 0.18)
                + f'<rect x="-70" y="-40" width="140" height="40" fill="#20202c"/>'
                f'<rect x="-74" y="-44" width="148" height="6" rx="2" fill="#2c2c3c"/>'
                + ''.join(f'<rect x="{-58 + i*30}" y="-32" width="18" height="18" rx="2" '
                          f'fill="{GOLD}" opacity="0.6"/>' for i in range(4))
                + f'<rect x="-70" y="-46" width="140" height="4" fill="{col}" opacity="0.9"/></g>')

    def car(x, y, s=1.0, body='#8f2f3f', head=True):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-52" y="-22" width="104" height="17" rx="6" fill="{body}"/>'
                f'<path d="M-30,-22 L-22,-38 L24,-38 L34,-22 Z" fill="{body}"/>'
                f'<path d="M-26,-24 L-19,-35 L0,-35 L0,-24 Z" fill="#2a3a4e"/>'
                f'<path d="M4,-24 L4,-35 L22,-35 L30,-24 Z" fill="#2a3a4e"/>'
                f'<g fill="#1a1a22"><circle cx="-32" cy="-3" r="10"/><circle cx="32" cy="-3" r="10"/></g>'
                f'<g fill="#4a4a5a"><circle cx="-32" cy="-3" r="4"/><circle cx="32" cy="-3" r="4"/></g>'
                + (glow(-56, -14, 6, '#fff3c0', 0.7) + f'<ellipse cx="-56" cy="-14" rx="5" ry="3.4" '
                   f'fill="#fff8e0"/>' if head else '')
                + glow(54, -14, 5, RED, 0.7) + f'<ellipse cx="54" cy="-14" rx="4" ry="3" fill="{RED}"/></g>')

    def person(x, y, s=1.0, col='#2a2a38', rim=CYAN):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<g stroke="{col}" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-15 L-5,-1 M3,-15 L6,-1"/><path d="M-6,-30 L-11,-13 M6,-30 L11,-13"/></g>'
                f'<rect x="-7" y="-33" width="14" height="20" rx="6" fill="{col}"/>'
                f'<circle cx="0" cy="-40" r="6.5" fill="{col}"/>'
                f'<path d="M4,-46 a6.5,6.5 0 0 1 3,10" stroke="{rim}" stroke-width="2" '
                f'fill="none" opacity="0.75"/></g>')

    def streetlamp(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-2.4" y="-84" width="4.8" height="84" fill="#33333f"/>'
                f'<path d="M-2,-84 q10,-4 13,4" stroke="#33333f" stroke-width="3" fill="none"/>'
                + glow(12, -78, 7, '#ffd9a0', 0.5)
                + f'<ellipse cx="12" cy="-78" rx="6" ry="4" fill="#fff3d0"/></g>')

    back = ('    ' + ''.join(lowmotel(x, y, s, c) for x, y, s, c in
                             [(120, 350, 0.62, CYAN), (300, 352, 0.56, PINK),
                              (980, 352, 0.58, GREEN), (1170, 350, 0.62, PURPLE)])
            + ''.join(neon_sign(x, y, s, w, h, c, c2, wd) for x, y, s, w, h, c, c2, wd in
                      [(196, 348, 0.62, 50, 88, PINK, GOLD, 'MOTL'),
                       (392, 350, 0.56, 46, 80, CYAN, GOLD, 'CAFE'),
                       (880, 348, 0.6, 50, 86, GOLD, RED, 'STAY'),
                       (1084, 350, 0.58, 46, 82, PURPLE, CYAN, 'LUCK')])
            + ''.join(palm(x, y, s, c) for x, y, s, c in
                      [(60, 404, 0.6, CYAN), (250, 400, 0.52, PINK), (452, 404, 0.58, GOLD),
                       (760, 400, 0.54, CYAN), (940, 404, 0.6, PINK), (1240, 400, 0.56, GOLD)])
            + ''.join(streetlamp(x, 352, 0.6) for x in (80, 340, 520, 820, 1120))
            + car(566, 392, 0.42, '#3f5f8f') + car(1006, 396, 0.4, '#8f2f3f')
            + person(676, 396, 0.4) + person(700, 398, 0.36))

    front = ('    ' + welcome_sign(268, 636, 1.0)
             + ''.join(palm(x, y, s, c) for x, y, s, c in
                       [(60, 700, 1.45, CYAN), (1230, 712, 1.4, PINK), (860, 620, 1.0, GOLD),
                        (452, 600, 0.9, PURPLE)])
             + neon_sign(1020, 640, 1.0, 56, 96, PINK, GOLD, 'EATS')
             + car(920, 700, 1.0, '#8f2f3f') + car(180, 716, 0.9, '#2f6f8f', head=False)
             + ''.join(streetlamp(x, y, s) for x, y, s in
                       [(120, 596, 0.95), (760, 600, 1.0), (1160, 604, 0.95)])
             + person(438, 704, 1.05) + person(478, 710, 0.92, '#2a2a38', PINK)
             + person(1104, 700, 1.0, '#2a2a38', GOLD))

    scene('las-vegas', 'LAS VEGAS — the Strip after dark, neon pooling on wet asphalt', {
        'sky': sky_l,
        'far': mountains + '\n' + strip,
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#ffffff" opacity="0.04"><rect x="0" y="706" width="1280" height="6"/></g>',
        'roadkw': dict(surface='#26262f', surface2='#191922', shoulder='#4a4a5e', dash='#ffd94a'),
        'trackkw': dict(ballast='#3a3a46', ballast_hi='#47475a', tie='#2a2620', rail='#8f95a8'),
    }, d)


# ================================================================== 14. MOAB
def moab():
    """MOAB — the slickrock bench below Delicate Arch, looking south-east across Arches
    to the La Sal Mountains. Named viewpoint, because "Utah desert" is what produced the
    flat field with an arch sitting on it. Three things make this place and nothing else:
    the snow-topped La Sals floating blue behind red rock, the Wingate wall that runs off
    the top of the frame, and slickrock — bare cross-bedded stone in swells and domes, not
    soil with trees on it. Plants are the exception here, not the ground cover."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#1a6ab4"/><stop offset="0.46" stop-color="#5ea6d6"/>
      <stop offset="0.82" stop-color="#a8cfe2"/><stop offset="1" stop-color="#dfe8e6"/>
    </linearGradient>
    <linearGradient id="lasal" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#7b7fae"/><stop offset="1" stop-color="#9a8aa8"/>
    </linearGradient>
    <linearGradient id="sand" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#cf7a3c"/><stop offset="0.4" stop-color="#c06432"/>
      <stop offset="1" stop-color="#a04e28"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#fff0c8" stop-opacity="0.4"/>
      <stop offset="0.6" stop-color="#ffc06a" stop-opacity="0.14"/>
      <stop offset="1" stop-color="#ff9a3c" stop-opacity="0"/>
    </radialGradient>''')

    state = [90210]
    def rnd():
        state[0] = (state[0] * 1103515245 + 12345) % 2147483648
        return state[0] / 2147483648.0

    sky_l = ('    <rect x="0" y="0" width="1280" height="306" fill="url(#skyg)"/>\n'
             '    <circle cx="250" cy="80" r="210" fill="url(#sung)"/>\n'
             '    <g fill="#ffffff" opacity="0.66">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{w}" ry="{w*0.09:.0f}"/>'
                       for x, y, w in [(160, 40, 128), (452, 26, 96), (742, 50, 116),
                                       (300, 84, 104), (598, 96, 80), (128, 128, 72),
                                       (860, 112, 66)]) + '</g>')

    # ---------------------------------------------------------- La Sal Mountains ----
    # Laccoliths, not a range: a compact clump of rounded 12,000-ft peaks that stand
    # completely apart from the desert in front of them. Snow lingers into summer.
    lasals = ('    <g id="la-sals">'
              # haze layer behind, so the clump has depth
              '<polygon points="700,300 742,258 786,268 830,236 878,252 918,222 962,244 '
              '1010,230 1056,254 1094,240 1140,262 1186,246 1230,268 1280,254 1280,300" '
              'fill="#8f92bc" opacity="0.5"/>'
              # the clump itself, irregular on purpose
              '<polygon points="662,302 712,266 748,276 792,238 818,250 856,206 884,224 '
              '916,190 952,214 984,196 1018,232 1050,214 1084,248 1122,226 1158,258 '
              '1196,240 1238,266 1280,248 1280,302" fill="url(#lasal)"/>'
              # snow on the high ground only — patchy, following the ridges
              '<g fill="#eef2f6" opacity="0.92">'
              '<polygon points="916,190 936,204 928,212 946,208 952,214 934,222 918,214 906,220 898,208"/>'
              '<polygon points="856,206 872,218 866,226 880,222 884,224 872,234 858,226 848,232 842,218"/>'
              '<polygon points="984,196 1002,212 996,220 1010,218 1018,232 1000,236 986,226 976,232 970,214"/>'
              '<polygon points="792,238 806,248 800,254 812,252 818,250 810,262 796,256 788,262 782,250"/>'
              '<polygon points="1084,248 1096,256 1092,262 1104,260 1108,266 1094,270 1084,264 1076,268"/>'
              '</g>'
              # shadowed north-east flanks
              '<g fill="#6a6c96" opacity="0.4">'
              '<polygon points="916,190 952,214 984,196 1018,232 1050,214 1084,248 1122,226 '
              '1158,258 1196,240 1238,266 1280,248 1280,302 900,302"/></g>'
              # a low mesa line in front, the Moab valley rim, cutting their feet off
              '<polygon points="600,302 660,282 720,286 800,276 880,282 960,272 1050,280 '
              '1140,272 1220,282 1280,276 1280,306 600,306" fill="#a06a72" opacity="0.72"/>'
              '</g>')

    # ------------------------------------------------- red rock across the middle ----
    def tower(x, base, h, w, lit='#e08c46', mid='#c2662e', dark='#8f451f'):
        """A free-standing sandstone tower — vertical, fluted, wider at the foot."""
        f = w * 0.42
        return (f'<g>'
                # the tower body, with a stepped and broken crown rather than a flat cut
                f'<path d="M{x-w:.0f},{base} L{x-f*1.1:.0f},{base-h*0.62:.0f} '
                f'L{x-f:.0f},{base-h*0.88:.0f} L{x-f*0.7:.0f},{base-h*0.9:.0f} '
                f'L{x-f*0.55:.0f},{base-h:.0f} L{x+f*0.3:.0f},{base-h*0.97:.0f} '
                f'L{x+f*0.45:.0f},{base-h*0.82:.0f} L{x+f:.0f},{base-h*0.8:.0f} '
                f'L{x+f*1.08:.0f},{base-h*0.5:.0f} L{x+w:.0f},{base} Z" fill="{mid}"/>'
                f'<path d="M{x-w:.0f},{base} L{x-f*1.1:.0f},{base-h*0.62:.0f} '
                f'L{x-f:.0f},{base-h*0.88:.0f} L{x-f*0.55:.0f},{base-h:.0f} '
                f'L{x-f*0.28:.0f},{base-h*0.99:.0f} L{x-f*0.6:.0f},{base-h*0.6:.0f} '
                f'L{x-w*0.5:.0f},{base} Z" fill="{lit}"/>'
                f'<path d="M{x+f*0.3:.0f},{base-h*0.97:.0f} L{x+f*0.45:.0f},{base-h*0.82:.0f} '
                f'L{x+f:.0f},{base-h*0.8:.0f} L{x+f*1.08:.0f},{base-h*0.5:.0f} '
                f'L{x+w:.0f},{base} L{x+w*0.42:.0f},{base} '
                f'L{x+f*0.34:.0f},{base-h*0.6:.0f} Z" fill="{dark}"/>'
                # skirt of rubble at the foot — nothing in the desert meets the ground flat
                f'<path d="M{x-w*1.5:.0f},{base} C {x-w*0.7:.0f},{base-h*0.12:.0f} '
                f'{x+w*0.7:.0f},{base-h*0.12:.0f} {x+w*1.5:.0f},{base} Z" fill="{dark}"/>'
                + '<g fill="%s" opacity="0.22">' % dark
                + ''.join(f'<rect x="{x-w*0.9:.0f}" y="{base - h*fr:.0f}" '
                          f'width="{w*1.8:.0f}" height="{max(3, h*0.035):.0f}"/>'
                          for fr in (0.72, 0.46, 0.24))
                + '</g></g>')

    def fin(x, base, w, h, lit='#dd8742', mid='#bf6430', dark='#8d441f'):
        """A slickrock fin: a long whaleback ridge, flat on top, blunt at the ends."""
        return (f'<g><path d="M{x-w:.0f},{base} C {x-w*0.86:.0f},{base-h*0.86:.0f} '
                f'{x-w*0.62:.0f},{base-h:.0f} {x-w*0.2:.0f},{base-h:.0f} '
                f'L{x+w*0.34:.0f},{base-h*0.96:.0f} C {x+w*0.76:.0f},{base-h*0.9:.0f} '
                f'{x+w*0.92:.0f},{base-h*0.4:.0f} {x+w:.0f},{base} Z" fill="{mid}"/>'
                f'<path d="M{x-w:.0f},{base} C {x-w*0.86:.0f},{base-h*0.86:.0f} '
                f'{x-w*0.62:.0f},{base-h:.0f} {x-w*0.2:.0f},{base-h:.0f} '
                f'L{x-w*0.24:.0f},{base-h*0.86:.0f} C {x-w*0.56:.0f},{base-h*0.82:.0f} '
                f'{x-w*0.74:.0f},{base-h*0.5:.0f} {x-w*0.8:.0f},{base} Z" fill="{lit}"/>'
                f'<path d="M{x+w*0.34:.0f},{base-h*0.96:.0f} C {x+w*0.76:.0f},{base-h*0.9:.0f} '
                f'{x+w*0.92:.0f},{base-h*0.4:.0f} {x+w:.0f},{base} '
                f'L{x+w*0.64:.0f},{base} C {x+w*0.6:.0f},{base-h*0.46:.0f} '
                f'{x+w*0.5:.0f},{base-h*0.8:.0f} {x+w*0.34:.0f},{base-h*0.96:.0f} Z" fill="{dark}"/>'
                + f'<g fill="{dark}" opacity="0.2">'
                + ''.join(f'<path d="M{x-w*0.94:.0f},{base-h*fr:.0f} '
                          f'C {x-w*0.2:.0f},{base-h*(fr+0.06):.0f} '
                          f'{x+w*0.4:.0f},{base-h*(fr+0.04):.0f} {x+w*0.9:.0f},{base-h*fr*0.8:.0f} '
                          f'L{x+w*0.9:.0f},{base-h*fr*0.8+h*0.05:.0f} '
                          f'C {x+w*0.4:.0f},{base-h*(fr+0.04)+h*0.05:.0f} '
                          f'{x-w*0.2:.0f},{base-h*(fr+0.06)+h*0.05:.0f} '
                          f'{x-w*0.94:.0f},{base-h*fr+h*0.05:.0f} Z"/>' for fr in (0.62, 0.34))
                + '</g></g>')

    def balanced(x, base, s=1.0, lit='#e28e48', mid='#c26730', dark='#8d441f'):
        """Balanced Rock, the real one on the park road. The proportions matter more than
        the detail: the caprock is TALLER than it is wide and only modestly overhangs. Make
        it a wide dome on a thin stalk and you have drawn a mushroom, which is exactly what
        happened the first two times."""
        return (f'<g transform="translate({x},{base}) scale({s})">{shadow(0, 4, 50, 9, 0.24)}'
                # the mound it stands on
                f'<path d="M-58,2 C -38,-18 -16,-28 6,-28 C 30,-28 50,-16 62,2 Z" fill="{mid}"/>'
                f'<path d="M-58,2 C -38,-18 -16,-28 6,-28 C -14,-18 -36,-6 -58,2 Z" fill="{lit}"/>'
                # pedestal: tapers upward, and is stubbier than instinct says
                f'<path d="M-26,-24 L-20,-64 L-16,-92 L18,-92 L21,-64 L27,-24 Z" fill="{mid}"/>'
                f'<path d="M-26,-24 L-20,-64 L-16,-92 L-4,-92 L-6,-64 L-9,-24 Z" fill="{lit}"/>'
                f'<path d="M9,-92 L18,-92 L21,-64 L27,-24 L14,-24 L11,-64 Z" fill="{dark}"/>'
                # caprock: a boxy tower, taller than wide, overhanging by about a third
                f'<path d="M-34,-88 L-30,-128 L-22,-158 L-6,-172 L18,-172 L32,-156 '
                f'L38,-124 L40,-86 L14,-78 L-14,-78 Z" fill="{mid}"/>'
                f'<path d="M-34,-88 L-30,-128 L-22,-158 L-6,-172 L0,-160 L-14,-148 '
                f'L-20,-124 L-22,-84 Z" fill="{lit}"/>'
                f'<path d="M18,-172 L32,-156 L38,-124 L40,-86 L22,-80 L24,-120 L20,-152 Z" '
                f'fill="{dark}"/>'
                # the undercut — the shadow line that says "this is resting, not attached"
                f'<path d="M-34,-88 L-14,-78 L14,-78 L40,-86 L40,-80 C 14,-70 -12,-70 -34,-80 Z" '
                f'fill="{dark}"/>'
                f'<g fill="{dark}" opacity="0.2">'
                f'<path d="M-32,-112 L38,-112 L38,-104 L-32,-104 Z"/>'
                f'<path d="M-28,-140 L34,-140 L34,-133 L-28,-133 Z"/></g></g>')

    def window_fin(x, base, w, h, lit='#dd8742', mid='#bf6430', dark='#8d441f'):
        """A fin with a window punched through it — the stage before an arch, and half of
        Arches is at this stage. Sky showing through rock is what sells the place."""
        return (f'<g><path d="M{x-w},{base} L{x-w*0.78},{base-h*0.72} L{x-w*0.5},{base-h} '
                f'L{x+w*0.12},{base-h*0.94} L{x+w*0.54},{base-h*0.66} L{x+w},{base} Z" fill="{mid}"/>'
                f'<path d="M{x-w},{base} L{x-w*0.78},{base-h*0.72} L{x-w*0.5},{base-h} '
                f'L{x-w*0.3},{base-h*0.97} L{x-w*0.6},{base-h*0.68} L{x-w*0.72},{base} Z" fill="{lit}"/>'
                f'<path d="M{x+w*0.12},{base-h*0.94} L{x+w*0.54},{base-h*0.66} L{x+w},{base} '
                f'L{x+w*0.66},{base} L{x+w*0.36},{base-h*0.62} Z" fill="{dark}"/>'
                # the hole. It is cut by drawing the sky colour back in.
                f'<path d="M{x-w*0.3},{base} C {x-w*0.3},{base-h*0.6} {x-w*0.06},{base-h*0.74} '
                f'{x+w*0.1},{base-h*0.72} C {x+w*0.26},{base-h*0.7} {x+w*0.32},{base-h*0.5} '
                f'{x+w*0.32},{base} Z" fill="#8fc0dd"/>'
                f'<path d="M{x-w*0.3},{base} C {x-w*0.3},{base-h*0.6} {x-w*0.06},{base-h*0.74} '
                f'{x+w*0.1},{base-h*0.72} L{x+w*0.08},{base-h*0.64} '
                f'C {x-w*0.04},{base-h*0.66} {x-w*0.22},{base-h*0.54} {x-w*0.22},{base} Z" '
                f'fill="{dark}"/></g>')

    def hoodoo(x, base, h, s=1.0, lit='#e08c46', mid='#c2662e', dark='#8f451f'):
        """A stubby capped spire. Cheap, and three of them at different heights turn a
        skyline from a shape into a place."""
        return (f'<g transform="translate({x},{base}) scale({s})">'
                f'<path d="M{-h*0.3:.0f},0 L{-h*0.22:.0f},{-h*0.6:.0f} '
                f'L{-h*0.26:.0f},{-h*0.84:.0f} L{h*0.26:.0f},{-h*0.84:.0f} '
                f'L{h*0.22:.0f},{-h*0.6:.0f} L{h*0.3:.0f},0 Z" fill="{mid}"/>'
                f'<path d="M{-h*0.3:.0f},0 L{-h*0.22:.0f},{-h*0.6:.0f} '
                f'L{-h*0.26:.0f},{-h*0.84:.0f} L{-h*0.06:.0f},{-h*0.84:.0f} '
                f'L{-h*0.04:.0f},{-h*0.58:.0f} L{-h*0.1:.0f},0 Z" fill="{lit}"/>'
                f'<path d="M{-h*0.34:.0f},{-h*0.82:.0f} L{-h*0.28:.0f},{-h*0.98:.0f} '
                f'L{h*0.28:.0f},{-h*0.98:.0f} L{h*0.34:.0f},{-h*0.82:.0f} Z" fill="{dark}"/>'
                f'</g>')

    def scatter(pts, a='#b0592c', b='#d2793e', c='#883f1e'):
        """Loose blocks. Cheap way to fill dead stone with something to look at."""
        return ''.join(f'<g transform="translate({x},{y}) scale({s})">'
                       f'{shadow(0, 3, 22, 5, 0.2)}'
                       f'<polygon points="-20,4 -16,-11 -4,-19 10,-17 19,-6 21,4" fill="{a}"/>'
                       f'<polygon points="-4,-19 10,-17 19,-6 1,-4 -7,-11" fill="{b}"/>'
                       f'<polygon points="-20,4 -16,-11 -7,-11 -4,3" fill="{c}"/></g>'
                       for x, y, s in pts)

    # a broken escarpment right across the middle distance, heights all different
    escarp = ('    <g id="escarpment">'
              # the haze-blued back row
              + tower(96, 302, 74, 20, '#c98a62', '#b0714c', '#8f5a3c')
              + tower(148, 302, 46, 15, '#c98a62', '#b0714c', '#8f5a3c')
              + fin(300, 304, 120, 40, '#c98a62', '#ac6d49', '#8d5739')
              + fin(520, 304, 90, 28, '#c98a62', '#ac6d49', '#8d5739')
              + tower(760, 302, 58, 16, '#c98a62', '#b0714c', '#8f5a3c')
              + window_fin(880, 304, 74, 52, '#c68764', '#ab6c4a', '#8b563a')
              + ''.join(hoodoo(x, 304, h, sc, '#c98a62', '#b0714c', '#8f5a3c')
                        for x, h, sc in [(206, 40, 0.8), (222, 28, 0.7), (466, 46, 0.85),
                                         (600, 30, 0.7), (830, 36, 0.75)])
              # the front row, full colour
              + fin(60, 316, 150, 62)
              + tower(232, 318, 116, 26)
              + tower(268, 318, 74, 17)
              + fin(400, 320, 130, 52)
              + window_fin(516, 318, 66, 44)
              + fin(640, 316, 110, 38)
              + tower(742, 318, 92, 21)
              + tower(776, 316, 54, 13)
              + fin(860, 322, 120, 44)
              + ''.join(hoodoo(x, 320, h, sc)
                        for x, h, sc in [(126, 52, 1.0), (144, 34, 0.8), (350, 44, 0.9),
                                         (588, 38, 0.85), (706, 30, 0.75), (916, 46, 0.95)])
              + '</g>')

    # ------------------------------ THE WALL — runs off the top; you never see its top ----
    def wall():
        cols = []
        x = 960
        while x < 1310:
            w = 16 + rnd() * 34
            t = rnd()
            fill = ('#b8602c' if t < 0.3 else '#cf7538' if t < 0.58 else
                    '#a55427' if t < 0.8 else '#dd8b48')
            lean = (x - 960) * 0.05
            base = 322 + (x - 960) * 0.11 + rnd() * 16
            cols.append(f'<polygon points="{x:.0f},-20 {x+w:.0f},-20 '
                        f'{x+w*0.88+lean:.0f},{base:.0f} {x+lean:.0f},{base:.0f}" fill="{fill}"/>')
            x += w * 0.9
        streaks = []
        x = 968
        while x < 1300:
            w = 5 + rnd() * 15
            h = 110 + rnd() * 190
            streaks.append(f'<path d="M{x:.0f},-10 L{x+w:.0f},-10 L{x+w*0.55:.0f},{h:.0f} '
                           f'L{x+w*0.14:.0f},{h*0.92:.0f} Z"/>')
            x += 26 + rnd() * 56
        # broken left profile: the wall does not end in a ruled line
        edge = ('<polygon points="940,-20 968,-20 962,60 972,140 958,214 968,300 950,346" '
                'fill="#8d4522"/>')
        talus = ('<path d="M930,352 C 1000,318 1090,300 1180,294 C 1240,290 1280,290 1300,292 '
                 'L1300,368 Z" fill="#a04e26"/>'
                 '<path d="M930,352 C 1000,318 1090,300 1180,294 C 1096,308 1010,330 942,358 Z" '
                 'fill="#c97038"/>')
        return ('    <g id="wall">'
                '<polygon points="948,-20 1300,-20 1300,376 934,344" fill="#bb6330"/>'
                + f'<g>{"".join(cols)}</g>'
                + f'<g fill="#8a4322" opacity="0.2">{"".join(streaks)}</g>'
                + edge
                # horizontal ledges stepping across the face — an alcove drawn as a lens
                # just reads as a floating eye; a ledge reads as rock because it spans
                + '<g fill="#8a4322" opacity="0.22">'
                + ''.join('<path d="M%d,%d L1300,%d L1300,%d L%d,%d Z"/>'
                          % (940 + i * 10, y, y - 14, y + 12, 940 + i * 10, y + 22)
                          for i, y in enumerate((96, 178, 262)))
                + '</g>'
                + talus + '</g>')

    # ------------------------------------------------------ slickrock, not a field ----
    def swell(cx, base, w, h, lit, mid, dark, sk=0.0):
        """One bare slickrock swell: a lopsided dome, lit on the upper left, shadowed on
        the right flank, with two faint bedding lines following its curve. Nested rings
        turned this into a bullseye — a swell is a single rock, and depth comes from
        overlapping several at different sizes, not from banding one."""
        lx = cx + w * sk
        crown_x, crown_y = lx + w * 0.04, base - h * 1.12
        return (
            f'<path d="M{cx-w:.0f},{base:.0f} C {cx-w*0.72:.0f},{base-h:.0f} '
            f'{lx-w*0.26:.0f},{base-h*1.14:.0f} {crown_x:.0f},{crown_y:.0f} '
            f'C {lx+w*0.42:.0f},{base-h*1.1:.0f} {cx+w*0.8:.0f},{base-h*0.56:.0f} '
            f'{cx+w:.0f},{base:.0f} Z" fill="{mid}"/>'
            f'<path d="M{cx-w:.0f},{base:.0f} C {cx-w*0.72:.0f},{base-h:.0f} '
            f'{lx-w*0.26:.0f},{base-h*1.14:.0f} {crown_x:.0f},{crown_y:.0f} '
            f'L{crown_x:.0f},{crown_y+h*0.1:.0f} C {lx-w*0.22:.0f},{base-h*1.02:.0f} '
            f'{cx-w*0.64:.0f},{base-h*0.88:.0f} {cx-w*0.84:.0f},{base:.0f} Z" fill="{lit}"/>'
            f'<path d="M{crown_x:.0f},{crown_y:.0f} C {lx+w*0.42:.0f},{base-h*1.1:.0f} '
            f'{cx+w*0.8:.0f},{base-h*0.56:.0f} {cx+w:.0f},{base:.0f} '
            f'L{cx+w*0.74:.0f},{base:.0f} C {cx+w*0.62:.0f},{base-h*0.52:.0f} '
            f'{lx+w*0.34:.0f},{base-h*0.94:.0f} {crown_x:.0f},{crown_y+h*0.08:.0f} Z" fill="{dark}"/>'
            + f'<g stroke="{dark}" fill="none" opacity="0.26">'
            + ''.join(f'<path stroke-width="{max(2, h*0.045):.0f}" '
                      f'd="M{cx-w*0.8:.0f},{base-h*(0.22+o):.0f} '
                      f'C {cx-w*0.42:.0f},{base-h*(0.8+o):.0f} '
                      f'{lx+w*0.12:.0f},{base-h*(0.86+o):.0f} '
                      f'{cx+w*0.66:.0f},{base-h*(0.3+o):.0f}"/>' for o in (0.0, 0.2))
            + '</g>')

    def highway():
        """The road at the foot of the wall — Highway 128 in the reference photo. It is the
        single cheapest way to say how big the wall is: a two-lane road reduced to a thread
        under it does the work that no amount of rock detail can."""
        cl = []
        n = 22
        for i in range(n + 1):
            t = i / n
            cl.append((896 + 392 * t, 340 + 46 * (t ** 1.8), 2.6 + 9.5 * (t ** 1.7)))
        up = ' '.join(f'{x:.0f},{y - w:.0f}' for x, y, w in cl)
        dn = ' '.join(f'{x:.0f},{y + w:.0f}' for x, y, w in reversed(cl))
        centre = ' '.join(f'{x:.0f},{y:.0f}' for x, y, w in cl)
        # cut-and-fill shelf the road is benched onto
        shelf_up = ' '.join(f'{x:.0f},{y - w * 2.4:.0f}' for x, y, w in cl)
        shelf_dn = ' '.join(f'{x:.0f},{y + w * 3.2:.0f}' for x, y, w in reversed(cl))
        posts = ''.join(f'<rect x="{x:.0f}" y="{y + w * 0.6:.0f}" width="2.4" '
                        f'height="{4 + w * 0.5:.1f}" fill="#e6e6e0"/>'
                        for x, y, w in cl[3::2])
        return ('    <g id="highway-128">'
                f'<polygon points="{shelf_up} {shelf_dn}" fill="#a2542a"/>'
                f'<polygon points="{up} {dn}" fill="#5c534c"/>'
                f'<polyline points="{centre}" fill="none" stroke="#e8d27a" '
                'stroke-width="1.6" stroke-dasharray="9 11" opacity="0.85"/>'
                f'<g opacity="0.8">{posts}</g>'
                # a shoulder of rock swallowing the far end, so the road goes somewhere
                '<path d="M872,318 C 906,326 934,344 946,368 C 950,382 944,392 928,392 '
                'L862,392 C 852,368 856,338 872,318 Z" fill="#b45d2c"/>'
                '<path d="M872,318 C 906,326 934,344 946,368 C 926,352 898,338 866,334 Z" '
                'fill="#d17c3f"/>'
                # one car, tiny, which is the whole point of drawing the road at all
                '<g transform="translate(1128,375) scale(0.14)">'
                '<rect x="-30" y="-16" width="60" height="15" rx="5" fill="#dfe4e8"/>'
                '<path d="M-17,-16 L-11,-31 L14,-31 L21,-16 Z" fill="#eef2f5"/>'
                '<g fill="#2b2f34"><circle cx="-16" cy="0" r="7"/><circle cx="18" cy="0" r="7"/></g>'
                '</g></g>\n')

    ground_l = ('    <rect x="0" y="306" width="1280" height="414" fill="url(#sand)"/>\n'
                # bench one — far, small swells
                '    <g id="slick-far">'
                + swell(90, 400, 150, 46, '#cf7738', '#c26a32', '#ab5a2c', -0.18)
                + swell(260, 404, 190, 34, '#cd7436', '#c06831', '#a95829', 0.22)
                + swell(560, 398, 130, 56, '#d17a3a', '#c46c33', '#ac5b2c', 0.1)
                + swell(760, 406, 220, 40, '#cd7436', '#c06831', '#a95829', -0.26)
                + swell(1010, 424, 120, 32, '#d17a3a', '#c46c33', '#ac5b2c', 0.16)
                + '</g>\n'
                + highway()
                # the drop to the next bench — a real edge with shadow beneath it
                + '    <g id="ledge-1">'
                '<path d="M-20,452 C 180,438 380,446 560,438 C 760,430 980,442 1300,432 '
                'L1300,470 C 980,480 760,468 560,476 C 380,484 180,476 -20,490 Z" fill="#8f4520"/>'
                '<path d="M-20,452 C 180,438 380,446 560,438 C 760,430 980,442 1300,432 '
                'L1300,442 C 980,452 760,440 560,448 C 380,456 180,448 -20,462 Z" fill="#eda059"/>'
                '</g>\n'
                # bench two
                '    <g id="slick-mid">'
                + swell(180, 560, 220, 60, '#d67f3d', '#c96f34', '#b0602d', 0.24)
                + swell(460, 566, 160, 40, '#d37c3b', '#c66c33', '#ad5d2c', -0.2)
                + swell(760, 558, 250, 72, '#d8823f', '#cb7135', '#b0602d', 0.12)
                + swell(1090, 564, 190, 48, '#d37c3b', '#c66c33', '#ad5d2c', -0.14)
                + '</g>\n'
                # the second drop
                '    <g id="ledge-2">'
                '<path d="M-20,606 C 220,590 420,600 640,592 C 880,584 1080,598 1300,586 '
                'L1300,632 C 1080,644 880,630 640,638 C 420,646 220,636 -20,652 Z" fill="#8a411e"/>'
                '<path d="M-20,606 C 220,590 420,600 640,592 C 880,584 1080,598 1300,586 '
                'L1300,598 C 1080,610 880,596 640,604 C 420,612 220,602 -20,618 Z" fill="#f0a55d"/>'
                '</g>\n'
                # bench three — foreground stone, biggest swells of all
                '    <g id="slick-near">'
                + swell(120, 722, 300, 88, '#dd8843', '#cf7336', '#b4632e', 0.2)
                + swell(520, 726, 200, 54, '#d9843f', '#cb7034', '#b1602d', -0.24)
                + swell(950, 722, 340, 100, '#dd8843', '#cf7336', '#b4632e', -0.16)
                + '</g>\n'
                # blown sand caught in the low spots — the only soft ground here
                '    <g fill="#dba167" opacity="0.55">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.17:.0f}"/>'
                          for x, y, r in [(470, 492, 140), (860, 500, 110), (330, 660, 120),
                                          (1160, 656, 100), (620, 706, 130)]) + '</g>\n'
                # joints — straight-ish and roughly parallel, the way stone actually cracks
                '    <g stroke="#93481f" stroke-width="2.6" fill="none" opacity="0.4">'
                + ''.join(f'<path d="M{x},{y} L{x+dx},{y+dy}"/>'
                          for x, y, dx, dy in [(40, 470, 210, 16), (300, 486, 190, 14),
                                               (700, 464, 220, 18), (1010, 480, 200, 14),
                                               (60, 626, 250, 20), (420, 646, 230, 18),
                                               (880, 630, 260, 22), (120, 706, 240, 14),
                                               (760, 714, 220, -16)])
                + '</g>')

    # --------------------------------------------------- Delicate Arch on its rim ----
    def arch(x, y, s=1.0):
        lit, mid, dark, deep = '#f2a355', '#dd8038', '#b25c2c', '#8a4322'
        return (f'<g id="delicate-arch" transform="translate({x},{y}) scale({s})">'
                f'{shadow(-18, 10, 116, 12, 0.2)}'
                # the plinth it stands on
                f'<path d="M-130,12 C -96,-12 -40,-22 20,-20 C 82,-18 128,-4 152,12 Z" fill="{mid}"/>'
                f'<path d="M-130,12 C -96,-12 -40,-22 20,-20 C -24,-10 -78,2 -130,12 Z" fill="{lit}"/>'
                f'<path d="M98,-16 C 122,-12 142,-4 152,12 L110,12 Z" fill="{deep}"/>'
                # left leg — thick at the foot, thin at the shoulder
                f'<path d="M-84,0 C -80,-46 -74,-96 -60,-138 C -46,-172 -20,-186 12,-188 '
                f'C 44,-190 72,-174 86,-142 C 98,-112 102,-58 104,0 '
                f'L58,0 C 56,-52 52,-100 42,-126 C 32,-148 12,-156 -8,-150 '
                f'C -26,-144 -36,-122 -40,-90 C -44,-56 -44,-26 -44,0 Z" fill="{mid}"/>'
                f'<path d="M-84,0 C -80,-46 -74,-96 -60,-138 C -46,-172 -20,-186 12,-188 '
                f'L10,-176 C -18,-172 -38,-156 -48,-124 C -56,-94 -60,-46 -62,0 Z" fill="{lit}"/>'
                f'<path d="M86,-142 C 98,-112 102,-58 104,0 L88,0 C 86,-56 82,-108 72,-136 Z" '
                f'fill="{deep}"/>'
                f'<path d="M58,0 C 56,-52 52,-100 42,-126 L52,-122 C 62,-94 68,-48 70,0 Z" '
                f'fill="{lit}" opacity="0.4"/>'
                # only the faintest bedding — heavy banding turned this into a barcode
                + f'<g fill="{dark}" opacity="0.16">'
                f'<path d="M-82,-40 C -60,-46 -54,-46 -46,-46 L-46,-38 C -56,-38 -62,-38 -82,-32 Z"/>'
                f'<path d="M-76,-92 C -60,-98 -54,-98 -48,-98 L-49,-90 C -56,-90 -62,-90 -78,-84 Z"/>'
                f'<path d="M60,-52 L102,-52 L102,-44 L60,-44 Z"/>'
                f'<path d="M56,-98 L98,-98 L98,-90 L56,-90 Z"/>'
                f'<path d="M-48,-152 C -12,-180 44,-176 78,-144 L72,-136 '
                f'C 42,-166 -10,-168 -44,-144 Z"/></g>'
                # a person under it, for scale — the reason anyone photographs this arch
                + f'<g transform="translate(4,6) scale(0.5)">'
                f'<g stroke="#3f2a20" stroke-width="5" stroke-linecap="round" fill="none">'
                f'<path d="M-3,-15 L-5,-1 M3,-15 L6,-1"/><path d="M-6,-30 L-14,-16 M6,-30 L14,-16"/></g>'
                f'<rect x="-7" y="-33" width="14" height="20" rx="6" fill="#3f2a20"/>'
                f'<circle cx="0" cy="-40" r="6.5" fill="#3f2a20"/></g></g>')

    arch_rim = ('    <g id="arch-rim">'
                # the slickrock bowl the arch sits on, lifted above the bench line
                '<path d="M40,336 C 110,300 200,282 300,280 C 402,278 486,296 546,330 '
                'L560,352 L28,352 Z" fill="#bb6430"/>'
                '<path d="M40,336 C 110,300 200,282 300,280 C 402,278 486,296 546,330 '
                'L536,338 C 480,308 400,290 300,292 C 200,294 112,312 46,344 Z" fill="#e8994e"/>'
                '<g stroke="#8f4520" stroke-width="3" fill="none" opacity="0.3">'
                '<path d="M62,332 C 140,300 240,288 340,290"/>'
                '<path d="M84,346 C 170,314 264,302 380,306"/></g></g>')

    # ---------------------------------------------------------------- props ----
    def juniper(x, y, s=1.0, a='#5e6d4c', b='#6d7c58', trunk='#8a6b52', dead='#c2ab8c'):
        """Utah juniper: shaggy, grey-green, low and wide, with a dead silver limb.
        Nothing here looks like a lollipop tree."""
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 4, 30, 6, 0.2)}'
                f'<path d="M-5,4 C -8,-8 -14,-14 -20,-22 L-8,-18 C -5,-26 -3,-30 0,-38 '
                f'C 3,-30 6,-26 11,-18 L24,-24 C 15,-14 7,-8 5,4 Z" fill="{trunk}"/>'
                f'<path d="M7,-20 C 20,-30 28,-40 31,-52" stroke="{dead}" stroke-width="3.2" '
                f'fill="none" stroke-linecap="round"/>'
                f'<path d="M-14,-24 C -24,-32 -30,-40 -32,-48" stroke="{dead}" stroke-width="2.4" '
                f'fill="none" stroke-linecap="round"/>'
                # canopy: a ragged, notched, wider-than-tall mass. Junipers look chewed up
                # — a smooth round blob is a broccoli tree, and broccoli does not grow here.
                f'<path d="M-38,-28 L-31,-40 L-37,-45 L-25,-45 L-27,-58 L-15,-49 '
                f'L-13,-63 L-3,-51 L3,-66 L10,-52 L18,-61 L21,-47 L31,-52 L28,-41 '
                f'L39,-38 L30,-31 L36,-25 L20,-23 L4,-26 L-14,-23 L-30,-25 Z" fill="{a}"/>'
                f'<path d="M-26,-37 L-20,-46 L-16,-37 L-8,-49 L-2,-37 L2,-47 L6,-35 '
                f'L-4,-31 L-18,-31 Z" fill="{b}"/>'
                f'<path d="M14,-45 L20,-53 L24,-43 L31,-47 L27,-35 L14,-35 Z" fill="{b}"/>'
                f'</g>')

    def blackbrush(x, y, s=1.0, a='#7d8355', b='#929868'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 18, 4, 0.16)}'
                f'<ellipse cx="-10" cy="-5" rx="11" ry="6" fill="{a}"/>'
                f'<ellipse cx="9" cy="-4" rx="12" ry="7" fill="{a}"/>'
                f'<ellipse cx="-2" cy="-10" rx="14" ry="7" fill="{b}"/>'
                f'<ellipse cx="6" cy="-15" rx="8" ry="4" fill="{b}"/></g>')

    def pricklypear(x, y, s=1.0, col='#5f8f52', dark='#4d7743'):
        pads = [(-14, -12, 12, 15, -20), (13, -15, 11, 14, 18), (-3, -28, 10, 13, -6),
                (14, -34, 8, 11, 24), (-18, -31, 7, 10, -28)]
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 24, 5)}'
                + ''.join(f'<g transform="translate({px},{py}) rotate({r})">'
                          f'<ellipse cx="0" cy="0" rx="{rx}" ry="{ry}" fill="{col}"/>'
                          f'<ellipse cx="{-rx*0.3:.0f}" cy="0" rx="{rx*0.5:.0f}" ry="{ry*0.6:.0f}" '
                          f'fill="{dark}" opacity="0.45"/></g>' for px, py, rx, ry, r in pads)
                + f'<g fill="#e8a63c"><circle cx="2" cy="-40" r="4"/><circle cx="-14" cy="-40" r="3.4"/>'
                f'</g></g>')

    def rock(x, y, s=1.0, a='#b0592c', b='#d2793e', c='#883f1e'):
        """A fallen block. Scale it wildly — house-sized down to knee-high."""
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 6, 48, 8, 0.24)}'
                f'<polygon points="-46,8 -40,-24 -18,-44 14,-42 40,-22 48,8" fill="{a}"/>'
                f'<polygon points="-18,-44 14,-42 40,-22 4,-16 -20,-26" fill="{b}"/>'
                f'<polygon points="-46,8 -40,-24 -20,-26 -12,6" fill="{c}"/>'
                f'<polygon points="-18,-44 -20,-26 4,-16 14,-42" fill="{b}" opacity="0.45"/>'
                f'<polygon points="4,-16 40,-22 48,8 24,6" fill="{a}" opacity="0.55"/>'
                f'<g stroke="{c}" stroke-width="2.4" opacity="0.4" fill="none">'
                f'<path d="M-30,-4 L30,0 M-34,6 L26,10 M-24,-24 L-14,4"/></g></g>')

    def jeep(x, y, s=1.0, body='#3f7d4a', top='#2f2f36', rot=0):
        return (f'<g transform="translate({x},{y}) rotate({rot}) scale({s})">'
                + (shadow(0, 7, 58, 8, 0.26) if not rot else '')
                + f'<rect x="-50" y="-30" width="100" height="20" rx="4" fill="{body}"/>'
                f'<path d="M-22,-30 L-16,-50 L28,-50 L36,-30 Z" fill="{body}"/>'
                f'<path d="M-14,-32 L-10,-46 L6,-46 L6,-32 Z" fill="#cfe6f5"/>'
                f'<path d="M10,-32 L10,-46 L24,-46 L31,-32 Z" fill="#cfe6f5"/>'
                f'<g stroke="{top}" stroke-width="3" fill="none">'
                f'<path d="M-18,-50 L-18,-58 L32,-58 L38,-50"/><path d="M4,-58 L4,-50"/></g>'
                f'<rect x="-52" y="-22" width="104" height="5" rx="2" fill="#2a2a30"/>'
                f'<g fill="#22262b"><circle cx="-30" cy="-6" r="14"/><circle cx="32" cy="-6" r="14"/></g>'
                f'<g fill="#8d949c"><circle cx="-30" cy="-6" r="6"/><circle cx="32" cy="-6" r="6"/></g>'
                f'<g fill="#f2d06a"><rect x="-54" y="-28" width="7" height="6" rx="2"/></g>'
                f'<g fill="#c0392b"><rect x="47" y="-28" width="6" height="5" rx="2"/></g></g>')

    def raven(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})" fill="#22222a">'
                f'<path d="M-22,0 q11,-9 22,-2 q11,-7 22,2 q-11,5 -22,2 q-11,3 -22,-2 Z"/>'
                f'<circle cx="0" cy="-2" r="2.6"/></g>')

    # Plants are sparse and clustered where water collects — never an even scatter.
    back = ('    ' + balanced(792, 442, 0.82, '#f2a75e', '#d67c3c', '#8a4019')
            + rock(1064, 424, 0.66) + rock(146, 418, 0.5)
            + scatter([(232, 428, 0.5), (300, 422, 0.36), (498, 430, 0.44),
                       (846, 434, 0.4), (940, 428, 0.46), (1108, 438, 0.52),
                       (1236, 424, 0.38), (52, 434, 0.42)])
            + ''.join(hoodoo(x, y, h, sc) for x, y, h, sc in
                      [(190, 424, 34, 0.9), (474, 428, 26, 0.75), (1152, 432, 30, 0.85)])
            + ''.join(juniper(x, y, s) for x, y, s in
                      [(66, 424, 0.62), (98, 430, 0.44), (352, 428, 0.5),
                       (386, 424, 0.66), (700, 430, 0.48), (742, 426, 0.58),
                       (1176, 436, 0.6)])
            + ''.join(blackbrush(x, y, s) for x, y, s in
                      [(130, 430, 0.5), (176, 424, 0.4), (330, 432, 0.46), (420, 428, 0.4),
                       (664, 432, 0.44), (776, 428, 0.5), (830, 434, 0.42),
                       (1140, 440, 0.5), (1216, 434, 0.44), (1012, 436, 0.4)])
            + jeep(880, 424, 0.4, '#c0392b')
            + ''.join(raven(x, y, s) for x, y, s in
                      [(392, 168, 0.68), (452, 196, 0.48), (330, 210, 0.4)]))

    # The jeep road. Moab is a 4WD town — a red dirt track squeezing past a fallen block
    # bigger than a house is the most Moab thing in the frame, and it gives the block
    # something to be bigger *than*. Built as a real perspective ribbon: a constant-width
    # band reads as a painted stripe, not a road coming towards you.
    def _trail():
        cl = []
        n = 24
        for i in range(n + 1):
            t = i / n
            cl.append((-20 + 420 * t, 592 + 134 * (t ** 2.2), 9 + 41 * (t ** 2.2)))
        left = ' '.join(f'{x - w:.0f},{y:.0f}' for x, y, w in cl)
        right = ' '.join(f'{x + w:.0f},{y:.0f}' for x, y, w in reversed(cl))
        inner = ' '.join(f'{x - w * 0.62:.0f},{y:.0f}' for x, y, w in cl)
        inner_r = ' '.join(f'{x + w * 0.62:.0f},{y:.0f}' for x, y, w in reversed(cl))
        berm_l = ' '.join(f'{x - w * 1.5:.0f},{y + 5:.0f}' for x, y, w in cl)
        berm_r = ' '.join(f'{x + w * 1.5:.0f},{y + 5:.0f}' for x, y, w in reversed(cl))
        rut_a = ' '.join(f'{x - w * 0.4:.0f},{y:.0f}' for x, y, w in cl)
        rut_b = ' '.join(f'{x + w * 0.34:.0f},{y:.0f}' for x, y, w in cl)
        return (f'<polygon points="{berm_l} {berm_r}" fill="#8e4520"/>'
                f'<polygon points="{left} {right}" fill="#d99a62"/>'
                f'<polygon points="{inner} {inner_r}" fill="#efc characterized"/>'.replace(' characterized', '093')
                + f'<g stroke="#93481f" stroke-width="4" fill="none" opacity="0.5">'
                f'<polyline points="{rut_a}"/><polyline points="{rut_b}"/></g>')

    jeep_road = ('<g id="jeep-road">' + _trail()
                 + '<g fill="#e8b482" opacity="0.5">'
                 + ''.join('<ellipse cx="%d" cy="%d" rx="%d" ry="%d"/>' % (x, y, r, max(2, r // 3))
                           for x, y, r in [(66, 598, 18), (168, 606, 13), (250, 626, 17),
                                           (318, 664, 12), (372, 702, 16)])
                 + '</g></g>')

    front = ('    ' + jeep_road
             # the scale ladder, biggest first: a house-sized block against knee-high brush
             + rock(178, 706, 2.4)
             # one jeep up on the block, tilted to the rock's own slope — this is what
             # people actually come to Moab to do, and it gives the block a use
             + '<ellipse cx="188" cy="612" rx="31" ry="5" fill="#000" opacity="0.2"/>'
             + jeep(186, 606, 0.56, '#c0392b', '#2f2f36', 17)
             + rock(1104, 700, 1.8)
             + rock(292, 592, 1.15) + rock(880, 704, 1.35)
             + rock(384, 646, 0.8) + rock(842, 668, 0.62) + rock(1252, 612, 0.46)
             + scatter([(96, 600, 0.9), (466, 706, 1.2), (438, 632, 0.7), (486, 606, 0.6),
                        (790, 660, 0.85), (800, 718, 1.15), (930, 620, 0.7),
                        (1010, 676, 1.0), (1178, 640, 0.8), (1256, 706, 1.3),
                        (36, 662, 1.0), (222, 634, 0.6)])
             + juniper(76, 640, 1.7) + juniper(1224, 686, 1.5)
             + juniper(300, 592, 1.05) + juniper(340, 600, 0.8)
             + juniper(966, 604, 1.1) + juniper(1060, 596, 0.85)
             + jeep(312, 678, 0.55, '#3f7d4a')
             + ''.join(pricklypear(x, y, s) for x, y, s in
                       [(140, 594, 1.15), (446, 704, 1.3), (1146, 648, 1.1), (52, 704, 1.05),
                        (486, 694, 0.9)])
             + ''.join(blackbrush(x, y, s) for x, y, s in
                       [(250, 662, 1.1), (286, 672, 0.8), (404, 714, 1.2), (390, 600, 0.9),
                        (806, 716, 1.15), (1024, 704, 1.1), (1180, 596, 0.9),
                        (108, 664, 1.0), (930, 650, 0.85), (1206, 660, 0.7)])
             + raven(1148, 540, 0.9))

    scene('moab', 'MOAB — the slickrock bench under Delicate Arch, La Sals behind', {
        'sky': sky_l,
        'far': lasals + '\n' + escarp + '\n' + arch_rim + '\n    ' + arch(292, 288, 0.74)
               + '\n' + wall(),
        'ground': ground_l,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#8f4326" opacity="0.4"><rect x="0" y="710" width="1280" height="4"/></g>',
        'roadkw': dict(surface='#7a6a60', surface2='#63544c', shoulder='#d8a068', dash='#ffe066'),
        'trackkw': dict(ballast='#a8724a', ballast_hi='#bb8455', tie='#5f3a22', rail='#d3d7dc'),
    }, d)

def nashville():
    """NASHVILLE — Lower Broadway looking west, late afternoon. The viewpoint matters:
    from the river end of Broadway you look uphill at a solid two-block wall of brick
    honky tonks with the downtown towers stacked up behind them, and the AT&T building's
    twin spires over the top. The neon blades are the signature, but the thing that makes
    it Broadway and not any old main street is that the signs hang off *ordinary Victorian
    commercial brick* — three storeys, arched upper windows, heavy bracketed cornices."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#3d84c2"/><stop offset="0.42" stop-color="#78b0d6"/>
      <stop offset="0.76" stop-color="#c8d8dc"/><stop offset="1" stop-color="#f2cf9c"/>
    </linearGradient>
    <linearGradient id="asphalt" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5a5b60"/><stop offset="1" stop-color="#46474c"/>
    </linearGradient>
    <linearGradient id="glass" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5f7f9e"/><stop offset="1" stop-color="#8fb2c8"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#fff0c0" stop-opacity="0.55"/>
      <stop offset="0.55" stop-color="#ffc673" stop-opacity="0.2"/>
      <stop offset="1" stop-color="#ff9d3c" stop-opacity="0"/>
    </radialGradient>''')

    sky_l = ('    <rect x="0" y="0" width="1280" height="300" fill="url(#skyg)"/>\n'
             '    <circle cx="196" cy="252" r="220" fill="url(#sung)"/>\n'
             '    <g fill="#ffffff" opacity="0.5">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{w}" ry="{w*0.11:.0f}"/>'
                       for x, y, w in [(220, 44, 130), (560, 30, 96), (880, 54, 118),
                                       (360, 88, 100), (1080, 96, 86), (140, 122, 76)])
             + '</g>\n'
             '    <g fill="#f6d9a8" opacity="0.32">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{w}" ry="{w*0.055:.0f}"/>'
                       for x, y, w in [(420, 178, 130), (520, 186, 90), (900, 198, 116),
                                       (820, 206, 78), (180, 202, 96), (1140, 190, 84)])
             + '</g>')

    # ------------------------------------------------------------- skyline ----
    def tower(x, w, top, body='#7d8794', lit='#98a3ae', dark='#606a76', win='#c8d8e4',
              rows=None, cap=None):
        base = 306
        h = base - top
        rows = rows or int(h / 22)
        cols = max(2, int(w / 20))
        wins = ''.join(
            f'<rect x="{x + 6 + c * (w - 12) / cols:.0f}" y="{top + 14 + r * (h - 20) / rows:.0f}" '
            f'width="{(w - 12) / cols * 0.55:.0f}" height="{(h - 20) / rows * 0.45:.0f}" '
            f'fill="{win}" opacity="{0.3 + 0.5 * ((c + r) % 3) / 2:.2f}"/>'
            for r in range(rows) for c in range(cols))
        return (f'<g><rect x="{x}" y="{top}" width="{w}" height="{h}" fill="{body}"/>'
                f'<rect x="{x}" y="{top}" width="{w * 0.3:.0f}" height="{h}" fill="{lit}"/>'
                f'<rect x="{x + w * 0.78:.0f}" y="{top}" width="{w * 0.22:.0f}" height="{h}" '
                f'fill="{dark}"/>{wins}{cap or ""}</g>')

    def batman(x, base=306):
        """The AT&T Building — 'the Batman building'. Two needle spires off a stepped
        blue-glass tower. It is the one silhouette everybody in Nashville knows."""
        return (f'<g id="batman">'
                # shoulders
                f'<rect x="{x - 74}" y="196" width="34" height="{base - 196}" fill="#5c7285"/>'
                f'<rect x="{x + 40}" y="196" width="34" height="{base - 196}" fill="#4e6274"/>'
                f'<rect x="{x - 46}" y="164" width="30" height="{base - 164}" fill="#67809a"/>'
                f'<rect x="{x + 16}" y="164" width="30" height="{base - 164}" fill="#5a7186"/>'
                # core
                f'<rect x="{x - 18}" y="150" width="36" height="{base - 150}" fill="url(#glass)"/>'
                # the ears
                f'<polygon points="{x - 44},164 {x - 34},92 {x - 24},164" fill="#8fa8bc"/>'
                f'<polygon points="{x + 24},164 {x + 34},92 {x + 44},164" fill="#7b94a8"/>'
                f'<polygon points="{x - 38},128 {x - 34},92 {x - 30},128" fill="#c2d6e4"/>'
                f'<polygon points="{x + 30},128 {x + 34},92 {x + 38},128" fill="#a8bfd0"/>'
                + '<g fill="#cfe2ee" opacity="0.5">'
                + ''.join(f'<rect x="{x - 70}" y="{y}" width="140" height="3"/>'
                          for y in range(206, base - 10, 16))
                + '</g></g>')

    skyline = ('    <g id="skyline">'
               # haze rank
               + ''.join(tower(x, w, t, '#93a3b0', '#a4b3bf', '#8291a0', '#cddbe6')
                         for x, w, t in [(30, 54, 238), (110, 40, 216), (996, 62, 224),
                                         (1110, 46, 206), (1190, 60, 232)])
               # mid rank
               + ''.join(tower(x, w, t) for x, w, t in
                         [(176, 62, 186), (256, 44, 214), (598, 54, 200), (676, 40, 176),
                          (742, 58, 208), (900, 48, 190), (1058, 52, 172)])
               + tower(824, 66, 148, '#6f7c89', '#8a95a1', '#57626d', '#d2e0ea',
                       cap='<polygon points="824,148 890,148 866,120 848,120" fill="#8a95a1"/>')
               # a brick 1920s block, because downtown Nashville is not all glass
               + tower(320, 58, 206, '#9a6a58', '#ae7c68', '#7d5245', '#e6cdb4')
               + tower(956, 40, 214, '#8f6353', '#a37461', '#734a3f', '#e6cdb4')
               + batman(468)
               + '</g>')

    # -------------------------------------------------------- the Broadway wall ----
    BRICK = [('#9c4a3c', '#b25a4a', '#7a382d'), ('#a8543f', '#bf664f', '#83402f'),
             ('#8e5a48', '#a56d59', '#6f4436'), ('#b8705a', '#cd856e', '#8f5442'),
             ('#a45c52', '#bb7065', '#82443c'), ('#c08a5e', '#d69f71', '#996a46')]
    AWN = ['#c0392b', '#2f6f4f', '#2a5a8c', '#8e4a9e', '#c9762a']
    NEON = [('#ff4d5a', '#ffd166'), ('#39d0e8', '#ffe066'), ('#ffb020', '#ff5470'),
            ('#8ee36b', '#ffd166'), ('#ff7ac0', '#7ad4ff')]

    def blade(x, top, h, w, tube, glow, kind='bar', word=None):
        """A vertical projecting neon sign. Broadway's are mounted on a bracket arm and
        hang clear of the facade, which is what makes the block read as Nashville rather
        than as a generic old high street."""
        parts = [f'<rect x="{x - 3}" y="{top + 4}" width="{w * 0.5:.0f}" height="4" fill="#3a3238"/>']
        if kind == 'guitar':
            cy = top + h * 0.70
            bw, bh = w * 0.58, h * 0.30
            def body(k):
                W, H = bw * k, bh * k
                return (f'M{x},{cy - H:.1f} '
                        f'C {x - W * 0.74:.1f},{cy - H:.1f} {x - W * 0.8:.1f},{cy - H * 0.42:.1f} '
                        f'{x - W * 0.7:.1f},{cy - H * 0.08:.1f} '
                        f'C {x - W:.1f},{cy + H * 0.3:.1f} {x - W * 0.72:.1f},{cy + H:.1f} '
                        f'{x},{cy + H:.1f} '
                        f'C {x + W * 0.72:.1f},{cy + H:.1f} {x + W:.1f},{cy + H * 0.3:.1f} '
                        f'{x + W * 0.7:.1f},{cy - H * 0.08:.1f} '
                        f'C {x + W * 0.8:.1f},{cy - H * 0.42:.1f} {x + W * 0.74:.1f},{cy - H:.1f} '
                        f'{x},{cy - H:.1f} Z')
            # headstock and neck
            parts.append(f'<rect x="{x - w * 0.19:.0f}" y="{top}" width="{w * 0.38:.0f}" '
                         f'height="{h * 0.11:.0f}" rx="3" fill="#3a3238"/>')
            parts.append(f'<rect x="{x - w * 0.1:.0f}" y="{top + h * 0.1:.0f}" '
                         f'width="{w * 0.2:.0f}" height="{h * 0.32:.0f}" fill="#3a3238"/>')
            parts.append(f'<rect x="{x - w * 0.045:.0f}" y="{top + h * 0.11:.0f}" '
                         f'width="{w * 0.09:.0f}" height="{h * 0.3:.0f}" fill="{glow}"/>')
            parts.append('<g fill="#ffe9b0">'
                         + ''.join(f'<circle cx="{x - w * 0.13:.0f}" cy="{top + 5 + k * 6}" r="1.7"/>'
                                   f'<circle cx="{x + w * 0.13:.0f}" cy="{top + 5 + k * 6}" r="1.7"/>'
                                   for k in range(2)) + '</g>')
            # body: waisted, lower bout bigger than upper — a figure-8 of equal circles
            # reads as a snowman, which is what the first attempt drew
            parts.append(f'<path d="{body(1.0)}" fill="#3a3238"/>')
            parts.append(f'<path d="{body(0.78)}" fill="{tube}"/>')
            parts.append(f'<circle cx="{x}" cy="{cy + bh * 0.22:.0f}" r="{bw * 0.19:.0f}" fill="#2a242a"/>')
            parts.append(f'<rect x="{x - 1.2:.1f}" y="{cy - bh * 0.5:.0f}" width="2.4" '
                         f'height="{bh * 0.66:.0f}" fill="#2a242a" opacity="0.7"/>')
        elif kind == 'boot':
            parts.append(f'<path d="M{x - w * 0.3:.0f},{top} L{x + w * 0.3:.0f},{top} '
                         f'L{x + w * 0.34:.0f},{top + h * 0.66:.0f} L{x + w * 0.7:.0f},{top + h * 0.8:.0f} '
                         f'L{x + w * 0.72:.0f},{top + h:.0f} L{x - w * 0.32:.0f},{top + h:.0f} Z" '
                         f'fill="#3a3238"/>')
            parts.append(f'<path d="M{x - w * 0.18:.0f},{top + 8:.0f} L{x + w * 0.18:.0f},{top + 8:.0f} '
                         f'L{x + w * 0.2:.0f},{top + h * 0.7:.0f} L{x + w * 0.56:.0f},{top + h * 0.82:.0f} '
                         f'L{x + w * 0.57:.0f},{top + h - 7:.0f} L{x - w * 0.2:.0f},{top + h - 7:.0f} Z" '
                         f'fill="{tube}" opacity="0.9"/>')
        else:
            parts.append(f'<rect x="{x - w / 2:.0f}" y="{top}" width="{w}" height="{h}" rx="3" '
                         f'fill="#3a3238"/>')
            parts.append(f'<rect x="{x - w / 2 + 3:.0f}" y="{top + 3}" width="{w - 6}" '
                         f'height="{h - 6}" rx="2" fill="none" stroke="{tube}" stroke-width="2.4"/>')
            n = max(2, int(h / 15))
            parts.append('<g fill="%s">' % glow
                         + ''.join(f'<rect x="{x - 3}" y="{top + 9 + i * (h - 16) / n:.0f}" '
                                   f'width="6" height="{(h - 16) / n * 0.5:.0f}" rx="1"/>'
                                   for i in range(n)) + '</g>')
            # chase bulbs down both edges
            parts.append('<g fill="#ffe9b0">'
                         + ''.join(f'<circle cx="{x - w / 2 + 2:.0f}" cy="{top + 8 + i * 11}" r="1.6"/>'
                                   f'<circle cx="{x + w / 2 - 2:.0f}" cy="{top + 8 + i * 11}" r="1.6"/>'
                                   for i in range(int((h - 12) / 11))) + '</g>')
        return ''.join(parts)

    def honky(x, w, h, i, blade_kind='bar', side=1):
        """One Broadway building. Three things every time: a bracketed cornice, arched
        upper windows, and a dark storefront under an awning."""
        base = 374
        top = base - h
        body, lit, dark = BRICK[i % len(BRICK)]
        awn = AWN[i % len(AWN)]
        tube, glow = NEON[i % len(NEON)]
        g = [f'<rect x="{x}" y="{top}" width="{w}" height="{h}" fill="{body}"/>',
             f'<rect x="{x}" y="{top}" width="{w * 0.16:.0f}" height="{h}" fill="{lit}" opacity="0.5"/>',
             f'<rect x="{x + w * 0.86:.0f}" y="{top}" width="{w * 0.14:.0f}" height="{h}" '
             f'fill="{dark}" opacity="0.55"/>']
        # brick courses
        g.append(f'<g fill="{dark}" opacity="0.16">'
                 + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2"/>'
                           for y in range(top + 8, base - 60, 9)) + '</g>')
        # cornice: a slab on brackets
        g.append(f'<rect x="{x - 4}" y="{top - 9}" width="{w + 8}" height="10" fill="{lit}"/>')
        g.append(f'<rect x="{x - 4}" y="{top - 11}" width="{w + 8}" height="4" fill="#e4d3bd"/>')
        g.append(f'<g fill="{dark}">'
                 + ''.join(f'<rect x="{x + 5 + k * (w - 12) / max(2, int(w / 18)):.0f}" y="{top + 1}" '
                           f'width="5" height="9"/>' for k in range(max(2, int(w / 18)) + 1))
                 + '</g>')
        # upper-floor windows, arched
        floors = 2 if h < 108 else 3
        per = max(2, int(w / 26))
        ww = (w - 14) / per * 0.62
        for f_i in range(floors):
            wy = top + 20 + f_i * ((h - 76) / floors)
            wh = (h - 76) / floors * 0.62
            for c in range(per):
                wx = x + 8 + c * (w - 14) / per
                g.append(f'<path d="M{wx:.0f},{wy + wh:.0f} L{wx:.0f},{wy + ww * 0.5:.0f} '
                         f'A{ww * 0.5:.0f},{ww * 0.5:.0f} 0 0 1 {wx + ww:.0f},{wy + ww * 0.5:.0f} '
                         f'L{wx + ww:.0f},{wy + wh:.0f} Z" fill="#2f3a44"/>')
                g.append(f'<path d="M{wx + 1.5:.0f},{wy + wh - 2:.0f} L{wx + 1.5:.0f},{wy + ww * 0.55:.0f} '
                         f'A{ww * 0.4:.0f},{ww * 0.4:.0f} 0 0 1 {wx + ww * 0.5:.0f},{wy + ww * 0.16:.0f} '
                         f'L{wx + ww * 0.5:.0f},{wy + wh - 2:.0f} Z" fill="#6d8496" opacity="0.7"/>')
                g.append(f'<rect x="{wx - 2:.0f}" y="{wy + wh:.0f}" width="{ww + 4:.0f}" height="3" '
                         f'fill="#e4d3bd"/>')
        # ground floor: dark shopfront, awning, door
        sf = base - 52
        g.append(f'<rect x="{x + 3}" y="{sf}" width="{w - 6}" height="52" fill="#2b2229"/>')
        # plate glass, lit warm from inside — a dark band reads as a shut shop
        g.append(f'<rect x="{x + 7}" y="{sf + 8}" width="{w * 0.40:.0f}" height="30" rx="1" '
                 f'fill="#e8b45c"/>')
        g.append(f'<rect x="{x + 7}" y="{sf + 8}" width="{w * 0.40:.0f}" height="9" fill="#f2cf8a"/>')
        g.append(f'<g fill="#8a5a2c" opacity="0.55">'
                 + ''.join(f'<rect x="{x + 12 + k * 13}" y="{sf + 18}" width="4" height="20"/>'
                           for k in range(int(w * 0.40 / 13))) + '</g>')
        g.append(f'<rect x="{x + w * 0.52:.0f}" y="{sf + 8}" width="{w * 0.22:.0f}" height="30" rx="1" '
                 f'fill="#d9a04e" opacity="0.85"/>')
        # the door, with light spilling out of it
        g.append(f'<rect x="{x + w - 27:.0f}" y="{sf + 6}" width="19" height="46" rx="2" fill="#5d3a24"/>')
        g.append(f'<rect x="{x + w - 24:.0f}" y="{sf + 10}" width="13" height="26" fill="#ffd98f"/>')
        # a lit marquee band over the shopfront
        g.append(f'<rect x="{x + 6}" y="{sf - 14}" width="{w - 12}" height="12" rx="2" fill="#241d24"/>')
        g.append(f'<g fill="{glow}" opacity="0.95">'
                 + ''.join(f'<rect x="{x + 11 + k * 9}" y="{sf - 10}" width="6" height="4" rx="1"/>'
                           for k in range(int((w - 22) / 9))) + '</g>')
        g.append('<g fill="#ffe9b0">'
                 + ''.join(f'<circle cx="{x + 10 + k * 11}" cy="{sf - 15}" r="1.8"/>'
                           for k in range(int((w - 18) / 11))) + '</g>')
        # awning, striped
        aw = w - 10
        g.append(f'<path d="M{x + 5},{sf - 2} L{x + 5 + aw:.0f},{sf - 2} '
                 f'L{x + 3 + aw:.0f},{sf + 15} L{x + 7},{sf + 15} Z" fill="{awn}"/>')
        g.append('<g fill="#f2ece2" opacity="0.85">'
                 + ''.join(f'<path d="M{x + 8 + k * 22},{sf - 2} L{x + 17 + k * 22},{sf - 2} '
                           f'L{x + 15 + k * 22},{sf + 15} L{x + 6 + k * 22},{sf + 15} Z"/>'
                           for k in range(int(aw / 22))) + '</g>')
        g.append(f'<rect x="{x + 4}" y="{sf - 5}" width="{aw + 2:.0f}" height="4" rx="2" fill="#2b2229"/>')
        # the blade sign, hung off the street-facing edge
        bx = x + (w * 0.78 if side > 0 else w * 0.22)
        g.append(f'<rect x="{bx - 27:.0f}" y="{top + 10}" width="54" height="19" rx="3" '
                 f'fill="#241d24"/>')
        g.append(f'<rect x="{bx - 23:.0f}" y="{top + 14}" width="46" height="11" rx="2" '
                 f'fill="none" stroke="{glow}" stroke-width="2.2"/>')
        g.append('<g fill="%s" opacity="0.9">' % tube
                 + ''.join(f'<rect x="{bx - 18 + k * 8:.0f}" y="{top + 17}" width="5" height="5"/>'
                           for k in range(5)) + '</g>')
        g.append(blade(bx, top + 32, max(62, min(122, h - 96)), 30, tube, glow, blade_kind))
        # a flag on a pole, which every one of these buildings actually has
        if i % 2 == 0:
            fx = x + (w * 0.26 if side > 0 else w * 0.74)
            g.append(f'<g transform="translate({fx:.0f},{base - 74}) rotate(-26)">'
                     f'<rect x="0" y="-1" width="22" height="2" fill="#4a4048"/>'
                     f'<rect x="4" y="-8" width="16" height="14" fill="#b8323c"/>'
                     f'<rect x="4" y="-8" width="7.5" height="7" fill="#2b4a8c"/>'
                     f'<g fill="#f2ece2">'
                     + ''.join(f'<rect x="4" y="{-8 + k * 2.8:.1f}" width="16" height="1.3"/>'
                               for k in (1, 2, 3, 4)) + '</g></g>')
        return ''.join(g)

    LEFT = [(-30, 124, 132, 0, 'bar'), (98, 96, 168, 1, 'guitar'), (194, 132, 190, 2, 'bar'),
            (330, 100, 152, 3, 'boot'), (396, 96, 150, 4, 'bar')]
    RIGHT = [(788, 108, 168, 5, 'bar'), (840, 98, 172, 2, 'guitar'), (940, 136, 186, 0, 'bar'),
             (1080, 104, 158, 3, 'boot'), (1188, 122, 128, 1, 'bar')]

    # the block that closes the far end of the street, small and hazy
    # What you actually see at the bottom of Broadway is the river, and both bridges
    # across it: the white pedestrian truss and the orange arch beyond. Putting them in
    # the gap keeps the vista honest and gives the street somewhere to go.
    far_block = ('<g id="river-vista">'
                 # East Nashville on the far bank, low and hazy
                 '<rect x="480" y="300" width="320" height="22" fill="#9c8f8c" opacity="0.6"/>'
                 + '<g fill="#8a7d7c" opacity="0.7">'
                 + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{322 - y}"/>'
                           for x, y, w in [(488, 306, 26), (520, 300, 20), (546, 310, 24),
                                           (592, 304, 22), (620, 312, 26), (668, 302, 20),
                                           (694, 310, 28), (736, 306, 22), (764, 312, 26)])
                 + '</g>'
                 + '<g fill="#5c7f4c" opacity="0.75">'
                 + ''.join(f'<ellipse cx="{x}" cy="321" rx="{r}" ry="{r * 0.5:.0f}"/>'
                           for x, r in [(500, 13), (536, 10), (578, 12), (614, 9),
                                        (654, 11), (700, 13), (748, 10), (782, 12)])
                 + '</g>'
                 # the river FIRST — drawing it after the bridges left them floating
                 '<rect x="480" y="324" width="320" height="42" fill="#5a7f96"/>'
                 '<rect x="480" y="324" width="320" height="4" fill="#6e93a8"/>'
                 + '<g fill="#8fb2c4" opacity="0.5">'
                 + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2" rx="1"/>'
                           for x, y, w in [(500, 344, 36), (600, 350, 28), (700, 342, 40),
                                           (520, 360, 30), (740, 360, 26)])
                 + '</g>'
                 # the orange arch bridge, upstream and higher
                 '<g id="arch-bridge">'
                 + '<g fill="#8a8074">'
                 + ''.join(f'<rect x="{x}" y="334" width="6" height="12"/>' for x in (534, 640, 744))
                 + '</g>'
                 '<rect x="480" y="330" width="320" height="4.5" fill="#9a9086"/>'
                 '<path d="M492,331 C 560,302 720,302 788,331" fill="none" stroke="#d9552c" '
                 'stroke-width="5"/>'
                 '<path d="M492,329.4 C 560,300.4 720,300.4 788,329.4" fill="none" '
                 'stroke="#ee7a44" stroke-width="1.8"/>'
                 + '<g stroke="#c04a26" stroke-width="1.1">'
                 + ''.join(f'<path d="M{x},{330 - (1 - ((x - 640) / 148.0) ** 2) * 25:.1f} '
                           f'L{x},330"/>' for x in range(508, 780, 17))
                 + '</g></g>'
                 # the white pedestrian truss bridge, nearer and lower
                 '<g id="ped-bridge">'
                 + '<g fill="#b8b2a6">'
                 + ''.join(f'<rect x="{x}" y="356" width="7" height="12"/>' for x in (516, 620, 724))
                 + '</g>'
                 '<rect x="480" y="352" width="320" height="5" fill="#ddd8cc"/>'
                 '<rect x="480" y="357" width="320" height="2.5" fill="#a8a296"/>'
                 + '<g stroke="#dcd8cc" stroke-width="1.3" fill="none" opacity="0.9">'
                 + ''.join(f'<path d="M{x},352 L{x + 13},341 L{x + 26},352"/>'
                           f'<path d="M{x + 13},341 L{x + 13},352"/>' for x in range(480, 800, 26))
                 + '<path d="M480,341 L800,341"/></g></g>'
                 # the near bank, where Broadway meets the water
                 '<rect x="480" y="364" width="320" height="12" fill="#6f7a52"/>'
                 '<rect x="480" y="364" width="320" height="4" fill="#82905f"/>'
                 '</g>')

    BLOCK = ('    <g id="broadway">' + far_block
             + ''.join(honky(x, w, h, i, k, -1) for x, w, h, i, k in LEFT)
             + ''.join(honky(x, w, h, i, k, 1) for x, w, h, i, k in RIGHT)
             + '</g>')

    # ------------------------------------------------------------- the street ----
    street = ('    <rect x="0" y="300" width="1280" height="420" fill="url(#asphalt)"/>\n'
              # the street receding between the two blocks, so the gap is not raw asphalt
              '    <polygon points="556,404 724,404 706,336 574,336" fill="#57585d"/>\n'
              '    <g fill="#e8e2c9" opacity="0.3">'
              + ''.join(f'<polygon points="{638 - w},{y} {642 + w},{y} {641 + w * 0.9:.0f},{y + hh} '
                        f'{639 - w * 0.9:.0f},{y + hh}"/>'
                        for w, y, hh in [(2, 326, 4), (3, 338, 5), (4, 352, 6), (5, 366, 7)])
              + '</g>\n'
              # THE BLOCK — drawn here, after the road surface, or the asphalt buries it
              + BLOCK + '\n'
              # sidewalk in front of the block
              '    <g fill="#b9b5ae"><rect x="0" y="374" width="1280" height="28"/></g>\n'
              '    <g fill="#cbc7c0"><rect x="0" y="374" width="1280" height="4"/></g>\n'
              '    <g fill="#a29e98" opacity="0.7">'
              + ''.join(f'<rect x="{x}" y="378" width="2.5" height="24"/>' for x in range(0, 1280, 38))
              + '</g>\n'
              '    <g fill="#6f6b66"><rect x="0" y="402" width="1280" height="4"/></g>\n'
              # the traffic lane, with a centre line, between kerb and crossing
              '    <g fill="#e8e2c9" opacity="0.4">'
              + ''.join(f'<rect x="{x}" y="426" width="28" height="3"/>' for x in range(0, 1280, 64))
              + '</g>\n'
              # a second sidewalk this side of the tracks, where we are standing
              '    <g fill="#b9b5ae"><rect x="0" y="560" width="1280" height="46"/></g>\n'
              '    <g fill="#cbc7c0"><rect x="0" y="560" width="1280" height="5"/></g>\n'
              '    <g fill="#a29e98" opacity="0.7">'
              + ''.join(f'<rect x="{x}" y="566" width="3" height="40"/>' for x in range(16, 1280, 44))
              + '</g>\n'
              '    <g fill="#adaaa4"><rect x="0" y="560" width="1280" height="160"/></g>\n'
              '    <g fill="#cbc7c0"><rect x="0" y="560" width="1280" height="5"/></g>\n'
              '    <g fill="#a29e98" opacity="0.55">'
              + ''.join(f'<rect x="{x}" y="566" width="3" height="154"/>' for x in range(20, 1280, 74))
              + ''.join(f'<rect x="0" y="{y}" width="1280" height="3"/>' for y in (626, 686))
              + '</g>\n'
              # warm low sun raking across the asphalt
              '    <g fill="#e0b073" opacity="0.16">'
              '<polygon points="0,300 1280,300 1280,340 0,368"/>'
              '<polygon points="0,612 1280,612 1280,700 0,720"/></g>')

    # ---------------------------------------------------------------- props ----
    def lamp(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-4" y="-96" width="8" height="96" fill="#2f2b33"/>'
                f'<rect x="-9" y="-4" width="18" height="6" rx="2" fill="#2f2b33"/>'
                f'<rect x="-16" y="-100" width="32" height="6" rx="3" fill="#2f2b33"/>'
                f'<g fill="#2f2b33"><circle cx="-16" cy="-108" r="9"/><circle cx="16" cy="-108" r="9"/>'
                f'<circle cx="0" cy="-116" r="10"/></g>'
                f'<g fill="#ffeec2"><circle cx="-16" cy="-108" r="6.5"/><circle cx="16" cy="-108" r="6.5"/>'
                f'<circle cx="0" cy="-116" r="7.5"/></g></g>')

    def barricade(x, y, n, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})" fill="#9aa0a8">'
                + ''.join(f'<g transform="translate({k * 58},0)">'
                          f'<rect x="0" y="-30" width="54" height="3.5" rx="1.5"/>'
                          f'<rect x="0" y="-18" width="54" height="3.5" rx="1.5"/>'
                          f'<rect x="0" y="-34" width="3.5" height="34"/>'
                          f'<rect x="50" y="-34" width="3.5" height="34"/>'
                          f'<rect x="-4" y="-2" width="16" height="3" rx="1.5"/>'
                          f'<rect x="42" y="-2" width="16" height="3" rx="1.5"/></g>' for k in range(n))
                + '</g>')

    def person(x, y, s=1.0, shirt='#3f6ea8', trouser='#2f3440', skin='#c98d63', hat=None):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 1, 11, 3, 0.16)}'
                f'<g fill="{trouser}"><rect x="-6" y="-22" width="5" height="22" rx="2"/>'
                f'<rect x="1" y="-22" width="5" height="22" rx="2"/></g>'
                f'<rect x="-8" y="-42" width="16" height="22" rx="5" fill="{shirt}"/>'
                f'<rect x="-11" y="-40" width="4" height="17" rx="2" fill="{shirt}"/>'
                f'<rect x="7" y="-40" width="4" height="17" rx="2" fill="{shirt}"/>'
                f'<circle cx="0" cy="-49" r="7" fill="{skin}"/>'
                + (f'<path d="M-11,-52 L11,-52 L9,-56 L-9,-56 Z" fill="{hat}"/>'
                   f'<ellipse cx="0" cy="-52" rx="13" ry="2.6" fill="{hat}"/>' if hat else
                   f'<path d="M-7,-52 C -7,-58 7,-58 7,-52 Z" fill="#4a3a2e"/>')
                + '</g>')

    def busker(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 2, 16, 4, 0.18)}'
                f'<g fill="#2f3440"><rect x="-7" y="-24" width="6" height="24" rx="2"/>'
                f'<rect x="2" y="-24" width="6" height="24" rx="2"/></g>'
                f'<rect x="-10" y="-48" width="20" height="26" rx="6" fill="#b8442f"/>'
                f'<circle cx="0" cy="-56" r="8" fill="#c98d63"/>'
                f'<path d="M-14,-60 L14,-60 L11,-65 L-11,-65 Z" fill="#6b4a2e"/>'
                f'<ellipse cx="0" cy="-60" rx="17" ry="3" fill="#6b4a2e"/>'
                # the guitar
                f'<g transform="translate(4,-32) rotate(-18)">'
                f'<ellipse cx="0" cy="0" rx="13" ry="10" fill="#d99a4e"/>'
                f'<ellipse cx="-6" cy="0" rx="9" ry="7.5" fill="#e8b269"/>'
                f'<circle cx="2" cy="0" r="3.4" fill="#6b4a2e"/>'
                f'<rect x="10" y="-2" width="22" height="4" rx="1" fill="#5d3a24"/>'
                f'<rect x="30" y="-4" width="7" height="8" rx="2" fill="#3f2a1c"/></g>'
                f'<g fill="#e8d6b8"><rect x="-11" y="-44" width="8" height="4" rx="2"/></g></g>')

    def street_tree(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 26, 5, 0.2)}'
                f'<rect x="-24" y="-10" width="48" height="10" rx="2" fill="#5f5348"/>'
                f'<rect x="-24" y="-13" width="48" height="4" rx="2" fill="#75655a"/>'
                f'<rect x="-3" y="-46" width="6" height="36" fill="#5d4234"/>'
                f'<circle cx="0" cy="-62" r="21" fill="#4a7a42"/>'
                f'<circle cx="-13" cy="-52" r="14" fill="#3f6b39"/>'
                f'<circle cx="14" cy="-54" r="13" fill="#3f6b39"/>'
                f'<circle cx="-5" cy="-74" r="13" fill="#5c9050"/>'
                f'<circle cx="9" cy="-70" r="11" fill="#5c9050"/></g>')

    def stage(x, y, sc=1.0):
        """An outdoor stage with a band on it. Nashville has live music on the street at
        two in the afternoon; a scene of it without a band playing is missing the point."""
        def player(px, py, shirt, kind):
            g = [f'<g fill="#2f3440"><rect x="{px - 5}" y="{py - 20}" width="4.5" height="20" rx="2"/>'
                 f'<rect x="{px + 1}" y="{py - 20}" width="4.5" height="20" rx="2"/></g>',
                 f'<rect x="{px - 7}" y="{py - 38}" width="14" height="20" rx="5" fill="{shirt}"/>',
                 f'<circle cx="{px}" cy="{py - 44}" r="6" fill="#c98d63"/>',
                 f'<path d="M{px - 11},{py - 47} L{px + 11},{py - 47} L{px + 9},{py - 51} '
                 f'L{px - 9},{py - 51} Z" fill="#5d4234"/>'
                 f'<ellipse cx="{px}" cy="{py - 47}" rx="13" ry="2.4" fill="#5d4234"/>']
            if kind == 'guitar':
                g.append(f'<g transform="translate({px + 4},{py - 26}) rotate(-16)">'
                         f'<ellipse cx="0" cy="0" rx="10" ry="8" fill="#d99a4e"/>'
                         f'<ellipse cx="-4" cy="0" rx="7" ry="6" fill="#e8b269"/>'
                         f'<circle cx="1" cy="0" r="2.6" fill="#6b4a2e"/>'
                         f'<rect x="8" y="-1.6" width="17" height="3.2" rx="1" fill="#5d3a24"/>'
                         f'<rect x="23" y="-3" width="6" height="6" rx="2" fill="#3f2a1c"/></g>')
            elif kind == 'bass':
                g.append(f'<g transform="translate({px - 10},{py - 20})">'
                         f'<ellipse cx="0" cy="0" rx="8" ry="11" fill="#b0763a"/>'
                         f'<ellipse cx="0" cy="-1" rx="6" ry="8" fill="#c98d4e"/>'
                         f'<rect x="-1.6" y="-30" width="3.2" height="20" fill="#5d3a24"/>'
                         f'<rect x="-3.4" y="-35" width="7" height="7" rx="2" fill="#3f2a1c"/></g>')
            elif kind == 'fiddle':
                g.append(f'<g transform="translate({px + 6},{py - 32}) rotate(-32)">'
                         f'<ellipse cx="0" cy="0" rx="6" ry="9" fill="#a8632c"/>'
                         f'<rect x="-1.6" y="-20" width="3.2" height="12" fill="#5d3a24"/>'
                         f'<path d="M-12,4 L14,-6" stroke="#e2d8c0" stroke-width="1.6"/></g>')
            return ''.join(g)

        return (f'<g id="stage" transform="translate({x},{y}) scale({sc})">'
                f'{shadow(0, 4, 108, 10, 0.22)}'
                # deck
                f'<rect x="-104" y="-34" width="208" height="34" fill="#3a3238"/>'
                f'<rect x="-104" y="-38" width="208" height="6" rx="2" fill="#6b5344"/>'
                f'<g fill="#2b242a" opacity="0.6">'
                + ''.join(f'<rect x="{-100 + k * 26}" y="-32" width="4" height="30"/>'
                          for k in range(8)) + '</g>'
                # back wall with a banner
                f'<rect x="-92" y="-118" width="184" height="82" fill="#241d24"/>'
                f'<rect x="-76" y="-108" width="152" height="42" rx="4" fill="#8f2f3c"/>'
                f'<rect x="-70" y="-102" width="140" height="30" rx="3" fill="none" '
                f'stroke="#f2cf8a" stroke-width="2.4"/>'
                f'<g transform="translate(0,-87) scale(0.62)">'
                f'<ellipse cx="0" cy="0" rx="13" ry="10" fill="#f2cf8a"/>'
                f'<circle cx="2" cy="0" r="3.4" fill="#8f2f3c"/>'
                f'<rect x="10" y="-2" width="24" height="4" rx="1" fill="#f2cf8a"/>'
                f'<rect x="-38" y="-2" width="24" height="4" rx="1" fill="#f2cf8a"/></g>'
                # roof canopy on a truss
                f'<path d="M-116,-124 L116,-124 L104,-140 L-104,-140 Z" fill="#2b242a"/>'
                f'<rect x="-118" y="-126" width="236" height="6" rx="3" fill="#3f3740"/>'
                f'<g stroke="#4a4048" stroke-width="2.4" fill="none">'
                + ''.join(f'<path d="M{-104 + k * 29},-140 L{-92 + k * 29},-126"/>'
                          f'<path d="M{-92 + k * 29},-140 L{-104 + k * 29},-126"/>' for k in range(8))
                + '</g>'
                f'<rect x="-98" y="-124" width="6" height="88" fill="#3f3740"/>'
                f'<rect x="92" y="-124" width="6" height="88" fill="#3f3740"/>'
                # stage lights hanging off the truss, throwing warm cones
                + '<g>'
                + ''.join(f'<rect x="{-84 + k * 34}" y="-122" width="10" height="9" rx="2" '
                          f'fill="#4a4048"/>'
                          f'<circle cx="{-79 + k * 34}" cy="-112" r="5" fill="#ffe6a8"/>'
                          f'<path d="M{-86 + k * 34},-110 L{-72 + k * 34},-110 '
                          f'L{-62 + k * 34},-40 L{-96 + k * 34},-40 Z" fill="#ffe6a8" '
                          f'opacity="0.13"/>' for k in range(6)) + '</g>'
                # PA stacks
                + ''.join(f'<g transform="translate({sx},-36)">'
                          f'<rect x="-15" y="-64" width="30" height="64" rx="3" fill="#1f1a20"/>'
                          f'<g fill="#3a3238"><circle cx="0" cy="-48" r="9"/>'
                          f'<circle cx="0" cy="-24" r="11"/></g>'
                          f'<g fill="#575059"><circle cx="0" cy="-48" r="4"/>'
                          f'<circle cx="0" cy="-24" r="5"/></g></g>' for sx in (-84, 84))
                # the band
                + player(-32, -36, '#c0392b', 'guitar')
                + player(26, -36, '#2f6f9e', 'bass')
                + player(62, -36, '#4f9d6a', 'fiddle')
                # a couple of people watching, on the ground in front
                + f'<g transform="translate(-118,4)">'
                f'<g fill="#2f3440"><rect x="-5" y="-20" width="4.5" height="20" rx="2"/>'
                f'<rect x="1" y="-20" width="4.5" height="20" rx="2"/></g>'
                f'<rect x="-7" y="-38" width="14" height="20" rx="5" fill="#e8d24a"/>'
                f'<circle cx="0" cy="-44" r="6" fill="#8a5a3c"/></g>'
                + f'<g transform="translate(134,6)">'
                f'<g fill="#4a4a52"><rect x="-5" y="-20" width="4.5" height="20" rx="2"/>'
                f'<rect x="1" y="-20" width="4.5" height="20" rx="2"/></g>'
                f'<rect x="-7" y="-38" width="14" height="20" rx="5" fill="#7a4f9e"/>'
                f'<circle cx="0" cy="-44" r="6" fill="#c98d63"/>'
                f'<path d="M-11,-47 L11,-47 L9,-51 L-9,-51 Z" fill="#5d4234"/>'
                f'<ellipse cx="0" cy="-47" rx="13" ry="2.4" fill="#5d4234"/></g>'
                + '</g>')

    def car(x, y, s=1.0, body='#2f5f9e'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 6, 60, 8, 0.24)}'
                f'<rect x="-54" y="-30" width="108" height="24" rx="8" fill="{body}"/>'
                f'<path d="M-30,-30 L-20,-52 L24,-52 L36,-30 Z" fill="{body}"/>'
                f'<path d="M-26,-32 L-17,-48 L0,-48 L0,-32 Z" fill="#cfe4f2"/>'
                f'<path d="M4,-32 L4,-48 L22,-48 L31,-32 Z" fill="#cfe4f2"/>'
                f'<g fill="#1b1f25"><circle cx="-32" cy="-4" r="11"/><circle cx="32" cy="-4" r="11"/></g>'
                f'<g fill="#9aa2ab"><circle cx="-32" cy="-4" r="4.5"/><circle cx="32" cy="-4" r="4.5"/></g>'
                f'<rect x="-56" y="-24" width="8" height="6" rx="2" fill="#f6e0a0"/>'
                f'<rect x="48" y="-24" width="8" height="6" rx="2" fill="#c0392b"/></g>')

    back = ('    ' + ''.join(lamp(x, 402, 0.42) for x in (56, 268, 466, 812, 1010, 1224))
            + barricade(24, 402, 3, 0.6) + barricade(304, 402, 3, 0.6)
            + barricade(768, 402, 3, 0.6) + barricade(1064, 402, 3, 0.6)
            + ''.join(street_tree(x, 402, 0.44) for x in (172, 386, 496, 800, 926, 1146))
            + car(150, 446, 0.44, '#2f5f9e') + car(392, 446, 0.44, '#e8b02a')
            + car(880, 446, 0.44, '#f2f2ec') + car(1130, 446, 0.44, '#b8342c')
            + ''.join(person(x, 400, s, sh, tr, sk, hat) for x, s, sh, tr, sk, hat in
                      [(96, 0.5, '#e8d24a', '#2f3440', '#c98d63', None),
                       (128, 0.46, '#3f6ea8', '#4a4a52', '#8a5a3c', '#4a3a2e'),
                       (236, 0.52, '#c0392b', '#2f3440', '#c98d63', None),
                       (262, 0.48, '#4f9d6a', '#37414f', '#e0b58c', '#6b4a2e'),
                       (392, 0.5, '#7a4f9e', '#2f3440', '#8a5a3c', None),
                       (498, 0.46, '#e07a2a', '#3a3f4a', '#c98d63', '#6b4a2e'),
                       (786, 0.5, '#2f8fa8', '#2f3440', '#e0b58c', None),
                       (876, 0.48, '#d9455e', '#4a4a52', '#8a5a3c', '#4a3a2e'),
                       (1128, 0.52, '#3f6ea8', '#2f3440', '#c98d63', None),
                       (1160, 0.46, '#e8d24a', '#37414f', '#e0b58c', '#6b4a2e')]))

    front = ('    ' + lamp(1200, 606, 0.78)
             + busker(978, 610, 1.05)
             + person(1058, 610, 0.86, '#3f6ea8', '#2f3440', '#c98d63', '#6b4a2e')
             + person(1094, 604, 0.78, '#d9455e', '#4a4a52', '#e0b58c', None)
             + person(206, 608, 0.9, '#4f9d6a', '#2f3440', '#8a5a3c', '#6b4a2e')
             + person(174, 604, 0.8, '#e8d24a', '#37414f', '#c98d63', None)
             # planters, which are all over Broadway and stop the kerb reading as empty
             + ''.join(f'<g transform="translate({x},606) scale({s})">'
                       f'{shadow(0, 4, 30, 6, 0.2)}'
                       f'<path d="M-26,0 L-22,-26 L22,-26 L26,0 Z" fill="#7a5344"/>'
                       f'<rect x="-24" y="-30" width="48" height="6" rx="2" fill="#8d6252"/>'
                       f'<g fill="#3f7a4a"><ellipse cx="-10" cy="-34" rx="14" ry="9"/>'
                       f'<ellipse cx="10" cy="-36" rx="13" ry="9"/>'
                       f'<ellipse cx="0" cy="-42" rx="12" ry="8"/></g>'
                       f'<g fill="#e8d24a"><circle cx="-14" cy="-38" r="3"/><circle cx="8" cy="-42" r="3"/>'
                       f'<circle cx="14" cy="-32" r="2.6"/></g></g>'
                       for x, s in [(430, 0.95), (856, 1.0), (1256, 0.9)])
             + barricade(806, 606, 2, 0.95)
             + ''.join(street_tree(x, 626, sc) for x, sc in
                       [(492, 0.85), (782, 0.85), (1152, 0.95)])
             + stage(250, 698, 1.06)
             # a hot chicken cart, because that is what is actually parked on this street
             + '<g transform="translate(872,668) scale(0.9)">'
             + shadow(0, 4, 44, 7, 0.22)
             + '<rect x="-38" y="-44" width="76" height="42" rx="4" fill="#c0392b"/>'
             + '<rect x="-38" y="-44" width="76" height="10" rx="4" fill="#a5302a"/>'
             + '<rect x="-30" y="-30" width="60" height="18" rx="2" fill="#f2e4cc"/>'
             + '<g fill="#c0392b"><rect x="-24" y="-25" width="48" height="4" rx="2"/>'
               '<rect x="-16" y="-18" width="32" height="4" rx="2"/></g>'
             + '<path d="M-46,-46 L46,-46 L40,-58 L-40,-58 Z" fill="#e8b02a"/>'
             + '<g fill="#f2ece2"><path d="M-40,-46 L-28,-46 L-24,-58 L-36,-58 Z"/>'
               '<path d="M-16,-46 L-4,-46 L-2,-58 L-14,-58 Z"/>'
               '<path d="M8,-46 L20,-46 L20,-58 L8,-58 Z"/>'
               '<path d="M32,-46 L40,-46 L38,-58 L28,-58 Z"/></g>'
             + '<g fill="#2a2f36"><circle cx="-22" cy="-2" r="9"/><circle cx="22" cy="-2" r="9"/></g>'
             + '<g fill="#8d949c"><circle cx="-22" cy="-2" r="3.5"/><circle cx="22" cy="-2" r="3.5"/></g>'
             + '</g>'
             + person(818, 672, 0.82, '#3f6ea8', '#2f3440', '#c98d63', None)
             + person(940, 674, 0.86, '#e07a2a', '#37414f', '#8a5a3c', '#6b4a2e')
             + person(1088, 664, 0.84, '#7a4f9e', '#2f3440', '#e0b58c', None)
             + person(404, 700, 0.88, '#2f8fa8', '#4a4a52', '#c98d63', '#4a3a2e')
             # a bench, so the plaza has somewhere to sit
             + ''.join(f'<g transform="translate({bx},672) scale(0.9)">'
                       f'{shadow(0, 3, 40, 6, 0.2)}'
                       f'<rect x="-38" y="-14" width="76" height="6" rx="2" fill="#7a5344"/>'
                       f'<rect x="-38" y="-24" width="76" height="6" rx="2" fill="#8d6252"/>'
                       f'<rect x="-34" y="-14" width="6" height="14" fill="#3f3a40"/>'
                       f'<rect x="28" y="-14" width="6" height="14" fill="#3f3a40"/></g>'
                       for bx in (500, 862)))

    scene('nashville', 'NASHVILLE — Lower Broadway, honky tonk neon, late afternoon', {
        'sky': sky_l,
        'far': skyline,
        'ground': street,
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#3a3438" opacity="0.35"><rect x="0" y="712" width="1280" height="8"/></g>',
        'roadkw': dict(surface='#4e4f54', surface2='#3f4045', shoulder='#b9b5ae', dash='#f0d878'),
        'trackkw': dict(ballast='#6b6660', ballast_hi='#7d7871', tie='#4a3a2e', rail='#d3d7dc'),
    }, d)


def boston():
    """BOSTON — the Charles from the Cambridge bank, looking at Back Bay in early autumn,
    with the road crossing on the bridge. Naming the viewpoint solved the composition:
    Boston is a *low brick city under a few tall things*, and you only see that from across
    the water. The Hancock's blue-green slab, the Prudential's mast and the State House
    dome sit above an unbroken wall of bow-fronted row houses, and the Esplanade's gold
    trees run along their feet. The Green Line is the train, so it isn't drawn here."""
    d = ('''    <linearGradient id="skyg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#2f7cc0"/><stop offset="0.44" stop-color="#74aed6"/>
      <stop offset="0.8" stop-color="#bcd8e4"/><stop offset="1" stop-color="#f0dcc0"/>
    </linearGradient>
    <linearGradient id="charles" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#3f6f96"/><stop offset="0.5" stop-color="#4f83a8"/>
      <stop offset="1" stop-color="#6b9cbc"/>
    </linearGradient>
    <linearGradient id="grassg" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#5f8a48"/><stop offset="1" stop-color="#4a7038"/>
    </linearGradient>
    <linearGradient id="hancock" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="#6f9ba8"/><stop offset="0.55" stop-color="#4a7482"/>
      <stop offset="1" stop-color="#39606d"/>
    </linearGradient>
    <radialGradient id="sung" cx="0.5" cy="0.5" r="0.5">
      <stop offset="0" stop-color="#fff2cf" stop-opacity="0.5"/>
      <stop offset="0.6" stop-color="#ffd58c" stop-opacity="0.16"/>
      <stop offset="1" stop-color="#ffb45c" stop-opacity="0"/>
    </radialGradient>''')

    sky_l = ('    <rect x="0" y="0" width="1280" height="306" fill="url(#skyg)"/>\n'
             '    <circle cx="1050" cy="120" r="230" fill="url(#sung)"/>\n'
             '    <g fill="#ffffff" opacity="0.55">'
             + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{w}" ry="{w*0.1:.0f}"/>'
                       for x, y, w in [(180, 38, 130), (520, 26, 100), (830, 48, 120),
                                       (320, 82, 104), (660, 92, 84), (1080, 66, 90),
                                       (140, 120, 70)]) + '</g>')

    # -------------------------------------------------------------- skyline ----
    BASE = 288

    def slab(x, w, top, a, b, c, win='#c6dae6', step=18):
        h = BASE - top
        return (f'<g><rect x="{x}" y="{top}" width="{w}" height="{h}" fill="{b}"/>'
                f'<rect x="{x}" y="{top}" width="{w * 0.34:.0f}" height="{h}" fill="{a}"/>'
                f'<rect x="{x + w * 0.8:.0f}" y="{top}" width="{w * 0.2:.0f}" height="{h}" fill="{c}"/>'
                + f'<g fill="{win}" opacity="0.34">'
                + ''.join(f'<rect x="{x + 3}" y="{y}" width="{w - 6}" height="3"/>'
                          for y in range(top + 10, BASE - 4, step)) + '</g></g>')

    def dome(x, y, s=1.0):
        """The State House. Gold leaf, and nothing else in Boston is that colour."""
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-52" y="-30" width="104" height="30" fill="#c8b49c"/>'
                f'<rect x="-52" y="-34" width="104" height="6" fill="#ded0bc"/>'
                f'<g fill="#8f7f6c" opacity="0.6">'
                + ''.join(f'<rect x="{-44 + k * 15}" y="-26" width="6" height="20"/>' for k in range(6))
                + '</g>'
                f'<rect x="-26" y="-46" width="52" height="14" fill="#d6c6b0"/>'
                f'<path d="M-24,-46 C -24,-76 24,-76 24,-46 Z" fill="#e0a92c"/>'
                f'<path d="M-24,-46 C -24,-76 0,-78 0,-78 L0,-46 Z" fill="#f2c451"/>'
                f'<rect x="-5" y="-88" width="10" height="12" rx="3" fill="#e0a92c"/>'
                f'<rect x="-1.6" y="-98" width="3.2" height="12" fill="#e0a92c"/></g>')

    def spire(x, base, h, body='#d8d2c6', roof='#7a8c8a'):
        return (f'<g><rect x="{x - 11}" y="{base - h * 0.6:.0f}" width="22" '
                f'height="{h * 0.6:.0f}" fill="{body}"/>'
                f'<rect x="{x - 8}" y="{base - h * 0.78:.0f}" width="16" '
                f'height="{h * 0.2:.0f}" fill="{body}"/>'
                f'<polygon points="{x - 11},{base - h * 0.78:.0f} {x + 11},{base - h * 0.78:.0f} '
                f'{x},{base - h:.0f}" fill="{roof}"/>'
                f'<g fill="#5f6f70"><rect x="{x - 5}" y="{base - h * 0.74:.0f}" width="10" '
                f'height="{h * 0.14:.0f}" rx="4"/></g></g>')

    skyline = ('    <g id="skyline">'
               # hazy back rank
               + ''.join(slab(x, w, t, '#a9bcc8', '#98adbb', '#8397a6', '#cbdde8', 22)
                         for x, w, t in [(60, 48, 214), (150, 36, 232), (300, 44, 220),
                                         (880, 40, 226), (1150, 52, 218), (1230, 40, 236)])
               # the middle city
               + ''.join(slab(x, w, t, '#9a9084', '#877d72', '#6e665d', '#e0d4c0', 16)
                         for x, w, t in [(206, 54, 196), (368, 46, 208), (600, 50, 190),
                                         (676, 38, 214), (840, 44, 200), (1064, 48, 186)])
               # 1920s setback towers, which Boston has a lot of
               + '<g><rect x="740" y="176" width="58" height="112" fill="#8d8074"/>'
               '<rect x="740" y="176" width="20" height="112" fill="#a2958a"/>'
               '<rect x="752" y="152" width="34" height="28" fill="#8d8074"/>'
               '<polygon points="752,152 786,152 769,124" fill="#6b7c74"/>'
               '<g fill="#e0d4c0" opacity="0.3">'
               + ''.join(f'<rect x="744" y="{y}" width="50" height="3"/>' for y in range(186, 284, 15))
               + '</g></g>'
               # the Prudential: broad, grey, with the mast
               + '<g><rect x="902" y="116" width="80" height="172" fill="#8b939a"/>'
               '<rect x="902" y="116" width="26" height="172" fill="#a3aab0"/>'
               '<rect x="964" y="116" width="18" height="172" fill="#737b83"/>'
               '<rect x="902" y="116" width="80" height="8" fill="#b6bcc2"/>'
               '<rect x="938" y="70" width="6" height="48" fill="#6f777e"/>'
               '<g fill="#cfd8de" opacity="0.4">'
               + ''.join(f'<rect x="906" y="{y}" width="72" height="4"/>' for y in range(128, 286, 13))
               + '</g></g>'
               # the Hancock: a thin blue-green glass slab with a notch down one face
               + '<g id="hancock-tower">'
               '<rect x="466" y="86" width="76" height="202" fill="url(#hancock)"/>'
               '<rect x="466" y="86" width="76" height="6" fill="#8fb4bf"/>'
               '<rect x="518" y="86" width="5" height="202" fill="#2e5460"/>'
               '<g fill="#a8ccd6" opacity="0.28">'
               + ''.join(f'<rect x="468" y="{y}" width="72" height="3"/>' for y in range(96, 286, 11))
               + '</g>'
               '<rect x="466" y="86" width="16" height="202" fill="#7fa8b4" opacity="0.6"/></g>'
               + spire(646, BASE, 118)
               + spire(1006, BASE, 74, '#cfc8bc', '#6f8180')
               + dome(178, BASE - 4, 1.35)
               + '</g>')

    # ---------------------------------------------- the Back Bay wall of brick ----
    ROW = [('#8f4a3c', '#a45a49', '#6f3629'), ('#a3564a', '#b96b5c', '#7d3d32'),
           ('#7d4a44', '#956058', '#5f3630'), ('#b06b52', '#c58066', '#8a4f3c'),
           ('#8a5544', '#a06a58', '#683d30'), ('#98604e', '#ae7563', '#744538')]

    def rowhouse(x, w, h, i, bow=True):
        """A Back Bay row house: bow front, mansard roof, tall windows, a stoop. They are
        never detached — the wall is continuous, which is the whole character of the place."""
        base = 292
        top = base - h
        body, lit, dark = ROW[i % len(ROW)]
        g = [f'<rect x="{x}" y="{top}" width="{w}" height="{h}" fill="{body}"/>']
        if bow:
            g.append(f'<path d="M{x + w * 0.18:.0f},{top} L{x + w * 0.82:.0f},{top} '
                     f'L{x + w * 0.82:.0f},{base} L{x + w * 0.18:.0f},{base} Z" fill="{lit}"/>')
            g.append(f'<path d="M{x + w * 0.18:.0f},{top} C {x + w * 0.06:.0f},{top + 6} '
                     f'{x + w * 0.06:.0f},{base - 6} {x + w * 0.18:.0f},{base} Z" fill="{dark}"/>')
            g.append(f'<path d="M{x + w * 0.82:.0f},{top} C {x + w * 0.94:.0f},{top + 6} '
                     f'{x + w * 0.94:.0f},{base - 6} {x + w * 0.82:.0f},{base} Z" fill="{dark}"/>')
        # mansard roof with dormers
        g.append(f'<path d="M{x - 2},{top} L{x + w + 2:.0f},{top} L{x + w - 3:.0f},{top - 16} '
                 f'L{x + 3},{top - 16} Z" fill="#4a4a52"/>')
        g.append(f'<rect x="{x - 3}" y="{top - 3}" width="{w + 6}" height="5" fill="#e2d8c8"/>')
        for k in range(max(1, int(w / 26))):
            dx = x + 8 + k * (w - 12) / max(1, int(w / 26))
            g.append(f'<rect x="{dx:.0f}" y="{top - 14}" width="11" height="12" fill="#4a4a52"/>')
            g.append(f'<rect x="{dx + 2:.0f}" y="{top - 11}" width="7" height="8" fill="#cfe0ea"/>')
        # chimneys, because a Boston roofline without them is a warehouse
        g.append(f'<rect x="{x + w * 0.12:.0f}" y="{top - 30}" width="9" height="16" fill="{dark}"/>')
        if w > 60:
            g.append(f'<rect x="{x + w * 0.74:.0f}" y="{top - 26}" width="8" height="12" fill="{dark}"/>')
        # tall sash windows, two or three per floor, black shutters
        floors = max(2, int((h - 18) / 26))
        per = max(2, int(w / 22))
        for f_i in range(floors):
            wy = top + 8 + f_i * ((h - 20) / floors)
            wh = (h - 20) / floors * 0.62
            for c in range(per):
                wx = x + 6 + c * (w - 10) / per
                ww = (w - 10) / per * 0.5
                g.append(f'<rect x="{wx:.0f}" y="{wy:.0f}" width="{ww:.0f}" height="{wh:.0f}" '
                         f'fill="#2f3a44"/>')
                g.append(f'<rect x="{wx:.0f}" y="{wy:.0f}" width="{ww * 0.45:.0f}" '
                         f'height="{wh:.0f}" fill="#7d95a6" opacity="0.65"/>')
                g.append(f'<rect x="{wx - 1.5:.1f}" y="{wy + wh:.0f}" width="{ww + 3:.0f}" '
                         f'height="2.5" fill="#e2d8c8"/>')
        return ''.join(g)

    backbay = ('    <g id="back-bay">'
               # a hazy rank behind, so the wall has depth
               + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="{292 - y}" '
                         f'fill="#7d6a68" opacity="0.6"/>'
                         for x, y, w in [(20, 236, 90), (130, 244, 70), (250, 232, 80),
                                         (400, 240, 76), (560, 234, 88), (700, 244, 72),
                                         (830, 236, 84), (980, 242, 78), (1120, 234, 92),
                                         (1230, 244, 70)])
               + ''.join(rowhouse(x, w, h, i, bow)
                         for x, w, h, i, bow in
                         [(-20, 64, 50, 0, True), (44, 52, 44, 1, False), (96, 70, 54, 2, True),
                          (166, 56, 46, 3, False), (222, 66, 56, 4, True), (288, 50, 44, 5, False),
                          (338, 72, 52, 1, True), (410, 54, 46, 2, False), (464, 68, 58, 3, True),
                          (532, 52, 44, 0, False), (584, 70, 50, 4, True), (654, 56, 54, 5, False),
                          (710, 66, 46, 2, True), (776, 52, 52, 3, False), (828, 74, 56, 0, True),
                          (902, 54, 44, 1, False), (956, 68, 54, 4, True), (1024, 56, 48, 5, False),
                          (1080, 72, 58, 2, True), (1152, 52, 44, 3, False),
                          (1204, 68, 52, 0, True), (1272, 56, 46, 1, False)])
               # a church campanile and one taller apartment block, because an unbroken
               # cornice line for 1280px reads as a wall rather than a neighbourhood
               + '<g id="campanile">'
               '<rect x="352" y="180" width="40" height="112" fill="#a3968a"/>'
               '<rect x="352" y="180" width="14" height="112" fill="#b8aa9c"/>'
               '<rect x="348" y="176" width="48" height="8" fill="#cabcae"/>'
               '<g fill="#4a4a52"><rect x="360" y="196" width="9" height="18" rx="4"/>'
               '<rect x="375" y="196" width="9" height="18" rx="4"/></g>'
               '<polygon points="348,176 396,176 372,146" fill="#6f8180"/>'
               '<rect x="370" y="132" width="4" height="16" fill="#6f8180"/></g>'
               '<g id="tall-block">'
               '<rect x="1096" y="196" width="66" height="96" fill="#8f4a3c"/>'
               '<rect x="1096" y="196" width="20" height="96" fill="#a45a49"/>'
               '<rect x="1092" y="192" width="74" height="7" fill="#e2d8c8"/>'
               + '<g fill="#2f3a44">'
               + ''.join(f'<rect x="{1104 + c * 18}" y="{206 + r * 22}" width="10" height="14"/>'
                         for r in range(4) for c in range(3)) + '</g></g>'
               + '</g>')

    # -------------------------------------------- the Esplanade along the far bank ----
    def maple(x, y, s=1.0, a='#c8762c', b='#e0983c', c='#a85a24', trunk='#5d4234'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<path d="M-3,2 L-2,-16 L-8,-26 L-1,-22 L0,-34 L2,-22 L9,-28 L2,-16 L3,2 Z" '
                f'fill="{trunk}"/>'
                f'<circle cx="0" cy="-44" r="20" fill="{a}"/>'
                f'<circle cx="-14" cy="-34" r="14" fill="{c}"/>'
                f'<circle cx="14" cy="-36" r="13" fill="{c}"/>'
                f'<circle cx="-6" cy="-54" r="13" fill="{b}"/>'
                f'<circle cx="9" cy="-50" r="11" fill="{b}"/></g>')

    def elm(x, y, s=1.0, a='#4a7a42', b='#5c9050', trunk='#5d4234'):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<path d="M-3,2 L-2,-18 L-9,-30 L-1,-24 L0,-38 L2,-24 L10,-32 L2,-18 L3,2 Z" '
                f'fill="{trunk}"/>'
                f'<ellipse cx="0" cy="-48" rx="24" ry="18" fill="{a}"/>'
                f'<ellipse cx="-9" cy="-54" rx="14" ry="10" fill="{b}"/>'
                f'<ellipse cx="11" cy="-44" rx="12" ry="9" fill="{b}"/></g>')

    esplanade = ('    <g id="esplanade">'
                 '<rect x="0" y="286" width="1280" height="26" fill="#4e7340"/>'
                 '<rect x="0" y="286" width="1280" height="5" fill="#628947"/>'
                 '<rect x="0" y="306" width="1280" height="6" fill="#8f8a80"/>'
                 # the Hatch Shell — a half dome on the lawn, and unmistakable once you know it
                 '<g transform="translate(742,304)">'
                 '<path d="M-40,0 C -40,-32 40,-32 40,0 Z" fill="#d8cfc0"/>'
                 '<path d="M-40,0 C -40,-32 0,-34 0,-34 L0,0 Z" fill="#e8e0d2"/>'
                 '<g stroke="#b0a692" stroke-width="1.4" fill="none">'
                 '<path d="M-30,0 C -30,-22 -14,-30 0,-31"/><path d="M-16,0 C -16,-26 -6,-32 0,-32"/>'
                 '<path d="M16,0 C 16,-26 6,-32 0,-32"/><path d="M30,0 C 30,-22 14,-30 0,-31"/></g>'
                 '<rect x="-46" y="-2" width="92" height="4" fill="#c2b8a6"/></g>'
                 + ''.join(maple(x, 304, s) for x, s in
                           [(40, 0.5), (120, 0.44), (232, 0.52), (330, 0.46), (470, 0.5),
                            (560, 0.44), (664, 0.48), (860, 0.5), (960, 0.44), (1076, 0.52),
                            (1180, 0.46), (1256, 0.5)])
                 + ''.join(elm(x, 304, s) for x, s in
                           [(80, 0.44), (180, 0.5), (286, 0.42), (400, 0.48), (516, 0.44),
                            (612, 0.5), (818, 0.44), (912, 0.48), (1024, 0.42), (1128, 0.5)])
                 + '</g>')

    # ------------------------------------------------------------ the Charles ----
    water_l = ('    <rect x="0" y="310" width="1280" height="88" fill="url(#charles)"/>\n'
               '    <g fill="#8fb8cf" opacity="0.5">'
               + ''.join(f'<rect x="{x}" y="{y}" width="{w}" height="2.5" rx="1.2"/>'
                         for x, y, w in [(60, 320, 90), (300, 328, 70), (520, 316, 110),
                                         (760, 334, 80), (980, 322, 96), (1160, 340, 70),
                                         (140, 352, 120), (420, 360, 90), (700, 356, 104),
                                         (900, 372, 86), (1100, 366, 110), (30, 380, 96),
                                         (560, 384, 74), (820, 390, 90)]) + '</g>\n'
               # reflection of the city, only under the tall things
               '    <g fill="#3a6178" opacity="0.35">'
               '<rect x="470" y="310" width="66" height="42"/>'
               '<rect x="906" y="310" width="72" height="34"/>'
               '<rect x="740" y="310" width="58" height="28"/></g>\n'
               # sailboats — small, and there are always dozens
               + '    <g>' + ''.join(
                   f'<g transform="translate({x},{y}) scale({s})">'
                   f'<path d="M0,0 L0,-26 L15,-2 Z" fill="#f4f4ee"/>'
                   f'<path d="M-2,-24 L-11,-2 L-2,-2 Z" fill="#e2e6e6"/>'
                   f'<path d="M-15,0 L17,0 L13,5 L-11,5 Z" fill="#2f4a5c"/></g>'
                   for x, y, s in [(148, 352, 0.86), (238, 336, 0.7), (392, 366, 0.94),
                                   (628, 344, 0.74), (866, 358, 0.9), (1042, 338, 0.68),
                                   (1190, 372, 1.0), (80, 386, 1.05), (960, 388, 1.0),
                                   (466, 330, 0.6), (1108, 352, 0.82), (742, 378, 1.0),
                                   (206, 368, 0.9), (1266, 336, 0.66)])
               + '</g>\n'
               # a rowing eight, which is the other thing always on this water
               '    <g transform="translate(300,392) scale(0.9)">'
               '<path d="M-64,0 C -40,-5 40,-5 64,0 C 40,4 -40,4 -64,0 Z" fill="#e8e4d8"/>'
               '<g fill="#2f3a44">'
               + ''.join(f'<rect x="{-46 + k * 16}" y="-4" width="4" height="5" rx="1.5"/>'
                         for k in range(7)) + '</g>'
               '<g stroke="#c8b48c" stroke-width="1.8">'
               + ''.join(f'<path d="M{-46 + k * 16},-1 L{-56 + k * 16},9"/>' for k in range(7))
               + '</g></g>')

    # -------------------------------------------------- the bridge carrying the road ----
    def bridge():
        """The road crosses the Charles here, so it has to cross on something. Getting the
        edge maths backwards the first time put the parapet posts out in open water, which
        is a good reminder to derive both rails from the same function."""
        TOPY, BOTY, SPAN = 310, 432, 720
        def edge_l(y):
            return 594 - (y - TOPY) * (164.0 / (SPAN - TOPY))
        def edge_r(y):
            return 686 + (y - TOPY) * (164.0 / (SPAN - TOPY))
        posts = []
        for y in (318, 334, 354, 378, 406, 428):
            t = (y - TOPY) / float(SPAN - TOPY)
            pw, ph = 2.5 + 4 * t, 14 + 26 * t
            posts.append(f'<rect x="{edge_l(y) - pw:.1f}" y="{y - ph:.0f}" width="{pw:.1f}" '
                         f'height="{ph:.0f}"/>')
            posts.append(f'<rect x="{edge_r(y):.1f}" y="{y - ph:.0f}" width="{pw:.1f}" '
                         f'height="{ph:.0f}"/>')
        rail = (f'<polygon points="{edge_l(TOPY):.0f},{TOPY - 14} {edge_r(TOPY):.0f},{TOPY - 14} '
                f'{edge_r(TOPY):.0f},{TOPY - 9} {edge_l(TOPY):.0f},{TOPY - 9}"/>'
                f'<polygon points="{edge_l(TOPY):.0f},{TOPY - 14} {edge_l(TOPY):.0f},{TOPY - 9} '
                f'{edge_l(BOTY):.0f},{BOTY - 22} {edge_l(BOTY):.0f},{BOTY - 30}"/>'
                f'<polygon points="{edge_r(TOPY):.0f},{TOPY - 14} {edge_r(TOPY):.0f},{TOPY - 9} '
                f'{edge_r(BOTY):.0f},{BOTY - 22} {edge_r(BOTY):.0f},{BOTY - 30}"/>')
        return ('    <g id="bridge">'
                # the shadow the deck throws on the water
                f'<polygon points="{edge_l(398) - 16:.0f},398 {edge_r(398) + 16:.0f},398 '
                f'{edge_r(TOPY) + 8:.0f},{TOPY} {edge_l(TOPY) - 8:.0f},{TOPY}" '
                'fill="#2f5169" opacity="0.34"/>'
                # granite piers, biggest nearest
                + '<g>'
                + ''.join(f'<polygon points="{640 - w},{y + hh} {640 - w * 0.76:.0f},{y} '
                          f'{640 + w * 0.76:.0f},{y} {640 + w},{y + hh}" fill="#8f8a80"/>'
                          f'<polygon points="{640 - w},{y + hh} {640 - w * 0.76:.0f},{y} '
                          f'{640 - w * 0.22:.0f},{y} {640 - w * 0.34:.0f},{y + hh}" fill="#a8a296"/>'
                          for w, y, hh in [(15, 320, 18), (24, 344, 24), (36, 378, 30)])
                + '</g>'
                # deck
                + f'<polygon points="{edge_l(BOTY):.0f},{BOTY} {edge_r(BOTY):.0f},{BOTY} '
                f'{edge_r(TOPY):.0f},{TOPY} {edge_l(TOPY):.0f},{TOPY}" fill="#a5a094"/>'
                # raised footways, with a shadow line where they meet the carriageway
                + f'<polygon points="{edge_l(BOTY):.0f},{BOTY} {edge_l(BOTY) + 56:.0f},{BOTY} '
                f'{edge_l(TOPY) + 22:.0f},{TOPY} {edge_l(TOPY):.0f},{TOPY}" fill="#bdb7aa"/>'
                + f'<polygon points="{edge_r(BOTY) - 56:.0f},{BOTY} {edge_r(BOTY):.0f},{BOTY} '
                f'{edge_r(TOPY):.0f},{TOPY} {edge_r(TOPY) - 22:.0f},{TOPY}" fill="#b0aa9d"/>'
                + f'<polygon points="{edge_l(BOTY) + 56:.0f},{BOTY} {edge_l(BOTY) + 66:.0f},{BOTY} '
                f'{edge_l(TOPY) + 26:.0f},{TOPY} {edge_l(TOPY) + 22:.0f},{TOPY}" fill="#8a8579"/>'
                + f'<polygon points="{edge_r(BOTY) - 66:.0f},{BOTY} {edge_r(BOTY) - 56:.0f},{BOTY} '
                f'{edge_r(TOPY) - 22:.0f},{TOPY} {edge_r(TOPY) - 26:.0f},{TOPY}" fill="#8a8579"/>'
                + f'<polygon points="{edge_l(BOTY) - 10:.0f},{BOTY + 14} '
                f'{edge_r(BOTY) + 10:.0f},{BOTY + 14} {edge_r(BOTY):.0f},{BOTY - 6} '
                f'{edge_l(BOTY):.0f},{BOTY - 6}" fill="#8f8a80"/>'
                + f'<polygon points="{edge_l(BOTY) - 10:.0f},{BOTY + 14} '
                f'{edge_r(BOTY) + 10:.0f},{BOTY + 14} {edge_r(BOTY) + 10:.0f},{BOTY + 9} '
                f'{edge_l(BOTY) - 10:.0f},{BOTY + 9}" fill="#6f6a62"/>'
                + f'<g fill="#3f3f46">{"".join(posts)}{rail}</g>'
                + '</g>')

    # ------------------------------------------------------ the Cambridge bank ----
    ground_l = ('    <rect x="0" y="398" width="1280" height="322" fill="url(#grassg)"/>\n'
                # the sea wall and its shadow on the water
                '    <g><rect x="0" y="392" width="1280" height="10" fill="#9a958b"/>'
                '<rect x="0" y="392" width="1280" height="3" fill="#b6b0a4"/>'
                '<rect x="0" y="402" width="1280" height="4" fill="#3f5f38" opacity="0.5"/></g>\n'
                # the riverside path
                '    <g><rect x="0" y="424" width="1280" height="20" fill="#c2b49a"/>'
                '<rect x="0" y="424" width="1280" height="3" fill="#d4c7ae"/>'
                '<rect x="0" y="444" width="1280" height="3" fill="#8f8467"/></g>\n'
                # a second path this side of the tracks, where we are standing
                '    <g><rect x="0" y="600" width="1280" height="30" fill="#c2b49a"/>'
                '<rect x="0" y="600" width="1280" height="4" fill="#d4c7ae"/>'
                '<rect x="0" y="630" width="1280" height="4" fill="#8f8467"/></g>\n'
                # fallen leaves scattered on the grass
                '    <g>'
                + ''.join(f'<ellipse cx="{(i * 137) % 1280}" cy="{560 + (i * 53) % 150}" '
                          f'rx="{3 + i % 3}" ry="{2 + i % 2}" '
                          f'fill="{["#c8762c", "#e0983c", "#a85a24", "#d9a94c"][i % 4]}" '
                          f'opacity="0.8"/>' for i in range(64))
                + '</g>\n'
                '    <g fill="#3f5f38" opacity="0.18">'
                + ''.join(f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.16:.0f}"/>'
                          for x, y, r in [(200, 500, 150), (700, 520, 130), (1100, 496, 140),
                                          (400, 660, 160), (950, 676, 150)]) + '</g>')

    # ---------------------------------------------------------------- props ----
    def gaslamp(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<rect x="-3" y="-78" width="6" height="78" fill="#2b2b30"/>'
                f'<rect x="-8" y="-4" width="16" height="6" rx="2" fill="#2b2b30"/>'
                f'<path d="M-8,-80 L8,-80 L5,-98 L-5,-98 Z" fill="#2b2b30"/>'
                f'<path d="M-6,-82 L6,-82 L4,-96 L-4,-96 Z" fill="#ffedbe"/>'
                f'<path d="M-9,-98 L9,-98 L0,-108 Z" fill="#2b2b30"/>'
                f'<circle cx="0" cy="-110" r="2.6" fill="#2b2b30"/></g>')

    def railing(x, y, n, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})" fill="#2b2b30">'
                f'<rect x="0" y="-34" width="{n * 16 + 4}" height="3.5" rx="1.5"/>'
                f'<rect x="0" y="-6" width="{n * 16 + 4}" height="3" rx="1.5"/>'
                + ''.join(f'<rect x="{2 + k * 16}" y="-38" width="3" height="38"/>'
                          f'<circle cx="{3.5 + k * 16}" cy="-40" r="2.6"/>' for k in range(n + 1))
                + '</g>')

    def person(x, y, s=1.0, coat='#3f5f8c', trouser='#2f3440', skin='#c98d63', hat=None):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 1, 11, 3, 0.16)}'
                f'<g fill="{trouser}"><rect x="-6" y="-22" width="5" height="22" rx="2"/>'
                f'<rect x="1" y="-22" width="5" height="22" rx="2"/></g>'
                f'<rect x="-8" y="-42" width="16" height="23" rx="5" fill="{coat}"/>'
                f'<rect x="-11" y="-40" width="4" height="18" rx="2" fill="{coat}"/>'
                f'<rect x="7" y="-40" width="4" height="18" rx="2" fill="{coat}"/>'
                f'<circle cx="0" cy="-49" r="7" fill="{skin}"/>'
                + (f'<path d="M-8,-52 C -8,-59 8,-59 8,-52 Z" fill="{hat}"/>'
                   f'<rect x="-9" y="-53" width="18" height="2.6" rx="1.3" fill="{hat}"/>' if hat else
                   f'<path d="M-7,-52 C -7,-58 7,-58 7,-52 Z" fill="#4a3a2e"/>')
                + '</g>')

    def dog(x, y, s=1.0, col='#6b4a34'):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 1, 14, 3, 0.16)}'
                f'<ellipse cx="0" cy="-12" rx="14" ry="8" fill="{col}"/>'
                f'<g fill="{col}"><rect x="-10" y="-8" width="4" height="9" rx="2"/>'
                f'<rect x="-2" y="-8" width="4" height="9" rx="2"/>'
                f'<rect x="7" y="-8" width="4" height="9" rx="2"/></g>'
                f'<circle cx="14" cy="-18" r="7" fill="{col}"/>'
                f'<path d="M10,-24 L12,-32 L17,-25 Z" fill="{col}"/>'
                f'<path d="M-13,-16 C -20,-22 -20,-28 -15,-28" stroke="{col}" stroke-width="3.4" '
                f'fill="none" stroke-linecap="round"/>'
                f'<circle cx="20" cy="-17" r="2" fill="#2b2b30"/></g>')

    def bench(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">{shadow(0, 3, 40, 6, 0.2)}'
                f'<rect x="-38" y="-14" width="76" height="6" rx="2" fill="#6b4a34"/>'
                f'<rect x="-38" y="-24" width="76" height="6" rx="2" fill="#7d5940"/>'
                f'<rect x="-38" y="-34" width="76" height="6" rx="2" fill="#6b4a34"/>'
                f'<rect x="-34" y="-14" width="5" height="14" fill="#2b2b30"/>'
                f'<rect x="29" y="-14" width="5" height="14" fill="#2b2b30"/></g>')

    def swan(x, y, s=1.0):
        return (f'<g transform="translate({x},{y}) scale({s})">'
                f'<ellipse cx="0" cy="0" rx="13" ry="7" fill="#f4f4ee"/>'
                f'<path d="M6,-4 C 12,-10 12,-18 7,-20 C 4,-21 2,-19 3,-17 C 7,-15 7,-9 2,-4 Z" '
                f'fill="#f4f4ee"/>'
                f'<path d="M3,-19 L-2,-20 L3,-17 Z" fill="#e08a2c"/>'
                f'<circle cx="5.5" cy="-18.5" r="1" fill="#2b2b30"/></g>')

    back = ('    ' + ''.join(gaslamp(x, 444, 0.5) for x in (66, 296, 470, 830, 1010, 1226))
            + railing(0, 424, 12, 0.5) + railing(212, 424, 10, 0.5)
            + railing(742, 424, 12, 0.5) + railing(1010, 424, 12, 0.5)
            + ''.join(maple(x, 430, s) for x, s in [(150, 0.72), (392, 0.66), (886, 0.7), (1136, 0.64)])
            + ''.join(elm(x, 430, s) for x, s in [(250, 0.66), (500, 0.7), (960, 0.64), (1226, 0.72)])
            + ''.join(person(x, 438, s, c, t, sk, h) for x, s, c, t, sk, h in
                      [(108, 0.5, '#b8442f', '#2f3440', '#c98d63', None),
                       (208, 0.46, '#3f5f8c', '#4a4a52', '#8a5a3c', '#2f3440'),
                       (330, 0.5, '#4f8a6a', '#2f3440', '#e0b58c', None),
                       (556, 0.46, '#e0983c', '#37414f', '#c98d63', None),
                       (800, 0.5, '#7a4f9e', '#2f3440', '#8a5a3c', '#2f3440'),
                       (1064, 0.48, '#c8762c', '#4a4a52', '#e0b58c', None)])
            + swan(96, 396, 0.6) + swan(126, 392, 0.5) + swan(1174, 394, 0.55)
            + swan(430, 394, 0.52) + swan(458, 390, 0.44) + swan(908, 396, 0.58)
            # a little launch pottering across, which this river always has
            + '<g transform="translate(1010,364) scale(0.8)">'
              '<path d="M-22,0 L22,0 L17,7 L-17,7 Z" fill="#e8e4d8"/>'
              '<rect x="-9" y="-9" width="18" height="9" rx="2" fill="#f4f4ee"/>'
              '<rect x="-1.2" y="-19" width="2.4" height="11" fill="#6f6a62"/>'
              '<path d="M-24,7 C -10,11 10,11 24,7" stroke="#8fb8cf" stroke-width="2" fill="none" opacity="0.7"/></g>')

    front = ('    '
             # a big maple leaning in from each side, which frames the whole view
             + maple(70, 660, 2.1) + maple(1214, 676, 2.3)
             + elm(300, 604, 1.35) + maple(1010, 610, 1.5) + elm(884, 596, 1.15)
             + gaslamp(180, 632, 1.05) + gaslamp(1120, 632, 1.05)
             + railing(0, 632, 9, 0.95) + railing(796, 632, 12, 0.95)
             + bench(412, 636, 0.95) + bench(1006, 640, 1.0)
             + person(452, 634, 0.86, '#b8442f', '#2f3440', '#c98d63', '#2f3440')
             + person(486, 628, 0.78, '#3f5f8c', '#4a4a52', '#e0b58c', None)
             + person(244, 664, 0.92, '#4f8a6a', '#2f3440', '#8a5a3c', None)
             + dog(292, 668, 0.9)
             + person(956, 636, 0.84, '#e0983c', '#37414f', '#c98d63', None)
             + person(824, 668, 0.9, '#7a4f9e', '#2f3440', '#e0b58c', '#2f3440')
             # leaf piles under the big trees
             + ''.join(f'<g fill="{c}" opacity="0.85">'
                       f'<ellipse cx="{x}" cy="{y}" rx="{r}" ry="{r*0.28:.0f}"/></g>'
                       for x, y, r, c in [(118, 692, 46, '#c8762c'), (150, 700, 34, '#e0983c'),
                                          (1180, 706, 52, '#c8762c'), (1140, 714, 36, '#a85a24'),
                                          (330, 700, 30, '#d9a94c'), (930, 706, 34, '#c8762c')]))

    scene('boston', 'BOSTON — Back Bay across the Charles from Cambridge, early autumn', {
        'sky': sky_l,
        'far': skyline + '\n' + backbay + '\n' + esplanade,
        'ground': ground_l,
        'water': water_l + '\n' + bridge(),
        'scenery-back': back,
        'scenery-front': front,
        'foreground': '    <g fill="#3f5f38" opacity="0.3"><rect x="0" y="712" width="1280" height="8"/></g>',
        'roadkw': dict(surface='#5f5a54', surface2='#4d4842', shoulder='#b6b0a4', dash='#f0e3a8'),
        'trackkw': dict(ballast='#8a8378', ballast_hi='#9c958a', tie='#4a3a2e', rail='#d3d7dc'),
    }, d)


